    function matchTemplateOnBoard(boardData, templateData, options) {
        options = options || {};
        const bw = boardData.width;
        const bh = boardData.height;
        const tw = templateData.width;
        const th = templateData.height;
        const bp = boardData.data;
        const tp = templateData.data;
        if (bw < tw || bh < th) return null;

        const subsample = Math.max(1, options.subsample || 2);
        const alphaThreshold = options.alphaThreshold || 120;
        const mask = [];
        for (let y = 0; y < th; y += subsample) {
            for (let x = 0; x < tw; x += subsample) {
                const idx = (y * tw + x) * 4;
                if (tp[idx + 3] > alphaThreshold) {
                    mask.push(x, y, tp[idx], tp[idx + 1], tp[idx + 2]);
                }
            }
        }
        const maskCount = mask.length / 5;
        if (maskCount < 8) return null;

        let bestScore = Infinity;
        let bestX = 0, bestY = 0;
        const coarseStep = Math.max(2, options.coarseStep || 4);
        const maxY = bh - th;
        const maxX = bw - tw;

        for (let by = 0; by <= maxY; by += coarseStep) {
            for (let bx = 0; bx <= maxX; bx += coarseStep) {
                let diffSum = 0;
                for (let m = 0; m < mask.length; m += 5) {
                    const bIdx = ((by + mask[m + 1]) * bw + (bx + mask[m])) * 4;
                    diffSum += Math.abs(bp[bIdx] - mask[m + 2])
                             + Math.abs(bp[bIdx + 1] - mask[m + 3])
                             + Math.abs(bp[bIdx + 2] - mask[m + 4]);
                }
                const mae = diffSum / maskCount;
                if (mae < bestScore) {
                    bestScore = mae;
                    bestX = bx;
                    bestY = by;
                }
            }
        }

        let fineBestScore = bestScore;
        let fineBestX = bestX, fineBestY = bestY;
        const startY = Math.max(0, bestY - coarseStep);
        const endY = Math.min(maxY, bestY + coarseStep);
        const startX = Math.max(0, bestX - coarseStep);
        const endX = Math.min(maxX, bestX + coarseStep);

        for (let by = startY; by <= endY; by++) {
            for (let bx = startX; bx <= endX; bx++) {
                let diffSum = 0;
                for (let m = 0; m < mask.length; m += 5) {
                    const bIdx = ((by + mask[m + 1]) * bw + (bx + mask[m])) * 4;
                    diffSum += Math.abs(bp[bIdx] - mask[m + 2])
                             + Math.abs(bp[bIdx + 1] - mask[m + 3])
                             + Math.abs(bp[bIdx + 2] - mask[m + 4]);
                }
                const mae = diffSum / maskCount;
                if (mae < fineBestScore) {
                    fineBestScore = mae;
                    fineBestX = bx;
                    fineBestY = by;
                }
            }
        }

        const confidence = Math.max(0, Math.min(100, Math.round(100 - (fineBestScore / 2.5))));
        return {
            bestX: fineBestX,
            bestY: fineBestY,
            centerX: Math.round(fineBestX + tw / 2),
            centerY: Math.round(fineBestY + th / 2),
            width: tw,
            height: th,
            score: fineBestScore,
            confidence
        };
    }

    const loadedIconCache = new Map();

    function getCanvasImageData(source, w, h) {
        if (typeof document?.createElement !== 'function') return null;
        try {
            const canvas = document.createElement('canvas');
            canvas.width = w;
            canvas.height = h;
            const ctx = canvas.getContext('2d', { willReadFrequently: true });
            if (!ctx) return null;
            ctx.drawImage(source, 0, 0, w, h);
            return ctx.getImageData(0, 0, w, h);
        } catch (_) { return null; }
    }

    function loadBrowserImage(src) {
        return new Promise((resolve, reject) => {
            const ImgClass = (typeof Image !== 'undefined') ? Image : (window.Image || null);
            if (!ImgClass) return reject(new Error('NO_IMAGE_CONSTRUCTOR'));
            const img = new ImgClass();
            img.crossOrigin = 'anonymous';
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error('LOAD_FAILED'));
            img.src = src;
        });
    }

    function findGoldenFrame(boardData) {
        if (!boardData || !boardData.data) return null;
        const bw = boardData.width;
        const bh = boardData.height;
        const bp = boardData.data;

        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let count = 0;

        for (let y = 15; y < Math.min(160, bh); y++) {
            for (let x = 120; x < Math.min(360, bw); x++) {
                const idx = (y * bw + x) * 4;
                const r = bp[idx];
                const g = bp[idx + 1];
                const b = bp[idx + 2];
                if (r > 150 && g > 120 && b < 120 && r >= g - 15 && r - b > 40) {
                    if (x < minX) minX = x;
                    if (x > maxX) maxX = x;
                    if (y < minY) minY = y;
                    if (y > maxY) maxY = y;
                    count++;
                }
            }
        }

        const fw = maxX - minX;
        const fh = maxY - minY;
        if (count >= 25 && fw >= 45 && fw <= 150 && fh >= 45 && fh <= 145) {
            return { x: minX, y: minY, width: fw, height: fh };
        }
        return { x: 175, y: 20, width: 130, height: 117 };
    }

    function extractBoxObject(boardData, x1, y1, x2, y2) {
        const bw = boardData.width;
        const bh = boardData.height;
        const bp = boardData.data;
        x1 = Math.max(0, Math.min(bw - 1, Math.round(x1)));
        x2 = Math.max(x1 + 4, Math.min(bw - 1, Math.round(x2)));
        y1 = Math.max(0, Math.min(bh - 1, Math.round(y1)));
        y2 = Math.max(y1 + 4, Math.min(bh - 1, Math.round(y2)));
        const w = x2 - x1 + 1;
        const h = y2 - y1 + 1;

        const R = new Float32Array(w * h);
        const G = new Float32Array(w * h);
        const B = new Float32Array(w * h);
        const greenPts = [];
        for (let ly = 0; ly < h; ly++) {
            for (let lx = 0; lx < w; lx++) {
                const i = ((y1 + ly) * bw + (x1 + lx)) * 4;
                const r = bp[i], g = bp[i + 1], b = bp[i + 2];
                R[ly * w + lx] = r;
                G[ly * w + lx] = g;
                B[ly * w + lx] = b;
                if (g > 140 && g - r > 95 && b > 85 && Math.abs(g - 185) < 55 && Math.abs(b - 129) < 55 && r < 65) {
                    greenPts.push([lx, ly]);
                }
            }
        }

        if (greenPts.length >= 25) {
            let sx = 0, sy = 0;
            for (const [gx, gy] of greenPts) { sx += gx; sy += gy; }
            const cx0 = sx / greenPts.length, cy0 = sy / greenPts.length;
            let bestCx = cx0, bestCy = cy0, bestCnt = -1;
            for (let dy = -6; dy <= 6; dy += 0.5) {
                for (let dx = -6; dx <= 6; dx += 0.5) {
                    let cnt = 0;
                    for (const [gx, gy] of greenPts) {
                        const d = Math.hypot(gx - (cx0 + dx), gy - (cy0 + dy));
                        if (d >= 24.2 && d <= 27.8) cnt++;
                    }
                    if (cnt > bestCnt) { bestCnt = cnt; bestCx = cx0 + dx; bestCy = cy0 + dy; }
                }
            }
            const isRing = new Uint8Array(w * h);
            for (let ly = Math.max(0, Math.floor(bestCy - 31)); ly <= Math.min(h - 1, Math.ceil(bestCy + 31)); ly++) {
                for (let lx = Math.max(0, Math.floor(bestCx - 31)); lx <= Math.min(w - 1, Math.ceil(bestCx + 31)); lx++) {
                    const d = Math.hypot(lx - bestCx, ly - bestCy);
                    if (d >= 23.2 && d <= 28.8) {
                        const p = ly * w + lx;
                        if (G[p] - R[p] > 35 && G[p] > 75 && B[p] > 55) isRing[p] = 1;
                    }
                }
            }
            for (let pass = 0; pass < 4; pass++) {
                const cR = new Float32Array(R), cG = new Float32Array(G), cB = new Float32Array(B);
                for (let ly = Math.max(2, Math.floor(bestCy - 31)); ly <= Math.min(h - 3, Math.ceil(bestCy + 31)); ly++) {
                    for (let lx = Math.max(2, Math.floor(bestCx - 31)); lx <= Math.min(w - 3, Math.ceil(bestCx + 31)); lx++) {
                        const p = ly * w + lx;
                        if (!isRing[p]) continue;
                        let sr = 0, sg = 0, sb = 0, cnt = 0;
                        for (let dy = -3; dy <= 3; dy++) {
                            for (let dx = -3; dx <= 3; dx++) {
                                const np = (ly + dy) * w + (lx + dx);
                                if (!isRing[np]) {
                                    sr += cR[np]; sg += cG[np]; sb += cB[np];
                                    cnt++;
                                }
                            }
                        }
                        if (cnt > 0) {
                            R[p] = sr / cnt; G[p] = sg / cnt; B[p] = sb / cnt;
                            isRing[p] = 0;
                        }
                    }
                }
            }
        }

        for (let pass = 0; pass < 2; pass++) {
            const nR = new Float32Array(R), nG = new Float32Array(G), nB = new Float32Array(B);
            const rad = pass === 0 ? 2 : 3;
            for (let ly = rad; ly < h - rad; ly++) {
                for (let lx = rad; lx < w - rad; lx++) {
                    const p = ly * w + lx;
                    const dirs = [
                        [p - rad, p + rad],
                        [p - rad * w, p + rad * w],
                        [p - rad * w - rad, p + rad * w + rad],
                        [p - rad * w + rad, p + rad * w - rad]
                    ];
                    let matchPairs = 0, sR = 0, sG = 0, sB = 0;
                    for (const [p1, p2] of dirs) {
                        const d12 = Math.abs(R[p1] - R[p2]) + Math.abs(G[p1] - G[p2]) + Math.abs(B[p1] - B[p2]);
                        const mR = (R[p1] + R[p2]) * 0.5, mG = (G[p1] + G[p2]) * 0.5, mB = (B[p1] + B[p2]) * 0.5;
                        const dC = Math.abs(R[p] - mR) + Math.abs(G[p] - mG) + Math.abs(B[p] - mB);
                        if (d12 < 24 && dC > 30 && (pass === 0 || dC < 190)) {
                            matchPairs++;
                            sR += mR; sG += mG; sB += mB;
                        }
                    }
                    if (matchPairs >= 2) {
                        nR[p] = sR / matchPairs;
                        nG[p] = sG / matchPairs;
                        nB[p] = sB / matchPairs;
                    }
                }
            }
            R.set(nR); G.set(nG); B.set(nB);
        }
        for (const rad of [3, 4, 3, 4]) {
            const nR = new Float32Array(R), nG = new Float32Array(G), nB = new Float32Array(B);
            for (let ly = rad; ly < h - rad; ly++) {
                for (let lx = rad; lx < w - rad; lx++) {
                    const p = ly * w + lx;
                    const dirs = [
                        [p - rad, p + rad],
                        [p - rad * w, p + rad * w],
                        [p - rad * w - rad, p + rad * w + rad],
                        [p - rad * w + rad, p + rad * w - rad]
                    ];
                    let scribPairs = 0, sR = 0, sG = 0, sB = 0;
                    for (const [p1, p2] of dirs) {
                        const d12 = Math.abs(R[p1] - R[p2]) + Math.abs(G[p1] - G[p2]) + Math.abs(B[p1] - B[p2]);
                        if (d12 >= 22) continue;
                        const mR = (R[p1] + R[p2]) * 0.5, mG = (G[p1] + G[p2]) * 0.5, mB = (B[p1] + B[p2]) * 0.5;
                        const dR = R[p] - mR, dG = G[p] - mG, dB = B[p] - mB;
                        const chromaDelta = Math.max(dR, dG, dB) - Math.min(dR, dG, dB);
                        if (dR > 10 && dG > 10 && dB > 10 && dR < 85 && chromaDelta <= 16) {
                            scribPairs++;
                            sR += mR; sG += mG; sB += mB;
                        }
                    }
                    if (scribPairs >= 1) {
                        nR[p] = sR / scribPairs;
                        nG[p] = sG / scribPairs;
                        nB[p] = sB / scribPairs;
                    }
                }
            }
            R.set(nR); G.set(nG); B.set(nB);
        }

        const colorBins = new Map();
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                let maxDiff = 0;
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        const np = (ly + dy) * w + (lx + dx);
                        const d = Math.abs(R[p] - R[np]) + Math.abs(G[p] - G[np]) + Math.abs(B[p] - B[np]);
                        if (d > maxDiff) maxDiff = d;
                    }
                }
                if (maxDiff <= 15) {
                    const kr = Math.round(R[p] / 8), kg = Math.round(G[p] / 8), kb = Math.round(B[p] / 8);
                    const key = (kr << 12) | (kg << 6) | kb;
                    let entry = colorBins.get(key);
                    if (!entry) {
                        entry = { count: 0, sumR: 0, sumG: 0, sumB: 0 };
                        colorBins.set(key, entry);
                    }
                    entry.count++;
                    entry.sumR += R[p];
                    entry.sumG += G[p];
                    entry.sumB += B[p];
                }
            }
        }

        const bgColors = [{ r: 25, g: 22, b: 37 }];
        for (const entry of colorBins.values()) {
            const mr = entry.sumR / entry.count, mg = entry.sumG / entry.count, mb = entry.sumB / entry.count;
            const sum = mr + mg + mb;
            const sat = Math.max(mr, mg, mb) - Math.min(mr, mg, mb);
            if (sum < 265 && sat < 56 && (entry.count >= 14 || (entry.count >= 5 && sum < 115))) {
                bgColors.push({ r: mr, g: mg, b: mb });
            }
        }

        const mask = new Uint8Array(w * h);
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                let minDist = Infinity;
                for (const bg of bgColors) {
                    const d = Math.abs(R[p] - bg.r) + Math.abs(G[p] - bg.g) + Math.abs(B[p] - bg.b);
                    if (d < minDist) minDist = d;
                }
                if (minDist > 28) {
                    mask[p] = 1;
                }
            }
        }

        const eroded = new Uint8Array(w * h);
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                if (!mask[p]) continue;
                let n = 0;
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        n += mask[(ly + dy) * w + (lx + dx)];
                    }
                }
                if (n >= 5) eroded[p] = 1;
            }
        }

        let activeSeed = eroded;
        let seedSum = 0;
        for (let i = 0; i < w * h; i++) seedSum += eroded[i];
        if (seedSum < 15) activeSeed = mask;

        const visited = new Uint8Array(w * h);
        const comps = [];
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                if (activeSeed[p] && !visited[p]) {
                    const q = [p];
                    visited[p] = 1;
                    const pts = [];
                    let sx = 0, sy = 0;
                    while (q.length > 0) {
                        const cur = q.pop();
                        const cy = Math.floor(cur / w), cx = cur % w;
                        pts.push([cx, cy]);
                        sx += cx; sy += cy;
                        for (let dy = -3; dy <= 3; dy++) {
                            for (let dx = -3; dx <= 3; dx++) {
                                const ny = cy + dy, nx = cx + dx;
                                if (ny >= 0 && ny < h && nx >= 0 && nx < w) {
                                    const np = ny * w + nx;
                                    if (activeSeed[np] && !visited[np]) {
                                        visited[np] = 1;
                                        q.push(np);
                                    }
                                }
                            }
                        }
                    }
                    if (pts.length >= 12) {
                        comps.push({ pts, count: pts.length, cx: sx / pts.length, cy: sy / pts.length });
                    }
                }
            }
        }
        comps.sort((a, b) => b.count - a.count);
        if (!comps.length) return null;

        const finalMask = new Uint8Array(w * h);
        const main = comps[0];
        const validPts = [];
        for (const c of comps) {
            const distMain = Math.hypot(c.cx - main.cx, c.cy - main.cy);
            const inInterior = c.cx >= 16 && c.cx <= w - 16 && c.cy >= 16 && c.cy <= h - 16;
            const isBowPart = inInterior && ((main.count <= 900 && c.count >= 135 && distMain <= 50) || (main.count < 180 && c.count >= 65 && distMain <= 40));
            if (c === main || (c.count >= 25 && distMain <= 32) || isBowPart) {
                for (const [px, py] of c.pts) {
                    for (let dy = -1; dy <= 1; dy++) {
                        for (let dx = -1; dx <= 1; dx++) {
                            const ny = py + dy, nx = px + dx;
                            if (ny >= 0 && ny < h && nx >= 0 && nx < w) {
                                const np = ny * w + nx;
                                if (mask[np] && !finalMask[np]) {
                                    finalMask[np] = 1;
                                    validPts.push([nx, ny]);
                                }
                            }
                        }
                    }
                }
            }
        }
        if (validPts.length < 10) return null;

        const grad = new Float32Array(w * h);
        for (let ly = 1; ly < h - 1; ly++) {
            for (let lx = 1; lx < w - 1; lx++) {
                const p = ly * w + lx;
                grad[p] = Math.abs(R[p + 1] - R[p - 1]) + Math.abs(G[p + 1] - G[p - 1]) + Math.abs(B[p + 1] - B[p - 1])
                        + Math.abs(R[p + w] - R[p - w]) + Math.abs(G[p + w] - G[p - w]) + Math.abs(B[p + w] - B[p - w]);
            }
        }

        // Prune scribble lines by computing core mask (pixels with >=6 neighbors in 3x3 or >=14 in 5x5)
        const coreMask = new Uint8Array(w * h);
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                if (!finalMask[p]) continue;
                let nb3 = 0;
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        if (finalMask[(ly + dy) * w + (lx + dx)]) nb3++;
                    }
                }
                let nb5 = 0;
                for (let dy = -2; dy <= 2; dy++) {
                    for (let dx = -2; dx <= 2; dx++) {
                        if (finalMask[(ly + dy) * w + (lx + dx)]) nb5++;
                    }
                }
                if (nb3 >= 6 || nb5 >= 14) coreMask[p] = 1;
            }
        }
        const corePts = [];
        for (let ly = 2; ly < h - 2; ly++) {
            for (let lx = 2; lx < w - 2; lx++) {
                const p = ly * w + lx;
                if (!finalMask[p]) continue;
                let nearCore = false;
                for (let dy = -2; dy <= 2 && !nearCore; dy++) {
                    for (let dx = -2; dx <= 2; dx++) {
                        if (coreMask[(ly + dy) * w + (lx + dx)]) { nearCore = true; break; }
                    }
                }
                if (nearCore) corePts.push([lx, ly]);
            }
        }
        if (corePts.length >= 80 && corePts.length >= validPts.length * 0.50) {
            finalMask.fill(0);
            validPts.length = 0;
            for (const pt of corePts) {
                finalMask[pt[1] * w + pt[0]] = 1;
                validPts.push(pt);
            }
        }

        let cx = 0, cy = 0, lumSum = 0, lumSqSum = 0, satSum = 0;
        let sumR = 0, sumG = 0, sumB = 0;
        const colorHist = new Float32Array(8);
        for (const [px, py] of validPts) {
            cx += px;
            cy += py;
            const p = py * w + px;
            const r = R[p], g = G[p], b = B[p];
            sumR += r; sumG += g; sumB += b;
            const l = 0.299 * r + 0.587 * g + 0.114 * b;
            const sat = Math.max(r, g, b) - Math.min(r, g, b);
            lumSum += l;
            lumSqSum += l * l;
            satSum += sat;
            if (sat < 22) {
                if (l > 95) colorHist[0]++;
                else colorHist[1]++;
            } else if (b > r + 15 && b >= g) {
                colorHist[2]++;
            } else if (b > g + 4 && r > g + 2) {
                colorHist[3]++;
            } else if (r - g > 42 && r > b + 35) {
                colorHist[4]++;
            } else if (r > g + 5 && r > b + 50 && g > b + 30) {
                colorHist[5]++;
            } else if (r >= g && g >= b) {
                colorHist[6]++;
            } else {
                colorHist[7]++;
            }
        }
        for (let i = 0; i < 8; i++) colorHist[i] /= validPts.length;
        cx /= validPts.length;
        cy /= validPts.length;
        const meanLum = lumSum / validPts.length;
        const stdLum = Math.max(10, Math.sqrt(Math.max(0, lumSqSum / validPts.length - meanLum * meanLum)));
        const meanSat = satSum / validPts.length;
        const meanR = sumR / validPts.length;
        const meanG = sumG / validPts.length;
        const meanB = sumB / validPts.length;

        let m20 = 0, m02 = 0, m11 = 0, r2Sum = 0;
        for (const [px, py] of validPts) {
            const dx = px - cx, dy = py - cy;
            m20 += dx * dx;
            m02 += dy * dy;
            m11 += dx * dy;
            r2Sum += dx * dx + dy * dy;
        }
        m20 /= validPts.length;
        m02 /= validPts.length;
        m11 /= validPts.length;
        const rmsRadius = Math.max(2, Math.sqrt(r2Sum / validPts.length));
        const trace = m20 + m02;
        const det = Math.sqrt((m20 - m02) * (m20 - m02) + 4 * m11 * m11);
        const l1 = Math.max(1, (trace + det) * 0.5);
        const l2 = Math.max(1, (trace - det) * 0.5);
        const elongation = Math.sqrt(l1 / l2);
        const fillRatio = validPts.length / (rmsRadius * rmsRadius);

        const NR = 12, NA = 36;
        const polarMask = new Float32Array(NR * NA);
        const polarLum = new Float32Array(NR * NA);
        const polarGrad = new Float32Array(NR * NA);

        for (let rIdx = 0; rIdx < NR; rIdx++) {
            const rNorm = 0.15 + (rIdx / (NR - 1)) * 1.9;
            const rad = rNorm * rmsRadius;
            for (let aIdx = 0; aIdx < NA; aIdx++) {
                const ang = (aIdx * 2 * Math.PI) / NA;
                const px = Math.round(cx + rad * Math.cos(ang));
                const py = Math.round(cy + rad * Math.sin(ang));
                let mVal = 0, lVal = 0, gVal = 0, cnt = 0;
                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        const sx = px + dx, sy = py + dy;
                        if (sx >= 0 && sx < w && sy >= 0 && sy < h) {
                            const p = sy * w + sx;
                            const m = finalMask[p];
                            mVal += m;
                            if (m) {
                                const l = 0.299 * R[p] + 0.587 * G[p] + 0.114 * B[p];
                                lVal += (l - meanLum) / stdLum;
                                gVal += grad[p] / 100;
                            }
                            cnt++;
                        }
                    }
                }
                if (cnt > 0) {
                    polarMask[rIdx * NA + aIdx] = mVal / cnt;
                    polarLum[rIdx * NA + aIdx] = mVal > 0 ? lVal / mVal : 0;
                    polarGrad[rIdx * NA + aIdx] = mVal > 0 ? gVal / mVal : 0;
                }
            }
        }

        return {
            cx: cx + x1,
            cy: cy + y1,
            x: Math.round(cx + x1),
            y: Math.round(cy + y1),
            area: validPts.length,
            rmsRadius,
            elongation,
            fillRatio,
            meanLum,
            stdLum,
            meanSat,
            meanR,
            meanG,
            meanB,
            colorHist,
            polarMask,
            polarLum,
            polarGrad
        };
    }

    function compareObjects(top, slot) {
        const NR = 12, NA = 36;
        let bestPolarDist = Infinity;

        for (const mirror of [1, -1]) {
            for (let shift = 0; shift < NA; shift++) {
                let maskDiff = 0;
                let lumDiff = 0;
                let gradDiff = 0;
                let overlapWeight = 0;
                let unionWeight = 0;
                for (let rIdx = 0; rIdx < NR; rIdx++) {
                    const rw = 0.5 + 0.5 * Math.sin((rIdx / (NR - 1)) * Math.PI);
                    for (let aIdx = 0; aIdx < NA; aIdx++) {
                        const bA = ((mirror * aIdx + shift) % NA + NA) % NA;
                        const idxA = rIdx * NA + aIdx;
                        const idxB = rIdx * NA + bA;
                        const mA = top.polarMask[idxA];
                        const mB = slot.polarMask[idxB];
                        maskDiff += rw * Math.abs(mA - mB);
                        unionWeight += rw * Math.max(mA, mB);
                        const minM = Math.min(mA, mB);
                        if (minM > 0.1) {
                            overlapWeight += minM;
                            lumDiff += minM * Math.abs(top.polarLum[idxA] - slot.polarLum[idxB]);
                            gradDiff += minM * Math.abs(top.polarGrad[idxA] - slot.polarGrad[idxB]);
                        }
                    }
                }
                const normMask = maskDiff / Math.max(1, unionWeight);
                const normLum = overlapWeight > 1 ? lumDiff / overlapWeight : 2.0;
                const normGrad = overlapWeight > 1 ? gradDiff / overlapWeight : 1.0;
                const dist = normMask * 2.6 + normLum * 0.65 + normGrad * 0.30;
                if (dist < bestPolarDist) bestPolarDist = dist;
            }
        }

        const rawElongDiff = Math.abs(Math.log(top.elongation / slot.elongation));
        const rawFillDiff = Math.abs(Math.log(top.fillRatio / slot.fillRatio));
        const maxEl = Math.max(top.elongation, slot.elongation), minEl = Math.min(top.elongation, slot.elongation);
        const maxFl = Math.max(top.fillRatio, slot.fillRatio), minFl = Math.min(top.fillRatio, slot.fillRatio);
        const ultraElongatedPair = maxEl >= 6.0 && (
            (minEl >= 2.15 && maxFl <= 2.35 && !(minFl <= 0.95 && maxFl >= 1.80)) ||
            (minEl >= 1.85 && maxFl <= 1.45)
        );
        const elongDiff = (ultraElongatedPair ? Math.min(0.28, rawElongDiff * 0.45) : rawElongDiff) * 0.95;
        const fillDiff = (ultraElongatedPair ? Math.min(0.25, rawFillDiff * 0.55) : rawFillDiff) * 0.95;
        const scaleRatio = slot.rmsRadius / top.rmsRadius;
        const scalePenalty = (scaleRatio < 0.48 || scaleRatio > 1.20)
            ? Math.abs(Math.log(scaleRatio)) * 0.85
            : Math.abs(Math.log(scaleRatio / 0.88)) * 0.12;
        const areaRatio = slot.area / (top.area * 0.85);
        const areaPenalty = Math.abs(Math.log(Math.max(0.35, Math.min(3.5, areaRatio)))) * 0.06;
        const lumStatPenalty = (Math.abs(top.meanLum - slot.meanLum) / 110 + Math.abs(top.stdLum - slot.stdLum) / 85 + Math.abs(top.meanSat - slot.meanSat) / 48) * 0.50;
        const rgbDiff = (Math.abs(top.meanR - slot.meanR) + Math.abs(top.meanG - slot.meanG) + Math.abs(top.meanB - slot.meanB));
        const topRG = top.meanR - top.meanG, slotRG = slot.meanR - slot.meanG;
        const topGB = top.meanG - top.meanB, slotGB = slot.meanG - slot.meanB;
        const chromaDiff = Math.abs(topRG - slotRG) + Math.abs(topGB - slotGB);
        let histDiff = 0;
        let structColorPenalty = 0;
        if (top.colorHist && slot.colorHist) {
            for (let i = 0; i < 8; i++) histDiff += Math.abs(top.colorHist[i] - slot.colorHist[i]);
            histDiff = histDiff - Math.abs(top.colorHist[4] - slot.colorHist[4]) - Math.abs(top.colorHist[5] - slot.colorHist[5])
                + Math.abs((top.colorHist[4] + top.colorHist[5]) - (slot.colorHist[4] + slot.colorHist[5])) * 0.85
                + (Math.abs(top.colorHist[4] - slot.colorHist[4]) + Math.abs(top.colorHist[5] - slot.colorHist[5])) * 0.35;

            if (top.colorHist[2] >= 0.45 && slot.colorHist[2] >= 0.45) {
                const topWarm = top.colorHist[4] + top.colorHist[5] + top.colorHist[6];
                const slotWarm = slot.colorHist[4] + slot.colorHist[5] + slot.colorHist[6];
                if ((topWarm >= 0.06 && slotWarm <= 0.015) || (slotWarm >= 0.06 && topWarm <= 0.015)) {
                    structColorPenalty += 1.45;
                }
            }
            const topGray = top.colorHist[0] + top.colorHist[1], slotGray = slot.colorHist[0] + slot.colorHist[1];
            const topWarmAll = top.colorHist[4] + top.colorHist[5] + top.colorHist[6], slotWarmAll = slot.colorHist[4] + slot.colorHist[5] + slot.colorHist[6];
            const isDaggerLike = (o, oGray, oWarm) => o.meanSat <= 23.5 && oGray >= 0.60 && o.colorHist[0] >= 0.38 && oWarm <= 0.30;
            const isWoodLike = (o, oGray, oWarm) => (o.meanSat >= 30 && oGray <= 0.40 && (oWarm >= 0.42 || o.colorHist[2] >= 0.06)) || (o.meanSat >= 24 && oWarm >= 0.45 && o.colorHist[0] <= 0.34);
            if ((isDaggerLike(slot, slotGray, slotWarmAll) && (isWoodLike(top, topGray, topWarmAll) || (top.elongation <= 1.65 && slot.elongation >= 3.2))) ||
                (isDaggerLike(top, topGray, topWarmAll) && (isWoodLike(slot, slotGray, slotWarmAll) || (slot.elongation <= 1.65 && top.elongation >= 3.2)))) {
                structColorPenalty += 0.75;
            }
            const isLargeRingLike = o => o.area >= 2400 && o.elongation <= 1.24 && o.colorHist[0] <= 0.06;
            const isSmallBottleLike = (o, ref) => o.area < ref.area * 0.55 && o.rmsRadius < ref.rmsRadius * 0.72 && o.colorHist[0] >= 0.10 && o.elongation >= 1.30;
            if ((isLargeRingLike(top) && isSmallBottleLike(slot, top)) || (isLargeRingLike(slot) && isSmallBottleLike(top, slot))) {
                structColorPenalty += 0.75;
            }
            const isCrownLike = o => o.area >= 2600 && o.elongation <= 1.16 && o.fillRatio >= 5.75 && o.colorHist[0] >= 0.15 && o.meanSat >= 50 && o.meanSat <= 78;
            const isPipeOrHairpinLike = o => (o.area <= 1550 && o.elongation >= 1.32 && o.colorHist[0] <= 0.06 && (o.colorHist[4] + o.colorHist[5] + o.colorHist[6]) >= 0.65) || (o.meanSat >= 82 && o.colorHist[0] <= 0.04 && o.colorHist[7] >= 0.15);
            if ((isCrownLike(top) && isPipeOrHairpinLike(slot)) || (isCrownLike(slot) && isPipeOrHairpinLike(top))) {
                structColorPenalty += 1.10;
            }
            const isGogglesLike = o => o.colorHist[2] >= 0.09 && o.colorHist[7] >= 0.15 && (o.colorHist[2] + o.colorHist[7]) >= 0.26;
            const isWarmNoTeal = o => o.colorHist[7] <= 0.06 && (o.colorHist[4] + o.colorHist[5] + o.colorHist[6]) >= 0.68;
            if ((isGogglesLike(top) && isWarmNoTeal(slot)) || (isGogglesLike(slot) && isWarmNoTeal(top))) {
                structColorPenalty += 0.65;
            }
            const isOpalLike = o => o.meanLum >= 170 && o.colorHist[0] >= 0.52 && o.elongation >= 1.16 && o.colorHist[7] <= 0.09;
            const isRoundShieldLike = o => o.meanLum <= 162 && o.elongation <= 1.12 && o.colorHist[7] >= 0.14;
            if ((isOpalLike(top) && isRoundShieldLike(slot)) || (isOpalLike(slot) && isRoundShieldLike(top))) {
                structColorPenalty += 0.55;
            }
        }
        const rgbPenalty = (rgbDiff / 220) * 0.35 + (chromaDiff / 90) * 0.40 + histDiff * 0.62 + structColorPenalty;

        const totalScore = bestPolarDist + elongDiff + fillDiff + scalePenalty + areaPenalty + lumStatPenalty + rgbPenalty;
        return { totalScore, bestPolarDist, elongDiff, fillDiff, scalePenalty, areaPenalty, lumStatPenalty, rgbPenalty, histDiff };
    }

    function findBottomCandidates(boardData) {
        if (!boardData || !boardData.data) return [];
        const bw = boardData.width || 480;
        const rawBh = boardData.height || 330;
        const bh = (bw === 480 && rawBh === 368) ? 330 : rawBh;
        const sx = bw / 480;
        const sy = bh / 330;
        const rawCols = [
            [15, 120],
            [130, 232],
            [248, 355],
            [365, 468]
        ];
        const y1 = Math.round(175 * sy);
        const y2 = Math.min(bh - 5, Math.round(306 * sy));

        return rawCols.map(([cx1, cx2], idx) => {
            const x1 = Math.round(cx1 * sx);
            const x2 = Math.round(cx2 * sx);
            const obj = extractBoxObject(boardData, x1, y1, x2, y2);
            if (obj) {
                return {
                    slot: idx + 1,
                    x: obj.x,
                    y: obj.y,
                    centerX: obj.x,
                    centerY: obj.y,
                    area: obj.area,
                    obj
                };
            }
            const fallbackX = Math.round(((cx1 + cx2) * 0.5) * sx);
            const fallbackY = Math.round(240 * sy);
            return {
                slot: idx + 1,
                x: fallbackX,
                y: fallbackY,
                centerX: fallbackX,
                centerY: fallbackY,
                area: 0,
                obj: null
            };
        });
    }

    const triedSlotsByImage = new Map();

    function solveFrameChallenge(boardData, options = {}) {
        if (!boardData || !boardData.data) return null;
        const frame = findGoldenFrame(boardData);
        if (!frame) return null;

        const insetX = frame.width >= 100 ? 11 : 8;
        const insetY = frame.height >= 100 ? 9 : 8;
        const fx1 = frame.x + insetX;
        const fy1 = frame.y + insetY;
        const fx2 = frame.x + frame.width - insetX;
        const fy2 = frame.y + frame.height - insetY;

        const topObj = extractBoxObject(boardData, fx1, fy1, fx2, fy2);
        const candidates = findBottomCandidates(boardData);
        try { window.__latestBoardCandidates = candidates.map(c => ({ slot: c.slot, x: c.x, y: c.y })); } catch (_) {}
        const validCandidates = candidates.filter(c => c.obj !== null);

        if (topObj && validCandidates.length > 0) {
            const scored = validCandidates.map(c => {
                const cmp = compareObjects(topObj, c.obj);
                return {
                    ...c,
                    score: cmp.totalScore,
                    cmp
                };
            });
            scored.sort((a, b) => a.score - b.score);
            const excludeRaw = options && options.excludeSlots;
            const excludeSet = excludeRaw instanceof Set
                ? excludeRaw
                : new Set(Array.isArray(excludeRaw) ? excludeRaw.map(Number) : []);
            const available = excludeSet.size > 0 ? scored.filter(s => !excludeSet.has(s.slot)) : scored;
            const best = available[0] || scored[0];
            const runnerUp = available.length > 1 ? available[1] : (scored.find(s => s !== best) || null);
            const secondScore = runnerUp ? runnerUp.score : best.score + 1.5;
            const margin = Math.max(0, secondScore - best.score);

            const rawConf = 100 - Math.max(0, best.score - 0.5) * 14 + Math.min(18, margin * 18);
            const confidence = Math.max(40, Math.min(99, Math.round(rawConf)));

            return {
                targetX: best.x,
                targetY: best.y,
                centerX: best.x,
                centerY: best.y,
                x: best.x,
                y: best.y,
                slot: best.slot,
                mae: best.score,
                score: best.score,
                margin,
                confidence,
                frame,
                candidates: candidates.map(c => ({ slot: c.slot, x: c.x, y: c.y })),
                ranked: scored.map(s => ({ slot: s.slot, x: s.x, y: s.y, score: s.score })),
                matchedName: `รูปในกรอบ (ช่องที่ ${best.slot})`
            };
        }

        return null;
    }
    window.findHumanCheckBoardCandidates = findBottomCandidates;

    async function solveBoardChallenge(snapshot) {
        if (typeof window.__mockImageBoardMatcher === 'function') {
            return window.__mockImageBoardMatcher(snapshot);
        }

        const bw = snapshot.packet.width || 480;
        const bh = snapshot.packet.height || 330;

        let boardImg = null;
        const rawSrc = snapshot.rawSrc || snapshot.packet.image || snapshot.boardEl?.querySelector?.('img')?.src;
        if (rawSrc) {
            try { boardImg = await loadBrowserImage(rawSrc); } catch (_) {}
        }
        if (!boardImg) return null;

        const boardData = getCanvasImageData(boardImg, bw, bh);
        if (!boardData) return null;

        const isFramePrompt = /รูปในกรอบ|ในกรอบ|ภาพในกรอบ/i.test(snapshot.prompt || '');
        const target = (typeof embeddedHumanCheckMatch?.resolveTarget === 'function')
            ? embeddedHumanCheckMatch.resolveTarget(snapshot.prompt)
            : null;

        if (target && target.iconPath && !isFramePrompt) {
            let iconImg = loadedIconCache.get(target.iconPath);
            if (!iconImg) {
                try {
                    iconImg = await loadBrowserImage(target.iconUrl || ('/art/icons/' + target.iconPath));
                    loadedIconCache.set(target.iconPath, iconImg);
                } catch (_) {}
            }
            if (iconImg) {
                const candidateSizes = [64, 48, 56, 72];
                let best = null;
                for (const size of candidateSizes) {
                    const tData = getCanvasImageData(iconImg, size, size);
                    if (!tData) continue;
                    const match = matchTemplateOnBoard(boardData, tData, { subsample: 2, coarseStep: 4 });
                    if (match && (!best || match.confidence > best.confidence)) {
                        best = match;
                        if (best.confidence >= 80) break;
                    }
                }
                if (best && best.confidence >= 60) {
                    return {
                        x: best.centerX,
                        y: best.centerY,
                        confidence: best.confidence,
                        matchedName: target.name
                    };
                }
            }
        }

        const excludeSlots = snapshot.imageSig ? triedSlotsByImage.get(snapshot.imageSig) : null;
        const frameSolution = solveFrameChallenge(boardData, { excludeSlots });
        if (frameSolution && frameSolution.confidence >= 40) {
            return {
                x: frameSolution.targetX,
                y: frameSolution.targetY,
                slot: frameSolution.slot,
                candidates: frameSolution.candidates,
                ranked: frameSolution.ranked,
                confidence: frameSolution.confidence,
                matchedName: frameSolution.matchedName || target?.name || 'รูปในกรอบ'
            };
        }

        return null;
    }

    function extractLiveHumanCheckFromDom(hc, rawBoard) {
        if (!hc) return null;
        let fiberCheck = null;
        let fiberId = null;
        let reactOnClick = null;
        const boardImgEl = (rawBoard && typeof rawBoard.querySelector === 'function') ? rawBoard.querySelector('img') : null;
        try {
            if (boardImgEl) {
                const pk = Object.keys(boardImgEl).find(k => k.startsWith('__reactProps$'));
                if (pk && boardImgEl[pk] && typeof boardImgEl[pk].onClick === 'function') {
                    reactOnClick = boardImgEl[pk].onClick;
                }
                const ifk = Object.keys(boardImgEl).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
                const imgFiber = ifk ? boardImgEl[ifk] : null;
                if (imgFiber) {
                    if (!reactOnClick && typeof imgFiber.memoizedProps?.onClick === 'function') {
                        reactOnClick = imgFiber.memoizedProps.onClick;
                    }
                    if (imgFiber.key != null && String(imgFiber.key).trim() !== '') {
                        fiberId = imgFiber.key;
                    }
                }
            }
            const fk = Object.keys(hc).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
            let cur = fk ? hc[fk] : null;
            for (let d = 0; d < 15 && cur; d++) {
                const mp = cur.memoizedProps;
                if (mp && mp.check && mp.check.id != null) {
                    fiberCheck = mp.check;
                    if (fiberId == null) fiberId = mp.check.id;
                } else if (mp && mp.humanCheck && mp.humanCheck.id != null) {
                    fiberCheck = mp.humanCheck;
                    if (fiberId == null) fiberId = mp.humanCheck.id;
                }
                let st = cur.memoizedState;
                let guard = 0;
                while (st && guard++ < 25) {
                    const ms = (st.memoizedState && typeof st.memoizedState === 'object' && st.memoizedState.id == null && st.memoizedState.value && typeof st.memoizedState.value === 'object')
                        ? st.memoizedState.value
                        : st.memoizedState;
                    if (ms && typeof ms === 'object' && ms.id != null && (ms.prompt || ms.image)) {
                        fiberCheck = ms;
                        if (fiberId == null) fiberId = ms.id;
                        break;
                    }
                    st = st.next;
                }
                if (fiberCheck) break;
                cur = cur.return;
            }
        } catch (_) {}
        return { fiberCheck, fiberId, reactOnClick, boardImgEl };
    }

    function submitHumanCheckBoardAnswer(hc, boardEl, packet, targetX, targetY) {
        const liveInfo = extractLiveHumanCheckFromDom(hc, boardEl) || {};
        const liveId = (liveInfo.fiberId != null)
            ? liveInfo.fiberId
            : (packet && !packet.isDomFallback && packet.id != null ? packet.id : null);
        const bw = (liveInfo.fiberCheck && liveInfo.fiberCheck.width) || (packet && packet.width) || 480;
        const bh = (liveInfo.fiberCheck && liveInfo.fiberCheck.height) || (packet && packet.height) || 330;

        let sentCount = 0;
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : (window.__colyseusRoom || null);
        let origSend = null;
        if (room && typeof room.send === 'function') {
            origSend = room.send;
            room.send = function(type) {
                if (type === 'human_check_answer') sentCount++;
                return origSend.apply(this, arguments);
            };
        }

        let reactClicked = false;
        try {
            if (typeof liveInfo.reactOnClick === 'function') {
                liveInfo.reactOnClick({
                    currentTarget: { getBoundingClientRect: () => ({ left: 0, top: 0, width: bw, height: bh }) },
                    target: liveInfo.boardImgEl || boardEl,
                    clientX: targetX,
                    clientY: targetY,
                    preventDefault() {},
                    stopPropagation() {},
                    nativeEvent: {}
                });
                reactClicked = true;
            }
        } catch (_) {}

        if (room && origSend) room.send = origSend;

        if (sentCount === 0 && room && typeof room.send === 'function' && liveId != null && !String(liveId).startsWith('dom-')) {
            try {
                room.send('human_check_answer', { id: liveId, x: targetX, y: targetY });
                sentCount++;
            } catch (_) {}
        }

        try {
            const actualBoardEl = boardEl || (typeof hc?.querySelector === 'function' ? hc.querySelector('.human-check-board') : null);
            if (actualBoardEl && !reactClicked) {
                const targetEl = (typeof actualBoardEl.querySelector === 'function' ? actualBoardEl.querySelector('img') : null) || actualBoardEl;
                const rect = (typeof targetEl.getBoundingClientRect === 'function')
                    ? targetEl.getBoundingClientRect()
                    : (typeof actualBoardEl.getBoundingClientRect === 'function' ? actualBoardEl.getBoundingClientRect() : { left: 0, top: 0, width: bw, height: bh });
                const clientX = rect.left + (targetX / bw) * (rect.width || bw);
                const clientY = rect.top + (targetY / bh) * (rect.height || bh);
                const opts = { bubbles: sentCount === 0, cancelable: true, view: window, clientX, clientY };
                if (typeof PointerEvent !== 'undefined') targetEl.dispatchEvent(new PointerEvent('pointerdown', opts));
                if (typeof MouseEvent !== 'undefined') {
                    targetEl.dispatchEvent(new MouseEvent('mousedown', opts));
                    targetEl.dispatchEvent(new MouseEvent('mouseup', opts));
                    targetEl.dispatchEvent(new MouseEvent('click', opts));
                } else if (typeof targetEl.click === 'function') {
                    targetEl.click();
                }
            }
        } catch (_) {}

        return sentCount > 0 || reactClicked;
    }
    window.submitHumanCheckBoardAnswer = submitHumanCheckBoardAnswer;

    function embeddedHumanCheckSnapshot() {
        const hc = (typeof document?.querySelector === 'function') ? document.querySelector('.human-check') : null;
        if (!hc) return null;
        const promptEl = (typeof hc.querySelector === 'function') ? hc.querySelector('.human-check-prompt') : null;
        const domPrompt = (promptEl && typeof promptEl.innerText === 'string') ? promptEl.innerText.trim() : '';
        const rawBoard = (typeof hc.querySelector === 'function') ? hc.querySelector('.human-check-board') : null;
        const isRealBoardEl = rawBoard && (rawBoard.classList?.contains?.('human-check-board') || rawBoard.className?.includes?.('human-check-board') || rawBoard.tagName === 'DIV' || typeof rawBoard.querySelector === 'function');

        let packet = window.__latestHumanCheck;
        if (isRealBoardEl && domPrompt) {
            const liveInfo = extractLiveHumanCheckFromDom(hc, rawBoard);
            const boardImgEl = liveInfo?.boardImgEl || ((typeof rawBoard.querySelector === 'function') ? rawBoard.querySelector('img') : null);
            const domSrc = (boardImgEl && typeof boardImgEl.getAttribute === 'function' ? boardImgEl.getAttribute('src') : (boardImgEl?.src || '')) || '';
            const fiberId = liveInfo?.fiberId ?? null;
            const fc = liveInfo?.fiberCheck || null;
            const packetStaleByAge = Boolean(packet && (Date.now() - (packet.timestamp || 0) > 120000));
            const packetStaleById = Boolean(packet && fiberId != null && String(packet.id) !== String(fiberId));

            if ((!packet || packetStaleByAge || packetStaleById) && (domSrc || fc)) {
                const sig = domSrc
                    ? `${domSrc.length}:${domSrc.slice(Math.max(0, Math.floor(domSrc.length / 2) - 24), Math.floor(domSrc.length / 2) + 24)}`
                    : String(Date.now());
                packet = window.__latestHumanCheck = {
                    id: fiberId != null ? fiberId : ('dom-' + sig),
                    prompt: domPrompt || (fc && fc.prompt) || '',
                    image: domSrc || (fc && fc.image) || '',
                    width: (fc && fc.width) || 480,
                    height: (fc && fc.height) || 330,
                    triesLeft: (fc && Number.isInteger(fc.triesLeft)) ? fc.triesLeft : undefined,
                    isDomFallback: fiberId == null,
                    timestamp: Date.now()
                };
            } else if (packet && fiberId != null && packet.isDomFallback) {
                packet.id = fiberId;
                packet.isDomFallback = false;
            }
            if (packet && fiberId != null && String(packet.id) === String(fiberId) && domPrompt && packet.prompt !== domPrompt) {
                packet.prompt = domPrompt;
            }
        }
        if (!packet || packet.id == null || typeof packet.prompt !== 'string') return null;

        const prompt = domPrompt || (packet.prompt || '').trim();
        if (prompt !== packet.prompt.trim()) return null;

        // Image Board Mode
        const isBoardMode = Boolean(packet.image || isRealBoardEl);

        if (isBoardMode) {
            const boardImgEl = (isRealBoardEl && typeof rawBoard.querySelector === 'function') ? rawBoard.querySelector('img') : null;
            const rawSrc = (boardImgEl && typeof boardImgEl.getAttribute === 'function' ? boardImgEl.getAttribute('src') : (boardImgEl?.src || '')) || packet.image || '';
            const imageSig = (typeof rawSrc === 'string' && rawSrc.length > 0)
                ? `${rawSrc.length}:${rawSrc.slice(Math.max(0, Math.floor(rawSrc.length / 2) - 24), Math.floor(rawSrc.length / 2) + 24)}`
                : '';
            const metaEl = (typeof hc.querySelector === 'function') ? hc.querySelector('.human-check-meta') : null;
            const metaText = (metaEl && typeof metaEl.innerText === 'string') ? metaEl.innerText : '';
            const triesMatch = metaText.match(/ตอบผิดได้อีก\s*(\d+)/);
            const triesLeft = triesMatch ? Number(triesMatch[1]) : (Number.isInteger(packet.triesLeft) ? packet.triesLeft : null);
            const keyParts = [String(packet.id), prompt];
            if (imageSig || triesLeft != null) {
                keyParts.push(imageSig);
                if (triesLeft != null) keyParts.push(triesLeft);
            }
            return {
                mode: 'board',
                hc,
                boardEl: rawBoard,
                packet,
                prompt,
                rawSrc,
                imageSig,
                triesLeft,
                key: JSON.stringify(keyParts)
            };
        }

        // Buttons Mode
        const buttons = (typeof hc.querySelectorAll === 'function') ? Array.from(hc.querySelectorAll('.human-check-pick')) : [];
        if (buttons.length && buttons.length <= 6 && Array.isArray(packet.items) && packet.items.length === buttons.length) {
            return {
                mode: 'buttons',
                hc,
                packet,
                prompt,
                buttons,
                key: JSON.stringify([String(packet.id), prompt])
            };
        }

        // Emergency shutdown if format is unrecognized
        if (!packet.image && (!Array.isArray(packet.items) || !packet.items.length)) {
            window.__humanCheckFormatUpdated = true;
            try {
                fetch('http://127.0.0.1:3888/api/stop-all', { method: 'POST' }).catch(() => {});
            } catch (_) {}
        }
        return null;
    }

    let embeddedBoardSolving = false;
    function tickEmbeddedHumanCheck() {
        const cfg = window.__pmHumanCheckSolverConfig || {};
        if (window.__autoHumanCheckEnabled === false || cfg.autoAnswer === false) return;
        const snapshot = embeddedHumanCheckSnapshot();
        if (!snapshot || snapshot.key === embeddedHumanCheckAttempt) return;
        if (embeddedHumanCheckPending?.key === snapshot.key) return;

        if (snapshot.mode === 'board') {
            if (embeddedBoardSolving) return;
            embeddedBoardSolving = true;
            Promise.resolve(solveBoardChallenge(snapshot)).then(solution => {
                embeddedBoardSolving = false;
                if (!solution) return;
                const active = embeddedHumanCheckSnapshot();
                if (!active || active.key !== snapshot.key) return;

                const pending = { key: snapshot.key, packet: snapshot.packet, hc: snapshot.hc, mode: 'board', solution };
                embeddedHumanCheckPending = pending;
                const delay = Math.max(800, Math.min(10000, Number(cfg.answerDelayMs) || 1800));

                setTimeout(() => {
                    if (embeddedHumanCheckPending !== pending) return;
                    embeddedHumanCheckPending = null;
                    const activeCfg = window.__pmHumanCheckSolverConfig || {};
                    if (window.__autoHumanCheckEnabled === false || activeCfg.autoAnswer === false) return;
                    const current = embeddedHumanCheckSnapshot();
                    if (!current || current.key !== pending.key || current.packet !== pending.packet || current.hc !== pending.hc || current.key === embeddedHumanCheckAttempt) return;
                    const prevSolved = window.__lastHumanCheckSolved;
                    if (prevSolved && (prevSolved.key === current.key || (prevSolved.source !== 'embedded-local-catalog' && (prevSolved.timestamp || 0) >= current.packet.timestamp))) return;

                    embeddedHumanCheckAttempt = current.key;
                    try { localStorage.setItem(humanCheckAttemptKey, current.key); } catch (_) {}
                    if (current.imageSig && Number.isInteger(solution.slot)) {
                        if (!triedSlotsByImage.has(current.imageSig)) {
                            if (triedSlotsByImage.size >= 30) triedSlotsByImage.clear();
                            triedSlotsByImage.set(current.imageSig, new Set());
                        }
                        triedSlotsByImage.get(current.imageSig).add(solution.slot);
                    }

                    const targetX = solution.x;
                    const targetY = solution.y;
                    let annotatedImageDataUrl = null;
                    try {
                        const boardEl = current.boardEl || (typeof current.hc.querySelector === 'function' ? current.hc.querySelector('.human-check-board') : null);
                        const boardImg = (boardEl && typeof boardEl.querySelector === 'function') ? boardEl.querySelector('img') : null;
                        if (boardImg && boardImg.complete && boardImg.naturalWidth > 0 && typeof document?.createElement === 'function') {
                            const bw = 480, bh = 330, stripH = 38;
                            const bCanvas = document.createElement('canvas');
                            bCanvas.width = bw;
                            bCanvas.height = bh + stripH;
                            const bCtx = bCanvas.getContext && bCanvas.getContext('2d');
                            if (bCtx && typeof bCanvas.toDataURL === 'function') {
                                bCtx.fillStyle = '#0f172a';
                                bCtx.fillRect(0, 0, bw, bh + stripH);
                                bCtx.drawImage(boardImg, 0, 0, bw, bh);
                                if (typeof targetX === 'number' && typeof targetY === 'number') {
                                    bCtx.save();
                                    bCtx.strokeStyle = '#10b981';
                                    bCtx.lineWidth = 3;
                                    bCtx.beginPath();
                                    if (typeof bCtx.arc === 'function') bCtx.arc(targetX, targetY, 26, 0, Math.PI * 2);
                                    bCtx.stroke();
                                    bCtx.restore();
                                }
                                const colCenters = [68, 181, 300, 416];
                                for (let i = 0; i < 4; i++) {
                                    const cx = colCenters[i];
                                    const bx = cx - 44, by = bh + 5;
                                    const isPicked = (solution.slot === i + 1);
                                    bCtx.fillStyle = isPicked ? '#065f46' : '#1e293b';
                                    bCtx.strokeStyle = isPicked ? '#10b981' : '#38bdf8';
                                    bCtx.lineWidth = isPicked ? 2 : 1.5;
                                    bCtx.beginPath();
                                    if (bCtx.roundRect) bCtx.roundRect(bx, by, 88, 28, 6); else if (bCtx.rect) bCtx.rect(bx, by, 88, 28);
                                    bCtx.fill();
                                    bCtx.stroke();
                                    bCtx.fillStyle = '#f8fafc';
                                    bCtx.font = 'bold 13px "Segoe UI", Tahoma, sans-serif';
                                    bCtx.textAlign = 'center';
                                    bCtx.fillText((isPicked ? '✓ ตัวเลือก ' : 'ตัวเลือก ') + (i + 1), cx, by + 19);
                                }
                                annotatedImageDataUrl = bCanvas.toDataURL('image/png');
                            }
                        }
                    } catch (_) {}

                    submitHumanCheckBoardAnswer(current.hc, current.boardEl, current.packet, targetX, targetY);

                    const timestamp = Date.now();
                    const pickedIndex = (Number.isInteger(solution.slot) && solution.slot >= 1 && solution.slot <= 4) ? (solution.slot - 1) : -1;
                    window.__lastHumanCheckSolved = {
                        pickIndex: pickedIndex,
                        slot: solution.slot || null,
                        x: targetX,
                        y: targetY,
                        confidence: solution.confidence,
                        matchedName: solution.matchedName,
                        timestamp,
                        key: current.key,
                        checkId: String(current.packet.id),
                        prompt: current.prompt,
                        triesLeftBefore: current.triesLeft,
                        rawSrc: current.rawSrc || null,
                        annotatedImageDataUrl: annotatedImageDataUrl || null,
                        verified: null,
                        source: 'embedded-local-catalog'
                    };
                    let character = '';
                    try { const c = typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null; character = String(c?.name || c?.characterName || ''); } catch (_) {}
                    const event = {
                        eventId: (window.crypto?.randomUUID?.() || 'hc-' + timestamp + '-' + Math.random().toString(36).slice(2)),
                        checkId: String(current.packet.id),
                        profileId: String(window.__pmProfileId || ''),
                        character,
                        timestamp,
                        pickIndex: pickedIndex,
                        slot: solution.slot || null,
                        x: targetX,
                        y: targetY,
                        confidence: solution.confidence,
                        matchedName: solution.matchedName,
                        source: 'embedded-local-catalog',
                        charged: 0
                    };
                    embeddedHumanCheckEvents.push(event);
                    try { localStorage.setItem(humanCheckEventsKey, JSON.stringify(embeddedHumanCheckEvents)); } catch (_) {}
                    if (window.showHudToast) window.showHudToast(`🤖 ตอบเช็คผู้เล่น (พิกัด): ${solution.matchedName} (${targetX}, ${targetY})`, 'success', 5000);
                }, delay);
            }).catch(() => { embeddedBoardSolving = false; });
            return;
        }

        // Buttons mode
        const options = snapshot.buttons.map((button, index) => ({ index, icon: button.querySelector?.('img')?.getAttribute?.('src') || '' }));
        const solution = embeddedHumanCheckMatch({ prompt: snapshot.prompt, options, items: snapshot.packet.items });
        if (!solution) return;
        const pending = { key: snapshot.key, packet: snapshot.packet, hc: snapshot.hc, mode: 'buttons', solution };
        embeddedHumanCheckPending = pending;
        const delay = Math.max(800, Math.min(10000, Number(cfg.answerDelayMs) || 1800));
        setTimeout(() => {
            if (embeddedHumanCheckPending !== pending) return;
            embeddedHumanCheckPending = null;
            const activeCfg = window.__pmHumanCheckSolverConfig || {};
            if (window.__autoHumanCheckEnabled === false || activeCfg.autoAnswer === false) return;
            const current = embeddedHumanCheckSnapshot();
            if (!current || current.key !== pending.key || current.packet !== pending.packet || current.hc !== pending.hc || current.key === embeddedHumanCheckAttempt) return;
            const target = current.buttons[solution.pickIndex];
            if (!target || target.disabled || (window.__lastHumanCheckSolved?.timestamp || 0) >= current.packet.timestamp) return;

            embeddedHumanCheckAttempt = current.key;
            try { localStorage.setItem(humanCheckAttemptKey, current.key); } catch (_) {}
            try { target.click(); } catch (_) { return; }
            const timestamp = Date.now();
            window.__lastHumanCheckSolved = { pickIndex: solution.pickIndex, matchedName: solution.matchedName, timestamp, verified: null, source: 'embedded-local-catalog' };
            let character = '';
            try { const c = typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null; character = String(c?.name || c?.characterName || ''); } catch (_) {}
            const event = { eventId: (window.crypto?.randomUUID?.() || 'hc-' + timestamp + '-' + Math.random().toString(36).slice(2)), checkId: String(current.packet.id), profileId: String(window.__pmProfileId || ''), character, timestamp, pickIndex: solution.pickIndex, matchedName: solution.matchedName, source: 'embedded-local-catalog', charged: 0 };
            embeddedHumanCheckEvents.push(event);
            try { localStorage.setItem(humanCheckEventsKey, JSON.stringify(embeddedHumanCheckEvents)); } catch (_) {}
            if (window.showHudToast) window.showHudToast('🤖 ตอบเช็คผู้เล่น: ' + solution.matchedName, 'success', 5000);
        }, delay);
    }

    window.__pmLocalHumanCheckEvents = embeddedHumanCheckEvents;
    window.__pmSolveEmbeddedHumanCheck = function () {
        const cfg = window.__pmHumanCheckSolverConfig || {};
        if (window.__autoHumanCheckEnabled === false || cfg.autoAnswer === false) return false;
        const snapshot = embeddedHumanCheckSnapshot();
        if (!snapshot || snapshot.key === embeddedHumanCheckAttempt) return false;
        if (embeddedHumanCheckPending?.key === snapshot.key) return false;
        if (snapshot.mode === 'board') {
            tickEmbeddedHumanCheck();
            return true;
        }
        const options = snapshot.buttons.map((button, index) => ({index, icon: button.querySelector?.('img')?.getAttribute?.('src') || button.querySelector?.('img')?.src || ''}));
        const solution = embeddedHumanCheckMatch({prompt:snapshot.prompt, options, items:snapshot.packet.items});
        if (!solution) return false;
        if (snapshot.buttons[solution.pickIndex]?.disabled) return false;
        tickEmbeddedHumanCheck();
        return !!embeddedHumanCheckPending;
    };
    window.__pmAckLocalHumanCheckEvents = window.__pmAckHumanCheckEvents;
    // END EMBEDDED HUMAN CHECK HOTFIX

    window.playInGameHumanCheckBeep = function(urgent = false) {
        try {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtx) return;
            if (!window.__pmAlertAudioCtx || window.__pmAlertAudioCtx.state === 'closed') {
                window.__pmAlertAudioCtx = new AudioCtx();
            }
            const ctx = window.__pmAlertAudioCtx;
            if (ctx.state === 'suspended' && typeof ctx.resume === 'function') {
                ctx.resume().catch(() => {});
            }
            const notes = urgent ? [987.77, 1318.51, 987.77, 1318.51] : [880, 1174.66];
            notes.forEach((freq, idx) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = urgent ? 'sawtooth' : 'triangle';
                osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.16);
                gain.gain.setValueAtTime(urgent ? 0.32 : 0.22, ctx.currentTime + idx * 0.16);
                gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.16 + 0.14);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(ctx.currentTime + idx * 0.16);
                osc.stop(ctx.currentTime + idx * 0.16 + 0.15);
            });
        } catch (_) {}
    };

    let hasNotifiedHumanCheck = false;
    let humanCheckOpenedAt = 0;
    let lastInGameAlarmAt = 0;
    let unconfirmedRetryCount = 0;
    function checkHumanCheckStatus() {
        const hc = document.querySelector('.human-check');
        const lastSolved = window.__lastHumanCheckSolved;
        if (lastSolved && lastSolved.verified == null && Date.now() - (lastSolved.timestamp || 0) >= 850) {
            if (!hc) {
                lastSolved.verified = 'correct';
                lastSolved.isCorrect = true;
            } else {
                const elapsed = Date.now() - (lastSolved.timestamp || 0);
                const metaEl = hc.querySelector('.human-check-meta');
                const metaText = (metaEl && typeof metaEl.innerText === 'string') ? metaEl.innerText.trim() : '';
                const triesMatch = metaText.match(/ตอบผิดได้อีก\s*(\d+)/);
                const triesLeftAfter = triesMatch ? Number(triesMatch[1]) : null;
                const triesBefore = lastSolved.triesLeftBefore ?? 1;
                const triesDropped = (triesLeftAfter != null && triesBefore != null && triesLeftAfter < triesBefore);

                // If triesLeft has NOT decreased yet (still "ตอบผิดได้อีก 1 ครั้ง"), the game/server is lagging!
                // Re-send at ~1.8s via both React onClick and room.send; if still open at 4.2s, reset attempt so solver retries!
                if (!triesDropped && elapsed < 4200) {
                    if (!lastSolved.retriedLagSend && elapsed >= 1800) {
                        lastSolved.retriedLagSend = true;
                        try {
                            if (typeof lastSolved.x === 'number' && typeof lastSolved.y === 'number') {
                                submitHumanCheckBoardAnswer(hc, hc.querySelector('.human-check-board'), window.__latestHumanCheck, lastSolved.x, lastSolved.y);
                            }
                        } catch (_) {}
                    }
                } else if (triesDropped || (triesLeftAfter == null && elapsed >= 4200)) {
                    lastSolved.verified = 'wrong';
                    lastSolved.isCorrect = false;
                    embeddedHumanCheckAttempt = '';
                    try { localStorage.removeItem(humanCheckAttemptKey); } catch (_) {}
                    try {
                        let imageDataUrl = lastSolved.rawSrc || null;
                        const boardImg = hc.querySelector('.human-check-board img');
                        if (boardImg && boardImg.complete && boardImg.naturalWidth > 0 && typeof document?.createElement === 'function') {
                            try {
                                const bw = 480, bh = 330, stripH = 38;
                                const bCanvas = document.createElement('canvas');
                                bCanvas.width = bw;
                                bCanvas.height = bh + stripH;
                                const bCtx = bCanvas.getContext('2d');
                                if (bCtx) {
                                    bCtx.fillStyle = '#0f172a';
                                    bCtx.fillRect(0, 0, bw, bh + stripH);
                                    bCtx.drawImage(boardImg, 0, 0, bw, bh);
                                    const colCenters = [68, 181, 300, 416];
                                    for (let i = 0; i < 4; i++) {
                                        const cx = colCenters[i];
                                        const bx = cx - 44, by = bh + 5;
                                        bCtx.fillStyle = (lastSolved.slot === i + 1) ? '#991b1b' : '#1e293b';
                                        bCtx.strokeStyle = (lastSolved.slot === i + 1) ? '#ef4444' : '#38bdf8';
                                        bCtx.lineWidth = 1.5;
                                        bCtx.beginPath();
                                        if (bCtx.roundRect) bCtx.roundRect(bx, by, 88, 28, 6); else bCtx.rect(bx, by, 88, 28);
                                        bCtx.fill();
                                        bCtx.stroke();
                                        bCtx.fillStyle = '#f8fafc';
                                        bCtx.font = 'bold 13px "Segoe UI", Tahoma, sans-serif';
                                        bCtx.textAlign = 'center';
                                        bCtx.fillText('ตัวเลือก ' + (i + 1), cx, by + 19);
                                    }
                                    imageDataUrl = bCanvas.toDataURL('image/png');
                                }
                            } catch (_) {}
                        }
                        if (!Array.isArray(window.__pmWrongHumanCheckQueue)) window.__pmWrongHumanCheckQueue = [];
                        if (window.__pmWrongHumanCheckQueue.length < 20) {
                            window.__pmWrongHumanCheckQueue.push({
                                timestamp: lastSolved.timestamp,
                                checkId: lastSolved.checkId || null,
                                prompt: lastSolved.prompt || '',
                                pickIndex: lastSolved.pickIndex,
                                slot: lastSolved.slot || (Number.isInteger(lastSolved.pickIndex) && lastSolved.pickIndex >= 0 ? lastSolved.pickIndex + 1 : null),
                                x: lastSolved.x ?? null,
                                y: lastSolved.y ?? null,
                                confidence: lastSolved.confidence ?? null,
                                matchedName: lastSolved.matchedName || '',
                                source: lastSolved.source || 'embedded-local-catalog',
                                manual: Boolean(lastSolved.manual),
                                answeredBy: lastSolved.answeredBy || null,
                                triesLeftBefore,
                                triesLeftAfter,
                                metaText,
                                imageDataUrl
                            });
                        }
                    } catch (_) {}
                } else {
                    // triesLeft is still >= triesBefore after 4.2s -> click did not register yet!
                    // Reset attempt state so tickEmbeddedHumanCheck() immediately retries instead of giving up!
                    lastSolved.verified = 'unconfirmed';
                    if (unconfirmedRetryCount < 8) {
                        unconfirmedRetryCount++;
                        embeddedHumanCheckAttempt = '';
                        try { localStorage.removeItem(humanCheckAttemptKey); } catch (_) {}
                        if (window.__lastHumanCheckSolved === lastSolved) {
                            window.__lastHumanCheckSolved = null;
                        }
                        if (lastSolved.slot && triedSlotsByImage.size > 0) {
                            for (const set of triedSlotsByImage.values()) set.delete(lastSolved.slot);
                        }
                    }
                }
            }
        }
        tickEmbeddedHumanCheck();
        if (!hc) {
            if (hasNotifiedHumanCheck || (window.__latestHumanCheck && Date.now() - (window.__latestHumanCheck.timestamp || 0) > 3000)) {
                window.__latestHumanCheck = null;
                embeddedHumanCheckAttempt = '';
                embeddedHumanCheckPending = null;
                try { localStorage.removeItem(humanCheckAttemptKey); } catch (_) {}
            }
            hasNotifiedHumanCheck = false;
            humanCheckOpenedAt = 0;
            unconfirmedRetryCount = 0;
            return;
        }
        const now = Date.now();
        if (!hasNotifiedHumanCheck) {
            hasNotifiedHumanCheck = true;
            humanCheckOpenedAt = now;
            lastInGameAlarmAt = now;
            unconfirmedRetryCount = 0;
            const promptEl = hc.querySelector('.human-check-prompt');
            const prompt = (promptEl ? promptEl.innerText : '').trim();
            console.log('[PmheeAether Anti-Bot] 🚨 ตรวจพบเช็คผู้เล่น (Human Check):', prompt);
            window.playInGameHumanCheckBeep(false);
            if (window.showHudToast) {
                window.showHudToast('🚨 ตรวจพบเช็คผู้เล่น! กำลังตรวจคำตอบจากฐานข้อมูลในบอท...', 'warning', 6000);
            }
        } else if (humanCheckOpenedAt > 0 && now - humanCheckOpenedAt >= 4000 && now - lastInGameAlarmAt >= 4000) {
            lastInGameAlarmAt = now;
            window.playInGameHumanCheckBeep(true);
        }
    }
    window.triggerHumanCheckTickNow = checkHumanCheckStatus;

    // Attach periodic watcher for human check detection
    setInterval(checkHumanCheckStatus, 650);

    // ==========================================
    // AUTO JOB CHANGE ENGINE (Valkyrie n5 @ Solhaven)
    // ==========================================
    // Put back the farm map that the walk to Valkyrie replaced with the capital
    // Systems that need the character in the capital right now (job change, weight scrolls, event pet, gear
    // set...). The farm map is put back only when the last of them is done — before, the first one to finish
    // sent the character back to the farm while another was still at work in town.
    const TOWN_NEEDS_KEY = 'pelican_town_needs';
    const townNeeds = () => { try { return JSON.parse(localStorage.getItem(TOWN_NEEDS_KEY) || '{}') || {}; } catch (e) { return {}; } };
    const saveTownNeeds = n => { try { localStorage.setItem(TOWN_NEEDS_KEY, JSON.stringify(n)); } catch (e) {} };
    window.needTown = function (who, minutes = 15) {
        const n = townNeeds();
        n[who] = Date.now() + minutes * 60000;
        saveTownNeeds(n);
    };
    window.otherTownNeeds = function (who) {
        const n = townNeeds(), now = Date.now();
        return Object.keys(n).filter(k => k !== who && n[k] > now);
    };
    function restoreFarmMapAfterJobChange(who = 'job') {
        const n = townNeeds(), now = Date.now();
        delete n[who];
        Object.keys(n).forEach(k => { if (!(n[k] > now)) delete n[k]; });
        saveTownNeeds(n);
        window.__lastTownTripAt = now;
        window.__townArrivalExplained = true;
        window.__unexpectedTownTicks = 0;
        if (Object.keys(n).length) {
            console.log(`%c[PmheeAether Plan] 🏛️ ${who} เสร็จแล้ว แต่ยังมีงานในเมือง (${Object.keys(n).join(', ')}) -> ยังไม่กลับแมพฟาร์ม`, 'color: #94a3b8;');
            return;
        }
        let map = null;
        try { map = localStorage.getItem('pelican_job_return_map'); localStorage.removeItem('pelican_job_return_map'); } catch (e) {}
        if (window.__planScriptEnabled && window.__currentScriptPlan && typeof window.planMapForNow === 'function') {
            map = window.planMapForNow() || map;
        }
        if (!map || !/เมืองหลวง|โซลเฮเวน/.test(window.__targetFarmMap || '')) return;
        console.log(`%c[PmheeAether Plan] 🗺️ คืนแมพฟาร์มเดิม "${map}" หลังจบงานในเมือง (${who})`, 'color: #38bdf8;');
        window.__targetFarmMap = map;
        try { localStorage.setItem('pelican_farm_map', map); } catch (e) {}
        const sel = document.getElementById('p-target-map-select');
        if (sel) sel.value = map;
        if (window.__isNavigating) {
            if (typeof stopArrivalWatcher === 'function') stopArrivalWatcher();
            window.__isNavigating = false;
            window.__navWalkOnly = false;
        }
        if (window.__isBotRunning && typeof isCharacterInCity === 'function' && !isCharacterInCity() && typeof window.walkToTargetMap === 'function') {
            window.walkToTargetMap(map, true);
        }
    }

    window.restoreFarmMapAfterJobChange = restoreFarmMapAfterJobChange;
    window.getCurrentMapName = getCurrentMapName;

    window.executeAutoJobChange = async function(targetClass) {
        if (!window.__planScriptEnabled) return false;
        if (!targetClass) return false;
        const targetClean = targetClass.trim().toLowerCase();

        const char = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        const curClass = (char.classId || char.class || window.__charClass || '').toLowerCase();
        const baseLv = char.baseLevel || char.level || 1;

        // 1. Already this class (or a later class of the same line): nothing to do
        if (planClassLineage(curClass).includes(targetClean)) {
            restoreFarmMapAfterJobChange('job');
            return true;
        }

        // 2. ถ้าเปลี่ยนอาชีพเป็นอาชีพนี้แล้ว ให้ผ่านทันที
        if (curClass.includes(targetClean)) {
            console.log(`%c[PmheeAether Plan] ✅ ตัวละครเป็นอาชีพ "${targetClass}" เรียบร้อยแล้ว`, 'color: #22c55e; font-weight: bold;');
            return true;
        }

        // 3. ตรวจสอบเงื่อนไข Job Level
        const curJob = char.jobLevel || 1;
        if (curJob < 10 && curClass === 'novice') {
            console.warn(`[PmheeAether Plan] ⚠️ Job Level ยังไม่ถึง 10 (ปัจจุบัน: Lv.${curJob}/10) ยังไม่สามารถเปลี่ยนอาชีพได้`);
            return false;
        }

        // 4. หากกำลังเดินทางกลับแมพฟาร์มผ่าน Alice Service ห้ามแทรกแซง
        if (window.__isWalkingToMap) {
            return false;
        }
        // Job change under way: the farm watchdog must not walk the character out of the capital meanwhile
        window.__planJobChangeHoldUntil = Date.now() + 30000; if (typeof window.needTown === 'function') window.needTown('job');

        // 5. ตรวจสอบแมพ: ต้องอยู่ที่เมืองหลวงโซลเฮเวน
        const curMap = (typeof getCurrentMapName === 'function') ? getCurrentMapName() : (char.map || '');
        if (!curMap.includes('โซลเฮเวน') && !curMap.includes('เมืองหลวง')) {
            console.log(`%c[PmheeAether Plan] 🏛️ ตัวละครไม่ได้อยู่ในเมืองหลวง -> กำลังเดินทางกลับเมืองหลวงโซลเฮเวน...`, 'color: #38bdf8;');
            if (typeof window.walkToTargetMap === 'function') {
                // walkToTargetMap() also makes the capital the farm map: remember the real one to restore it
                const farm = window.__targetFarmMap || '';
                if (farm && !/เมืองหลวง|โซลเฮเวน/.test(farm)) {
                    try { localStorage.setItem('pelican_job_return_map', farm); } catch (e) {}
                }
                window.planTripToCapital('job');
            }
            return false;
        }

        // 6. Valkyrie — key จากชื่อ NPC ในแมพ (เกมเพิ่ม NPC แล้ว key เลื่อน: เดิม n5 ตอนนี้ n6).
        // ไม่ต้องเดินเอง: npc_talk จากที่ไหนก็ได้ในแมพ เซิร์ฟเวอร์จะเดินตัวละครไปหา NPC แล้วเปิดบทสนทนาให้
        // (เกมเองก็ทำแบบนี้) — การ move_to เองเคยค้างเมื่อทางเดินอ้อมแม่น้ำ/สะพาน
        const valk = window.getValkyrieNpc();
        const pos = window.__currentPos || { x: 0, y: 0 };
        const dist = Math.round(Math.hypot(pos.x - valk.x, pos.y - valk.y));

        // 5. หากอยู่ใกล้แล้ว คุยกับ Valkyrie (หา key จากชื่อ NPC) แล้วไล่ตอบทีละหน้า
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (!room) {
            console.warn('[PmheeAether Plan] ⚠️ ไม่พบ Colyseus Room connection');
            return false;
        }
        if ((window.__jobChangeBackoffUntil || 0) > Date.now()) return false;

        const sleep = ms => new Promise(r => setTimeout(r, ms));
        const readDialog = () => {
            const d = document.querySelector('.npc-dialog');
            if (!d) return null;
            const body = d.querySelector('.npc-body p');
            const btns = Array.from(d.querySelectorAll('.npc-options button'));
            return {
                text: ((body ? body.innerText : d.innerText) || '').trim(),
                options: btns.map(b => (b.innerText || '').replace(/^\s*\d+\s*/, '').trim())
            };
        };
        const sig = dl => dl ? dl.text + '|' + dl.options.join('|') : '';
        // Wait until a dialog different from `prev` is shown (the server answers each option with a new page)
        const waitDialog = async (prev, ms) => {
            const end = Date.now() + ms;
            while (Date.now() < end) {
                const dl = readDialog();
                if (dl && dl.options.length && sig(dl) !== prev) return dl;
                await sleep(150);
            }
            return readDialog();
        };
        const classNow = () => String(((typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {}).classId || '').toLowerCase();

        const thaiName = (PLAN_CLASS_TREE[targetClean] || [])[0] || '';
        const classWords = {
            archer: ['archer', 'ธนู'], mage: ['mage', 'เวท'], swordsman: ['swordsman', 'sword', 'ดาบ'],
            thief: ['thief', 'โจร'], acolyte: ['acolyte', 'บวช'], merchant: ['merchant', 'ค้า']
        }[targetClean] || [];
        const isTarget = o => {
            const t = o.toLowerCase();
            return t.includes(targetClean) || (thaiName && o.includes(thaiName)) || classWords.some(w => t.includes(w));
        };
        // An option naming any class is never a plain 'continue' button (picking the wrong class can't be undone)
        const mentionsClass = o => Object.keys(PLAN_CLASS_TREE).some(id => o.toLowerCase().includes(id) || (PLAN_CLASS_TREE[id][0] && o.includes(PLAN_CLASS_TREE[id][0])));
        const isProceed = o => /พร้อมเปลี่ยนอาชีพ|ยืนยัน|ตกลง|ใช่|เปลี่ยนอาชีพ|confirm|^yes/i.test(o) && !/ไว้ก่อน|ยกเลิก|ไม่/.test(o) && !mentionsClass(o);

        // Close through the dialog's own ✕ (room 'npc_close' alone leaves the dialog on screen)
        const closeDialog = () => {
            const x = document.querySelector('.npc-dialog .win-close');
            if (x) x.click(); else room.send('npc_close', {});
        };

        console.log(`%c[PmheeAether Plan] 💬 พูดคุยกับ NPC Valkyrie (${valk.key}, ห่าง ${dist}px — เซิร์ฟเวอร์เดินไปให้)...`, 'color: #a855f7; font-weight: bold;');
        room.send('npc_talk', { npcKey: valk.key });
        window.__planJobChangeHoldUntil = Date.now() + 60000; if (typeof window.needTown === 'function') window.needTown('job');
        let dl = await waitDialog('', 40000);   // includes the walk over (far side of the river takes a while)
        if (!dl) console.warn(`[PmheeAether Plan] ⚠️ คุยกับ Valkyrie แล้วหน้าต่างไม่ขึ้น (ห่าง ${dist}px)`);

        for (let step = 0; step < 6 && dl; step++) {
            console.log(`[PmheeAether Plan] 📜 Valkyrie: "${dl.text.slice(0, 80)}" | ตัวเลือก: ${dl.options.map((o, i) => `${i}:${o}`).join(' / ')}`);
            if (/ยังเร็วไป|กลับมาเมื่อถึง|ยังไม่ถึง|ไม่สามารถ/.test(dl.text) && !dl.options.some(isTarget)) {
                console.warn('[PmheeAether Plan] ⚠️ Valkyrie แจ้งว่าเงื่อนไขยังไม่ครบ: ' + dl.text.replace(/\n+/g, ' '));
                closeDialog();
                window.__jobChangeBackoffUntil = Date.now() + 60 * 1000;
                return false;
            }

            let idx = dl.options.findIndex(isTarget);
            if (idx < 0) {
                // Class list without recognisable names: same count as the game's job options -> same order
                const opts = planJobOptions(char);
                if (opts.length > 1 && !dl.options.some(mentionsClass) && (dl.options.length === opts.length || dl.options.length === opts.length + 1)) idx = opts.indexOf(targetClean);
            }
            const picked = idx >= 0;
            if (idx < 0) idx = dl.options.findIndex(isProceed);
            if (idx < 0) break;

            console.log(`%c[PmheeAether Plan] ➡️ เลือก "${dl.options[idx]}" (npc_option ${idx})${picked ? ` — อาชีพเป้าหมาย ${targetClass}` : ''}`, 'color: #38bdf8;');
            const before = sig(dl);
            room.send('npc_option', { index: idx });

            // Done as soon as the class actually changed
            for (let t = 0; t < 10; t++) {
                await sleep(200);
                if (planClassLineage(classNow()).includes(targetClean)) {
                    console.log(`%c[PmheeAether Plan] 🎉 เปลี่ยนอาชีพเป็น "${targetClass}" สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
                    if (readDialog()) closeDialog();
                    window.__jobChangeFails = 0;
                    window.__planJobChangeHoldUntil = 0;
                    restoreFarmMapAfterJobChange('job');
                    return true;
                }
            }
            dl = await waitDialog(before, 3000);
            if (dl && sig(dl) === before) break;   // the page didn't move on
        }

        // Didn't work: close the dialog and slow down so it doesn't loop every few seconds
        if (readDialog()) closeDialog();
        window.__jobChangeFails = (window.__jobChangeFails || 0) + 1;
        const quick = window.__jobChangeFails < 3;
        const waitSec = quick ? 15 : Math.min(300, 20 * window.__jobChangeFails);
        window.__jobChangeBackoffUntil = Date.now() + waitSec * 1000;
        if (quick) {
            // stay in the capital for the next try (walking out and back in is what made it loop)
            window.__planJobChangeHoldUntil = Date.now() + (waitSec + 30) * 1000;
        } else {
            window.__planJobChangeHoldUntil = 0;
            restoreFarmMapAfterJobChange('job');
        }
        console.warn(`[PmheeAether Plan] ⚠️ เปลี่ยนอาชีพเป็น "${targetClass}" ยังไม่สำเร็จ (ครั้งที่ ${window.__jobChangeFails}) — จะลองใหม่ใน ${waitSec} วิ (ดูตัวเลือกของ Valkyrie ใน log ด้านบน)`);
        return false;
    };



