    window.sendNpcWarp = function(mapId) {
        if (!mapId) return;
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (room && typeof room.send === 'function') {
            room.send('npc_warp', { mapId });
            console.log(`%c[PmheeAether Warp] ⚡ ยิง Packet 'npc_warp' (MapId: "${mapId}") สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
            return;
        }
        if (!window.__gameSocket || window.__gameSocket.readyState !== 1) return;
        const token = window.__lastMoveToken || [0xd4, 0x72, 0x40];
        const prefix = [0x0D, 0xA8, 0x6E, 0x70, 0x63, 0x5F, 0x77, 0x61, 0x72, 0x70];
        const mapBytes = Array.from(mapId).map(c => c.charCodeAt(0));
        const suffix = [
            0x91, 0xA5, 0x6D, 0x61, 0x70, 0x49, 0x64,
            0xA0 + mapBytes.length, ...mapBytes
        ];
        const buf = new Uint8Array(prefix.length + token.length + suffix.length);
        buf.set(prefix, 0);
        buf.set(token, prefix.length);
        buf.set(suffix, prefix.length + token.length);
        window.__gameSocket.send(buf.buffer);
        console.log(`%c[PmheeAether Warp] ⚡ ยิง Packet 'npc_warp' (MapId: "${mapId}") สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
    };

    window.getCharacterHpSp = function() {
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : window.__gameRoom;
        const me = (room && room.state && room.state.players && typeof room.state.players.get === 'function')
            ? room.state.players.get(room.sessionId)
            : null;
        const liveChar = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        const derived = (liveChar && liveChar.derived && typeof liveChar.derived === 'object') ? liveChar.derived : {};

        let domHp = null, domMaxHp = null, domSp = null, domMaxSp = null;
        try {
            const hpBar = document.querySelector('.bar-fill.bar-hp')?.closest('.bar');
            const hpText = hpBar?.querySelector('.bar-num')?.innerText?.trim() || '';
            const mHp = hpText.match(/(\d+)\s*\/\s*(\d+)/);
            if (mHp) { domHp = Number(mHp[1]); domMaxHp = Number(mHp[2]); }
            const spBar = document.querySelector('.bar-fill.bar-sp')?.closest('.bar');
            const spText = spBar?.querySelector('.bar-num')?.innerText?.trim() || '';
            const mSp = spText.match(/(\d+)\s*\/\s*(\d+)/);
            if (mSp) { domSp = Number(mSp[1]); domMaxSp = Number(mSp[2]); }
        } catch (_) {}

        const maxHp = (me && typeof me.maxHp === 'number' && me.maxHp > 0) ? me.maxHp
            : (typeof derived.maxHp === 'number' && derived.maxHp > 0) ? derived.maxHp
            : (typeof liveChar.maxHp === 'number' && liveChar.maxHp > 0) ? liveChar.maxHp
            : (typeof domMaxHp === 'number' && domMaxHp > 0) ? domMaxHp : 0;

        const hp = (me && typeof me.hp === 'number' && me.hp >= 0) ? me.hp
            : (typeof domHp === 'number' && domHp >= 0) ? domHp
            : (typeof liveChar.hp === 'number' && liveChar.hp >= 0) ? liveChar.hp : maxHp;

        const maxSp = (me && typeof me.maxSp === 'number' && me.maxSp > 0) ? me.maxSp
            : (typeof derived.maxSp === 'number' && derived.maxSp > 0) ? derived.maxSp
            : (typeof liveChar.maxSp === 'number' && liveChar.maxSp > 0) ? liveChar.maxSp
            : (typeof domMaxSp === 'number' && domMaxSp > 0) ? domMaxSp : 0;

        const sp = (me && typeof me.sp === 'number' && me.sp >= 0) ? me.sp
            : (typeof domSp === 'number' && domSp >= 0) ? domSp
            : (typeof liveChar.sp === 'number' && liveChar.sp >= 0) ? liveChar.sp : maxSp;

        const needsHeal = (maxHp > 0 && hp < maxHp * 0.99) || (maxSp > 0 && sp < maxSp * 0.98) || maxHp === 0;
        return { hp, maxHp, sp, maxSp, needsHeal };
    };

    window.openAliceWarpService = function(callback, opts = {}) {
        const healOnly = !!(opts && opts.healOnly);
        // ล้างหน้าต่างร้านค้าหรือ dialog ค้างเก่าก่อนเริ่มคุยกับ Alice เสมอ
        if (typeof window.closeShopUI === 'function') {
            window.closeShopUI();
        }
        // Alice only stands in the capital: elsewhere use the world map (walking) instead of talking to a guess
        if (typeof isCharacterInCity === 'function' && !isCharacterInCity()) {
            console.log('%c[PmheeAether Warp] 🗺️ ไม่ได้อยู่ในเมืองหลวง (ไม่มี Alice ในแมพนี้) -> เปิดแผนที่โลกเดินไปแทน', 'color: #f59e0b;');
            if (healOnly) {
                if (callback) callback();
            } else {
                openWorldMap(() => { if (callback) callback(); });
            }
            return;
        }

        // ตรวจสอบว่าหน้าต่างบทสนทนาของ Alice เปิดอยู่บนจอหรือไม่
        function isAliceDialogOpen() {
            const dlg = document.querySelector('.npc-dialog');
            if (dlg) {
                const txt = (dlg.innerText || dlg.textContent || '').trim();
                if (txt.includes('Alice') || txt.includes('อลิซ') || txt.includes('ยินดีต้อนรับสู่เมืองหลวง') || txt.includes('ให้ฉันช่วยอะไรดี') || txt.includes('บันทึกจุดเกิดที่นี่') || txt.includes('วาร์ป (เลือกจากแผนที่โลก)') || txt.includes('ขอรักษาหน่อย')) {
                    return true;
                }
            }
            const candidates = Array.from(document.querySelectorAll('.npc-dialog, [class*="npc-dialog"]')).filter(el => {
                if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal') || el.closest('#pelican-log')) return false;
                const txt = (el.innerText || el.textContent || '').trim();
                return (txt.includes('ยินดีต้อนรับสู่เมืองหลวง') || txt.includes('ให้ฉันช่วยอะไรดี') || txt.includes('บันทึกจุดเกิดที่นี่') || txt.includes('วาร์ป (เลือกจากแผนที่โลก)') || txt.includes('ขอรักษาหน่อย'));
            });
            return candidates.length > 0;
        }

        // ตรวจสอบว่าหน้าต่างแผนที่วาร์ปของ Alice หรือหน้าต่าง WorldMap เปิดอยู่แล้วหรือไม่
        function isAliceMapWindowOpen(requireWarpMode = false) {
            const stage = document.querySelector('.worldmap-stage, .worldmap-body, .worldmap-window, [class*="worldmap"]');
            if (requireWarpMode) {
                if (!stage) return false;
                if (document.querySelector('.worldmap-warp')) return true;
                const warpBtn = Array.from(stage.querySelectorAll('button')).find(b => {
                    const txt = (b.innerText || b.textContent || '').trim();
                    return txt.includes('วาร์ปไปที่นี่');
                });
                return !!warpBtn;
            }
            if (stage) return true;
            if (typeof isWorldMapOpen === 'function' && isWorldMapOpen()) return true;
            const warpBtn = Array.from(document.querySelectorAll('button, [role="button"], div')).find(b => {
                if (b.closest('#pelican-hud') || b.closest('#pelican-data-modal')) return false;
                const txt = (b.innerText || b.textContent || '').trim();
                return (txt.includes('วาร์ปไปที่นี่') || txt.includes('เดินไปที่นี่')) && b.offsetWidth > 0;
            });
            return !!warpBtn;
        }

        // ฟังก์ชันช่วยค้นหาปุ่มตัวเลือกในหน้าต่างสนทนาตามคีย์เวิร์ด (เฉพาะปุ่มใน .npc-options เท่านั้น ห้ามจับทั้งกล่อง .npc-dialog)
        function findDialogOption(keywords) {
            const optionButtons = Array.from(document.querySelectorAll('.npc-dialog .npc-options button, .npc-options button'));
            for (const btn of optionButtons) {
                if (btn.closest('#pelican-hud') || btn.closest('#pelican-data-modal') || btn.closest('#pelican-log')) continue;
                const txt = (btn.innerText || btn.textContent || '').replace(/\s+/g, ' ').trim();
                if (!txt) continue;
                const matches = keywords.every(kw => txt.includes(kw)) || (keywords.length > 1 && keywords.some(kw => txt.includes(kw) && kw.length >= 3));
                if (matches) return btn;
            }
            return null;
        }

        function getLivePlayerPos() {
            const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : window.__gameRoom;
            const me = (room && room.state && room.state.players && typeof room.state.players.get === 'function')
                ? room.state.players.get(room.sessionId)
                : null;
            if (me && typeof me.x === 'number' && typeof me.y === 'number' && (me.x !== 0 || me.y !== 0)) {
                return { x: me.x, y: me.y };
            }
            return window.__currentPos || { x: 0, y: 0 };
        }

        const initHpSp = (typeof window.getCharacterHpSp === 'function')
            ? window.getCharacterHpSp()
            : { hp: 0, maxHp: 0, sp: 0, maxSp: 0, needsHeal: true };

        if (!healOnly && !initHpSp.needsHeal && isAliceMapWindowOpen(true)) {
            console.log('%c[PmheeAether Warp] 🗺️ เลือด/มานาเต็มแล้ว และหน้าต่าง Alice Warp Service เปิดอยู่แล้ว ทำงานต่อได้ทันที', 'color: #22c55e;');
            if (callback) callback();
            return;
        }
        // ถ้าแผนที่โลกเปิดค้างอยู่ (และต้องฮีลก่อน หรือไม่ใช่โหมดวาร์ปของ Alice) ให้ปิดแผนที่ก่อนเพื่อคุยกับ Alice
        const plainMapClose = document.querySelector('.worldmap-window .win-close');
        if (plainMapClose && (healOnly || initHpSp.needsHeal || !document.querySelector('.worldmap-warp'))) {
            try { plainMapClose.click(); } catch (e) {}
        }

        console.log(`%c[PmheeAether Warp] 🧙 กำลังเดินทางไปคุยกับ NPC Alice (${healOnly ? 'เพื่อฮีลเลือด/มานา' : 'เพื่อฮีลและเปิดวาร์ปเกต'})...`, 'color: #eab308; font-weight: bold;');

        // ฟังก์ชันช่วยค้นหาและคลิกป้ายชื่อ NPC Alice บนจอเกม (เฉพาะตอนที่ dialog ยังไม่เปิด)
        function findAliceElement() {
            if (isAliceDialogOpen()) return null;

            const candidates = Array.from(document.querySelectorAll('*')).filter(el => {
                if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal') || el.closest('#pelican-log')) return false;
                if (el.closest('.dialog, .modal, [class*="dialog"], [class*="modal"]')) return false;
                const txt = (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim();
                if (!txt.includes('Alice')) return false;
                if (txt.includes('ยินดีต้อนรับ') || txt.includes('ช่วยอะไรดี') || txt.includes('จุดเกิด')) return false;
                const rect = el.getBoundingClientRect();
                return rect.width >= 15 && rect.width <= 350 && rect.height >= 10 && rect.height <= 85;
            });
            if (candidates.length > 0) {
                candidates.sort((a, b) => {
                    const ra = a.getBoundingClientRect();
                    const rb = b.getBoundingClientRect();
                    return (ra.width * ra.height) - (rb.width * rb.height);
                });
                return candidates[0];
            }
            return null;
        }

        function clickAliceOnScreen() {
            if (isAliceDialogOpen()) return false;

            const aliceLabel = findAliceElement();
            if (aliceLabel) {
                console.log('%c[PmheeAether Warp] 🎯 พบคลิกป้ายชื่อ "Alice Service" บนจอเพื่อให้ตัวละครเดินไปหา...', 'color: #38bdf8; font-weight: bold;');
                triggerClick(aliceLabel);

                const rect = aliceLabel.getBoundingClientRect();
                const canvas = document.querySelector('canvas');
                if (canvas) {
                    const clientX = rect.left + rect.width / 2;
                    const clientY = rect.top + rect.height / 2;
                    const opts = { bubbles: true, cancelable: true, clientX, clientY, buttons: 1 };
                    try { canvas.dispatchEvent(new PointerEvent('pointerdown', opts)); } catch(e) {}
                    try { canvas.dispatchEvent(new MouseEvent('mousedown', opts)); } catch(e) {}
                    try { canvas.dispatchEvent(new PointerEvent('pointerup', opts)); } catch(e) {}
                    try { canvas.dispatchEvent(new MouseEvent('mouseup', opts)); } catch(e) {}
                    try { canvas.dispatchEvent(new MouseEvent('click', opts)); } catch(e) {}
                }
                return true;
            }
            return false;
        }

        const aliceNpc = ((typeof window.getAliceNpc === 'function') ? window.getAliceNpc() : null) || { key: null, x: 0, y: 0 };
        const aliceKey = aliceNpc.key;

        // 1. ตรวจสอบระยะห่าง ถ้าตัวละครอยู่ไกลจาก Alice ให้เดินเข้าหาก่อน (ไม่ส่ง npc_talk ตอนอยู่ไกลเกิน 115px เพราะเซิร์ฟเวอร์จะเพิกเฉย)
        const startPos = getLivePlayerPos();
        const distToAlice = (startPos.x && aliceNpc.x) ? Math.hypot(startPos.x - aliceNpc.x, startPos.y - aliceNpc.y) : 0;
        let lastMoveSentAt = 0;
        let lastTalkSentAt = 0;
        if (distToAlice > 110) {
            console.log(`%c[PmheeAether Warp] 🚶 ตัวละครอยู่ห่างจาก Alice Service (${Math.round(distToAlice)}px) -> กำลังเดินไปหาที่ (${aliceNpc.x}, ${aliceNpc.y})...`, 'color: #38bdf8;');
            const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
            if (room && aliceNpc.x && aliceNpc.y) {
                room.send('move_to', { x: aliceNpc.x, y: aliceNpc.y });
                lastMoveSentAt = Date.now();
            }
        } else {
            clickAliceOnScreen();
            if (aliceKey) {
                window.sendRemoteNpcTalk(aliceKey);
                lastTalkSentAt = Date.now();
            }
        }

        let attempts = 0;
        let lastPos = { x: 0, y: 0 };
        let stillCount = 0;
        let hasHealed = false;
        let healRequestedAt = 0;
        let hasRequestedMap = false;
        let lastActionTime = 0;
        const maxAttempts = 45; // 45 * 450ms ≈ 20.25 วินาที ให้เวลาเดินข้ามเมืองจากร้านค้ามาหา Alice อย่างสบายๆ

        if (window.__alicePollInterval) {
            clearInterval(window.__alicePollInterval);
            window.__alicePollInterval = null;
        }

        window.__alicePollInterval = setInterval(() => {
            if (!window.__isBotRunning && !window.__isManualWarping) {
                clearInterval(window.__alicePollInterval);
                window.__alicePollInterval = null;
                return;
            }

            attempts++;

            if (typeof isCharacterDead === 'function' && isCharacterDead()) {
                clearInterval(window.__alicePollInterval);
                window.__alicePollInterval = null;
                return;
            }

            // Left the capital (the warp went through, or teleported away): this loop is done
            if (typeof isCharacterInCity === 'function' && !isCharacterInCity()) {
                clearInterval(window.__alicePollInterval);
                window.__alicePollInterval = null;
                console.log('%c[PmheeAether Warp] ✅ ออกจากเมืองหลวงแล้ว -> หยุดเรียก Alice', 'color: #94a3b8;');
                return;
            }

            const dialogOpen = isAliceDialogOpen();
            const now = Date.now();
            const curAlice = ((typeof window.getAliceNpc === 'function') ? window.getAliceNpc() : null) || aliceNpc;
            const currentAliceKey = curAlice.key || aliceKey;
            const curHpSp = (typeof window.getCharacterHpSp === 'function')
                ? window.getCharacterHpSp()
                : { hp: 0, maxHp: 0, sp: 0, maxSp: 0, needsHeal: true };
            const needsHealNow = healOnly || curHpSp.needsHeal;

            // ถ้าเพิ่งส่งคำสั่งฮีลไปแล้ว รอตรวจว่าฮีลสำเร็จหรือหน้าต่างสนทนาถูกเซิร์ฟเวอร์ปิดลงก่อนค่อยเปิดคุยใหม่เพื่อกดวาร์ป
            if (healRequestedAt > 0 && !hasHealed) {
                const hpFull = curHpSp.maxHp > 0 && curHpSp.hp >= curHpSp.maxHp * 0.99 && (curHpSp.maxSp === 0 || curHpSp.sp >= curHpSp.maxSp * 0.98);
                if (!dialogOpen || hpFull || (now - healRequestedAt >= 1100)) {
                    hasHealed = true;
                    console.log(`%c[PmheeAether Warp] ✨ ฮีลฟื้นฟูเลือด/มานากับ NPC Alice สำเร็จ! (HP: ${curHpSp.hp}/${curHpSp.maxHp}, SP: ${curHpSp.sp}/${curHpSp.maxSp})`, 'color: #22c55e; font-weight: bold;');
                    if (healOnly) {
                        clearInterval(window.__alicePollInterval);
                        window.__alicePollInterval = null;
                        if (dialogOpen && typeof window.sendNpcClose === 'function') window.sendNpcClose();
                        setTimeout(() => { if (callback) callback(); }, 250);
                        return;
                    }
                    if (!dialogOpen) {
                        if (currentAliceKey) {
                            window.sendRemoteNpcTalk(currentAliceKey);
                            lastTalkSentAt = now;
                            lastActionTime = now;
                        }
                        return;
                    }
                } else {
                    return;
                }
            }

            // ถ้าหน้าต่างแผนที่วาร์ปเปิดแล้ว (และผ่านการเช็ก/ฮีลเรียบร้อยแล้ว) ให้ตัดจบและทำงานต่อทันที
            if (!healOnly && (hasHealed || !needsHealNow) && (isAliceMapWindowOpen(true) || (hasRequestedMap && isAliceMapWindowOpen()))) {
                clearInterval(window.__alicePollInterval);
                window.__alicePollInterval = null;
                console.log('%c[PmheeAether Warp] 🗺️ หน้าต่างแผนที่ Alice Warp Service พร้อมใช้งาน!', 'color: #00ffcc; font-weight: bold;');
                setTimeout(() => { if (callback) callback(); }, 300);
                return;
            }

            // =========================================================
            // กรณีที่ 1: หน้าต่างสนทนา Alice เปิดอยู่บนจอแล้ว
            // =========================================================
            if (dialogOpen) {
                const optionButtons = Array.from(document.querySelectorAll('.npc-dialog .npc-options button, .npc-options button')).filter(btn => {
                    return !btn.closest('#pelican-hud') && !btn.closest('#pelican-data-modal') && !btn.closest('#pelican-log');
                });
                const healOption = findDialogOption(['ขอรักษาหน่อย']) || findDialogOption(['รักษา']) || findDialogOption(['ฟื้นฟู']);
                const warpOption = findDialogOption(['วาร์ป', 'แผนที่โลก']) || findDialogOption(['วาร์ป']) || findDialogOption(['Alice Warp']);

                // สเต็ป 1: กดฮีลฟื้นฟูเลือด/มานาก่อนเสมอเมื่อเลือด/มานายังไม่เต็ม (การฮีลจะปิด dialog ทันที แล้วลูปจะเปิดคุยใหม่เพื่อกดวาร์ป)
                if (!hasHealed && needsHealNow) {
                    const healIdx = (healOption && optionButtons.indexOf(healOption) >= 0) ? optionButtons.indexOf(healOption) : 3;
                    console.log(`%c[PmheeAether Warp] 💖 ฮีลฟื้นฟูเลือด/มานากับ NPC Alice ก่อนวาร์ป (HP: ${curHpSp.hp}/${curHpSp.maxHp}, SP: ${curHpSp.sp}/${curHpSp.maxSp}, option: ${healIdx})...`, 'color: #ec4899; font-weight: bold;');
                    const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
                    if (room && typeof room.send === 'function') {
                        if (healIdx === 3 && typeof window.sendRemoteNpcHeal === 'function') {
                            window.sendRemoteNpcHeal();
                        } else {
                            window.sendRemoteNpcOption(healIdx);
                        }
                    } else if (healOption) {
                        triggerClick(healOption);
                    } else if (typeof window.sendRemoteNpcHeal === 'function') {
                        window.sendRemoteNpcHeal();
                    } else {
                        window.sendRemoteNpcOption(healIdx);
                    }
                    healRequestedAt = now;
                    lastActionTime = now;
                    return;
                }

                hasHealed = true;
                if (healOnly) {
                    clearInterval(window.__alicePollInterval);
                    window.__alicePollInterval = null;
                    if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
                    setTimeout(() => { if (callback) callback(); }, 250);
                    return;
                }

                // สเต็ป 2: เลือกเปิดแผนที่วาร์ป (Option 2 / index: 1) ทันทีเมื่อฮีลเสร็จแล้ว
                if (!hasRequestedMap || (now - lastActionTime > 1200)) {
                    const warpIdx = (warpOption && optionButtons.indexOf(warpOption) >= 0) ? optionButtons.indexOf(warpOption) : 1;
                    const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
                    console.log(`%c[PmheeAether Warp] 🗺️ ส่ง Packet เลือก Alice Warp Service (index: ${warpIdx})...`, 'color: #38bdf8; font-weight: bold;');
                    if (room && typeof room.send === 'function') {
                        window.sendRemoteNpcOption(warpIdx);
                    } else if (warpOption) {
                        triggerClick(warpOption);
                    } else {
                        window.sendRemoteNpcOption(warpIdx);
                    }
                    hasRequestedMap = true;
                    lastActionTime = now;
                }

                // อยู่ใน dialog: ห้ามคลิกเดินหรือส่งคำสั่งคุยซ้ำเด็ดขาด
                return;
            }

            // ถ้าเพิ่งกดฮีลไปแล้วหน้าต่างสนทนาถูกปิดลง ให้เปิดคุยกับ Alice ใหม่ทันทีเพื่อกดวาร์ป
            if (hasHealed && !hasRequestedMap && (now - lastTalkSentAt > 650)) {
                if (currentAliceKey) {
                    window.sendRemoteNpcTalk(currentAliceKey);
                    lastTalkSentAt = now;
                    lastActionTime = now;
                }
                return;
            }

            // =========================================================
            // กรณีที่ 2: หน้าต่างสนทนายังไม่เปิด (ตัวละครกำลังเดินข้ามเมืองไปหา Alice)
            // =========================================================
            const curPos = getLivePlayerPos();
            const isStationary = (curPos.x === lastPos.x && curPos.y === lastPos.y && curPos.x !== 0);
            lastPos = { x: curPos.x, y: curPos.y };
            if (isStationary) stillCount++; else stillCount = 0;

            const curDist = (curPos.x && curAlice.x) ? Math.hypot(curPos.x - curAlice.x, curPos.y - curAlice.y) : 0;
            if (curDist > 115) {
                if (now - lastMoveSentAt > 1800) {
                    if (typeof window.closeShopUI === 'function') window.closeShopUI();
                    const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
                    if (room && curAlice.x && curAlice.y) {
                        room.send('move_to', { x: curAlice.x, y: curAlice.y });
                        lastMoveSentAt = now;
                    }
                }
            } else if (now - lastTalkSentAt > 750) {
                if (typeof window.closeShopUI === 'function') window.closeShopUI();
                clickAliceOnScreen();
                if (currentAliceKey) {
                    window.sendRemoteNpcTalk(currentAliceKey);
                    lastTalkSentAt = now;
                }
            }

            // Timeout: ให้เวลาเดินอย่างน้อย ~20 วินาที (45 รอบ) และถ้าตัวละครกำลังเดินอยู่ ให้รอต่อไปห้ามตัดจบ
            const isStillMoving = !isStationary && curPos.x !== 0;
            if (attempts >= maxAttempts && !isStillMoving) {
                clearInterval(window.__alicePollInterval);
                window.__alicePollInterval = null;
                console.warn('%c[PmheeAether Warp] ⚠️ หมดเวลารอ Alice Warp Service -> สลับไปเปิดแผนที่โลกเพื่อเดินเท้าสำรอง...', 'color: #f59e0b; font-weight: bold;');
                if (healOnly) {
                    if (callback) callback();
                } else {
                    openWorldMap(() => {
                        if (callback) callback();
                    });
                }
            }
        }, 450);
    };

    window.warpToMap = function(targetMapNameOrId) {
        const mapId = MAP_NAME_TO_ID[targetMapNameOrId] || targetMapNameOrId;
        console.log(`%c[PmheeAether Warp] 🚀 กำลังวาร์ปด่วนไปแมพ: "${targetMapNameOrId}" (${mapId})...`, 'color: #22c55e; font-weight: bold;');
        window.openAliceWarpService(() => {
            setTimeout(() => {
                window.sendNpcWarp(mapId);
            }, 400);
        });
    };

    // ==========================================
    // SHOP BUY PACKET BUILDER (shop_buy_many)
    // ==========================================
    window.sendShopBuy = function(itemId = (window.__shopConfig ? window.__shopConfig.buyItemId : 0x00015fae), qty = (window.__shopConfig ? window.__shopConfig.buyItemQty : 10)) {
        try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {}
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        const totalQty = Math.max(1, Math.floor(Number(qty) || 0));
        const MAX_SHOP_LINE_QTY = 9999; // Game server max per shop_buy_many line (WR = 9999)
        if (room && typeof room.send === 'function') {
            let rem = totalQty;
            let chunkIdx = 0;
            while (rem > 0) {
                const chunkQty = Math.min(MAX_SHOP_LINE_QTY, rem);
                rem -= chunkQty;
                const delay = chunkIdx * 240;
                chunkIdx++;
                if (delay === 0) {
                    room.send('shop_buy_many', { lines: [{ itemId: Number(itemId), qty: chunkQty }] });
                } else {
                    setTimeout(() => {
                        try { room.send('shop_buy_many', { lines: [{ itemId: Number(itemId), qty: chunkQty }] }); } catch (_) {}
                    }, delay);
                }
            }
            setTimeout(() => { try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {} }, chunkIdx * 240 + 250);
            console.log(`%c[PmheeAether Shop] 🏹 ยิง Packet 'shop_buy_many' (ItemID: ${itemId} [0x${Number(itemId).toString(16)}], Qty: ${totalQty}${chunkIdx > 1 ? ` แบ่ง ${chunkIdx} รอบๆ ละ <=9999` : ''}) สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
            return;
        }
        if (!window.__gameSocket || window.__gameSocket.readyState !== 1) return;
        const token = window.__lastMoveToken || [0xd4, 0x72, 0x40];

        // Opcode 0x0D + "shop_buy_many"
        const prefix = [0x0D, 0xAD, 0x73, 0x68, 0x6F, 0x70, 0x5F, 0x62, 0x75, 0x79, 0x5F, 0x6D, 0x61, 0x6E, 0x79];

        // Container structure: ["lines"] -> [ [ "itemId", "qty" ], itemId (uint32), qty ]
        const mid = [
            0x91, 0xA5, 0x6C, 0x69, 0x6E, 0x65, 0x73,
            0x91, 0xD4, 0x72, 0x41,
            0x92, 0xA6, 0x69, 0x74, 0x65, 0x6D, 0x49, 0x64, 0xA3, 0x71, 0x74, 0x79,
            0xCE, (itemId >>> 24) & 0xFF, (itemId >>> 16) & 0xFF, (itemId >>> 8) & 0xFF, itemId & 0xFF
        ];

        let qtyBytes = [];
        if (qty <= 0x7F) {
            qtyBytes = [qty];
        } else if (qty <= 0xFF) {
            qtyBytes = [0xCC, qty];
        } else {
            qtyBytes = [0xCD, (qty >> 8) & 0xFF, qty & 0xFF];
        }

        const totalLen = prefix.length + token.length + mid.length + qtyBytes.length;
        const buf = new Uint8Array(totalLen);
        let offset = 0;
        buf.set(prefix, offset); offset += prefix.length;
        buf.set(token, offset); offset += token.length;
        buf.set(mid, offset); offset += mid.length;
        buf.set(qtyBytes, offset);

        window.__gameSocket.send(buf.buffer);
        setTimeout(() => { try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {} }, 300);
        console.log(`%c[PmheeAether Shop] 🏹 ยิง Packet 'shop_buy_many' (ItemID: ${itemId} [0x${itemId.toString(16)}], Qty: ${qty}) สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
    };

    // ==========================================
    // ITEMBAR & BUTTERFLY WING ACTIONS
    // ==========================================
    window.sendItembarSet = function(slot = 0, itemId = 0x00015fae) {
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (room && typeof room.send === 'function') {
            room.send('itembar_set', { slot: Number(slot), itemId: Number(itemId) });
            console.log(`%c[PmheeAether] 📌 ตั้งค่า ItemBar ช่อง ${slot} เป็น Item: 0x${Number(itemId).toString(16)} (${itemId}) เรียบร้อย!`, 'color: #38bdf8;');
            return;
        }
        if (!window.__gameSocket || window.__gameSocket.readyState !== 1) return;
        const token = window.__lastMoveToken || [0xd4, 0x72, 0x40];
        const prefix = [0x0D, 0xAB, 0x69, 0x74, 0x65, 0x6D, 0x62, 0x61, 0x72, 0x5F, 0x73, 0x65, 0x74];
        const suffix = [
            0x92, 0xA4, 0x73, 0x6C, 0x6F, 0x74, 0xA6, 0x69, 0x74, 0x65, 0x6D, 0x49, 0x64,
            slot,
            0xCE, (itemId >>> 24) & 0xFF, (itemId >>> 16) & 0xFF, (itemId >>> 8) & 0xFF, itemId & 0xFF
        ];
        const buf = new Uint8Array(prefix.length + token.length + suffix.length);
        buf.set(prefix, 0);
        buf.set(token, prefix.length);
        buf.set(suffix, prefix.length + token.length);
        window.__gameSocket.send(buf.buffer);
        console.log(`%c[PmheeAether] 📌 ตั้งค่า ItemBar ช่อง ${slot} เป็น Item: 0x${itemId.toString(16)} (${itemId}) เรียบร้อย!`, 'color: #38bdf8;');
    };

    window.sendEquip = function(slot = 0) {
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (room && typeof room.send === 'function') {
            room.send('equip', { slot: Number(slot) });
            console.log(`%c[PmheeAether Inv] 🎒 ส่ง Packet สวมใส่จากกระเป๋า (sendEquip Inventory Slot: ${slot})!`, 'color: #22c55e;');
            return;
        }
        if (!window.__gameSocket || window.__gameSocket.readyState !== 1) return;
        const token = window.__lastMoveToken || [0xd4, 0x72, 0x40];
        const prefix = [0x0D, 0xA5, 0x65, 0x71, 0x75, 0x69, 0x70];
        const suffix = [0x91, 0xA4, 0x73, 0x6C, 0x6F, 0x74, slot];
        const buf = new Uint8Array(prefix.length + token.length + suffix.length);
        buf.set(prefix, 0);
        buf.set(token, prefix.length);
        buf.set(suffix, prefix.length + token.length);
        window.__gameSocket.send(buf.buffer);
        console.log(`%c[PmheeAether Inv] 🎒 ส่ง Packet สวมใส่จากกระเป๋า (sendEquip Inventory Slot: ${slot})!`, 'color: #22c55e;');
    };

    function findItemInServerInv(filterFn) {
        if (typeof window.getLiveInventoryData === 'function') {
            try { window.getLiveInventoryData(); } catch (e) {}
        }
        if (!window.__latestInventory) return null;
        let found = null;
        function scan(obj, depth = 0) {
            if (!obj || depth > 6 || found) return;
            if (Array.isArray(obj)) {
                for (const item of obj) {
                    if (item && typeof item === 'object') {
                        if (filterFn(item)) {
                            found = item;
                            return;
                        }
                        scan(item, depth + 1);
                    }
                }
            } else if (typeof obj === 'object') {
                if (filterFn(obj)) {
                    found = obj;
                    return;
                }
                for (const k in obj) {
                    scan(obj[k], depth + 1);
                }
            }
        }
        scan(window.__latestInventory);
        return found;
    }

    // Nothing in the ammo slot but arrows in the bag (e.g. 996 Fire Arrows while the config says normal Arrow,
    // or a job change took them off): put them on instead of going to town to buy. The configured type first,
    // else the biggest stack. Returns true only on the tick it actually sends the equip packet.
    let lastAnyArrowEquipAt = 0;
    const anyArrowSlotFails = {};
    window.equipAnyArrowFromBag = function () {
        if (Date.now() - lastAnyArrowEquipAt < 10000) return false;
        const ch = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData;
        if (!ch || (!ch.classId && !ch.name && !ch.equipment)) return false;
        if (ch.ammo && (Number(ch.ammo.qty) || 0) > 0) return false;
        if (typeof window.getLiveInventoryData === 'function') {
            try { window.getLiveInventoryData(); } catch (e) {}
        }
        const items = ((window.__latestInventory && window.__latestInventory.items) || []).filter(it => {
            if (!it || typeof it.slot !== 'number' || (Number(it.qty) || 0) <= 0) return false;
            const isArrowItem = it.equipType === 'Ammo' || it.ammoType || (typeof ARROW_DATA !== 'undefined' && ARROW_DATA[Number(it.itemId)]) || /arrow|ลูกธนู/i.test(String(it.name || ''));
            if (!isArrowItem) return false;
            const key = `${it.slot}:${it.itemId}:${it.qty}`;
            return (anyArrowSlotFails[key] || 0) < 2;
        });
        if (!items.length) return false;
        const want = Number(window.__archerConfig && window.__archerConfig.arrowType) || 90030;
        const pick = items.find(it => Number(it.itemId) === want) || items.slice().sort((a, b) => (b.qty || 0) - (a.qty || 0))[0];
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (!room) return false;
        const slotKey = `${pick.slot}:${pick.itemId}:${pick.qty}`;
        anyArrowSlotFails[slotKey] = (anyArrowSlotFails[slotKey] || 0) + 1;
        lastAnyArrowEquipAt = Date.now();
        console.log(`%c[PmheeAether Ammo] 🏹 ยังไม่ได้ใส่ลูกธนู แต่มี "${pick.name}" x${pick.qty} ในกระเป๋า (slot ${pick.slot}) -> สวมใส่เลย (ไม่ต้องกลับไปซื้อ)`, 'color: #22c55e; font-weight: bold;');
        room.send('equip', { slot: pick.slot });
        return true;
    };

    window.equipArrowAndBow = function() {
        // 1. ตรวจสอบการสวมใส่ "ลูกธนู" ชนิดที่เลือกจากกระเป๋าเซิร์ฟเวอร์
        const targetArrowId = (window.__archerConfig && window.__archerConfig.arrowType) ? parseInt(window.__archerConfig.arrowType) : 90030;
        const arrowInfo = (typeof ARROW_DATA !== 'undefined' && ARROW_DATA[targetArrowId]) ? ARROW_DATA[targetArrowId] : { name: 'Arrow' };

        // ถ้าสวมใส่ลูกธนูชนิดที่ต้องการอยู่ในช่อง ammo แล้วและยังมีจำนวนเหลืออยู่ ไม่ต้องส่ง sendEquip ซ้ำ
        const ch = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData;
        if (ch && ch.ammo && (Number(ch.ammo.qty) || 0) > 0 && typeof isTargetArrow === 'function' && isTargetArrow(ch.ammo, targetArrowId)) {
            return;
        }

        console.log('%c[PmheeAether Ammo] 🏹 กำลังตรวจสอบและสวมใส่ลูกธนู (ไม่แตะต้องอาวุธของผู้เล่น)...', 'color: #38bdf8; font-weight: bold;');
        console.log(`%c[PmheeAether Ammo] 🏹 กำลังตรวจสอบและสวมใส่ลูกธนู "${arrowInfo.name}" (${targetArrowId})...`, 'color: #38bdf8; font-weight: bold;');

        const arrowInBag = findItemInServerInv(it => {
            const slot = it.slot ?? it.idx;
            return typeof isTargetArrow === 'function' && isTargetArrow(it, targetArrowId) && typeof slot === 'number';
        });

        if (arrowInBag) {
            const slot = arrowInBag.slot ?? arrowInBag.idx;
            console.log(`%c[PmheeAether Ammo] 🎯 พบลูกธนู "${arrowInBag.name || arrowInfo.name}" ในกระเป๋า Slot ${slot} (จำนวน: ${arrowInBag.qty || 1} ดอก) -> ส่งคำสั่งสวมใส่ทันที!`, 'color: #22c55e; font-weight: bold;');
            window.sendEquip(slot);
            return;
        }

        // 2. ถ้าใน Server Inventory ยังไม่เจอ ให้ลองดูถ้ามีกระเป๋าเปิดอยู่
        try {
            const bagModal = document.querySelector('.modal, .window, [class*="inventory"], [class*="bag"], [class*="dialog"]') || document.body;
            const slots = Array.from(bagModal.querySelectorAll('[class*="slot"], [class*="item"], [class*="cell"]')).filter(el => !el.closest('#pelican-hud') && el.offsetWidth > 0);
            for (const el of slots) {
                const img = el.querySelector('img');
                const src = img ? (img.src || '').toLowerCase() : '';
                const title = (el.getAttribute('title') || el.getAttribute('data-name') || el.innerText || '').toLowerCase();
                const isArrow = isTargetArrowDom(src, title, targetArrowId);
                if (isArrow) {
                    try { el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true })); } catch(e) {}
                    console.log(`%c[PmheeAether Ammo] 🎯 Double-click สวมใส่ลูกธนู "${arrowInfo.name}" จากหน้าต่างกระเป๋าสำเร็จ!`, 'color: #22c55e;');
                    return;
                }
            }
        } catch(e) {}

        // 3. Fallback สุดท้าย: ถ้าไม่มีทั้งข้อมูล Server และกระเป๋าไม่ได้เปิด จึงค่อยลองกด Hotbar สำรอง
        const hotbarSlot = window.__archerConfig ? window.__archerConfig.arrowHotbarSlot : -1;
        if (typeof hotbarSlot === 'number' && hotbarSlot >= 0) {
            window.pressKey((hotbarSlot + 1).toString());
        }
    };

    window.sendInvUse = function(slot = 8) {
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (room && typeof room.send === 'function') {
            room.send('inv_use', { slot: Number(slot) });
            console.log(`%c[PmheeAether] 🦋 ใช้วาร์ป Butterfly Wing (sendInvUse Slot: ${slot})!`, 'color: #38bdf8; font-weight: bold;');
            return;
        }
        if (!window.__gameSocket || window.__gameSocket.readyState !== 1) return;
        const token = window.__lastMoveToken || [0xd4, 0x72, 0x40];
        const prefix = [0x0D, 0xA7, 0x69, 0x6E, 0x76, 0x5F, 0x75, 0x73, 0x65];
        const suffix = [0x91, 0xA4, 0x73, 0x6C, 0x6F, 0x74, slot];
        const buf = new Uint8Array(prefix.length + token.length + suffix.length);
        buf.set(prefix, 0);
        buf.set(token, prefix.length);
        buf.set(suffix, prefix.length + token.length);
        window.__gameSocket.send(buf.buffer);
        console.log(`%c[PmheeAether] 🦋 ใช้วาร์ป Butterfly Wing (sendInvUse Slot: ${slot})!`, 'color: #38bdf8; font-weight: bold;');
    };

    // The game's "ยินดีต้อนรับ" / event announcement popups (footer.event-foot): tick "ไม่ต้องแสดงอีกวันนี้" and close
    // them, so they never sit over the game on unattended screens
    setInterval(() => {
        try {
            const foot = document.querySelector('footer.event-foot');
            if (!foot) return;
            const cb = foot.querySelector('input[type="checkbox"]');
            const close = foot.querySelector('button.event-close');
            if (!close) return;
            if (cb && !cb.checked) { cb.click(); return; }   // ticked first; closed on the next round
            close.click();
            console.log('%c[PmheeAether] ❎ ปิดหน้าต่างต้อนรับ/ประกาศ (ติ๊ก "ไม่ต้องแสดงอีกวันนี้")', 'color: #38bdf8;');
        } catch (e) {}
    }, 2000);

    // Back to the capital for every system that needs town (shop trip, money consolidation, plan steps, gear set):
    // a Butterfly Wing when the bag has one, else the world map's "เดินไปที่นี่" (a free walk, never a paid warp).
    // Returns 'here' | 'wing' | 'wing-wait' | 'walk' | 'walking'.
    const CAPITAL_MAP = 'เมืองหลวงโซลเฮเวน';
    const isCityMapName = m => /เมืองหลวง|โซลเฮเวน/.test(String(m || ''));
    window.isInCapital = () => isCityMapName(typeof getCurrentMapName === 'function' ? getCurrentMapName() : '');
    window.goToCapital = function (why = '', opts = {}) {
        window.__lastIntentionalWarpAt = Date.now();
        window.__lastTownTripAt = Date.now();
        if (window.isInCapital()) { window.__goHomeWingFails = 0; return 'here'; }
        const now = Date.now();
        if (window.__isNavigating && isCityMapName(window.__targetFarmMap)) return 'walking';
        if (now - (window.__goHomeWingAt || 0) < 10000) return 'wing-wait';   // a wing was just used: let it land
        if (window.__goHomeWingAt && now - window.__goHomeWingAt < 60000) window.__goHomeWingFails = (window.__goHomeWingFails || 0) + 1;
        const wings = typeof window.getBagItemCount === 'function' ? window.getBagItemCount(90311) : 0;
        if (wings > 0 && !opts.noWing && (window.__goHomeWingFails || 0) < 2) {
            window.__goHomeWingAt = now;
            console.log(`%c[PmheeAether] 🦋 ${why ? why + ' -> ' : ''}กลับเมืองหลวงด้วย Butterfly Wing (มี ${wings} ใบ)`, 'color: #38bdf8; font-weight: bold;');
            window.useButterflyWing();
            return 'wing';
        }
        window.__goHomeWingAt = 0;
        window.__goHomeWingFails = 0;
        console.log(`%c[PmheeAether] 🗺️ ${why ? why + ' -> ' : ''}${wings > 0 ? 'ใช้ Butterfly Wing ไม่ได้' : 'ไม่มี Butterfly Wing'} -> เปิดแผนที่แล้วเดินกลับเมืองหลวง (ไม่เสียค่าวาร์ป)`, 'color: #f59e0b; font-weight: bold;');
        // money consolidation must get home even while the "unexpected town return" pause blocks farm walks
        window.walkToTargetMap(CAPITAL_MAP, true, { walkOnly: true, allowDuringConsolidation: !!opts.allowDuringConsolidation, skipWait: !!opts.allowDuringConsolidation });
        return 'walk';
    };
    // The target map stuck on the capital although nothing needs town any more (a trip cut by STOP, a page
    // reload...): START BOT then "arrived" in town and tried AUTO there forever. Put a real farm map back — the
    // map a plan trip remembered, the plan's map, the HUD's farm map, or the last farm map used.
    window.rememberFarmMap = function (m) {
        if (m && !isCityMapName(m)) { try { localStorage.setItem('pelican_last_farm_map', m); } catch (e) {} }
    };
    window.recoverFarmTarget = function (why = '') {
        if (!isCityMapName(window.__targetFarmMap)) return null;
        if (window.__isShopping || window.__isStoring || window.__isConsolidating || window.__isNavigating || window.__isWalkingToMap
            || window.__isGearRefining || window.__isChangingJob || window.__isRecovering) return null;
        if ((window.__planJobChangeHoldUntil || 0) > Date.now() || window.otherTownNeeds('').length) return null;
        let map = null;
        try { map = localStorage.getItem('pelican_job_return_map'); } catch (e) {}
        if ((!map || isCityMapName(map)) && window.__planScriptEnabled && window.__currentScriptPlan && typeof window.planMapForNow === 'function') map = window.planMapForNow();
        const sel = document.getElementById('p-target-map-select');
        if ((!map || isCityMapName(map)) && sel && sel.value) map = sel.value;
        if (!map || isCityMapName(map)) { try { map = localStorage.getItem('pelican_last_farm_map'); } catch (e) {} }
        if (!map || isCityMapName(map)) return null;
        try { localStorage.removeItem('pelican_job_return_map'); } catch (e) {}
        window.__targetFarmMap = map;
        try { localStorage.setItem('pelican_farm_map', map); } catch (e) {}
        if (sel) sel.value = map;
        console.log(`%c[PmheeAether] 🗺️ แมพเป้าหมายค้างเป็นเมืองหลวง (ไม่มีงานในเมืองแล้ว${why ? ' · ' + why : ''}) -> คืนแมพฟาร์ม "${map}"`, 'color: #f59e0b; font-weight: bold;');
        return map;
    };

    // Plan systems (job change, weight scrolls, event pet, gear set): the capital becomes the target map for the
    // stay (so nothing walks the character out) and the farm map is remembered for restoreFarmMapAfterJobChange
    window.planTripToCapital = function (who) {
        window.__lastTownTripAt = Date.now();
        if (window.isInCapital()) return 'here';
        const farm = window.__targetFarmMap || '';
        if (farm && !isCityMapName(farm)) { try { localStorage.setItem('pelican_job_return_map', farm); } catch (e) {} }
        window.needTown(who || 'plan');
        window.__planJobChangeHoldUntil = Math.max(window.__planJobChangeHoldUntil || 0, Date.now() + 120000);
        if (!window.__isNavigating) {
            window.__targetFarmMap = CAPITAL_MAP;
            try { localStorage.setItem('pelican_farm_map', CAPITAL_MAP); } catch (e) {}
        }
        return window.goToCapital(who);
    };
    // Money consolidation: get to the capital however possible and wait for it (the farm map is kept)
    const KEEP_FARM_KEY = 'pelican_gohome_keep_farm';
    window.keepFarmMapForTrip = function () {
        const farm = window.__targetFarmMap || '';
        if (farm && !isCityMapName(farm)) { try { localStorage.setItem(KEEP_FARM_KEY, farm); } catch (e) {} }
    };
    window.restoreKeptFarmMap = function () {
        let keep = null;
        try { keep = localStorage.getItem(KEEP_FARM_KEY); localStorage.removeItem(KEEP_FARM_KEY); } catch (e) {}
        if (keep && !isCityMapName(keep) && isCityMapName(window.__targetFarmMap)) {
            window.__targetFarmMap = keep;
            try { localStorage.setItem('pelican_farm_map', keep); } catch (e) {}
        }
    };
    window.ensureInCapital = async function (timeoutMs = 360000) {
        if (window.isInCapital()) return { success: true, already: true };
        window.keepFarmMapForTrip();
        const start = Date.now();
        let how = window.goToCapital('รวมเงิน', { allowDuringConsolidation: true }), kickAt = Date.now();
        while (Date.now() - start < timeoutMs) {
            await new Promise(r => setTimeout(r, 1000));
            if (window.isInCapital()) return { success: true, how };
            if (!window.__isConsolidating) return { success: false, error: 'ยกเลิกแล้ว (ไม่ได้รวมเงินอยู่)' };   // never pulls a released character back
            if (Date.now() - kickAt > 12000 && !window.__isNavigating) { how = window.goToCapital('รวมเงิน', { allowDuringConsolidation: true }); kickAt = Date.now(); }
        }
        return { success: false, error: 'ไปไม่ถึงเมืองหลวง (หมดเวลารอ)' };
    };

    window.useButterflyWing = function() {
        window.__lastBwingUsedAt = Date.now();
        console.log('%c[PmheeAether] 🦋 กำลังใช้วาร์ป Butterfly Wing กลับเมืองหลวง...', 'color: #38bdf8; font-weight: bold;');

        // 1. ค้นหาช่อง Butterfly Wing ในข้อมูลกระเป๋าเซิร์ฟเวอร์ (ซิงก์จาก React Fiber / Colyseus ก่อนเสมอ)
        let bwingSlot = -1;
        const bwingInBag = findItemInServerInv(it => {
            const id = it.itemId || it.id || it.item_id;
            const name = (it.name || it.itemName || '').toLowerCase();
            return (Number(id) === 90311 || name.includes('butterfly')) && typeof (it.slot ?? it.idx) === 'number';
        });
        if (bwingInBag) {
            bwingSlot = bwingInBag.slot ?? bwingInBag.idx;
            console.log(`%c[PmheeAether] 🦋 พบ Butterfly Wing ใน Server Inventory Slot: ${bwingSlot}`, 'color: #22c55e;');
            window.sendInvUse(bwingSlot);
            const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
            if (room && typeof room.send === 'function') return;
        }

        // 2. ค้นหาใน DOM ช่องกระเป๋า (ถ้าหน้าต่างกระเป๋าเปิดอยู่)
        const bagModals = Array.from(document.querySelectorAll('.modal, .window, [class*="inventory"], [class*="bag"], [class*="dialog"]')).filter(el => {
            return !el.closest('#pelican-hud') && !el.closest('#pelican-data-modal');
        });

        let domFound = false;
        for (const modal of bagModals) {
            const slots = Array.from(modal.querySelectorAll('[class*="item"], .inventory-slot, [data-item-id], [class*="slot"]'));
            for (let idx = 0; idx < slots.length; idx++) {
                const s = slots[idx];
                const img = s.querySelector('img');
                const src = (img?.src || s.style?.backgroundImage || '').toLowerCase();
                const title = (s.getAttribute('title') || s.getAttribute('data-name') || s.innerText || '').toLowerCase();
                if (src.includes('160c7') || src.includes('90311') || src.includes('bwing') || src.includes('butterfly') || title.includes('butterfly') || title.includes('วิง')) {
                    domFound = true;
                    console.log(`%c[PmheeAether] 🦋 พบ Butterfly Wing ในช่องกระเป๋า DOM ช่องที่ ${idx} -> ดับเบิลคลิกใช้งาน!`, 'color: #22c55e; font-weight: bold;');
                    triggerClick(s);
                    try { s.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true })); } catch(e) {}
                    window.sendInvUse(idx);
                    break;
                }
            }
            if (domFound) break;
        }

        // 3. ตรวจสอบ Hotbar ช่องลัด 1-10 (จาก character.itembar หรือ DOM Hotbar เฉพาะช่องที่มี Butterfly Wing จริง)
        let hotbarKey = null;
        try {
            const ch = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
            if (ch && Array.isArray(ch.itembar)) {
                const idx = ch.itembar.findIndex(id => Number(id) === 90311);
                if (idx >= 0 && idx < 10) {
                    hotbarKey = (idx === 9 ? '0' : String(idx + 1));
                }
            }
        } catch(e) {}

        for (let i = 0; i < 10; i++) {
            const hotbarSlot = document.querySelector(`[data-slot="${i}"], .slot-${i}, #hotbar-${i}, .quick-slot-${i}, [class*="hotbar"] > *:nth-child(${i+1})`);
            if (hotbarSlot) {
                const img = hotbarSlot.querySelector('img');
                const src = (img?.src || hotbarSlot.style?.backgroundImage || '').toLowerCase();
                const txt = (hotbarSlot.getAttribute('title') || hotbarSlot.innerText || '').toLowerCase();
                if (src.includes('160c7') || src.includes('90311') || src.includes('bwing') || src.includes('butterfly') || txt.includes('butterfly') || txt.includes('วิง')) {
                    hotbarKey = (i === 9 ? '0' : (i + 1).toString());
                    console.log(`%c[PmheeAether] 🦋 พบ Butterfly Wing ใน Hotbar ช่องลัดเลข ${hotbarKey} -> กดใช้งาน!`, 'color: #22c55e;');
                    triggerClick(hotbarSlot);
                    break;
                }
            }
        }
        if (hotbarKey) {
            dispatchKeyAll(hotbarKey, 'Digit' + hotbarKey, hotbarKey.charCodeAt(0));
            return;
        }

        // 4. คลิกไอคอน Bwing บนหน้าจอถ้ามี
        try {
            const bwingEl = Array.from(document.querySelectorAll('*')).find(el => {
                if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal')) return false;
                const src = (el.src || el.style?.backgroundImage || '').toLowerCase();
                const txt = (el.innerText || el.textContent || '').toLowerCase();
                return (src.includes('160c7') || src.includes('90311') || src.includes('bwing') || src.includes('butterfly') || txt.includes('butterfly')) && el.offsetWidth > 0;
            });
            if (bwingEl) {
                triggerClick(bwingEl);
                try { bwingEl.dispatchEvent(new MouseEvent('dblclick', { bubbles: true, cancelable: true })); } catch(e) {}
                console.log('%c[PmheeAether] 🦋 คลิกปุ่ม Butterfly Wing บนหน้าจอสำเร็จ!', 'color: #22c55e;');
                return;
            }
        } catch(e) {}

        // 5. Fallback: ไม่มีปีกในกระเป๋า -> เปิดกระเป๋าให้เกมส่งข้อมูลมาสแกนใหม่
        if (!bwingInBag && !domFound) {
            console.warn('[PmheeAether] 🦋 ไม่พบ Butterfly Wing ในกระเป๋า');

            // ถ้าหน้าต่างกระเป๋ายังไม่เคยเปิด ให้กดเปิดเพื่อดึง Packet และสแกน DOM
            if (bagModals.length === 0) {
                dispatchKeyAll('i', 'KeyI', 73);
                setTimeout(() => {
                    window.useButterflyWing();
                }, 300);
            }
        }
    };

    // ---------- 👑 Premium Status Detection (ui:token buff) ----------
    // Matches the game client's exact check: `fF = e => !!e?.buffs.some(e => e.skillId === "ui:token")`
    window.getCharacterPremiumUntil = function () {
        const liveChar = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        const buffs = Array.isArray(liveChar.buffs) ? liveChar.buffs : [];
        const premBuff = buffs.find(b => b && (b.skillId === 'ui:token' || /^premium$/i.test(String(b.name || '').trim())));
        if (premBuff) {
            const endsAt = Number(premBuff.endsAt) || 0;
            if (endsAt > 0) return endsAt;
            const rem = Number(premBuff.remainingMs) || 0;
            if (rem > 0) return Date.now() + rem;
            return Date.now() + 86400000;
        }
        return Number(liveChar.premiumUntil) || Number(window.__gameRoom?.state?.players?.get?.(window.__gameRoom?.sessionId)?.premiumUntil) || 0;
    };

    window.hasCharacterPremium = function () {
        const until = window.getCharacterPremiumUntil();
        if (until > Date.now()) return true;
        const liveChar = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        if (Array.isArray(liveChar.buffs) && liveChar.buffs.some(b => b && (b.skillId === 'ui:token' || /^premium$/i.test(String(b.name || '').trim())))) {
            return true;
        }
        return Boolean(document.querySelector('.hud-buff-icon[title*="Premium" i], .hud-buff-icon[title*="พรีเมียม" i], .buff-icon[title*="Premium" i], [data-buff*="premium" i]'));
    };

    // ---------- 🏛️ Daily Guild Donation Material Reservation ----------
    // Always reserve the required daily guild donation quantity in the character's bag so NPC Auto-Sell,
    // Market Auto-Sell, and Kafra Storage Deposit only sell/deposit the excess above the required amount.
    const GUILD_DONATION_DEFAULT_BY_ID = { 90203: 20, 90205: 20 };
    const GUILD_DONATION_DEFAULT_BY_NAME = { 'oridecon': 20, 'โอริเดคอน': 20, 'elunium': 20, 'อีลูเนียม': 20 };
    let __guildDonationCacheAt = 0;
    let __guildDonationCache = null;

    window.getLiveGuildData = function (force = false) {
        const now = Date.now();
        if (!force && window.__pmGuildData && (now - (window.__pmGuildDataAt || 0) < 5000)) {
            return window.__pmGuildData;
        }
        let g = window.__pmGuildData || null;
        try {
            const root = document.getElementById('root') || document.body;
            const fk = root ? Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber')) : null;
            const q = fk && root[fk] ? [root[fk]] : [];
            const seen = new Set();
            while (q.length && seen.size < 600) {
                const n = q.shift();
                if (!n || seen.has(n)) continue;
                seen.add(n);
                if (n.memoizedProps && n.memoizedProps.guild && typeof n.memoizedProps.guild === 'object' && n.memoizedProps.guild.myPoints !== undefined) {
                    g = n.memoizedProps.guild;
                    window.__pmGuildData = g;
                    window.__pmGuildDataAt = now;
                    break;
                }
                let m = n.memoizedState;
                let guard = 0;
                while (m && guard++ < 35) {
                    const v = m.memoizedState;
                    if (v && typeof v === 'object' && !Array.isArray(v)) {
                        if (v.myPoints !== undefined && v.shopToday !== undefined && v.id) {
                            g = v;
                            window.__pmGuildData = g;
                            window.__pmGuildDataAt = now;
                            break;
                        }
                        if (v.value && typeof v.value === 'object' && v.value.myPoints !== undefined && v.value.shopToday !== undefined && v.value.id) {
                            g = v.value;
                            window.__pmGuildData = g;
                            window.__pmGuildDataAt = now;
                            break;
                        }
                        if ('guild' in v && 'inventory' in v) {
                            const liveG = typeof v.guild === 'function' ? v.guild() : v.guild;
                            if (liveG && typeof liveG === 'object' && liveG.id) {
                                g = liveG;
                                window.__pmGuildData = g;
                                window.__pmGuildDataAt = now;
                                break;
                            }
                        }
                    }
                    m = m.next;
                }
                if (g && window.__pmGuildDataAt === now) break;
                if (n.child) q.push(n.child);
                if (n.sibling) q.push(n.sibling);
            }
        } catch (e) {}
        return g;
    };

    window.getGuildDonationReserveMap = function () {
        const now = Date.now();
        if (__guildDonationCache && (now - __guildDonationCacheAt < 5000)) return __guildDonationCache;
        const byId = Object.assign({}, GUILD_DONATION_DEFAULT_BY_ID);
        const byName = Object.assign({}, GUILD_DONATION_DEFAULT_BY_NAME);
        try {
            const g = window.getLiveGuildData(now - (window.__pmGuildDataAt || 0) > 15000);
            if (g && Array.isArray(g.materials)) {
                g.materials.forEach(tier => {
                    if (!tier || !Array.isArray(tier.items)) return;
                    tier.items.forEach(entry => {
                        const id = Number(entry && entry.itemId);
                        const qty = Number(entry && entry.qty) || 0;
                        if (Number.isFinite(id) && id > 0 && qty > 0) {
                            byId[id] = Math.max(byId[id] || 0, qty);
                        }
                    });
                });
            }
        } catch (e) {}
        __guildDonationCache = { byId, byName };
        __guildDonationCacheAt = now;
        return __guildDonationCache;
    };

    window.getGuildDonationReserveQty = function (itemOrNameOrId) {
        if (itemOrNameOrId === null || itemOrNameOrId === undefined) return 0;
        const { byId, byName } = window.getGuildDonationReserveMap();
        if (typeof itemOrNameOrId === 'number' || (typeof itemOrNameOrId === 'string' && /^\d+$/.test(itemOrNameOrId.trim()))) {
            return byId[Number(itemOrNameOrId)] || 0;
        }
        if (typeof itemOrNameOrId === 'string') {
            const norm = itemOrNameOrId.replace(/^\+\s*\d+\s*/, '').replace(/\s*\[\s*\d+\s*\]\s*$/, '').trim().toLowerCase();
            if (byName[norm] > 0) return byName[norm];
            const bag = (typeof window.getBagItems === 'function') ? window.getBagItems() : [];
            const match = bag.find(b => b && b.name && b.name.trim().toLowerCase() === norm);
            if (match) {
                const mid = Number((match.raw && match.raw.itemId) ?? match.itemId ?? match.id);
                if (Number.isFinite(mid) && byId[mid] > 0) return byId[mid];
            }
            return 0;
        }
        const raw = itemOrNameOrId.raw || itemOrNameOrId;
        const id = Number(raw.itemId ?? raw.id ?? itemOrNameOrId.itemId ?? itemOrNameOrId.id);
        if (Number.isFinite(id) && byId[id] > 0) return byId[id];
        const name = String(raw.name || itemOrNameOrId.name || '').replace(/^\+\s*\d+\s*/, '').replace(/\s*\[\s*\d+\s*\]\s*$/, '').trim().toLowerCase();
        return byName[name] || 0;
    };

    window.getGuildDonationSlotSellableQty = function (slot, bagList, itemHint = null) {
        const bag = Array.isArray(bagList) ? bagList : ((typeof window.getBagItems === 'function') ? window.getBagItems() : []);
        const targetSlot = Number(slot);
        const slotEntry = bag.find(b => b && Number(b.slot) === targetSlot) || itemHint;
        if (!slotEntry) return { reserveQty: 0, keepQty: 0, sellableQty: 0, totalQty: 0, reserveSource: '' };
        const raw = slotEntry.raw || slotEntry;
        const slotQty = Math.max(0, Number(slotEntry.qty ?? raw.qty) || 1);
        const gdReserveQty = window.getGuildDonationReserveQty(slotEntry);
        const gearOreReserveQty = (typeof window.getGearOreReserveQty === 'function') ? window.getGearOreReserveQty(slotEntry) : 0;
        const reserveQty = Math.max(gdReserveQty, gearOreReserveQty);
        const reserveSource = (gearOreReserveQty > 0 && gearOreReserveQty >= gdReserveQty) ? 'gear' : (gdReserveQty > 0 ? 'guild' : '');
        if (reserveQty <= 0) {
            return { reserveQty: 0, keepQty: 0, sellableQty: slotQty, totalQty: slotQty, reserveSource: '' };
        }
        const targetId = Number(raw.itemId ?? raw.id ?? slotEntry.itemId ?? slotEntry.id);
        const targetName = String(raw.name || slotEntry.name || '').trim().toLowerCase();
        const sameStacks = bag
            .filter(b => {
                if (!b) return false;
                const r = b.raw || b;
                const bid = Number(r.itemId ?? r.id ?? b.itemId ?? b.id);
                if (Number.isFinite(targetId) && targetId > 0 && Number.isFinite(bid) && bid > 0) return bid === targetId;
                return String(r.name || b.name || '').trim().toLowerCase() === targetName;
            })
            .slice()
            .sort((a, b) => Number(a.slot) - Number(b.slot));
        if (!sameStacks.length) {
            const keepQty = Math.min(slotQty, reserveQty);
            return { reserveQty, keepQty, sellableQty: Math.max(0, slotQty - keepQty), totalQty: slotQty, reserveSource };
        }
        const totalQty = sameStacks.reduce((sum, b) => sum + Math.max(0, Number(b.qty ?? (b.raw && b.raw.qty)) || 1), 0);
        let reserveRemaining = reserveQty;
        for (const b of sameStacks) {
            const q = Math.max(0, Number(b.qty ?? (b.raw && b.raw.qty)) || 1);
            const keepHere = Math.min(q, reserveRemaining);
            reserveRemaining = Math.max(0, reserveRemaining - keepHere);
            if (Number(b.slot) === targetSlot) {
                return {
                    reserveQty,
                    keepQty: keepHere,
                    sellableQty: Math.max(0, q - keepHere),
                    totalQty,
                    reserveSource
                };
            }
        }
        const keepFallback = Math.min(slotQty, reserveRemaining);
        return {
            reserveQty,
            keepQty: keepFallback,
            sellableQty: Math.max(0, slotQty - keepFallback),
            totalQty,
            reserveSource
        };
    };

    // ---------- 🔮 Auto Guild Shop Enchant Rune Exchange ----------
    // Automatically exchanges guild donation points for Enchant Rune (itemId: 90340, 10 points each, max 10/day)
    // whenever the character belongs to a guild, has >= 10 points, and still has daily exchange quota left.
    const GUILD_ENCHANT_RUNE_ITEM_ID = 90340;
    const GUILD_ENCHANT_RUNE_COST_POINTS = 10;
    const GUILD_ENCHANT_RUNE_MAX_PER_DAY = 10;
    let __lastGuildEnchantRuneBuyAt = 0;
    let __lastGuildEnchantRuneDayKey = '';

    function getBangkokDateKeyForGuild() {
        try {
            return new Date(Date.now() + 7 * 3600000).toISOString().slice(0, 10);
        } catch (e) {
            return '';
        }
    }

    window.getGuildEnchantRuneStatus = function (force = false) {
        const g = window.getLiveGuildData(force);
        if (!g || !g.id) {
            return { hasGuild: false, guildName: '', myPoints: 0, boughtToday: 0, leftToday: 0, canBuyQty: 0 };
        }
        const shopToday = (g.shopToday && typeof g.shopToday === 'object') ? g.shopToday : {};
        const boughtToday = Math.max(0, Number(shopToday[GUILD_ENCHANT_RUNE_ITEM_ID] ?? shopToday[String(GUILD_ENCHANT_RUNE_ITEM_ID)] ?? 0) || 0);
        const leftToday = Math.max(0, GUILD_ENCHANT_RUNE_MAX_PER_DAY - boughtToday);
        const myPoints = Math.max(0, Number(g.myPoints) || 0);
        const affordable = Math.floor(myPoints / GUILD_ENCHANT_RUNE_COST_POINTS);
        const canBuyQty = Math.max(0, Math.min(leftToday, affordable));
        return {
            hasGuild: true,
            guildId: g.id,
            guildName: g.name || '',
            myPoints,
            boughtToday,
            leftToday,
            canBuyQty
        };
    };

    window.checkAndAutoBuyGuildEnchantRune = function (triggerSource = 'interval', force = false) {
        try {
            if (window.__autoGuildEnchantRuneEnabled === false) return { exchanged: false, reason: 'disabled' };
            const now = Date.now();
            if (!force && (now - __lastGuildEnchantRuneBuyAt < 10000)) {
                return { exchanged: false, reason: 'cooldown' };
            }
            if (window.__latestHumanCheck && (now - (window.__latestHumanCheck.timestamp || 0) < 15000)) {
                return { exchanged: false, reason: 'human_check' };
            }
            const room = (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null)
                || (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null)
                || window.__colyseusRoom
                || window.__gameRoom;
            if (!room || typeof room.send !== 'function' || (room.connection && room.connection.isOpen === false)) {
                return { exchanged: false, reason: 'no_room' };
            }
            const todayKey = getBangkokDateKeyForGuild();
            if (todayKey && __lastGuildEnchantRuneDayKey && __lastGuildEnchantRuneDayKey !== todayKey) {
                window.__pmGuildDataAt = 0;
            }
            __lastGuildEnchantRuneDayKey = todayKey;

            const status = window.getGuildEnchantRuneStatus(true);
            if (!status.hasGuild) return { exchanged: false, reason: 'no_guild', status };
            if (status.leftToday <= 0) return { exchanged: false, reason: 'daily_limit_reached', status };
            if (status.canBuyQty <= 0) return { exchanged: false, reason: 'insufficient_points', status };

            const qty = status.canBuyQty;
            const costPoints = qty * GUILD_ENCHANT_RUNE_COST_POINTS;
            const remainPoints = status.myPoints - costPoints;
            __lastGuildEnchantRuneBuyAt = now;

            room.send('guild', {
                action: 'shopBuy',
                itemId: GUILD_ENCHANT_RUNE_ITEM_ID,
                qty
            });

            if (window.__pmGuildData && window.__pmGuildData.id === status.guildId) {
                window.__pmGuildData = Object.assign({}, window.__pmGuildData, {
                    myPoints: Math.max(0, remainPoints),
                    shopToday: Object.assign({}, window.__pmGuildData.shopToday || {}, {
                        [GUILD_ENCHANT_RUNE_ITEM_ID]: status.boughtToday + qty
                    })
                });
                window.__pmGuildDataAt = now;
            }

            setTimeout(() => {
                try {
                    const dlg = document.querySelector('.guild-shop-dialog');
                    if (dlg && /Enchant Rune/i.test(dlg.innerText || '')) {
                        const closeBtn = dlg.querySelector('button.win-close');
                        if (closeBtn) closeBtn.click();
                    }
                    if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true);
                } catch (_) {}
            }, 400);

            console.log(
                `%c[PmheeAether Guild] 🔮 แลก Enchant Rune x${qty} อัตโนมัติสำเร็จ! (กิลด์ ${status.guildName} · ใช้ ${costPoints} คะแนน · คงเหลือ ${remainPoints} คะแนน · แลกวันนี้ ${status.boughtToday + qty}/${GUILD_ENCHANT_RUNE_MAX_PER_DAY})`,
                'color: #c084fc; font-weight: bold;'
            );
            return { exchanged: true, qty, costPoints, remainPoints, guildName: status.guildName, triggerSource };
        } catch (e) {
            return { exchanged: false, reason: 'error', error: e && e.message };
        }
    };

    if (!window.__pmGuildEnchantRuneInterval) {
        window.__pmGuildEnchantRuneInterval = setInterval(() => {
            try {
                if (typeof window.checkAndAutoBuyGuildEnchantRune === 'function') {
                    window.checkAndAutoBuyGuildEnchantRune('interval');
                }
            } catch (_) {}
        }, 15000);
    }

    window.triggerAutoSellTrash = triggerAutoSellTrash;
    function triggerAutoSellTrash(callback) {
        const sellCfg = window.__sellConfig || {};
        const canSellAny = sellCfg.sellMaterials || sellCfg.sellRefineOres || sellCfg.sellConsumables ||
            (sellCfg.weaponRarity && sellCfg.weaponRarity !== 'none') ||
            (sellCfg.armorRarity && sellCfg.armorRarity !== 'none') ||
            (sellCfg.accRarity && sellCfg.accRarity !== 'none') ||
            sellCfg.sellWeapons || sellCfg.sellArmors;

        if (!sellCfg.enabled || !canSellAny) {
            if (callback) callback();
            return;
        }

        console.log('%c[PmheeAether Shop] 💰 เริ่มต้นระบบคัดกรองขายไอเทม (Auto-Sell & Whitelist)...', 'color: #f59e0b; font-weight: bold;');

        const rawWhitelist = (sellCfg.whitelist || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

        function normalizeItemBaseName(name) {
            if (!name) return '';
            return name
                .replace(/^\+\s*\d+\s*/, '')                          // ตัดค่าตีบวก (+7, +10)
                .replace(/\s*\[\s*\d+\s*\]\s*$/, '')                  // ตัดจำนวนรูการ์ด ([1], [2], [3], [4])
                .replace(/\s*\[\s*(?:ธรรมดา|ดี|หายาก|มหากาพย์|ตำนาน)\s*\]/gi, '') // ตัดป้ายระดับความหายาก
                .replace(/มี\s*(?:option|options|ออฟชั่น|ออปชั่น|ออฟ|opt).*/i, '')
                .replace(/\b(?:option|options|ออฟชั่น|ออปชั่น)\b.*/i, '')
                .replace(/มี\s*\d+.*/, '')
                .replace(/\bx\s*\d+\b.*/i, '')
                .replace(/\b\d+[\s,]*z\b.*/i, '')
                .trim();
        }

        function isWhitelisted(itemName) {
            if (!itemName) return false;
            const baseName = normalizeItemBaseName(itemName).toLowerCase();
            const fullName = itemName.toLowerCase();

            return rawWhitelist.some(w => {
                const target = w.trim().toLowerCase();
                if (!target) return false;

                // 1. ตรงกับชื่อหลัก หรือชื่อเต็มแบบเป๊ะๆ (เช่น 'bow' === 'bow', 'hunter bow' === 'hunter bow')
                if (baseName === target || fullName === target) return true;

                // กรณีพิเศษ: ถ้าพิมพ์ 'bow' ใน Whitelist จะหมายถึงธนูธรรมดา 'Bow' เท่านั้น ไม่ครอบคลุม 'Hunter Bow' หรือ 'Crossbow'
                if (target === 'bow') {
                    return baseName === 'bow';
                }

                // 2. คำใน Whitelist เป็นวลีระบุเฉพาะที่ตรงกับชื่อไอเทม (เช่น 'hunter bow' ตรงกับ 'Hunter Bow [1]')
                // สำคัญ: ห้ามใช้ target.includes(baseName) เด็ดขาด เพราะจะทำให้ 'Hunter Bow' ไปครอบคลุมไอเทมสั้นอย่าง 'Bow'
                if (baseName.includes(target) || fullName.includes(target)) {
                    return true;
                }

                // 3. ป้องกันการพิมพ์ผิดยอดฮิต เช่น 'angrelic protection' -> 'angelic protection'
                if ((target.includes('angrelic') || target.includes('angelic')) && (baseName.includes('angelic') || baseName.includes('angrelic'))) {
                    return true;
                }

                return false;
            });
        }

        function parseOptionCount(text) {
            if (!text) return null;
            const lower = text.toLowerCase();

            // 1. ถ้ามี 0 option อย่างชัดเจน (เช่น '0 option', '0  option', '0 ออฟชั่น')
            const isZero = /(?:^|[^\d])0\s*(?:option|options|ออฟชั่น|ออปชั่น|ออฟ|opt)(?:[^\u0E00-\u0E7Fa-zA-Z]|$)/i.test(lower);

            // 2. รูปแบบตัวเลขนำหน้า เช่น '1 Option', '2 options', '3 ออฟชั่น', '4 ออฟ'
            const mPrefix = lower.match(/(?:^|[^\d])([1-9]\d*)\s*(?:option|options|ออฟชั่น|ออปชั่น|ออฟ|opt)(?:[^\u0E00-\u0E7Fa-zA-Z]|$)/i);
            if (mPrefix) {
                return parseInt(mPrefix[1], 10);
            }

            // 3. รูปแบบ Option: 1-5 (ในบรรทัดเดียวกันเท่านั้น ห้ามข้ามบรรทัดไปตรงกับราคา zeny)
            const mSuffix = lower.match(/(?:option|options|ออฟชั่น|ออปชั่น|ออฟ|opt)[^\S\r\n]*[:=][^\S\r\n]*([1-9]\d*)/i);
            if (mSuffix) {
                return parseInt(mSuffix[1], 10);
            }

            if (isZero) return 0;
            return null;
        }

        function hasOptions(rowText, row) {
            const text = ((row ? (row.innerText || row.textContent || '') : '') + ' ' + (rowText || '')).toLowerCase();

            // ตรวจสอบจำนวนออฟชั่นด้วย parseOptionCount
            const optCount = parseOptionCount(text);
            if (optCount !== null) {
                return optCount > 0;
            }

            // ข้อความระบุว่ามีออฟชั่น
            if (text.includes('มี option') || text.includes('ออฟชั่นพิเศษ') || text.includes('มีออฟชั่น')) {
                return true;
            }

            // มีคำว่า option แต่ไม่ใช่ 0 option
            if ((text.includes('option') || text.includes('ออฟชั่น') || text.includes('ออปชั่น')) && 
                !text.includes('0 option') && !text.includes('0  option') && !text.includes('0ออฟชั่น') && 
                !text.includes('0 ออฟชั่น') && !text.includes('0 ออปชั่น') && !text.includes('ไม่มี option')) {
                return true;
            }

            // ตรวจสอบ DOM Element พิเศษ เช่น badge, class ที่เกี่ยวข้องกับ option
            if (row && typeof row.querySelectorAll === 'function') {
                const optEls = row.querySelectorAll('[class*="option"], [class*="opt"], [class*="affix"], [class*="bonus"]');
                for (const el of optEls) {
                    const elTxt = (el.innerText || el.textContent || '').toLowerCase();
                    if (elTxt) {
                        const badgeCount = parseOptionCount(elTxt);
                        if (badgeCount !== null) return badgeCount > 0;
                        if (!elTxt.includes('0 option') && !elTxt.includes('0 opt') && !elTxt.includes('0ออฟ')) return true;
                    }
                }
            }

            return false;
        }

        function getItemRarity(itemName, rowText, titleEl, row) {
            const fullText = [
                itemName || '',
                titleEl ? (titleEl.innerText || titleEl.textContent || '') : '',
                row ? (row.innerText || row.textContent || '') : '',
                rowText || ''
            ].join(' ').toLowerCase();

            // กฎเหล็กสูงสุด: การ์ดมอนสเตอร์ทุกชนิด ถือเป็นระดับสูงสุด (999) เสมอ ห้ามคิดเป็นของขาวธรรมดาเด็ดขาด!
            if (fullText.includes('card') || fullText.includes('การ์ด')) return 999;

            // 1. ตรวจสอบข้อความระดับ Rarity ภาษาไทย / อังกฤษ โดยตรงเป็นอันดับแรก (ป้องกันของหายาก/มหากาพย์/ตำนาน หลุดรอด 100%)
            if (fullText.includes('ตำนาน') || fullText.includes('legendary')) return 5;
            if (fullText.includes('มหากาพย์') || fullText.includes('epic')) return 4;
            if (fullText.includes('หายาก') || fullText.includes('rare')) return 3;
            if (fullText.includes('ระดับ: ดี') || fullText.includes('ระดับ ดี') || fullText.includes('ระดับดี') || 
                fullText.includes('· ดี') || /(?:^|\s|[·•|])ดี(?:\s|[·•|]|$)/.test(fullText) || 
                fullText.includes('good') || fullText.includes('ชำนาญ') || fullText.includes('ขั้นดี')) return 2;

            // 2. ตรวจสอบจำนวน Option จากตัวเลขชัดเจน
            const optCount = parseOptionCount(fullText);
            if (optCount !== null) {
                if (optCount >= 4) return 5; // ตำนาน (4+ Option)
                if (optCount === 3) return 4; // มหากาพย์ (3 Option)
                if (optCount === 2) return 3; // หายาก (2 Option)
                if (optCount === 1) return 2; // ดี (1 Option)
                if (optCount === 0) return 1; // ขาวธรรมดา (0 Option)
            }

            // 3. ในเกม Aetheria: ไอเทมที่มีป้าย [มี option] แต่ไม่มีคำว่าหายาก/มหากาพย์/ตำนาน คือของระดับ "ดี (เขียว 1 Option)" เสมอ
            if (hasOptions(rowText, row)) {
                return 2;
            }

            // 4. ตรวจสอบ Class name เฉพาะของ Title / Badge (เฉพาะคลาส rarity โดยตรง ห้ามตรวจคำว่า gold/amber/orange เด็ดขาด เพราะจะไปตรงกับราคา Zeny ในร้านค้า)
            const elementsToScan = [];
            if (titleEl) elementsToScan.push(titleEl);
            if (row && typeof row.querySelectorAll === 'function') {
                const badges = row.querySelectorAll('[class*="rarity"], [class*="badge"], [class*="rank"], [class*="tier"]');
                badges.forEach(b => elementsToScan.push(b));
            }

            for (const el of elementsToScan) {
                const cls = (el.className || '').toString().toLowerCase();
                if (cls.includes('legendary') || cls.includes('tier-5') || cls.includes('rank-5')) return 5;
                if (cls.includes('epic') || cls.includes('tier-4') || cls.includes('rank-4')) return 4;
                if (cls.includes('rare') || cls.includes('tier-3') || cls.includes('rank-3')) return 3;
                if (cls.includes('good') || cls.includes('tier-2') || cls.includes('rank-2')) return 2;
            }

            // 5. ถ้ามีข้อความระบุธรรมดา หรือไม่มีอะไรบ่งบอก ให้ถือเป็นระดับ 1 (ธรรมดา/ขาว)
            return 1;
        }

        function isRefined(itemName, rowText, titleEl) {
            // ของตีบวกจะมีเครื่องหมาย + นำหน้าชื่อไอเทมเสมอ เช่น "+4 Damascus", "+7 Knife", "+9 Crossbow"
            // ห้ามตรวจเช็ค /\+\s*\d+/ ใน rowText สุ่มสี่สุ่มห้า เพราะจะไปตรงกับ Tooltip "ATK +7", "HIT +1" หรือปุ่ม '+' กับตัวเลขจำนวน '1' (+\n1)
            const name = (itemName || (titleEl ? (titleEl.innerText || titleEl.textContent) : '') || '').trim();
            if (/^\s*\+\s*[1-9]\d*/.test(name)) return true;
            if (/\+\s*[1-9]\d*\s+[a-zA-Z\u0E00-\u0E7F]/.test(name)) return true;
            if (name.includes('ตีบวก')) return true;
            return false;
        }

        function hasSockets(itemName, rowText, titleEl) {
            // ของมีรูการ์ดจะมี [1], [2], [3], [4] อยู่ในชื่อไอเทม เช่น "Damascus [1]", "Crossbow [3]"
            const name = (itemName || (titleEl ? (titleEl.innerText || titleEl.textContent) : '') || '').trim();
            if (/\[\s*[1-4]\s*\]/.test(name)) return true;
            const text = (rowText || '');
            if (text.includes('ช่องการ์ด 1') || text.includes('ช่องการ์ด 2') || text.includes('ช่องการ์ด 3') || text.includes('ช่องการ์ด 4')) {
                return true;
            }
            return false;
        }

        // The game's item category of a bag item (same rule as its bag / shop tabs)
        function itemShopCategory(it) {
            if (!it) return null;
            const t = it.type, e = it.equipType;
            if (t === 'Card') return 'การ์ด';
            if (t === 'Equipment') return (e === 'Weapon' || e === 'Ammo') ? 'อาวุธ' : (e === 'Acc' || e === 'Gem') ? 'ประดับ/เจม' : 'ชุดเกราะ';
            if (t === 'Consumable') return 'ใช้ได้';
            if (t === 'Enchantment') return 'แร่/ตีบวก';
            if (t === 'Miscellaneous') return 'วัตถุดิบ';
            return 'อื่นๆ';
        }

        function findCategoryTab(catName) {
            // The bag window has the very same tabs ("อาวุธ 2" ...): clicking those left the shop list unchanged and
            // the bot judged the rows of another tab with this tab's rules. Look inside the shop window only.
            const shopWin = document.querySelector('.shop-window');
            if (shopWin) {
                const chip = Array.from(shopWin.querySelectorAll('.inv-tabs button, [role="tab"]'))
                    .find(b => (b.innerText || '').trim().startsWith(catName));
                if (chip) return chip;
            }
            const shopModal = shopWin || document.querySelector('.shop-window, [class*="shop"], .modal-body, .window') || document.body;
            const candidates = Array.from(shopModal.querySelectorAll('button, [role="tab"], [class*="tab"], li, div, span, a')).filter(el => {
                if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal')) return false;
                if (el.offsetWidth <= 0 || el.offsetHeight <= 0) return false;
                
                const txt = (el.innerText || el.textContent || '').trim();
                const searchKey = catName.includes('/') ? catName.split('/')[0] : catName;
                if (!txt.includes(catName) && !txt.includes(searchKey)) return false;
                if (txt.length > 25) return false;

                // กรอง container แม่ทิ้ง: ถ้ามีชื่อแท็บหมวดอื่นปนอยู่ แสดงว่าเป็นแถบแท็บรวม ไม่ใช่ตัวปุ่มแท็บ
                const knownTabs = ['ทั้งหมด', 'อาวุธ', 'ชุดเกราะ', 'ประดับ', 'ใช้ได้', 'การ์ด', 'แร่', 'วัตถุดิบ', 'อื่นๆ'];
                const overlap = knownTabs.filter(t => {
                    if (t === catName || catName.includes(t) || t.includes(catName) || t === searchKey) return false;
                    return txt.includes(t);
                }).length;
                if (overlap > 0) return false;

                return true;
            });

            if (candidates.length === 0) return null;

            candidates.sort((a, b) => {
                const aTxt = (a.innerText || a.textContent || '').trim();
                const bTxt = (b.innerText || b.textContent || '').trim();
                return aTxt.length - bTxt.length;
            });

            return candidates.find(el => el.tagName === 'BUTTON' || (el.className && el.className.includes('tab'))) || candidates[0];
        }

        function findItemRow(btn) {
            let curr = btn.parentElement;
            let bestRow = null;
            while (curr && curr !== document.body) {
                if (curr.classList.contains('shop-window') || curr.classList.contains('modal') || (curr.innerText && (curr.innerText.includes('ตะกร้าขาย') || curr.innerText.includes('General Goods')))) {
                    break;
                }
                const txt = (curr.innerText || '').trim();
                const h = curr.offsetHeight;
                
                // ตรวจสอบว่าคอนเทนเนอร์นี้มีราคา zeny และมีชื่อไอเทม (ไม่ใช่แค่ปุ่ม '+' หรือราคาอย่างเดียว)
                const hasZeny = /\d+[\s,]*z/i.test(txt);
                const cleanTxt = txt.replace(/\b\d+\s*z\b/gi, '').replace(/\boption\b/gi, '').replace(/\bออฟชั่น\b/gi, '').replace(/มี\s*\d+/g, '').replace(/[+\-0-9\s]/g, '');
                const hasItemName = cleanTxt.length >= 2;

                if (hasZeny && hasItemName && h >= 25 && h <= 130) {
                    bestRow = curr;
                    if (curr.querySelector('img, [class*="icon"], [class*="thumb"]')) {
                        return curr;
                    }
                }
                curr = curr.parentElement;
            }
            return bestRow || btn.closest('[class*="item"], [class*="row"], li, tr') || btn.parentElement?.parentElement || btn.parentElement;
        }

        function extractItemName(row) {
            if (!row) return '';

            // 0. ตรวจสอบจาก aria-label ของปุ่มใส่ตะกร้า (แม่นยำที่สุด 100% ในหน้าต่างร้านค้า Aetheria)
            const addBtnWithAria = row.querySelector('button[aria-label*="ใส่ตะกร้า"], [aria-label*="ใส่ตะกร้า"]');
            if (addBtnWithAria) {
                const aria = addBtnWithAria.getAttribute('aria-label') || '';
                const ariaClean = aria.replace(/ใส่ตะกร้า/gi, '').trim();
                if (ariaClean && ariaClean.length >= 2) {
                    return ariaClean;
                }
            }

            function cleanName(str) {
                if (!str) return '';
                return str.split('\n')[0]
                          .replace(/มี\s*(?:option|options|ออฟชั่น|ออปชั่น|ออฟ|opt).*/i, '')
                          .replace(/\b(?:option|options|ออฟชั่น|ออปชั่น)\b.*/i, '')
                          .replace(/\[\s*มี\s*(?:option|options|ออฟชั่น|ออปชั่น|opt)\s*\]/gi, '')
                          .replace(/\[\s*(?:ธรรมดา|ดี|หายาก|มหากาพย์|ตำนาน)\s*\]/gi, '')
                          .replace(/มี\s*\d+.*/, '')
                          .replace(/\bx\s*\d+\b.*/i, '')
                          .replace(/\b\d+[\s,]*z\b.*/i, '')
                          .trim();
            }

            // 1. ค้นหาจาก element ชื่อโดยตรง
            const nameEl = row.querySelector('[class*="name"], [class*="title"], h3, h4, h5, b, strong, .item-label');
            if (nameEl) {
                const cleaned = cleanName(nameEl.innerText || nameEl.textContent);
                if (cleaned && !/^\d+[\s,]*z$/i.test(cleaned) && !/^\d+$/.test(cleaned) && cleaned !== '+' && cleaned !== '-' && cleaned.length >= 2) {
                    return cleaned;
                }
            }

            // 2. ถ้าไม่พบ element เฉพาะ ให้แยกบรรทัดข้อความทั้งหมดในแถว
            const lines = (row.innerText || '').split('\n').map(s => s.trim()).filter(Boolean);
            for (const line of lines) {
                if (/^\d+$/.test(line)) continue;
                if (/^\d+[\s,]*z$/i.test(line)) continue;
                if (line === '+' || line === '-' || line === 'ทั้งหมด') continue;
                if (/^มี\s*\d+/.test(line) || /^x\s*\d+/i.test(line) || /^จำนวน/i.test(line)) continue;
                if (line.includes('ขาย') || line.includes('ราคา') || line.includes('น้ำหนัก')) continue;

                const cleaned = cleanName(line);
                if (cleaned.length <= 1) continue;
                if (cleaned === 'ธรรมดา' || cleaned === 'ดี' || cleaned === 'หายาก' || cleaned === 'มหากาพย์' || cleaned === 'ตำนาน') continue;
                return cleaned;
            }
            return '';
        }

        // 1. สลับไปแท็บ "ขาย" (เฉพาะปุ่มแท็บในหน้าต่างร้านค้า)
        const sellTabs = Array.from(document.querySelectorAll('button, div')).filter(el => {
            if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal')) return false;
            const txt = (el.innerText || '').trim();
            return txt === 'ขาย' && (el.closest('.shop-window') || el.closest('[class*="shop"]') || el.offsetHeight > 0);
        });
        const sellTab = sellTabs[0];
        if (sellTab) {
            triggerClick(sellTab);
            if (typeof sellTab.click === 'function') sellTab.click();
        }

        function processCategory(catName, isItemByItem, targetMaxRarity, onDone) {
            if (typeof targetMaxRarity === 'function') {
                onDone = targetMaxRarity;
                targetMaxRarity = sellCfg.maxRarityToSell || 'normal';
            }
            const rankMap = {
                'normal': 1, 'common': 1,
                'good': 2, 'magic': 2,
                'rare': 3,
                'epic': 4,
                'legendary': 5
            };
            const maxRank = rankMap[targetMaxRarity || 'normal'] || 1;
            const rankNames = { 1: 'ธรรมดา (ขาว 0 Option)', 2: 'ดี (เขียว 1 Option)', 3: 'หายาก (ฟ้า 2 Option)', 4: 'มหากาพย์ (ม่วง 3 Option)', 5: 'ตำนาน (ทอง/ส้ม 4+ Option)' };

            console.log(`[PmheeAether Shop] 🔍 ตรวจสอบหมวดหมู่: "${catName}" (เกณฑ์ขายไม่เกิน: ${rankNames[maxRank] || maxRank})...`);
            
            const catBtn = findCategoryTab(catName);
            if (!catBtn) {
                console.warn(`[PmheeAether Shop] ⚠️ ไม่พบปุ่มแท็บหมวดหมู่ "${catName}" ในร้านค้า -> ข้ามหมวดนี้ทันทีเพื่อความปลอดภัยเด็ดขาด!`);
                onDone();
                return;
            }

            const tabTitle = (catBtn.innerText || catBtn.textContent || '').trim();
            if (catBtn.disabled) {
                console.log(`[PmheeAether Shop] ℹ️ แท็บ "${tabTitle}" ไม่มีของ -> ข้าม`);
                onDone();
                return;
            }
            console.log(`%c[PmheeAether Shop] 🎯 พบคลิกแท็บหมวดหมู่: "${tabTitle}"`, 'color: #38bdf8; font-weight: bold;');
            catBtn.click();

            // รอ 600ms ให้หน้าร้านค้าเปลี่ยนรายการตามแท็บที่เลือก
            setTimeout(() => {
                const shopModal = document.querySelector('.shop-window') || document.querySelector('[class*="shop"]') || document.body;
                const shownTab = shopModal.querySelector('.inv-tabs button.active, .inv-tabs [aria-selected="true"]');
                if (shownTab && !(shownTab.innerText || '').trim().startsWith(catName)) {
                    console.warn(`[PmheeAether Shop] 🛑 ร้านยังแสดงแท็บ "${(shownTab.innerText || '').trim()}" ไม่ใช่ "${catName}" -> ข้ามหมวดนี้ (กันขายผิดหมวด)`);
                    onDone();
                    return;
                }

                // กฎเหล็ก: ป้องกันการขายมั่วในขณะที่หน้าร้านค้าเปิดค้างที่แท็บ 'การ์ด' หรือ 'ทั้งหมด'
                const activeTab = shopModal.querySelector('[class*="active"], [class*="selected"], [aria-selected="true"], .tab.active, button.active');
                const activeText = (activeTab ? (activeTab.innerText || activeTab.textContent || '') : '').trim();
                if (activeText.includes('การ์ด') || activeText.includes('แร่') || activeText.includes('ใช้ได้') || activeText.startsWith('ทั้งหมด')) {
                    console.warn(`[PmheeAether Shop] 🛑 หน้าร้านค้ากำลังแสดงแท็บ "${activeText}" (ไม่ใช่หมวด ${catName}) -> ข้ามทันทีเพื่อความปลอดภัยเด็ดขาด!`);
                    onDone();
                    return;
                }
                if (!isItemByItem) {
                    // หมวด "วัตถุดิบ": คลิก "ใส่วัตถุดิบทั่งหมดลงตะกร้า" (button.shop-sell-junk)
                    const putAllBtn = document.querySelector('button.shop-sell-junk') ||
                        Array.from(document.querySelectorAll('button')).find(el => {
                            if (el.closest('#pelican-hud')) return false;
                            const t = (el.innerText || '').trim();
                            return t.includes('ใส่วัตถุดิบ') || t.includes('ขายขยะ');
                        });
                    
                    if (putAllBtn && !putAllBtn.disabled && !putAllBtn.className.includes('disabled') && !putAllBtn.innerText.includes('0 รายการ') && !putAllBtn.innerText.includes('ไม่มีวัตถุดิบ')) {
                        console.log('%c[PmheeAether Shop] 🧺 คลิก "ใส่วัตถุดิบทั่งหมดลงตะกร้า"...', 'color: #eab308; font-weight: bold;');
                        triggerClick(putAllBtn);
                        if (typeof putAllBtn.click === 'function') putAllBtn.click();
                    } else {
                        console.log('[PmheeAether Shop] ℹ️ ไม่มีวัตถุดิบขยะให้ขายในกระเป๋า');
                    }
                    setTimeout(onDone, 400);
                } else {
                    // หมวด "อาวุธ", "ชุดเกราะ", หรือ "ประดับ/เจม": กรองตาม Whitelist, ระดับ Rarity, ตีบวก, รูการ์ด, และ Option
                    const shopModal = document.querySelector('.shop-window, [class*="shop"]') || document.body;
                    const plusBtns = Array.from(shopModal.querySelectorAll('button, div')).filter(b => {
                        if (b.closest('#pelican-hud') || b.closest('#pelican-data-modal')) return false;
                        const txt = (b.innerText || '').trim();
                        if (txt !== '+') return false;
                        if (b.offsetWidth <= 0 || b.offsetHeight <= 0) return false;
                        const row = findItemRow(b);
                        if (!row || row.offsetWidth <= 0 || row.offsetHeight <= 0) return false;
                        try {
                            const rowStyle = window.getComputedStyle(row);
                            if (rowStyle.display === 'none' || rowStyle.visibility === 'hidden' || rowStyle.opacity === '0') return false;
                            const btnStyle = window.getComputedStyle(b);
                            if (btnStyle.display === 'none' || btnStyle.visibility === 'hidden' || btnStyle.opacity === '0') return false;
                        } catch(e) {}
                        return true;
                    });

                    console.log(`[PmheeAether Shop] 🔎 พบปุ่มขาย (+) ในหมวด "${catName}" ทั้งหมด ${plusBtns.length} ปุ่ม`);

                    const itemsToSell = [];
                    // The game renders each sell row with React key = bag slot -> read the exact item of this row
                    function getShopRowSlot(btn) {
                        const rowEl = btn && btn.closest ? btn.closest('.shop-row') : null;
                        if (!rowEl) return null;
                        const fk = Object.keys(rowEl).find(k => k.startsWith('__reactFiber'));
                        const key = fk && rowEl[fk] ? rowEl[fk].key : null;
                        return key != null && /^\d+$/.test(String(key)) ? Number(key) : null;
                    }

                    function findMatchingBagItem(targetName, rText, tEl, btn) {
                        const bagItems = (typeof window.getBagItems === 'function') ? window.getBagItems() : [];
                        if (!bagItems || bagItems.length === 0) return null;
                        const baseTarget = normalizeItemBaseName(targetName).toLowerCase();
                        const sameName = b => normalizeItemBaseName(b.name).toLowerCase() === baseTarget || b.name.toLowerCase() === targetName.toLowerCase();

                        const slot = getShopRowSlot(btn);
                        if (slot !== null) {
                            const b = bagItems.find(x => Number(x.slot) === slot);
                            if (b && sameName(b)) return b.raw || b;
                        }

                        // Fallback (row slot unknown): several bag items share this name, so only decide when they
                        // would all get the same filter result -- otherwise return null = keep it (safe side)
                        const isRowRef = isRefined(targetName, rText, tEl);
                        const hasRowSock = hasSockets(targetName, rText, tEl);
                        const candidates = bagItems.filter(b => sameName(b)
                            && !(isRowRef && !(b.refine > 0))
                            && !(hasRowSock && !(b.raw && b.raw.slots > 0)));
                        if (candidates.length === 0) return null;
                        const results = candidates.map(b => window.checkItemStatsFilter(b.raw || b).pass);
                        if (results.some(r => r !== results[0])) {
                            console.log(`[PmheeAether Shop] ⚠️ "${targetName}" มีหลายชิ้นที่ออฟชั่นต่างกันและระบุแถวไม่ได้ -> เก็บไว้ก่อน`);
                            return null;
                        }
                        return candidates[0].raw || candidates[0];
                    }

                    plusBtns.forEach((btn, btnIdx) => {
                        const row = findItemRow(btn);
                        if (!row) {
                            console.warn(`[PmheeAether Shop] ⚠️ ข้ามปุ่ม (+) ลำดับที่ ${btnIdx + 1}: ไม่พบ Item Row`);
                            return;
                        }

                        const rowText = row.innerText || '';
                        const itemName = extractItemName(row);
                        if (!itemName) {
                            console.warn(`[PmheeAether Shop] ⚠️ ข้ามปุ่ม (+) ลำดับที่ ${btnIdx + 1}: ไม่สามารถอ่านชื่อไอเทมจากแถวได้ (${rowText.replace(/\n+/g, ' | ')})`);
                            return;
                        }

                        const titleEl = row.querySelector('[class*="name"], [class*="title"], h3, h4, h5, b, strong, .item-label') || 
                                        Array.from(row.querySelectorAll('*')).find(el => (el.innerText || '').trim() === itemName) || row;

                        // The row's real item (bag slot = React key of the row) must belong to this tab
                        const rowSlot = getShopRowSlot(btn);
                        const rowItem = rowSlot === null ? null : ((typeof window.getBagItems === 'function' ? window.getBagItems() : []).find(x => Number(x.slot) === rowSlot) || null);
                        const rowCat = rowItem ? itemShopCategory(rowItem.raw || rowItem) : null;
                        if (rowCat && rowCat !== catName) {
                            console.warn(`[PmheeAether Shop] 🛑 "${itemName}" เป็นหมวด "${rowCat}" ไม่ใช่ "${catName}" -> ข้าม`);
                            return;
                        }
                        if (rowItem && typeof window.isGearKeptItem === 'function' && window.isGearKeptItem(rowItem.raw || rowItem)) {
                            console.log(`[PmheeAether Shop] 🔒 [เซ็ตอุปกรณ์] เก็บไว้ใส่ตามแผน: "${itemName}"`);
                            return;
                        }
                        if (typeof window.isStashOnlyItem === 'function' && (window.isStashOnlyItem(rowItem ? (rowItem.raw || rowItem) : null) || window.isStashOnlyItem(itemName))) {
                            console.log(`%c[PmheeAether Shop] 🔒 [เก็บเข้าคลังอย่างเดียว] ห้ามขายเด็ดขาด: "${itemName}"`, 'color: #38bdf8; font-weight: bold;');
                            return;
                        }

                        // กฎความปลอดภัย 0 (กฎเหล็กสูงสุด): ห้ามขาย "การ์ด (Card)" หรือ "แร่/ตีบวก (Ores/Refine)" เด็ดขาด 100%!
                        const lower = itemName.toLowerCase();
                        const isCard = (catName !== 'อาวุธ' && catName !== 'ชุดเกราะ') && (
                            lower.endsWith(' card') || lower.startsWith('card ') || lower === 'card' || lower.includes('การ์ด') || 
                            rowText.includes('การ์ด') || rowText.includes('card') ||
                            (row.querySelector('img') && (row.querySelector('img').src || '').includes('card'))
                        );

                        // แร่ตีบวก: เช็คเฉพาะถ้าไม่ใช่หมวดอาวุธ/ชุดเกราะ และต้องเป็นชื่อแร่จริง (ไม่ใช่ชื่ออุปกรณ์เช่น Iron Cain, Steel Shield, Oridecon Dagger)
                        const oreExactList = ['iron', 'iron ore', 'steel', 'phracon', 'emveretarcon', 'oridecon', 'rough oridecon', 'elunium', 'rough elunium', 'enriched elunium', 'refine shard', 'blacksmith blessing', 'enchant rune', 'accessory enchant rune', 'gold'];
                        const isOre = (catName !== 'อาวุธ' && catName !== 'ชุดเกราะ') && (
                            oreExactList.includes(lower) || lower === 'แร่เหล็ก' || lower === 'เหล็ก' || lower === 'โอริเดคอน' || lower === 'อีลูเนียม' || 
                            rowText.includes('แร่/ตีบวก')
                        );

                        if (isCard) {
                            console.log(`%c[PmheeAether Shop] 🛑 [การ์ดมีค่า!] ป้องกันการขายเด็ดขาด: "${itemName}"`, 'color: #ef4444; font-weight: bold;');
                            return;
                        }
                        if (isOre) {
                            console.log(`%c[PmheeAether Shop] 🛑 [แร่ตีบวก!] ป้องกันการขายเด็ดขาด: "${itemName}"`, 'color: #f59e0b; font-weight: bold;');
                            return;
                        }

                        // กฎความปลอดภัย 1: ห้ามขายของใช้ / ใบวาร์ป / ยา / ลูกธนู (Consumables / Ammo) เด็ดขาด
                        const isGem = lower.includes('gem') || lower.includes('เจม') || rowText.includes('ประเภท เจม') || rowText.includes('ช่องเจม');
                        const isTeleportWing = lower.includes('fly wing') || lower.includes('butterfly wing') || lower === 'wing' || lower.includes('ใบวาร์ป');
                        const isPotion = lower.includes('potion') || lower.includes('ขวดยา');
                        // ข้อสำคัญ: เจมของ Archer/Hunter มักมีชื่อสกิล เช่น "Dancing Arrow Gem", "Arrow Shower Gem" ห้ามกรองทิ้งเป็นลูกธนูจริง
                        const isActualArrow = (lower.includes('arrow') || lower.includes('ลูกธนู')) && !isGem && !lower.includes('bow');

                        if (isTeleportWing || isPotion || isActualArrow) {
                            console.log(`[PmheeAether Shop] 🛑 [ของใช้/เสบียง] ข้าม: "${itemName}"`);
                            return;
                        }

                        // กฎความปลอดภัย 1.5: ล็อกป้องกันเจมสกิลทุกชนิดเด็ดขาด (Gem Safe Guard)
                        if (isGem && (sellCfg.statsFilter?.protectGems !== false)) {
                            console.log(`%c[PmheeAether Shop] 💎 [Gem Protected] ป้องกันเจมสกิลเด็ดขาด (ห้ามขาย): "${itemName}"`, 'color: #a855f7; font-weight: bold;');
                            return;
                        }

                        // กฎความปลอดภัย 2: Whitelist & Smart Stats Filter
                        // When the option filter judged a whitelisted item "not worth keeping", that verdict is final:
                        // the rarity cap and the option/socket locks below must not keep it again (they always would for
                        // rare gear, e.g. a หายาก Gakkung Bow without random DEX). Refined items and inserted cards still win.
                        let filterSellItem = null;
                        if (isWhitelisted(itemName)) {
                            const sf = sellCfg.statsFilter;
                            if (sf && sf.enabled) {
                                const bagItem = findMatchingBagItem(itemName, rowText, titleEl, btn);
                                if (bagItem) {
                                    const statRes = window.checkItemStatsFilter(bagItem);
                                    if (statRes.pass) {
                                        console.log(`%c[PmheeAether Shop] 🔒 [Whitelist Pass] เก็บไอเทม: "${itemName}" (${statRes.reason} | ${statRes.matchedCount || 0} ออฟชั่นตรงเกณฑ์)`, 'color: #38bdf8; font-weight: bold;');
                                        return; // ผ่านเกณฑ์ -> ห้ามขายเด็ดขาด!
                                    } else {
                                        const randomOpts = (bagItem.affixes || []).map(a => `${a.type}${a.mode === 'increasedPercent' ? '%' : ''}+${a.value}`).join(', ') || 'ไม่มี';
                                        console.log(`%c[PmheeAether Shop] 🗑️ [Whitelist Filtered] "${itemName}" ออฟสุ่ม [${randomOpts}] ไม่ตรงเกณฑ์ (${statRes.reason}) -> ขาย`, 'color: #f59e0b; font-weight: bold;');
                                        filterSellItem = bagItem;
                                    }
                                } else {
                                    console.log(`[PmheeAether Shop] 🔒 [Whitelist Safe] ข้าม: "${itemName}" (ไม่พบข้อมูลในกระเป๋า ปลอดภัยไว้ก่อน)`);
                                    return;
                                }
                            } else {
                                console.log(`[PmheeAether Shop] 🔒 [Whitelist] ข้าม: "${itemName}"`);
                                return;
                            }
                        }

                        if (filterSellItem) {
                            const hasCard = Array.isArray(filterSellItem.cards) && filterSellItem.cards.some(Boolean);
                            if (sellCfg.keepRefined && (filterSellItem.refine || 0) > 0) {
                                console.log(`[PmheeAether Shop] 🔒 [ของตีบวก] เก็บ: "${itemName}" +${filterSellItem.refine}`);
                                return;
                            }
                            if (hasCard) {
                                console.log(`[PmheeAether Shop] 🔒 [มีการ์ดใส่อยู่] เก็บ: "${itemName}"`);
                                return;
                            }
                            console.log(`%c[PmheeAether Shop] 🛒 เลือกขาย (ตามตัวกรองออฟชั่น): "${itemName}"`, 'color: #22c55e;');
                            itemsToSell.push({ name: itemName, btn: btn, row: row });
                            return;
                        }

                        // กฎความปลอดภัย 3: กรองระดับความหายาก (Rarity ตามเกณฑ์เฉพาะของหมวดนี้: ธรรมดา, ดี, หายาก, มหากาพย์, ตำนาน)
                        const rarityRank = getItemRarity(itemName, rowText, titleEl, row);

                        if (rarityRank > maxRank) {
                            console.log(`[PmheeAether Shop] 🔒 [ระดับสูง] ข้าม: "${itemName}" (ระดับ: ${rankNames[rarityRank] || rarityRank} > เกณฑ์ที่เลือก: ${rankNames[maxRank]})`);
                            return;
                        }

// (กฎ 4-6 ควบคุมการล็อกตีบวก / รูการ์ด / Option ตามที่ผู้เล่นติ๊กเลือกใน UI โดยตรง)

                        // กฎความปลอดภัย 4: ห้ามขายของตีบวก (+1 ขึ้นไป)
                        if (sellCfg.keepRefined && isRefined(itemName, rowText, titleEl)) {
                            console.log(`[PmheeAether Shop] 🔒 [ของตีบวก] ข้ามไอเทมตีบวก: "${itemName}"`);
                            return;
                        }

                        // กฎความปลอดภัย 5: ห้ามขายของมีรูการ์ด [1-4]
                        if (sellCfg.keepSockets && hasSockets(itemName, rowText, titleEl)) {
                            console.log(`[PmheeAether Shop] 🔒 [มีรูการ์ด] ข้ามไอเทมมีรู: "${itemName}"`);
                            return;
                        }

                        // กฎความปลอดภัย 6: ห้ามขายของมี Option สุ่ม (เฉพาะเมื่อผู้เล่นติ๊ก "ล็อคของมี Option")
                        if (sellCfg.keepSpecial && hasOptions(rowText, row)) {
                            console.log(`[PmheeAether Shop] 🔒 [มี Option] ข้ามไอเทม: "${itemName}" (เนื่องจากติ๊ก 'ล็อคของมี Option')`);
                            return;
                        }

                        console.log(`%c[PmheeAether Shop] 🛒 เลือกขาย: "${itemName}" (ระดับ: ${rankNames[rarityRank] || rarityRank})`, 'color: #22c55e;');
                        itemsToSell.push({ name: itemName, btn: btn, row: row });
                    });

                    if (itemsToSell.length === 0) {
                        console.log(`[PmheeAether Shop] ℹ️ ไม่มีไอเทมในหมวด "${catName}" ที่ตรงตามเงื่อนไขการขาย`);
                        setTimeout(onDone, 300);
                        return;
                    }

                    console.log(`%c[PmheeAether Shop] 📋 เตรียมใส่ไอเทมลงตะกร้า ${itemsToSell.length} ชิ้น...`, 'color: #22c55e; font-weight: bold;');

                    // คลิกปุ่ม '+' ทีละชิ้นอย่างต่อเนื่อง (เว้นจังหวะ 130ms เพื่อให้ UI อัปเดตเสถียร)
                    let clickIdx = 0;
                    function stepClick() {
                        if (clickIdx >= itemsToSell.length) {
                            setTimeout(onDone, 500);
                            return;
                        }
                        const item = itemsToSell[clickIdx++];
                        console.log(`%c[PmheeAether Shop] ➕ ใส่ไอเทมลงตะกร้า (${clickIdx}/${itemsToSell.length}): "${item.name}"`, 'color: #22c55e;');
                        triggerClick(item.btn);
                        if (typeof item.btn.click === 'function') item.btn.click();
                        setTimeout(stepClick, 130);
                    }
                    stepClick();
                }
            }, 600);
        }

        // Stacked items the game's "ใส่วัตถุดิบทั้งหมดลงตะกร้า" button leaves out: materials it labels "หายาก",
        // "Life" materials (shown in the อื่นๆ tab) and, when enabled, refine ores. Every row is matched to its
        // bag item by slot (React key of .shop-row) and only sold when the item's real type is in `types`,
        // it isn't whitelisted, refined, carded or has options.
        function shopRowSlotOf(rowEl) {
            const fk = rowEl ? Object.keys(rowEl).find(k => k.startsWith('__reactFiber')) : null;
            const key = fk && rowEl[fk] ? rowEl[fk].key : null;
            return key != null && /^\d+$/.test(String(key)) ? Number(key) : null;
        }

        // One click only: triggerClick fires several click paths, which would add a stack to the cart more than once
        function clickOnce(el) {
            const pk = Object.keys(el).find(k => k.startsWith('__reactProps'));
            if (pk && el[pk] && typeof el[pk].onClick === 'function') el[pk].onClick({ stopPropagation() {}, preventDefault() {} });
            else el.click();
        }

        function setShopCartSlotQty(slot, desiredQty) {
            const shopModal = document.querySelector('.shop-window') || document.body;
            const targetKey = 's' + Number(slot);
            const lines = Array.from(shopModal.querySelectorAll('.cart-line'));
            const lineEl = lines.find(el => {
                const fk = Object.keys(el).find(k => k.startsWith('__reactFiber'));
                return fk && el[fk] && String(el[fk].key) === targetKey;
            });
            if (!lineEl) return false;
            if (desiredQty <= 0) {
                const rmBtn = lineEl.querySelector('button.cart-remove');
                if (rmBtn) { clickOnce(rmBtn); return true; }
            }
            const stepper = lineEl.querySelector('.qty-stepper') || lineEl.querySelector('input');
            if (stepper) {
                const fk = Object.keys(stepper).find(k => k.startsWith('__reactFiber'));
                let f = fk ? stepper[fk] : null;
                while (f) {
                    const mp = f.memoizedProps;
                    if (mp && typeof mp.onChange === 'function' && (typeof mp.max === 'number' || typeof mp.value === 'number')) {
                        mp.onChange(desiredQty);
                        return true;
                    }
                    f = f.return;
                }
                const inp = lineEl.querySelector('input');
                if (inp) {
                    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set;
                    if (setter) setter.call(inp, String(desiredQty));
                    else inp.value = String(desiredQty);
                    inp.dispatchEvent(new Event('input', { bubbles: true }));
                    inp.dispatchEvent(new Event('change', { bubbles: true }));
                    inp.dispatchEvent(new Event('blur', { bubbles: true }));
                    return true;
                }
            }
            return false;
        }

        function enforceGuildDonationReserveInShopCart() {
            const shopModal = document.querySelector('.shop-window') || document.body;
            const bag = (typeof window.getBagItems === 'function') ? window.getBagItems() : [];
            const bySlot = {};
            bag.forEach(b => { bySlot[Number(b.slot)] = b; });
            shopModal.querySelectorAll('.cart-line').forEach(lineEl => {
                const fk = Object.keys(lineEl).find(k => k.startsWith('__reactFiber'));
                const key = fk && lineEl[fk] ? String(lineEl[fk].key || '') : '';
                if (!/^s\d+$/.test(key)) return;
                const slot = Number(key.slice(1));
                const b = bySlot[slot];
                const raw = b ? (b.raw || b) : null;
                if (!raw) return;
                const rawId = Number(raw.itemId || raw.id || (b && b.id) || 0);
                const rawLower = String(raw.name || '').trim().toLowerCase();
                if (rawId === 90340 || rawId === 90341 || rawLower === 'enchant rune' || rawLower === 'accessory enchant rune') {
                    console.log(`%c[PmheeAether Shop] 🏛️ [หินออฟกิลด์] เอา "${raw.name}" ออกจากตะกร้าขายเด็ดขาด`, 'color: #a855f7; font-weight: bold;');
                    setShopCartSlotQty(slot, 0);
                    return;
                }
                const gdInfo = window.getGuildDonationSlotSellableQty(slot, bag, b);
                if (gdInfo.reserveQty <= 0) return;
                if (isWhitelisted(raw.name) || gdInfo.sellableQty <= 0) {
                    console.log(`%c[PmheeAether Shop] 🏛️ [ของบริจาคกิลด์] เอา "${raw.name}" ออกจากตะกร้าขาย (เก็บสำรองไว้บริจาค ${gdInfo.reserveQty} ชิ้น)`, 'color: #38bdf8; font-weight: bold;');
                    setShopCartSlotQty(slot, 0);
                } else if (gdInfo.keepQty > 0) {
                    console.log(`%c[PmheeAether Shop] 🏛️ [ของบริจาคกิลด์] ปรับจำนวนขาย "${raw.name}" เหลือ ${gdInfo.sellableQty} ชิ้น (เก็บสำรองไว้บริจาค ${gdInfo.keepQty} ชิ้น)`, 'color: #38bdf8; font-weight: bold;');
                    setShopCartSlotQty(slot, gdInfo.sellableQty);
                }
            });
        }

        function processStackCategory(catName, types, onDone) {
            const catBtn = findCategoryTab(catName);
            if (!catBtn) {
                console.log(`[PmheeAether Shop] ℹ️ ไม่พบแท็บ "${catName}" -> ข้าม`);
                onDone();
                return;
            }
            clickOnce(catBtn);

            setTimeout(() => {
                const bag = (typeof window.getBagItems === 'function') ? window.getBagItems() : [];
                const bySlot = {};
                bag.forEach(b => { bySlot[Number(b.slot)] = b; });
                const shopModal = document.querySelector('.shop-window') || document.body;
                const picks = [];
                shopModal.querySelectorAll('.shop-row').forEach(row => {
                    if (row.classList.contains('sold-out') || row.classList.contains('in-cart')) return;
                    const slot = shopRowSlotOf(row);
                    const b = slot !== null ? bySlot[slot] : null;
                    const raw = b ? (b.raw || b) : null;
                    if (!raw || !types.includes(raw.type)) return;
                    if (raw.locked || (b && b.locked)) return;
                    const rawId = Number(raw.itemId || raw.id || (b && b.id) || 0);
                    const rawLower = String(raw.name || '').trim().toLowerCase();
                    if (rawId === 90340 || rawId === 90341 || rawLower === 'enchant rune' || rawLower === 'accessory enchant rune') {
                        console.log(`%c[PmheeAether Shop] 🏛️ [หินออฟกิลด์] ห้ามขายเด็ดขาด: "${raw.name}"`, 'color: #a855f7; font-weight: bold;');
                        return;
                    }
                    if (rawId === 90311 || rawId === 90310 || rawLower.includes('butterfly wing') || rawLower.includes('fly wing') || rawLower.includes('rebirth feather') || rawLower.includes('token')) {
                        console.log(`[PmheeAether Shop] 🔒 [ของใช้จำเป็น] เก็บไว้ใช้งาน: "${raw.name}"`);
                        return;
                    }
                    if (window.__buffPotionConfig && window.__buffPotionConfig[rawId] && window.__buffPotionConfig[rawId].enabled) {
                        console.log(`[PmheeAether Shop] 🧪 [ยาบัพที่เปิดใช้งาน] เก็บไว้กินอัตโนมัติ: "${raw.name}"`);
                        return;
                    }
                    if (typeof isItemOnMarketSellList === 'function' && isItemOnMarketSellList(raw)) {
                        console.log(`[PmheeAether Shop] 🏷️ [รายการขายตลาดกลาง] เก็บไว้ลงขายตลาดกลาง: "${raw.name}"`);
                        return;
                    }
                    if (typeof window.isStashOnlyItem === 'function' && window.isStashOnlyItem(raw)) {
                        console.log(`%c[PmheeAether Shop] 🔒 [เก็บเข้าคลังอย่างเดียว] ห้ามขายเด็ดขาด: "${raw.name}"`, 'color: #38bdf8; font-weight: bold;');
                        return;
                    }
                    if ((raw.refine || 0) > 0 || (Array.isArray(raw.affixes) && raw.affixes.length) || (raw.cards && raw.cards.some(Boolean))) return;
                    if (isWhitelisted(raw.name)) {
                        console.log(`[PmheeAether Shop] 🔒 [Whitelist] เก็บ: "${raw.name}"`);
                        return;
                    }
                    if (typeof window.isGearKeptItem === 'function' && window.isGearKeptItem(raw)) {
                        console.log(`[PmheeAether Shop] 🔒 [เซ็ตอุปกรณ์] เก็บไว้ตีบวก: "${raw.name}" x${raw.qty || 1} (เก็บสูงสุดไม่เกิน ${window.GEAR_ORE_MAX_KEEP || 100} ก้อน)`);
                        return;
                    }
                    const gdInfo = window.getGuildDonationSlotSellableQty(slot, bag, b);
                    if (gdInfo.reserveQty > 0 && gdInfo.sellableQty <= 0) {
                        if (gdInfo.reserveSource === 'gear') {
                            console.log(`[PmheeAether Shop] 🔒 [เซ็ตอุปกรณ์] เก็บไว้ตีบวก: "${raw.name}" x${raw.qty || 1} (เก็บสำรองสูงสุด ${gdInfo.reserveQty} ก้อน)`);
                        } else {
                            console.log(`%c[PmheeAether Shop] 🏛️ [ของบริจาคกิลด์] เก็บสำรองไว้บริจาคกิลด์รายวัน: "${raw.name}" x${raw.qty || 1} (สำรอง ${gdInfo.reserveQty} ชิ้น)`, 'color: #38bdf8; font-weight: bold;');
                        }
                        return;
                    }
                    const allBtn = row.querySelector('button.cart-all');
                    const addBtn = row.querySelector('button.cart-add');
                    const btn = (allBtn && !allBtn.disabled) ? allBtn : addBtn;
                    if (!btn || btn.disabled) return;
                    const sellQty = gdInfo.reserveQty > 0 ? gdInfo.sellableQty : (raw.qty || 1);
                    picks.push({ name: raw.name, slot, qty: sellQty, totalSlotQty: raw.qty || 1, keepQty: gdInfo.keepQty || 0, reserveSource: gdInfo.reserveSource || 'guild', btn });
                });

                if (!picks.length) {
                    console.log(`[PmheeAether Shop] ℹ️ แท็บ "${catName}": ไม่มีของที่ต้องขายเพิ่ม`);
                    setTimeout(onDone, 300);
                    return;
                }
                let i = 0;
                (function step() {
                    if (i >= picks.length) { setTimeout(onDone, 500); return; }
                    const p = picks[i++];
                    if (p.keepQty > 0) {
                        if (p.reserveSource === 'gear') {
                            console.log(`%c[PmheeAether Shop] ➕ ใส่ตะกร้าส่วนเกินแร่เซ็ตอุปกรณ์ (${catName}): "${p.name}" ขาย ${p.qty}/${p.totalSlotQty} ก้อน (เก็บสำรองไว้ตีบวก ${p.keepQty} ก้อน)`, 'color: #22c55e;');
                        } else {
                            console.log(`%c[PmheeAether Shop] ➕ ใส่ตะกร้าส่วนเกินของบริจาคกิลด์ (${catName}): "${p.name}" ขาย ${p.qty}/${p.totalSlotQty} ชิ้น (เก็บสำรองบริจาค ${p.keepQty} ชิ้น)`, 'color: #22c55e;');
                        }
                    } else {
                        console.log(`%c[PmheeAether Shop] ➕ ใส่ตะกร้า (${catName}): "${p.name}" x${p.qty}`, 'color: #22c55e;');
                    }
                    clickOnce(p.btn);
                    if (p.keepQty > 0 && p.slot !== null) {
                        setTimeout(() => {
                            setShopCartSlotQty(p.slot, p.qty);
                            setTimeout(step, 120);
                        }, 80);
                    } else {
                        setTimeout(step, 150);
                    }
                })();
            }, 600);
        }

        setTimeout(() => {
            const steps = [];
            if (sellCfg.sellMaterials) {
                steps.push((next) => processCategory('วัตถุดิบ', false, 'all', next));
                // "ขายขยะทั้งหมด" also sells what the game's junk button skips (rare-labelled / Life materials)
                if (sellCfg.materialMode !== 'common') {
                    steps.push((next) => processStackCategory('วัตถุดิบ', ['Miscellaneous'], next));
                    steps.push((next) => processStackCategory('อื่นๆ', ['Life', 'Miscellaneous'], next));
                }
            }
            if (sellCfg.sellRefineOres) {
                steps.push((next) => processStackCategory('แร่/ตีบวก', ['Enchantment'], next));
            }
            if (sellCfg.sellConsumables) {
                steps.push((next) => processStackCategory('ใช้ได้', ['Consumable'], next));
            }
            if (sellCfg.weaponRarity && sellCfg.weaponRarity !== 'none') {
                steps.push((next) => processCategory('อาวุธ', true, sellCfg.weaponRarity, next));
            } else if (sellCfg.sellWeapons && (!sellCfg.weaponRarity || sellCfg.weaponRarity === 'none')) {
                steps.push((next) => processCategory('อาวุธ', true, sellCfg.maxRarityToSell || 'normal', next));
            }

            if (sellCfg.armorRarity && sellCfg.armorRarity !== 'none') {
                steps.push((next) => processCategory('ชุดเกราะ', true, sellCfg.armorRarity, next));
            } else if (sellCfg.sellArmors && (!sellCfg.armorRarity || sellCfg.armorRarity === 'none')) {
                steps.push((next) => processCategory('ชุดเกราะ', true, sellCfg.maxRarityToSell || 'normal', next));
            }

            if (sellCfg.accRarity && sellCfg.accRarity !== 'none') {
                steps.push((next) => processCategory('ประดับ/เจม', true, sellCfg.accRarity, next));
            }

            function runSteps(idx) {
                if (idx >= steps.length) {
                    enforceGuildDonationReserveInShopCart();
                    setTimeout(() => {
                        if (typeof window.isStashOnlyItem === 'function') {
                            document.querySelectorAll('.cart-line').forEach(line => {
                                const nameEl = line.querySelector('.cart-name');
                                const rawTxt = nameEl ? (nameEl.innerText || nameEl.textContent || '') : '';
                                const cleanTxt = rawTxt.replace(/\s*x\d+\s*$/i, '').trim();
                                if (cleanTxt && window.isStashOnlyItem(cleanTxt)) {
                                    const rmBtn = line.querySelector('button.cart-rm, button.cart-remove');
                                    if (rmBtn) {
                                        console.log(`%c[PmheeAether Shop] 🔒 นำ "${cleanTxt}" ออกจากตะกร้าขาย (โหมดเก็บเข้าคลังอย่างเดียว)`, 'color: #38bdf8; font-weight: bold;');
                                        clickOnce(rmBtn);
                                    }
                                }
                            });
                        }

                        const confirmBtn = document.querySelector('button.cart-go') ||
                            Array.from(document.querySelectorAll('button')).find(el => {
                                if (el.closest('#pelican-hud')) return false;
                                return (el.innerText || '').includes('ตรวจสอบและขาย') && el.offsetWidth > 0;
                            });

                        if (confirmBtn && !confirmBtn.disabled && !confirmBtn.className.includes('disabled')) {
                            console.log('%c[PmheeAether Shop] 💵 คลิก "ตรวจสอบและขาย" (cart-go)...', 'color: #22c55e; font-weight: bold;');
                            triggerClick(confirmBtn);
                            if (typeof confirmBtn.click === 'function') confirmBtn.click();

                            // รอให้หน้าต่าง Modal "ยืนยันการขาย" เด้งขึ้นมา แล้วกดปุ่ม "ยืนยันขาย" สีทอง
                            if (window.__shopConfirmInterval) {
                                clearInterval(window.__shopConfirmInterval);
                                window.__shopConfirmInterval = null;
                            }

                            let confirmAttempts = 0;
                            window.__shopConfirmInterval = setInterval(() => {
                                if (!window.__isBotRunning && !window.__isManualSelling) {
                                    clearInterval(window.__shopConfirmInterval);
                                    window.__shopConfirmInterval = null;
                                    return;
                                }

                                confirmAttempts++;

                                // 1. หาปุ่มที่มีคำว่า "ยืนยันขาย" โดยตรง
                                let finalBtn = Array.from(document.querySelectorAll('button')).find(b => {
                                    if (b.closest('#pelican-hud')) return false;
                                    const txt = (b.innerText || '').trim();
                                    return (txt === 'ยืนยันขาย' || txt.includes('ยืนยันขาย')) && b.offsetWidth > 0;
                                });

                                // 2. ถ้าไม่พบตรงๆ ให้หาจากกล่อง Modal ยืนยันการขาย (ไม่เอากล่องร้านหลัก)
                                if (!finalBtn) {
                                    const confirmModal = Array.from(document.querySelectorAll('div, section, aside')).find(el => {
                                        if (el.closest('#pelican-hud')) return false;
                                        const t = el.innerText || '';
                                        return t.includes('ยืนยันการขาย') && (t.includes('ยกเลิก') || t.includes('รวมที่ได้รับ'));
                                    });
                                    if (confirmModal) {
                                        finalBtn = Array.from(confirmModal.querySelectorAll('button')).find(b => {
                                            if (b.closest('#pelican-hud')) return false;
                                            const txt = (b.innerText || '').trim();
                                            return txt.includes('ยืนยัน') && !txt.includes('ยกเลิก') && b.offsetWidth > 0;
                                        });
                                    }
                                }

                                if (finalBtn) {
                                    clearInterval(window.__shopConfirmInterval);
                                    window.__shopConfirmInterval = null;
                                    try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {}
                                    console.log('%c[PmheeAether Shop] 💰 พบปุ่ม "ยืนยันขาย" สีทองตัวจริง กำลังกดยืนยัน...', 'color: #22c55e; font-weight: bold;', finalBtn);
                                    triggerClick(finalBtn);
                                    if (typeof finalBtn.click === 'function') finalBtn.click();
                                    const inner = finalBtn.querySelector('button, span, div') || finalBtn;
                                    if (typeof inner.click === 'function') inner.click();
                                    setTimeout(() => { try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {} }, 250);
                                    setTimeout(() => { try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {} }, 500);

                                    // รอให้ Modal ปิดลงและระบบบันทึกเงิน Zeny จากนั้นสลับกลับไปแท็บ "ซื้อ"
                                    setTimeout(() => {
                                        try { if (typeof window.getLiveCharacterData === 'function') window.getLiveCharacterData(true); } catch (_) {}
                                        if (!window.__isBotRunning && !window.__isManualSelling) return;
                                        const buyTabs = Array.from(document.querySelectorAll('button, div')).filter(el => {
                                            if (el.closest('#pelican-hud')) return false;
                                            return (el.innerText || '').trim() === 'ซื้อ' && (el.closest('.shop-window') || el.closest('[class*="shop"]') || el.offsetHeight > 0);
                                        });
                                        const buyTab = buyTabs[0];
                                        if (buyTab) {
                                            triggerClick(buyTab);
                                            if (typeof buyTab.click === 'function') buyTab.click();
                                        }
                                        if (callback) callback();
                                    }, 700);
                                    return;
                                }

                                if (confirmAttempts >= 12) {
                                    clearInterval(window.__shopConfirmInterval);
                                    window.__shopConfirmInterval = null;
                                    console.warn('[PmheeAether Shop] ⚠️ หมดเวลารอปุ่มยืนยันขาย (Timeout)');
                                    const buyTabs = Array.from(document.querySelectorAll('button, div')).filter(el => {
                                        if (el.closest('#pelican-hud')) return false;
                                        return (el.innerText || '').trim() === 'ซื้อ';
                                    });
                                    if (buyTabs[0]) triggerClick(buyTabs[0]);
                                    if (callback) callback();
                                }
                            }, 200);
                        } else {
                            console.log('[PmheeAether Shop] ตะกร้าขายว่างเปล่า (ไม่มีไอเทมจะขาย) -> สลับไปขั้นตอนซื้อ');
                            const buyTabs = Array.from(document.querySelectorAll('button, div')).filter(el => {
                                if (el.closest('#pelican-hud')) return false;
                                return (el.innerText || '').trim() === 'ซื้อ';
                            });
                            if (buyTabs[0]) triggerClick(buyTabs[0]);
                            if (callback) callback();
                        }
                    }, 450);
                    return;
                }
                steps[idx](() => runSteps(idx + 1));
            }

            if (steps.length === 0) {
                if (callback) callback();
                return;
            }
            runSteps(0);
        }, 500);
    }

    
    // ==========================================
