    // ---------- 📦 Auto storage deposit (after the sell trip, still in the capital) ----------
    // What the sell trip kept — weapons, armor, accessories/gems, refine ores — goes to the account storage
    // (shared by every character of the account). Never deposited: Whitelist items (they stay on the character),
    // usables, arrows, locked items (switch), what the plan's gear set still needs. Settings in pelican_sell_cfg:
    // storeEnabled, storeWeapon / storeArmor / storeAcc / storeRefine (default on), storeSkipLocked (default on).
    const STORE_CAT_KEY = { weapon: 'storeWeapon', armor: 'storeArmor', accessory: 'storeAcc', refine: 'storeRefine' };
    const STORE_CAT_TH = { weapon: 'อาวุธ', armor: 'ชุดเกราะ', accessory: 'ประดับ/เจม', refine: 'แร่ตีบวก' };
    const STORAGE_NPC_KEY = 'pelican_storage_npc';
    function storeCategoryOf(it) {
        if (!it) return null;
        if (it.type === 'Equipment') {
            const e = it.equipType || '';
            if (e === 'Ammo') return null;   // arrows stay
            return e === 'Weapon' ? 'weapon' : (e === 'Acc' || e === 'Gem') ? 'accessory' : 'armor';
        }
        if (it.type === 'Enchantment') return 'refine';
        return null;   // usables, cards, materials...: not touched
    }
    // The sell trip's Whitelist rule (same matching as isWhitelisted in triggerAutoSellTrash)
    window.isSellWhitelisted = function (itemName) {
        if (!itemName) return false;
        const list = String((window.__sellConfig || {}).whitelist || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
        const base = String(itemName).replace(/^\+\s*\d+\s*/, '').replace(/\s*\[\s*\d+\s*\]\s*$/, '').trim().toLowerCase();
        const full = String(itemName).toLowerCase();
        return list.some(t => {
            if (base === t || full === t) return true;
            if (t === 'bow') return base === 'bow';
            if (base.includes(t) || full.includes(t)) return true;
            return (t.includes('angrelic') || t.includes('angelic')) && (base.includes('angelic') || base.includes('angrelic'));
        });
    };
    // ---------- 🔒 Stash-Only & Consolidation Trade Items (e.g. Enchant Rune) ----------
    const STASH_TRADE_CFG_KEY = 'pelican_stash_trade_cfg';
    (function initStashTradeCfg() {
        let saved = null;
        try { saved = JSON.parse(localStorage.getItem(STASH_TRADE_CFG_KEY) || 'null'); } catch (e) {}
        window.__stashTradeConfig = {
            storeOnlyEnabled: !!(saved && saved.storeOnlyEnabled),
            tradeOnConsolidate: !!(saved && saved.tradeOnConsolidate),
            items: (saved && Array.isArray(saved.items))
                ? saved.items.map(s => String(s || '').trim()).filter(Boolean)
                : ['Enchant Rune']
        };
    })();
    window.setStashTradeConfig = function (cfg = {}) {
        const cur = window.__stashTradeConfig || { storeOnlyEnabled: false, tradeOnConsolidate: false, items: ['Enchant Rune'] };
        const next = {
            storeOnlyEnabled: cfg.storeOnlyEnabled !== undefined ? !!cfg.storeOnlyEnabled : !!cur.storeOnlyEnabled,
            tradeOnConsolidate: cfg.tradeOnConsolidate !== undefined ? !!cfg.tradeOnConsolidate : !!cur.tradeOnConsolidate,
            items: Array.isArray(cfg.items)
                ? cfg.items.map(s => String(s || '').trim()).filter(Boolean)
                : (Array.isArray(cur.items) ? cur.items : ['Enchant Rune'])
        };
        window.__stashTradeConfig = next;
        try { localStorage.setItem(STASH_TRADE_CFG_KEY, JSON.stringify(next)); } catch (e) {}
        return next;
    };
    const STASH_PRESET_ID_TO_NAME = {
        90340: 'enchant rune',
        90341: 'accessory enchant rune',
        90204: 'rough elunium',
        90205: 'elunium',
        90206: 'enriched elunium',
        90203: 'oridecon',
        90201: 'phracon',
        90202: 'emveretarcon'
    };
    window.matchesStashItemList = function (itemOrName, customList) {
        const list = Array.isArray(customList)
            ? customList
            : ((window.__stashTradeConfig && Array.isArray(window.__stashTradeConfig.items)) ? window.__stashTradeConfig.items : []);
        if (!list.length) return false;
        const itemId = (itemOrName && typeof itemOrName === 'object')
            ? Number(itemOrName.itemId || itemOrName.id || (itemOrName.raw && (itemOrName.raw.itemId || itemOrName.raw.id)))
            : NaN;
        const mappedById = (!isNaN(itemId) && STASH_PRESET_ID_TO_NAME[itemId]) ? STASH_PRESET_ID_TO_NAME[itemId] : '';
        const rawName = (typeof itemOrName === 'string')
            ? itemOrName
            : ((itemOrName && (itemOrName.name || itemOrName.itemName || (itemOrName.raw && itemOrName.raw.name))) || mappedById || '');
        if (!rawName && isNaN(itemId)) return false;
        const clean = String(rawName)
            .replace(/^\+\s*\d+\s*/, '')
            .replace(/\s*\[\s*\d+\s*\]\s*$/, '')
            .replace(/\s*\[\s*(?:ธรรมดา|ดี|หายาก|มหากาพย์|ตำนาน)\s*\]/gi, '')
            .replace(/\bx\s*\d+\b.*$/i, '')
            .trim()
            .toLowerCase();
        const full = String(rawName).trim().toLowerCase();
        return list.some(target => {
            const t = String(target || '').trim().toLowerCase();
            if (!t) return false;
            if (!isNaN(itemId) && String(itemId) === t) return true;
            if (mappedById && mappedById === t) return true;
            return clean === t || full === t;
        });
    };
    window.isStashOnlyItem = function (itemOrName) {
        const cfg = window.__stashTradeConfig;
        if (!cfg || !cfg.storeOnlyEnabled) return false;
        return window.matchesStashItemList(itemOrName, cfg.items);
    };
    window.hasStashOnlyItemsInBag = function () {
        const cfg = window.__stashTradeConfig;
        if (!cfg || !cfg.storeOnlyEnabled || !Array.isArray(cfg.items) || !cfg.items.length) return false;
        const rawBag = (window.__latestInventory && Array.isArray(window.__latestInventory.items))
            ? window.__latestInventory.items.filter(Boolean)
            : ((typeof window.getBagItems === 'function') ? window.getBagItems() : []);
        return rawBag.some(it => window.isStashOnlyItem(it));
    };

    // Items the plan is waiting to wear: an "สวมใส่" action's item not worn yet (bought, level too low), or a gem
    // that is a better % of a worn gem (the gem auto-upgrade waits for its level) — depositing them made the plan
    // buy them again
    function planStillNeeds(it, bagList = null) {
        const lc = s => String(s || '').trim().toLowerCase();
        const name = lc(it.name);
        const worn = Object.values(((typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {}).equipment || {}).filter(Boolean);
        const plan = window.__planScriptEnabled ? window.__currentScriptPlan : null;
        if (plan && Array.isArray(plan.triggers) && !worn.some(w => lc(w.name) === name)
            && plan.triggers.some(t => (t.actions || []).some(a => a && a.type === 'equip_item' && lc(a.itemName) === name))) {
            if (Array.isArray(bagList) && bagList.length && it.slot !== undefined && it.slot !== null && it.slot !== '-') {
                const same = bagList
                    .filter(b => b && lc(b.name) === name)
                    .slice()
                    .sort((a, b) => ((Number(b.refine) || 0) - (Number(a.refine) || 0))
                        || (((Array.isArray(b.affixes) ? b.affixes.length : 0) - (Array.isArray(a.affixes) ? a.affixes.length : 0)))
                        || ((Number(a.slot) || 0) - (Number(b.slot) || 0)));
                if (same.length && Number(same[0].slot) !== Number(it.slot)) return false;
            }
            return true;
        }
        const tier = n => { const m = String(n || '').trim().match(/^(.*\S)\s+(\d+(?:\.\d+)?)\s*%$/); return m ? { fam: m[1].toLowerCase(), pct: parseFloat(m[2]) } : null; };
        const g = it.equipType === 'Gem' ? tier(it.name) : null;
        return !!g && worn.some(w => { const t = w.equipType === 'Gem' ? tier(w.name) : null; return t && t.fam === g.fam && t.pct < g.pct; });
    }
    const STORE_STATE_KEY = 'pelican_storage_state';
    const storeState = () => { try { return JSON.parse(localStorage.getItem(STORE_STATE_KEY) || '{}') || {}; } catch (e) { return {}; } };
    const saveStoreState = st => { try { localStorage.setItem(STORE_STATE_KEY, JSON.stringify(st)); } catch (e) {} };
    function isItemOnMarketSellList(it) {
        if (!it) return false;
        if (typeof window.isStashOnlyItem === 'function' && window.isStashOnlyItem(it)) return false;
        if (!window.__autoMarketSellConfig || !window.__autoMarketSellConfig.enabled) return false;
        const rules = Array.isArray(window.__autoMarketSellConfig.rules) ? window.__autoMarketSellConfig.rules : [];
        const name = String(it.name || '').trim().toLowerCase();
        const id = Number(it.itemId || it.id);
        return rules.some(r => {
            if (!r || r.enabled === false) return false;
            if (r.itemId && Number(r.itemId) === id) return true;
            if (r.itemName && String(r.itemName).trim().toLowerCase() === name) return true;
            return false;
        });
    }
    window.isItemOnMarketSellList = isItemOnMarketSellList;

    function storeEligible(it, cfg, refused, opts = {}, bagList = null) {
        if (!it || it.bound) return false;
        if (typeof window.isStashOnlyItem === 'function' && window.isStashOnlyItem(it)) {
            return true;
        }
        if (!cfg.storeEnabled && !opts.manual && !opts.humanize) return false;
        if (isItemOnMarketSellList(it)) return false;
        if (it.locked && cfg.storeSkipLocked !== false) return false;
        if (typeof window.isGearKeptItem === 'function' && window.isGearKeptItem(it)) return false;
        if (planStillNeeds(it, bagList)) return false;
        const cat = storeCategoryOf(it);
        if (cat !== 'refine' && refused && refused[it.itemId] && Date.now() - refused[it.itemId] < 24 * 3600 * 1000) return false;   // the game refused it before
        if (typeof window.getGuildDonationSlotSellableQty === 'function') {
            const gdInfo = window.getGuildDonationSlotSellableQty(it.slot, bagList, it);
            if (gdInfo.reserveQty > 0 && gdInfo.sellableQty <= 0) return false;
        }

        // Only weapons / armor / accessories+gems / refine ores, Whitelist or not: arrows, usables (potions,
        // Butterfly Wing, scrolls), cards and materials are never deposited — even when they are in the Whitelist
        if (!cat || cfg[STORE_CAT_KEY[cat]] === false) return false;
        // Whitelist items: deposited too (unless listed for the market, checked above)
        if (window.isSellWhitelisted(it.name)) return (cfg.storeWhitelist !== false || !!(opts && opts.storeWhitelist));
        return true;
    }
    window.getStorageDepositList = function (cfg = window.__sellConfig || {}, opts = {}) {
        const bag = (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items.filter(Boolean) : [];
        const refused = storeState().refused || {};
        return bag.filter(it => storeEligible(it, cfg, refused, opts, bag));
    };
    // Open the storage: the NPC that worked last time first, then Alice Service / anything storage-like, then the
    // other town NPCs; the dialog option with "คลัง" (never a guild storage) — remembered for next time
    async function openStorageWindow(roomOrTimeout, stopped = () => false) {
        const room = (roomOrTimeout && typeof roomOrTimeout === 'object' && typeof roomOrTimeout.send === 'function')
            ? roomOrTimeout
            : ((typeof window.getGameRoom === 'function' ? window.getGameRoom() : null) || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null));
        if (!room) return null;
        const stopFn = typeof stopped === 'function' ? stopped : () => false;
        const sleep = ms => new Promise(r => setTimeout(r, ms));
        const all = [];
        if (room && room.state && room.state.npcs && typeof room.state.npcs.forEach === 'function') {
            room.state.npcs.forEach((n, k) => all.push({ key: k, name: (n && n.name) || '', x: Number(n && n.x), y: Number(n && n.y) }));
        }
        let saved = null;
        try { saved = localStorage.getItem(STORAGE_NPC_KEY); } catch (e) {}
        const likely = /Alice|อลิซ|Kafra|Storage|Banker|คลัง/i, never = /Valkyrie|Event|Arena|Guild|Training|Auction|Blacksmith|Shopkeeper|Bag Merchant|Card|Auger/i;
        const order = [...all.filter(n => n.name === saved), ...all.filter(n => n.name !== saved && likely.test(n.name)),
            ...all.filter(n => n.name !== saved && !likely.test(n.name) && !never.test(n.name))].slice(0, 6);
        const closeDlg = () => {
            try {
                const stClose = document.querySelector('.storage-window .win-close');
                if (stClose) stClose.click();
                const x = document.querySelector('.npc-dialog .win-close');
                if (x) x.click();
            } catch (_) {}
        };
        if (typeof window.closeShopUI === 'function') { try { window.closeShopUI(); } catch (_) {} }
        closeDlg();
        for (const npc of order) {
            if (stopFn()) return null;
            // Walk close to the storage NPC first if standing far away (e.g. at Shopkeeper Bor)
            if (Number.isFinite(npc.x) && Number.isFinite(npc.y)) {
                const getMe = () => (room.state && room.state.players && typeof room.state.players.get === 'function') ? room.state.players.get(room.sessionId) : null;
                let me = getMe();
                if (me && Number.isFinite(me.x) && Math.hypot(me.x - npc.x, me.y - npc.y) > 115) {
                    const walkStart = Date.now();
                    let lastMove = 0;
                    while (Date.now() - walkStart < 15000 && !stopFn()) {
                        me = getMe();
                        if (me && Math.hypot(me.x - npc.x, me.y - npc.y) <= 115) break;
                        if (Date.now() - lastMove > 1800) {
                            lastMove = Date.now();
                            room.send('move_to', { x: npc.x, y: npc.y });
                        }
                        await sleep(250);
                    }
                    await sleep(250);
                }
            }
            for (let attempt = 0; attempt < 3; attempt++) {
                if (stopFn()) return null;
                let got = null, unsub;
                const wait = new Promise(resolve => {
                    const timer = setTimeout(() => { if (typeof unsub === 'function') unsub(); resolve(null); }, 7500);
                    unsub = room.onMessage('storage', msg => { clearTimeout(timer); if (typeof unsub === 'function') unsub(); got = msg; resolve(msg); });
                });
                room.send('npc_talk', { npcKey: npc.key });
                let dlg = null;
                for (let i = 0; i < 30 && !dlg && !got; i++) {
                    await sleep(180);
                    dlg = document.querySelector('.npc-dialog');
                    if (dlg && !dlg.querySelector('.npc-options button')) dlg = null;
                }
                if (!got && dlg) {
                    const btns = Array.from(dlg.querySelectorAll('.npc-options button'));
                    const opts = btns.map(b => (b.innerText || b.textContent || '').replace(/^\s*\d+\s*/, '').trim());
                    const idx = opts.findIndex(o => /คลัง|ฝากของ|storage/i.test(o) && !/กิลด์|guild/i.test(o));
                    if (idx < 0) {
                        closeDlg();
                        if (typeof unsub === 'function') unsub();
                        await sleep(300);
                        break;
                    }
                    room.send('npc_option', { index: idx });
                }
                const msg = await wait;
                if (msg && Array.isArray(msg.items)) {
                    try { localStorage.setItem(STORAGE_NPC_KEY, npc.name); } catch (e) {}
                    return msg;
                }
                closeDlg();
                await sleep(350);
            }
        }
        return null;
    }
    window.openStorageWindow = openStorageWindow;
    window.refreshStoreHud = function () {
        const c = window.__sellConfig || {};
        const set = (id, v) => { const el = document.getElementById(id); if (el && document.activeElement !== el) el.checked = v; };
        set('p-store-enabled', !!c.storeEnabled);
        set('p-store-weapon', c.storeWeapon !== false);
        set('p-store-armor', c.storeArmor !== false);
        set('p-store-acc', c.storeAcc !== false);
        set('p-store-refine', c.storeRefine !== false);
        set('p-store-skip-locked', c.storeSkipLocked !== false);
    };
    window.runAutoStorageDeposit = async function (opts = {}) {
        const cfg = window.__sellConfig || {};
        const hasStashOnly = typeof window.hasStashOnlyItemsInBag === 'function' && window.hasStashOnlyItemsInBag();
        if (!cfg.storeEnabled && !hasStashOnly && !opts.manual && !opts.humanize) return { skipped: 'off' };
        if (window.__consolidationPending && !opts.manual) return { skipped: 'consolidation' };
        if (window.__isStoring) return { skipped: 'busy' };
        if (typeof window.isInCapital === 'function' && !window.isInCapital()) {
            if (opts.manual) console.warn('[PmheeAether Storage] ⚠️ ต้องอยู่ในเมืองหลวงก่อนถึงจะฝากของเข้าคลังได้');
            return { skipped: 'not-in-capital' };
        }
        const list = window.getStorageDepositList(cfg, opts);
        if (!list.length) { if (opts.manual) console.log('[PmheeAether Storage] ℹ️ ไม่มีของที่ต้องฝากเข้าคลัง'); return { done: 0 }; }
        const state = storeState();
        if (!opts.manual) {
            if ((state.fullUntil || 0) > Date.now()) return { skipped: 'full' };               // storage was full: try again later
            if ((state.noStorageUntil || 0) > Date.now()) return { skipped: 'no-storage' };   // no NPC offered storage
            const z = Number(((window.getLiveCharacterData && window.getLiveCharacterData()) || {}).zeny) || 0;
            if (state.lastFee && z < state.lastFee) return { skipped: 'zeny' };
        }
        const room = (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null) || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null);
        if (!room) return { error: 'no-room' };
        const sleep = ms => new Promise(r => setTimeout(r, ms));
        const bagAt = slot => ((window.__latestInventory && window.__latestInventory.items) || []).find(x => x && Number(x.slot) === Number(slot));
        window.__isStoring = true;
        try {
            const zeny0 = Number(((window.getLiveCharacterData && window.getLiveCharacterData()) || {}).zeny) || 0;
            console.log(`%c[PmheeAether Storage] 📦 ฝากของเข้าคลัง ${list.length} รายการ -> หา NPC คลัง...`, 'color: #38bdf8; font-weight: bold;');
            const stopped = () => !opts.manual && !window.__isBotRunning;
            const st = await openStorageWindow(room, stopped);
            if (!st) {
                if (stopped()) return { skipped: 'stopped' };
                state.noStorageUntil = Date.now() + 3 * 3600 * 1000;
                saveStoreState(state);
                console.warn('[PmheeAether Storage] ⚠️ เปิดคลังไม่สำเร็จ (ไม่พบ NPC ที่มีตัวเลือก "คลัง") — เก็บของไว้ในกระเป๋าก่อน ลองใหม่ใน 3 ชั่วโมง');
                return { error: 'no-storage' };
            }
            state.noStorageUntil = 0;
            const fee = zeny0 - (Number(((window.getLiveCharacterData && window.getLiveCharacterData()) || {}).zeny) || 0);
            if (fee > 0) state.lastFee = fee;
            const maxStorageSlots = Number(st.slots ?? st.maxSlots) || ((typeof window.isPremiumCharacter === 'function' && window.isPremiumCharacter()) ? 500 : 300);
            let free = maxStorageSlots - (Array.isArray(st.items) ? st.items.length : 0);
            state.refused = state.refused || {};
            const done = {};
            let put = 0;
            let consecutiveFail = 0;
            for (const it of list) {
                if (stopped()) break;
                if (free <= 0) {
                    state.fullUntil = Date.now() + 6 * 3600 * 1000;
                    console.warn('[PmheeAether Storage] ⚠️ คลังเต็มแล้ว — ของที่เหลือเก็บไว้ในกระเป๋า (ไม่เปิดคลังอีก 6 ชั่วโมง)');
                    break;
                }
                const curBag = (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items.filter(Boolean) : [];
                const cur = curBag.find(x => x && Number(x.slot) === Number(it.slot));
                // the slot changed (bag sorted...): never deposit something else — same item, still allowed to go
                if (!cur || Number(cur.itemId) !== Number(it.itemId) || JSON.stringify(cur.affixes || []) !== JSON.stringify(it.affixes || [])
                    || (Number(cur.refine) || 0) !== (Number(it.refine) || 0) || !storeEligible(cur, cfg, null, opts, curBag)) continue;
                const beforeQty = Math.max(1, Number(cur.qty) || 1);
                const isStashOnlyCur = typeof window.isStashOnlyItem === 'function' && window.isStashOnlyItem(cur);
                const gdInfo = (!isStashOnlyCur && typeof window.getGuildDonationSlotSellableQty === 'function')
                    ? window.getGuildDonationSlotSellableQty(cur.slot, curBag, cur)
                    : { reserveQty: 0, keepQty: 0, sellableQty: beforeQty };
                const qtyToDeposit = gdInfo.reserveQty > 0 ? gdInfo.sellableQty : beforeQty;
                if (qtyToDeposit <= 0) continue;
                if (gdInfo.reserveQty > 0 && gdInfo.keepQty > 0) {
                    console.log(`%c[PmheeAether Storage] 🏛️ [ของบริจาคกิลด์] ฝากส่วนเกิน "${it.name}" x${qtyToDeposit} เข้าคลัง (เก็บสำรองไว้บริจาคกิลด์รายวัน ${gdInfo.keepQty} ชิ้น)`, 'color: #38bdf8; font-weight: bold;');
                }
                room.send('storage_put', { slot: Number(it.slot), qty: qtyToDeposit });
                let moved = false;
                for (let i = 0; i < 10 && !moved; i++) {
                    await sleep(200);
                    const now = bagAt(it.slot);
                    moved = !now || Number(now.itemId) !== Number(it.itemId) || (Number(now.qty) || 0) <= beforeQty - qtyToDeposit;
                }
                if (!moved) {
                    consecutiveFail++;
                    if (!document.querySelector('.storage-window') || consecutiveFail >= 2) {
                        console.warn(`[PmheeAether Storage] ⚠️ หน้าต่างคลังถูกปิดหรือฝากต่อเนื่องไม่สำเร็จ (${consecutiveFail} ชิ้น) -> หยุดการฝากรอบนี้เพื่อไม่ให้บล็อกไอเทมผิดพลาด`);
                        break;
                    }
                    if (!isStashOnlyCur && storeCategoryOf(it) !== 'refine') {
                        state.refused[it.itemId] = Date.now();
                    }
                    console.warn(`[PmheeAether Storage] ⚠️ ฝาก "${it.name}" ไม่สำเร็จ — ข้าม`);
                    continue;
                }
                consecutiveFail = 0;
                put++; free--;
                const cat = STORE_CAT_TH[storeCategoryOf(it)] || (isStashOnlyCur ? 'ของเก็บคลัง' : 'อื่นๆ');
                done[cat] = (done[cat] || 0) + 1;
                await sleep(250);
            }
            if (free > 0) state.fullUntil = 0;
            saveStoreState(state);
            const x = document.querySelector('.storage-window .win-close');
            if (x) x.click(); else if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
            console.log(`%c[PmheeAether Storage] ✅ ฝากเข้าคลังแล้ว ${put} ชิ้น (${Object.keys(done).map(k => k + ' ' + done[k]).join(', ') || '-'})${fee > 0 ? ` · ค่าเปิดคลัง ${fee.toLocaleString()} z` : ''}`, 'color: #22c55e; font-weight: bold;');
            return { done: put, fee };
        } catch (e) {
            console.warn('[PmheeAether Storage] error:', e);
            return { error: e.message };
        } finally {
            window.__isStoring = false;
        }
    };
    // The sell trip: sell + buy, then the storage deposit, then the trip goes on (back to the farm)
    function sellThenStore(onComplete) {
        executeSellAndBuyActions(() => {
            const hasStashOnly = typeof window.hasStashOnlyItemsInBag === 'function' && window.hasStashOnlyItemsInBag();
            if (!window.__isBotRunning || (!(window.__sellConfig || {}).storeEnabled && !hasStashOnly)) return onComplete();
            try { window.sendNpcClose(); if (typeof window.closeShopUI === 'function') window.closeShopUI(); } catch (e) {}
            setTimeout(() => { window.runAutoStorageDeposit().catch(() => {}).finally(onComplete); }, 800);
        });
    }

    function executeSellAndBuyActions(onComplete) {
        if (!window.__isBotRunning && !window.__isManualSelling) return;
        console.log('%c[PmheeAether Shop] 📦 กำลังดำเนินการซื้อ/ขายไอเทมตามตั้งค่า...', 'color: #00ffcc;');

        // 1. ดำเนินการขายขยะมอนสเตอร์ก่อน (ถ้าเปิดใช้งาน)
        triggerAutoSellTrash(() => {
            if (!window.__isBotRunning && !window.__isManualSelling) return;
            const cfg = window.__archerConfig || {};
            const useBwing = cfg.useBwing !== false;
            const bwingId = parseInt(cfg.bwingItemId) || 0x000160c7;
            const targetBwing = Math.max(1, parseInt(cfg.bwingBuyQty) || 5);
            const arrowId = parseInt(cfg.arrowType) || 0x00015fae;
            const targetQty = parseInt(cfg.arrowBuyQty) || 1000;
            const needArrows = window.arrowsNeeded();

            // 2. ซื้อ Butterfly Wing เป็นอันดับแรกเสมอ (ป้องกันซื้อลูกธนู/ยาจนเงินหรือน้ำหนักเต็มก่อนซื้อบีวิง)
            if (useBwing) {
                const curBwing = typeof window.getBagItemCount === 'function' ? window.getBagItemCount(bwingId) : 0;
                const needBwing = Math.max(0, targetBwing - curBwing);
                if (needBwing > 0) {
                    console.log(`%c[PmheeAether Shop] 🦋 คำนวณการเติม Butterfly Wing: ในกระเป๋ามี ${curBwing} ใบ / ตั้งเป้าพก ${targetBwing} ใบ -> ซื้อเพิ่ม ${needBwing} ใบ`, 'color: #38bdf8; font-weight: bold;');
                    window.sendShopBuy(bwingId, needBwing);
                } else {
                    console.log(`%c[PmheeAether Shop] 🦋 Butterfly Wing มีเพียงพอแล้ว (${curBwing} >= ${targetBwing} ใบ) ไม่จำเป็นต้องซื้อเพิ่ม`, 'color: #94a3b8;');
                }
            }

            // 3. ซื้อลูกธนูชนิดที่เลือก (Smart Restock: เติมส่วนต่างให้ครบ targetQty และจำกัดไม่ให้เกินน้ำหนัก/เงินที่มี)
            setTimeout(() => {
                if (!window.__isBotRunning && !window.__isManualSelling) return;
                const worn = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
                const wornSame = worn.ammo && Number(worn.ammo.itemId) === arrowId ? Number(worn.ammo.qty) || 0 : 0;
                const bagSame = typeof window.getBagItemCount === 'function' ? window.getBagItemCount(arrowId) : 0;
                const curAmmo = Math.max(wornSame, bagSame);
                let qtyToBuy = Math.max(0, targetQty - curAmmo);

                if (needArrows && qtyToBuy > 0) {
                    const inv = window.__latestInventory || {};
                    const curWeight = Number(inv.weight) || 0;
                    const maxWeight = Number(inv.weightLimit) || 0;
                    if (maxWeight > 0 && curWeight > 0) {
                        const safeFreeWeight = Math.max(0, maxWeight * 0.88 - curWeight);
                        const maxByWeight = Math.floor(safeFreeWeight / 0.1);
                        if (maxByWeight > 0 && qtyToBuy > maxByWeight) {
                            console.log(`%c[PmheeAether Shop] ⚖️ ปรับจำนวนซื้อลูกธนูจาก ${qtyToBuy} -> ${maxByWeight} ดอก เพื่อไม่ให้น้ำหนักเกิน 88%`, 'color: #f59e0b;');
                            qtyToBuy = maxByWeight;
                        }
                    }
                    const zeny = Number(worn.zeny) || Number(window.__currentZeny) || 0;
                    const estArrowPrice = arrowId === 90030 ? 1 : 3;
                    if (zeny > 0 && qtyToBuy * estArrowPrice > zeny) {
                        const maxByZeny = Math.max(0, Math.floor(zeny / estArrowPrice));
                        if (maxByZeny > 0 && maxByZeny < qtyToBuy) {
                            qtyToBuy = maxByZeny;
                        }
                    }
                    if (qtyToBuy > 0) {
                        console.log(`%c[PmheeAether Shop] 🏹 คำนวณการเติมลูกธนู: ปัจจุบันมี ${curAmmo} ดอก / ตั้งเป้าพก ${targetQty} ดอก -> ซื้อเพิ่ม ${qtyToBuy} ดอก`, 'color: #00ffcc; font-weight: bold;');
                        window.sendShopBuy(arrowId, qtyToBuy);
                    }
                } else if (needArrows) {
                    console.log(`%c[PmheeAether Shop] 🏹 ลูกธนูยังมีเพียงพอ (${curAmmo} >= ${targetQty} ดอก) ไม่จำเป็นต้องซื้อเพิ่ม`, 'color: #94a3b8;');
                }
            }, 250);

            // 3.5 ซื้อเติมยาบัพ (Smart Restock สำหรับ Concentration, Awakening, Berserk Potion)
            const arrowChunkDelay = needArrows ? Math.max(0, Math.ceil(targetQty / 9999) - 1) * 260 : 0;
            let potionDelay = 550 + arrowChunkDelay;
            if (typeof window.executeBuffPotionRestock === 'function') {
                potionDelay = Math.max(potionDelay, window.executeBuffPotionRestock() + 250 + arrowChunkDelay);
            }

            // 3.8 ตรวจสอบซ้ำว่า Butterfly Wing และลูกธนูเข้ากระเป๋าครบตามจำนวนที่ตั้งค่าจริงหรือไม่ (ถ้ายังไม่ครบให้ยิงซื้อซ้ำ)
            setTimeout(() => {
                if (!window.__isBotRunning && !window.__isManualSelling) return;
                if (useBwing) {
                    const afterBwing = typeof window.getBagItemCount === 'function' ? window.getBagItemCount(bwingId) : 0;
                    const stillNeedBwing = Math.max(0, targetBwing - afterBwing);
                    if (stillNeedBwing > 0) {
                        console.log(`%c[PmheeAether Shop] 🦋 ตรวจสอบซ้ำ: Butterfly Wing มี ${afterBwing}/${targetBwing} ใบ -> ส่งคำสั่งซื้อซ้ำอีก ${stillNeedBwing} ใบ`, 'color: #38bdf8; font-weight: bold;');
                        window.sendShopBuy(bwingId, stillNeedBwing);
                    }
                    setTimeout(() => {
                        if (typeof window.updatePotionHUD === 'function') window.updatePotionHUD();
                    }, 350);
                }
            }, potionDelay);

            // 4. นำลูกธนูและ Butterfly Wing ใส่ช่องลัดด้านล่างอัตโนมัติ (เฉพาะเมื่อระบุช่อง)
            setTimeout(() => {
                if (!window.__isBotRunning && !window.__isManualSelling) return;
                if (needArrows) {
                    if (typeof cfg.arrowHotbarSlot === 'number' && cfg.arrowHotbarSlot >= 0) {
                        window.sendItembarSet(cfg.arrowHotbarSlot, arrowId);
                    }
                    const actualAmmo = typeof window.getCurrentArrowCount === 'function' ? window.getCurrentArrowCount() : -1;
                    if (actualAmmo >= 0 && window.__latestInventory && Array.isArray(window.__latestInventory.items)) {
                        window.__currentAmmo = actualAmmo;
                    } else if (!window.__currentAmmo || window.__currentAmmo < targetQty) {
                        window.__currentAmmo = targetQty;
                    }
                    localStorage.setItem('pelican_current_ammo', window.__currentAmmo);
                    updateAmmoHUD();
                }
                if (useBwing) {
                    window.sendItembarSet(8, bwingId); // ใส่ Bwing ที่ช่อง 8
                }
                if (typeof window.updatePotionHUD === 'function') window.updatePotionHUD();
            }, potionDelay + 600);

            // 5. สั่งสวมใส่คันธนูและลูกธนู (ดึงคันธนูกลับเข้ามือแทนมีด Damascus และติดตั้งลูกธนู)
            setTimeout(() => {
                if (!window.__isBotRunning && !window.__isManualSelling) return;
                if (needArrows) {
                    if (typeof window.equipArrowAndBow === 'function') {
                        window.equipArrowAndBow();
                    } else if (typeof cfg.arrowHotbarSlot === 'number' && cfg.arrowHotbarSlot >= 0) {
                        window.pressKey((cfg.arrowHotbarSlot + 1).toString());
                    }
                    console.log(`%c[PmheeAether Shop] 🏹 สวมใส่คันธนูและลูกธนูเรียบร้อยแล้ว!`, 'color: #22c55e; font-weight: bold;');
                }
            }, potionDelay + 1100);

            setTimeout(() => {
                if (!window.__isBotRunning && !window.__isManualSelling) return;
                if (onComplete) onComplete();
            }, potionDelay + 2100);
        });
    }

    let lastAutoShopCompletionTime = 0;

    // A town trip cut off half way (bot stopped, a step that never called back) used to leave __isShopping on
    // for good: the farm loop and the plan then wait forever ("🛒 กำลังซื้อขาย" on the farm map). A trip takes
    // ~1-2 minutes (Butterfly Wing, walk to the NPC, sell/buy), so clear it after 6 minutes without a shop open.
    setInterval(() => {
        if (!window.__isShopping) return;
        if (!window.__shoppingSince) { window.__shoppingSince = Date.now(); return; }
        if (Date.now() - window.__shoppingSince < 6 * 60 * 1000 || document.querySelector('.shop-window')) return;
        if (window.__isNavigating || window.__isWalkingToMap || window.__isStoring) { window.__shoppingSince = Date.now() - 4 * 60 * 1000; return; }
        console.warn('[PmheeAether Shop] ⚠️ สถานะ "กำลังซื้อขาย" ค้างเกิน 6 นาที -> ยกเลิกรอบนี้แล้วทำงานต่อ');
        if (window.__shopWarpInterval) clearInterval(window.__shopWarpInterval);
        if (window.__shopArrivalInterval) clearInterval(window.__shopArrivalInterval);
        window.__shopWarpInterval = null;
        window.__shopArrivalInterval = null;
        window.__isShopping = false;
        window.__shoppingSince = 0;
        lastAutoShopCompletionTime = Date.now();
        // a trip that walked toward the capital set it as the farm map: put the real one back
        const back = window.__shopReturnMap;
        if (back && back !== window.__targetFarmMap && !/เมืองหลวง|โซลเฮเวน/.test(back) && typeof window.walkToTargetMap === 'function') {
            window.__pendingPostSellChannelCheck = true;
            window.__pendingPostSellAt = Date.now();
            window.walkToTargetMap(back);
        }
    }, 30000);

    window.executeAutoShopRoutine = function() {
        window.__lastTownTripAt = Date.now();
        if (window.__consolidationPending) return;   // money consolidation is about to start
        if (window.__isGearRefining) {
            console.warn('[PmheeAether Shop] ⏳ กำลังตีบวกตามเซ็ตอุปกรณ์อยู่ — เลื่อนการซื้อขายไปก่อน');
            return;
        }
        if (window.__isShopping) {
            console.warn('[PmheeAether Shop] ⚠️ กำลังดำเนินการซื้อขายอยู่แล้ว');
            return;
        }

        // Cooldown Guard: ป้องกันไม่ให้วนกลับมาเปิดร้านซ้ำทันทีหลังเพิ่งเสร็จสิ้น (Cooldown 20 วินาที)
        const now = Date.now();
        if (now - lastAutoShopCompletionTime < 20000) {
            console.log('[PmheeAether Shop] ⏳ เพิ่งดำเนินการซื้อขายเสร็จสิ้นไป อยู่ในช่วงพักคูลดาวน์ (Cooldown 20s)');
            return;
        }

        // GUARD 1: ป้องกันตัวละครตายแล้วยังพยายามซื้อของ
        if (typeof isCharacterDead === 'function' && isCharacterDead()) {
            console.warn('%c[PmheeAether Shop Guard] 🛑 ตัวละครเสียชีวิตอยู่! ยกเลิก Routine ร้านค้า และรอระบบชุบชีวิตทำงานก่อน', 'color: #ef4444; font-weight: bold;');
            return;
        }

        // GUARD 2: ถ้ากำลังเดินข้ามแมพอยู่ ให้รอเดินทางเสร็จก่อน
        if (window.__isNavigating) {
            console.warn('[PmheeAether Shop Guard] ⚠️ กำลังเดินทางข้ามแมพอยู่ ไม่สามารถเปิดร้านค้าได้');
            return;
        }

        window.__isShopping = true;
        window.__shoppingSince = Date.now();
        const startMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : 'ไม่ทราบแมพ';
        console.log(`%c[PmheeAether Shop] 🛒 เริ่มต้น Routine ซื้อ/ขายอัตโนมัติ (แมพปัจจุบัน: "${startMap}")`, 'color: #f59e0b; font-weight: bold;');

        const currentFarmMap = window.__targetFarmMap;
        window.__shopReturnMap = currentFarmMap;
        const targetNpc = (window.__shopConfig && window.__shopConfig.npcKey) ? window.__shopConfig.npcKey : 'n2';

        function startCityWalk() {
            // GUARD 3: ต้องมั่นใจ 100% ว่าตัวละครอยู่ในเมืองหลวงจริง ๆ จึงจะอนุญาตให้เดินหา NPC และเปิดร้าน!
            if (typeof isCharacterInCity === 'function' && !isCharacterInCity()) {
                console.error(`%c[PmheeAether Shop Guard] 🛑 ปฏิเสธการเปิดร้าน! ตัวละครไม่ได้อยู่ในเมืองหลวง (แมพปัจจุบัน: "${getCurrentMapName()}") เพื่อป้องกันซื้อของจนน้ำหนักเกินในแมพมอนสเตอร์`, 'color: #ef4444; font-weight: bold;');
                window.__isShopping = false;
                return;
            }

            // GUARD 4: ตรวจสอบการตายก่อนคุยกับ NPC
            if (typeof isCharacterDead === 'function' && isCharacterDead()) {
                console.error('%c[PmheeAether Shop Guard] 🛑 ตัวละครเสียชีวิต! ยกเลิกการเปิดร้านทันที', 'color: #ef4444; font-weight: bold;');
                window.__isShopping = false;
                return;
            }

            console.log(`%c[PmheeAether Shop] 🚶 เดินหา NPC ร้านค้า (${targetNpc}) ในเมือง: "${getCurrentMapName()}"`, 'color: #38bdf8;');
            window.sendRemoteNpcTalk(targetNpc);

            let moveAttempts = 0;
            let lastPlayerPos = { x: 0, y: 0 };

            if (window.__shopArrivalInterval) {
                clearInterval(window.__shopArrivalInterval);
                window.__shopArrivalInterval = null;
            }

            window.__shopArrivalInterval = setInterval(() => {
                if (!window.__isBotRunning) {
                    clearInterval(window.__shopArrivalInterval);
                    window.__shopArrivalInterval = null;
                    window.__isShopping = false;
                    return;
                }

                // GUARD 5: ระหว่างเดินหา NPC ถ้าตัวละครตาย ให้ตัดจบ
                if (typeof isCharacterDead === 'function' && isCharacterDead()) {
                    clearInterval(window.__shopArrivalInterval);
                    window.__shopArrivalInterval = null;
                    console.error('%c[PmheeAether Shop Guard] 🛑 ตัวละครเสียชีวิตระหว่างเดินในเมือง! ยกเลิกทันที', 'color: #ef4444; font-weight: bold;');
                    window.__isShopping = false;
                    return;
                }

                moveAttempts++;
                const curPos = window.__currentPos;
                const isStationary = (curPos.x === lastPlayerPos.x && curPos.y === lastPlayerPos.y && curPos.x !== 0);
                lastPlayerPos = { x: curPos.x, y: curPos.y };

                if (isStationary && moveAttempts >= 3) {
                    clearInterval(window.__shopArrivalInterval);
                    window.__shopArrivalInterval = null;

                    // GUARD 6: ตรวจสอบเมืองอีกครั้งก่อนส่ง packet เปิดร้านค้า
                    if (typeof isCharacterInCity === 'function' && !isCharacterInCity()) {
                        console.error('[PmheeAether Shop Guard] 🛑 หลุดออกจากเมืองหลวง ยกเลิกการเปิดร้าน');
                        window.__isShopping = false;
                        return;
                    }

                    console.log('%c[PmheeAether Shop] 🎯 ตัวละครหยุดเดิน (ถึงระยะ NPC) -> กำลังเปิดร้านค้า...', 'color: #22c55e; font-weight: bold;');
                    window.sendRemoteNpcTalk(targetNpc);

                    setTimeout(() => {
                        if (!window.__isBotRunning) return;
                        window.sendRemoteNpcOption(0);

                        setTimeout(() => {
                            if (!window.__isBotRunning) return;
                            sellThenStore(() => {
                                if (!window.__isBotRunning) return;
                                window.sendNpcClose();
                                if (typeof window.closeShopUI === 'function') {
                                    window.closeShopUI();
                                }
                                console.log('%c[PmheeAether Shop] 🔄 ซิงก์จัดเรียงกระเป๋าและอ่านน้ำหนักจริงหลังขาย...', 'color: #38bdf8; font-weight: bold;');

                                // ซิงก์น้ำหนักและกดจัดเรียงกระเป๋าทันทีที่หน้า NPC ร้านค้า (~300ms)
                                // เพื่อให้เกมคำนวณน้ำหนักจริงใหม่ ลบ Debuff 70% บนจอ และอัปเดตแคชตัวเลขจริงก่อนเริ่มเดินทางกลับ
                                const markPostShopSlots = () => {
                                    const postSlots = typeof getBagSlots === 'function' ? getBagSlots() : null;
                                    if (postSlots && (postSlots.percent >= 98 || postSlots.current >= postSlots.max - 2)) {
                                        window.__unfreeableBagSlotsCount = postSlots.current;
                                        window.__unfreeableBagSlotsUntil = Date.now() + 10 * 60 * 1000;
                                        console.warn(`%c[PmheeAether Shop] ⚠️ หลังขายและฝากคลังแล้ว ช่องกระเป๋ายังคงเต็ม (${postSlots.current}/${postSlots.max} ช่อง — ไอเทมในตัวอาจถูกล็อคหรือติด Whitelist ทั้งหมด) -> พักการตรวจช่องกระเป๋าเต็มชั่วคราว 10 นาที เพื่อไม่ให้วนกลับเมืองซ้ำ`, 'color: #f59e0b; font-weight: bold;');
                                    } else {
                                        window.__unfreeableBagSlotsCount = 0;
                                        window.__unfreeableBagSlotsUntil = 0;
                                    }
                                };
                                if (typeof window.refreshInventoryAndWeight === 'function') {
                                    window.refreshInventoryAndWeight((newWeight) => {
                                        lastAutoShopCompletionTime = Date.now();
                                        window.__isKnownOverweight = false;
                                        markPostShopSlots();
                                        if (newWeight) {
                                            window.__lastKnownWeight = newWeight;
                                        }
                                        const postSlots = typeof getBagSlots === 'function' ? getBagSlots() : null;
                                        const slotInfo = postSlots ? ` | ช่องกระเป๋า: ${postSlots.current}/${postSlots.max}` : '';
                                        console.log(`%c[PmheeAether Shop] 🚀 ภารกิจซื้อขายเสร็จสิ้น! น้ำหนักคงเหลือ: ${newWeight ? newWeight.percent + '%' : 'ปลอดภัย'}${slotInfo} | สั่งเดินกลับไปฟาร์ม: ${currentFarmMap}`, 'color: #a855f7; font-weight: bold;');
                                        setTimeout(() => {
                                            if (!window.__isBotRunning) return;
                                            if (typeof window.closeShopUI === 'function') window.closeShopUI();
                                            window.__isShopping = false;
                                            window.__pendingPostSellChannelCheck = true;
                                            window.__pendingPostSellAt = Date.now();
                                            if (typeof window.maybeRunHumanizeRoutine === 'function') {
                                                window.maybeRunHumanizeRoutine(() => {
                                                    if (!window.__isBotRunning) return;
                                                    window.walkToTargetMap(currentFarmMap);
                                                });
                                            } else {
                                                window.walkToTargetMap(currentFarmMap);
                                            }
                                        }, 600);
                                    });
                                } else {
                                    lastAutoShopCompletionTime = Date.now();
                                    window.__isKnownOverweight = false;
                                    markPostShopSlots();
                                    setTimeout(() => {
                                        if (!window.__isBotRunning) return;
                                        if (typeof window.closeShopUI === 'function') window.closeShopUI();
                                        window.__isShopping = false;
                                        window.__pendingPostSellChannelCheck = true;
                                        window.__pendingPostSellAt = Date.now();
                                        if (typeof window.maybeRunHumanizeRoutine === 'function') {
                                            window.maybeRunHumanizeRoutine(() => {
                                                if (!window.__isBotRunning) return;
                                                window.walkToTargetMap(currentFarmMap);
                                            });
                                        } else {
                                            window.walkToTargetMap(currentFarmMap);
                                        }
                                    }, 800);
                                }
                            });
                        }, 1200);

                    }, 700);
                }

                if (moveAttempts >= 45) {
                    clearInterval(window.__shopArrivalInterval);
                    window.__shopArrivalInterval = null;
                    console.error('[PmheeAether Shop] ❌ หมดเวลาเดินหา NPC (Timeout)');
                    window.__isShopping = false;
                }
            }, 1000);
        }

        // GUARD 7: วาร์ปกลับเมืองหลวง (Bwing Guard)
        const inCity = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;
        if (!inCity) {
            const allowWarp = (window.__archerConfig && window.__archerConfig.useBwing) || (typeof isCharacterOverweight === 'function' && isCharacterOverweight());
            if (!allowWarp) {
                console.warn(`%c[PmheeAether Shop Guard] 🛑 ตัวละครอยู่ที่ "${getCurrentMapName()}" (ไม่ใช่เมืองหลวง) และไม่ได้เปิดใช้งาน Butterfly Wing -> ยกเลิก Routine ร้านค้า!`, 'color: #ef4444; font-weight: bold;');
                window.__isShopping = false;
                return;
            }

            const noWing = typeof window.getBagItemCount === 'function' && window.getBagItemCount(90311) < 1;
            if (noWing) console.log(`%c[PmheeAether Shop] 🗺️ ไม่มี Butterfly Wing -> เปิดแผนที่แล้วเดินกลับเมืองหลวง`, 'color: #f59e0b; font-weight: bold;');
            else {
                console.log(`%c[PmheeAether Shop] ⚡ ตัวละครอยู่ที่ "${getCurrentMapName()}" (ไม่ใช่เมืองหลวง) -> กำลังใช้วาร์ป Butterfly Wing...`, 'color: #38bdf8; font-weight: bold;');
                window.useButterflyWing();
            }

            if (window.__shopWarpInterval) {
                clearInterval(window.__shopWarpInterval);
                window.__shopWarpInterval = null;
            }

            let warpAttempts = noWing ? 3 : 0;
            let walkFallbackStarted = false;
            window.__shopWarpInterval = setInterval(() => {
                if (!window.__isBotRunning) {
                    clearInterval(window.__shopWarpInterval);
                    window.__shopWarpInterval = null;
                    window.__isShopping = false;
                    return;
                }

                warpAttempts++;

                // เช็คว่าตัวละครตายหรือไม่ขณะรอวาร์ป
                if (typeof isCharacterDead === 'function' && isCharacterDead()) {
                    clearInterval(window.__shopWarpInterval);
                    window.__shopWarpInterval = null;
                    console.warn('%c[PmheeAether Shop Guard] 🛑 ตัวละครเสียชีวิตขณะพยายามวาร์ป! ยกเลิก Routine ร้านค้า', 'color: #ef4444; font-weight: bold;');
                    window.__isShopping = false;
                    return;
                }

                // เช็คว่าถึงเมืองหลวงสำเร็จหรือยัง
                if (typeof isCharacterInCity === 'function' && isCharacterInCity()) {
                    clearInterval(window.__shopWarpInterval);
                    window.__shopWarpInterval = null;
                    console.log(`%c[PmheeAether Shop] 🏛️ วาร์ปถึงเมืองหลวง (${getCurrentMapName()}) สำเร็จ 100%! เตรียมเดินหา NPC...`, 'color: #22c55e; font-weight: bold;');
                    setTimeout(() => {
                        if (window.__isBotRunning) startCityWalk();
                    }, 1200);
                    return;
                }

                // ถ้ายังไม่ถึงเมือง ลองใช้วาร์ปซ้ำ (สูงสุด 3 ครั้ง)
                if (warpAttempts <= 3) {
                    console.log(`%c[PmheeAether Shop] 🔄 ยังไม่ถึงเมืองหลวง (อยู่ที่ "${getCurrentMapName()}") กำลังใช้วาร์ปซ้ำ (${warpAttempts}/3)...`, 'color: #f59e0b;');
                    window.useButterflyWing();
                } else if (!walkFallbackStarted && typeof window.walkToTargetMap === 'function') {
                    // No Butterfly Wing (e.g. no zeny to buy any): travel to the capital the normal way (Alice
                    // warp, or walking when zeny is short) instead of giving up — the overweight check restarted
                    // the trip right away, forever. The farm map is put back at the end of the trip.
                    walkFallbackStarted = true;
                    console.log(`%c[PmheeAether Shop] 🚶 ใช้ Butterfly Wing ไม่ได้ (ไม่มีปีกในตัว?) -> เดินทางกลับเมืองหลวงแทน`, 'color: #f59e0b; font-weight: bold;');
                    window.__shoppingSince = Date.now();
                    window.walkToTargetMap('เมืองหลวงโซลเฮเวน', false, { walkOnly: true });
                } else if (walkFallbackStarted && warpAttempts < 180) {
                    // walking: keep waiting for the capital (checked at the top of this loop) — up to 6 minutes
                } else {
                    clearInterval(window.__shopWarpInterval);
                    window.__shopWarpInterval = null;
                    console.error(`%c[PmheeAether Shop Guard] ❌ วาร์ปกลับเมืองไม่สำเร็จหลังจากลอง 3 ครั้ง (แมพยังคงเป็น "${getCurrentMapName()}")! ยกเลิก Routine ร้านค้าทั้งหมด เพื่อป้องกันการซื้อของจนน้ำหนักเกินในแมพมอนสเตอร์`, 'color: #ef4444; font-weight: bold;');
                    if (walkFallbackStarted && /เมืองหลวง|โซลเฮเวน/.test(window.__targetFarmMap || '') && currentFarmMap && !/เมืองหลวง|โซลเฮเวน/.test(currentFarmMap)) {
                        window.__targetFarmMap = currentFarmMap;
                        try { localStorage.setItem('pelican_farm_map', currentFarmMap); } catch (e) {}
                    }
                    window.__isShopping = false;
                }
            }, 2000);
        } else {
            console.log(`%c[PmheeAether Shop] 🏛️ ตัวละครอยู่ที่เมืองหลวงอยู่แล้ว (${getCurrentMapName()}) -> เริ่มต้นเดินหา NPC ได้ทันที`, 'color: #22c55e;');
            startCityWalk();
        }
    };

    // ==========================================
    // 3.6 HUMANIZE RANDOM TASKS ENGINE
    // ==========================================
    window.__isHumanizing = false;
    window.__isManualTestingHumanize = false;

    async function humanizeBlacksmithTask() {
        console.log('%c[PmheeAether Humanize] 🔨 กิจกรรม: คุยกับ Blacksmith ซื้อหินมาขาย...', 'color: #38bdf8; font-weight: bold;');
        const live = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
        const zeny = Number(live.zeny) || window.__currentZeny || 0;
        if (zeny < 5000) {
            console.log('[PmheeAether Humanize] 💰 เงินคงเหลือน้อยกว่า 5,000 z -> ข้ามกิจกรรม Blacksmith');
            return;
        }

        const room = typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null;
        let smithKey = 'n7';
        if (room && room.state && room.state.npcs && typeof room.state.npcs.forEach === 'function') {
            room.state.npcs.forEach((n, k) => {
                if (n && n.name && (n.name.includes('Blacksmith') || n.name.includes('Enok') || n.name.includes('ช่างตีเหล็ก'))) {
                    smithKey = k;
                }
            });
        }

        window.sendRemoteNpcTalk(smithKey);
        await new Promise(r => setTimeout(r, 1100 + Math.floor(Math.random() * 400)));

        const dlg = document.querySelector('.npc-dialog');
        if (dlg && !document.querySelector('.shop-window')) {
            const opts = Array.from(dlg.querySelectorAll('.npc-options button')).map(b => (b.innerText || '').replace(/^\s*\d+\s*/, '').trim());
            const idx = opts.findIndex(o => /ซื้อ/.test(o) && !/แร่|ตีบวก/.test(o));
            if (idx >= 0) {
                window.sendRemoteNpcOption(idx);
                await new Promise(r => setTimeout(r, 800));
            }
        }

        const qty = Math.floor(Math.random() * 2) + 2;
        if (room) {
            room.send('shop_buy_many', { lines: [{ itemId: 90201, qty }] });
            console.log(`[PmheeAether Humanize] 🛒 ซื้อ Phracon x${qty} จาก Blacksmith...`);
        }

        await new Promise(r => setTimeout(r, 1600 + Math.floor(Math.random() * 800)));

        try {
            const shopModal = document.querySelector('.shop-window') || document.body;
            const rows = Array.from(shopModal.querySelectorAll('.shop-row'));
            const phraconRow = rows.find(r => {
                const txt = (r.innerText || '').toLowerCase();
                return txt.includes('phracon') || txt.includes('ฟราคอน');
            });
            if (phraconRow) {
                const addBtn = phraconRow.querySelector('button.cart-all') || phraconRow.querySelector('button.cart-add');
                if (addBtn && !addBtn.disabled) {
                    addBtn.click();
                    await new Promise(r => setTimeout(r, 350));
                    const confirmBtn = document.querySelector('button.cart-go');
                    if (confirmBtn && !confirmBtn.disabled) {
                        confirmBtn.click();
                        await new Promise(r => setTimeout(r, 450));
                        const finalBtn = Array.from(document.querySelectorAll('button')).find(b => (b.innerText || '').trim().includes('ยืนยันขาย'));
                        if (finalBtn) finalBtn.click();
                        console.log('[PmheeAether Humanize] 💵 ขาย Phracon คืนให้ NPC สำเร็จ');
                    }
                }
            }
        } catch (e) {}

        await new Promise(r => setTimeout(r, 600));
        if (typeof window.closeShopUI === 'function') window.closeShopUI();
        if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
        const closeX = document.querySelector('.shop-window .win-close, .npc-dialog .win-close');
        if (closeX) closeX.click();
    }

    async function humanizeSundriesTask() {
        console.log('%c[PmheeAether Humanize] 🏪 กิจกรรม: คุยกับร้านพ่อค้าซื้อยาเรดมาขาย...', 'color: #38bdf8; font-weight: bold;');
        const live = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
        const zeny = Number(live.zeny) || window.__currentZeny || 0;
        if (zeny < 5000) {
            console.log('[PmheeAether Humanize] 💰 เงินคงเหลือน้อยกว่า 5,000 z -> ข้ามกิจกรรมร้านของชำ');
            return;
        }

        const room = typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null;
        const targetNpc = (window.__shopConfig && window.__shopConfig.npcKey) ? window.__shopConfig.npcKey : 'n2';

        window.sendRemoteNpcTalk(targetNpc);
        await new Promise(r => setTimeout(r, 1000 + Math.floor(Math.random() * 400)));

        const dlg = document.querySelector('.npc-dialog');
        if (dlg && !document.querySelector('.shop-window')) {
            window.sendRemoteNpcOption(0);
            await new Promise(r => setTimeout(r, 800));
        }

        // ห้ามใช้ Butterfly Wing (90311) หรือกด cart-all เด็ดขาด เพราะจะขายบีวิงที่เพิ่งซื้อไว้กลับเมืองทิ้งทั้งหมด!
        const itemToBuy = { id: 90301, name: 'Red Potion', qty: Math.floor(Math.random() * 2) + 1 };

        if (room) {
            room.send('shop_buy_many', { lines: [{ itemId: itemToBuy.id, qty: itemToBuy.qty }] });
            console.log(`[PmheeAether Humanize] 🛒 ซื้อ ${itemToBuy.name} x${itemToBuy.qty} จากร้านของชำ...`);
        }

        await new Promise(r => setTimeout(r, 1500 + Math.floor(Math.random() * 800)));

        try {
            const shopModal = document.querySelector('.shop-window') || document.body;
            const rows = Array.from(shopModal.querySelectorAll('.shop-row'));
            const targetRow = rows.find(r => {
                const txt = (r.innerText || '').toLowerCase();
                return txt.includes('red potion') || txt.includes('เรด');
            });
            if (targetRow) {
                const addBtn = targetRow.querySelector('button.cart-add');
                if (addBtn && !addBtn.disabled) {
                    addBtn.click();
                    await new Promise(r => setTimeout(r, 350));
                    const confirmBtn = document.querySelector('button.cart-go');
                    if (confirmBtn && !confirmBtn.disabled) {
                        confirmBtn.click();
                        await new Promise(r => setTimeout(r, 450));
                        const finalBtn = Array.from(document.querySelectorAll('button')).find(b => (b.innerText || '').trim().includes('ยืนยันขาย'));
                        if (finalBtn) finalBtn.click();
                        console.log(`[PmheeAether Humanize] 💵 ขาย ${itemToBuy.name} 1 ชิ้นคืนให้ร้านเรียบร้อย`);
                    }
                }
            }
        } catch (e) {}

        await new Promise(r => setTimeout(r, 600));
        if (typeof window.closeShopUI === 'function') window.closeShopUI();
        if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
        const closeX = document.querySelector('.shop-window .win-close, .npc-dialog .win-close');
        if (closeX) closeX.click();
    }

    async function humanizeWalkTask() {
        console.log('%c[PmheeAether Humanize] 🚶 กิจกรรม: เดินสำรวจลานเมือง...', 'color: #38bdf8;');
        const room = typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null;
        if (!room) return;
        const cur = window.__currentPos || { x: 1664, y: 960 };
        const dx = (Math.random() < 0.5 ? -1 : 1) * (20 + Math.floor(Math.random() * 30));
        const dy = (Math.random() < 0.5 ? -1 : 1) * (20 + Math.floor(Math.random() * 30));
        room.send('move_to', { x: cur.x + dx, y: cur.y + dy });
        await new Promise(r => setTimeout(r, 1800 + Math.floor(Math.random() * 600)));
    }

    async function humanizeStorageTask() {
        console.log('%c[PmheeAether Humanize] 📦 กิจกรรม: ตรวจสอบและฝากของ Whitelist เข้าคลัง...', 'color: #38bdf8;');
        if (typeof window.runAutoStorageDeposit === 'function') {
            await window.runAutoStorageDeposit({ humanize: true, storeWhitelist: true });
        }
    }

    window.runHumanizeRoutine = async function(onDone) {
        if (!window.__isBotRunning && !window.__isManualTestingHumanize) {
            if (onDone) onDone();
            return;
        }
        if (window.__isHumanizing) {
            if (onDone) onDone();
            return;
        }

        window.__isHumanizing = true;
        console.log('%c[PmheeAether Humanize] 🎭 เริ่มต้นพฤติกรรมเสมือนคน (Humanize Routine)...', 'color: #38bdf8; font-weight: bold;');

        const cfg = window.__humanizeConfig || { enabled: true, buyBlacksmith: true, buySundries: true, randomWalk: true, storeDeposit: true };
        const taskPool = [];
        if (cfg.buyBlacksmith !== false) taskPool.push('blacksmith');
        if (cfg.buySundries !== false) taskPool.push('sundries');
        if (cfg.randomWalk !== false) taskPool.push('walk');
        if (cfg.storeDeposit !== false) taskPool.push('storage');

        const shuffled = taskPool.sort(() => Math.random() - 0.5);
        const count = Math.min(shuffled.length, Math.floor(Math.random() * 2) + 1);
        const selected = shuffled.slice(0, count);

        console.log(`[PmheeAether Humanize] 🎲 สุ่มทำ ${selected.length} กิจกรรมในรอบนี้: [${selected.join(', ')}]`);

        try {
            for (const t of selected) {
                if (!window.__isBotRunning && !window.__isManualTestingHumanize) break;
                if (t === 'blacksmith') await humanizeBlacksmithTask();
                else if (t === 'sundries') await humanizeSundriesTask();
                else if (t === 'walk') await humanizeWalkTask();
                else if (t === 'storage') await humanizeStorageTask();

                await new Promise(r => setTimeout(r, 800 + Math.floor(Math.random() * 1000)));
            }
        } catch (e) {
            console.warn('[PmheeAether Humanize] ⚠️ ขัดข้องระหว่างทำกิจกรรม:', e.message);
        } finally {
            window.__isHumanizing = false;
            window.__isManualTestingHumanize = false;
            console.log('%c[PmheeAether Humanize] ✅ กิจกรรมเสมือนคนในรอบนี้เสร็จสมบูรณ์', 'color: #22c55e; font-weight: bold;');
            if (typeof onDone === 'function') onDone();
        }
    };

    window.maybeRunHumanizeRoutine = function(onDone) {
        const cfg = window.__humanizeConfig || { enabled: true, chance: 70 };
        if (cfg.enabled === false) {
            if (onDone) onDone();
            return;
        }
        const roll = Math.random() * 100;
        if (roll > (cfg.chance || 70)) {
            console.log(`[PmheeAether Humanize] 🎲 ข้ามกิจกรรม Humanize ในรอบนี้ (Roll: ${Math.round(roll)} > ${cfg.chance || 70}%) -> เดินทางกลับไปฟาร์ม`);
            if (onDone) onDone();
            return;
        }
        window.runHumanizeRoutine(onDone);
    };

    // ==========================================
    // 4. World Map Opener (Unfocused-Safe)
    // ==========================================
    function closeAnyOpenMenus() {
        if (typeof window.closeShopUI === 'function') {
            window.closeShopUI();
        }
        const openNavMenu = document.querySelector('nav.hud-menu:not(.closed)');
        if (openNavMenu) {
            const menuToggleBtn = Array.from(document.querySelectorAll('button, div')).find(el => el.innerText && el.innerText.includes('เมนู'));
            if (menuToggleBtn) triggerClick(menuToggleBtn);
        }
        // ตรวจสอบถ้ามีปุ่มเมนูมุมขวาล่างเปิดอยู่
        const menuBtn = Array.from(document.querySelectorAll('button, div')).find(el => {
            if (el.closest('#pelican-hud')) return false;
            const txt = (el.innerText || '').trim();
            return txt === 'เมนู' || txt === '▼ เมนู' || txt === '▲ เมนู';
        });
        const hasOpenGrid = Array.from(document.querySelectorAll('button, div')).some(el => {
            if (el.closest('#pelican-hud')) return false;
            return (el.innerText || '').trim() === 'สมุดการ์ด' && el.offsetWidth > 0;
        });
        if (hasOpenGrid && menuBtn) {
            triggerClick(menuBtn);
        }
        dispatchKeyAll('Escape', 'Escape', 27);
    }

    function openWorldMap(callback) {
        if (isWorldMapOpen()) {
            if (callback) callback();
            return;
        }

        console.log('[PmheeAether] 🗺️ กำลังเปิดหน้าต่างแผนที่โลก...');

        closeAnyOpenMenus();

        const minimapStage = document.querySelector('.minimap-stage') ||
                             document.querySelector('[aria-label="เปิดแผนที่โลก"]') ||
                             document.querySelector('.minimap');

        if (minimapStage) {
            triggerClick(minimapStage);
            try { minimapStage.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true })); } catch(e) {}
        }

        dispatchKeyAll('m', 'KeyM', 77);

        if (window.__worldMapPollInterval) {
            clearInterval(window.__worldMapPollInterval);
            window.__worldMapPollInterval = null;
        }

        let attempts = 0;
        window.__worldMapPollInterval = setInterval(() => {
            if (!window.__isBotRunning && !window.__isNavigating) {
                clearInterval(window.__worldMapPollInterval);
                window.__worldMapPollInterval = null;
                return;
            }

            attempts++;
            if (isWorldMapOpen()) {
                clearInterval(window.__worldMapPollInterval);
                window.__worldMapPollInterval = null;
                console.log('%c[PmheeAether] ✅ หน้าต่างแผนที่โลกเปิดสำเร็จ!', 'color: #22c55e;');
                setTimeout(() => { if (callback) callback(); }, 350);
                return;
            }

            if (attempts % 3 === 0) {
                closeAnyOpenMenus();
                if (minimapStage) triggerClick(minimapStage);
                dispatchKeyAll('m', 'KeyM', 77);
            }

            if (attempts >= 16) {
                clearInterval(window.__worldMapPollInterval);
                window.__worldMapPollInterval = null;
                console.error('[PmheeAether] ❌ เปิดแผนที่โลกไม่สำเร็จ');
                window.__isNavigating = false;
                window.__isRecovering = false;
            }
        }, 250);
    }

    window.openMap = function() {
        openWorldMap();
    };

    window.__arrivalWatcherInterval = null;
    window.__arrivalTimeout = null;

    function stopArrivalWatcher() {
        if (window.__arrivalWatcherInterval) {
            clearInterval(window.__arrivalWatcherInterval);
            window.__arrivalWatcherInterval = null;
        }
        if (window.__arrivalTimeout) {
            clearTimeout(window.__arrivalTimeout);
            window.__arrivalTimeout = null;
        }
    }

    // "ประหยัดค่าวาร์ป": below this much zeny, travel on foot through the world map instead of paying
    // for Alice's warp (0 = off). Stored like the other bot settings.
    try {
        window.__travelConfig = Object.assign({ minZenyForWarp: 0 }, JSON.parse(localStorage.getItem('pelican_travel_cfg') || '{}'));
    } catch (e) { window.__travelConfig = { minZenyForWarp: 0 }; }
    window.saveTravelConfig = function() {
        try { localStorage.setItem('pelican_travel_cfg', JSON.stringify(window.__travelConfig)); } catch (e) {}
    };
    window.isWarpTooExpensive = function() {
        const min = Number(window.__travelConfig && window.__travelConfig.minZenyForWarp) || 0;
        if (min <= 0) return false;
        const ch = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : null;
        const zeny = ch && typeof ch.zeny === 'number' ? ch.zeny : null;
        return zeny !== null && zeny < min;
    };

    // (v4.24-4.25 moved characters to an easier map after repeated deaths; removed on request — forget what it
    //  saved so nobody keeps being sent back to the old map)
    try {
        Object.keys(localStorage).filter(k => /safe_map_/.test(k)).forEach(k => localStorage.removeItem(k));
    } catch (e) {}
    window.__safeMap = null;

    window.skipUnexpectedTownWait = function() {
        if (!window.__unexpectedTownWaiting) return;
        window.__unexpectedTownWaiting = false;
        window.__unexpectedTownWaitUntil = 0;
        window.__unexpectedTownTicks = 0;
        const unexpBox = document.getElementById('p-unexpected-town-box');
        if (unexpBox) unexpBox.style.display = 'none';
        console.log('%c[PmheeAether Watchdog] ⏩ ผู้ใช้กดข้ามเวลารอนิรภัย -> เตรียมตัวเดินทางกลับไปฟาร์ม', 'color: #22c55e; font-weight: bold;');
        const targetMap = window.__targetFarmMap || 'ถนนต้นหลิว';
        if (typeof window.walkToTargetMap === 'function') {
            window.walkToTargetMap(targetMap, true, { skipWait: true });
        }
    };

    window.walkToTargetMap = function(mapName = window.__targetFarmMap, force = false, opts = {}) {
        if (window.__unexpectedTownWaiting && !(opts && opts.skipWait)) {
            console.log('%c[PmheeAether] 🛑 อยู่ระหว่างการพักรอนิรภัยหลังกลับเมืองผิดปกติ ระงับการเดินไปแมพฟาร์ม', 'color: #f59e0b;');
            return;
        }
        if (window.__isConsolidating && !(opts && opts.allowDuringConsolidation)) {
            console.log('%c[PmheeAether] 🚫 อยู่ระหว่างขั้นตอนรวมเงิน (Consolidation) ระงับการเดินไปแมพฟาร์ม', 'color: #f59e0b;');
            return;
        }
        if (!mapName) mapName = window.__targetFarmMap;
        const skipPlanOverride = Boolean(
            (opts && opts.fromParty) ||
            (window.__partyForcedMap && mapName === window.__partyForcedMap) ||
            (typeof window.isPlanLevelMapProgressionDone === 'function' && window.isPlanLevelMapProgressionDone())
        );
        if (!skipPlanOverride && window.__planScriptEnabled && window.__currentScriptPlan && mapName === window.__targetFarmMap && !/เมืองหลวง|โซลเฮเวน/.test(mapName || '') && typeof window.planMapForNow === 'function') {
            const planMap = window.planMapForNow();
            if (planMap && planMap !== mapName) {
                console.log(`%c[PmheeAether Plan] 🗺️ แผนกำหนดแมพสำหรับเลเวลนี้คือ "${planMap}" (แทน "${mapName}")`, 'color: #38bdf8; font-weight: bold;');
                mapName = planMap;
            }
        }

        // ถ้ากำลังนำทางอยู่ แต่เป็นการกดสั่งใหม่ (force) หรือเปลี่ยนแมพเป้าหมาย ให้ยกเลิกการเดินเดิมทันที
        if (window.__isNavigating) {
            if (force || mapName !== window.__targetFarmMap) {
                console.log(`%c[PmheeAether] 🔄 ยกเลิกการเดินเดิม สลับไปเดินหาแมพใหม่ทันที: "${mapName}"`, 'color: #f59e0b; font-weight: bold;');
                stopArrivalWatcher();
                window.__isNavigating = false;
            } else {
                console.log(`[PmheeAether] กำลังเดินทางไปยัง "${window.__targetFarmMap}" อยู่แล้ว`);
                return;
            }
        }

        window.__isNavigating = true;
        window.__targetFarmMap = mapName;
        localStorage.setItem('pelican_farm_map', mapName);
        if (typeof window.rememberFarmMap === 'function') window.rememberFarmMap(mapName);
        if (!/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(mapName || '')) {
            const selMapEl = document.getElementById('p-target-map-select');
            if (selMapEl && selMapEl.value !== mapName) selMapEl.value = mapName;
        }
        const navSeq = window.__navSeq = (window.__navSeq || 0) + 1;
        const navLive = () => window.__navSeq === navSeq;
        let navClicked = false;   // a world-map walk/warp button was pressed for this trip

        // GUARD: ตรวจสอบการตาย
        if (typeof isCharacterDead === 'function' && isCharacterDead()) {
            console.warn('[PmheeAether Guard] 🛑 ตัวละครเสียชีวิตอยู่ ไม่สามารถเริ่มเดินไปแมพได้');
            window.__isNavigating = false;
            return;
        }

        console.log(`%c[PmheeAether] 🗺️ กำลังเริ่มกระบวนการเดินไปแมพ: ${mapName}`, 'color: #00ffcc; font-weight: bold;');

        const inCity = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;
        const curMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
        const isTargetCity = mapName.includes('เมืองหลวง') || mapName.includes('โซลเฮเวน') || mapName.includes('ตลาดคาราวาน');
        const cleanTargetMapName = mapName.replace(/\s*\(Lv\..*?\)/i, '').trim() || mapName;

        if (!isTargetCity && window.__channelCheckMode === 'always' && !window.__pendingPostSellChannelCheck) {
            if (inCity || window.__isRecovering || !curMap || !curMap.includes(cleanTargetMapName)) {
                window.__pendingPostSellChannelCheck = true;
                window.__pendingPostSellAt = Date.now();
                window.__pendingPostSellReason = window.__isRecovering ? 'after-death' : (inCity ? 'from-town' : 'arrive-map');
            }
        }

        // ถ้าตัวละครอยู่ในเมืองหลวง หรือกำลังฟื้นคืนชีพ (recovering) แต่เป้าหมายคือแมพมอนสเตอร์ -> ห้ามสรุปว่าถึงแล้วเด็ดขาด!
        if ((!inCity || isTargetCity) && curMap && cleanTargetMapName && curMap.includes(cleanTargetMapName) && !window.__isRecovering) {
            (async () => {
                try {
                    if (!inCity && !isTargetCity && window.__pendingPostSellChannelCheck && typeof window.runPostSellChannelCheck === 'function') {
                        await window.runPostSellChannelCheck(window.__pendingPostSellReason || 'after-sell');
                    }
                } catch (e) {}
                window.__lastFarmArrivalMapKey = cleanTargetMapName;
                console.log(`[PmheeAether] ตัวละครอยู่ที่แมพ "${mapName}" อยู่แล้ว เปิดบอททันที!`);
                window.startBot();
                window.__isNavigating = false;
                window.__navWalkOnly = false;
                window.__isRecovering = false;
            })();
            return;
        }

        // ปิด AUTO ในเกมชั่วคราวก่อนเดินข้ามแมพ เพื่อไม่ให้เซิร์ฟเวอร์ดึงตัวละครกลับจุดเปิด AUTO เดิมระหว่างวิ่งไปวาร์ป
        if (!inCity && typeof window.deactivateInGameAuto === 'function') {
            try { window.deactivateInGameAuto(); } catch (e) {}
        }

        const saveWarp = window.isWarpTooExpensive() || !!(opts && opts.walkOnly);
        window.__navWalkOnly = !!(opts && opts.walkOnly);
        const targetMapId = MAP_NAME_TO_ID[cleanTargetMapName] || MAP_NAME_TO_ID[mapName];

        function clickWalkButton() {
            // เงินต่ำกว่าที่ตั้งไว้: เดินผ่านแผนที่โลก (ฟรี) ก่อน — วาร์ปเฉพาะเมื่อเดินจากตรงนี้ไม่ได้
            if (saveWarp) {
                const freeWalk = document.querySelector('.worldmap-walk button');
                if (freeWalk && !freeWalk.disabled) {
                    navClicked = true;
                    triggerClick(freeWalk);
                    console.log(`%c[PmheeAether Warp] 💸 ${window.__navWalkOnly ? 'เดินกลับเมืองผ่านแผนที่' : 'เงินต่ำกว่าที่ตั้งไว้'} -> เดินไปเอง (ไม่เสียค่าวาร์ป)`, 'color: #f59e0b; font-weight: bold;');
                    setTimeout(() => { if (isWorldMapOpen()) dispatchKeyAll('m', 'KeyM', 77); }, 1500);
                    startArrivalWatcher(mapName);
                    return true;
                }
                if (freeWalk) console.warn('[PmheeAether Warp] ⚠️ เดินไปจากตรงนี้ไม่ได้ -> จำเป็นต้องวาร์ป');
            }
            // 1. ถ้ามีปุ่ม "วาร์ปไปที่นี่" (Alice Warp Service จาก NPC n6) ให้กดวาร์ปทันที!
            // ไม่เช็ก offsetWidth > 0 เพราะตอนพับจอ/ย่อจอขนาดอาจเป็น 0
            const warpBtn = Array.from(document.querySelectorAll('.worldmap-window button, .worldmap-inspect button, button')).find(b => {
                const txt = (b.innerText || b.textContent || '').trim();
                return txt.includes('วาร์ปไปที่นี่') && !b.disabled && !b.className.includes('disabled');
            });

            if (warpBtn) {
                navClicked = true;
                triggerClick(warpBtn);
                console.log('%c[PmheeAether Warp] ⚡ พบคลิก "วาร์ปไปที่นี่ (NPC Alice)" สำเร็จ! กำลังวาร์ปตรง...', 'color: #eab308; font-weight: bold;');

                setTimeout(() => {
                    if (isWorldMapOpen()) {
                        dispatchKeyAll('m', 'KeyM', 77);
                    }
                }, 1200);

                startArrivalWatcher(mapName);
                return true;
            }

            // 2. ถ้าไม่มีปุ่มวาร์ป ให้กด "เดินไปที่นี่" ปกติ
            const walkBtn = document.querySelector('.worldmap-walk button') ||
                            Array.from(document.querySelectorAll('button')).find(b => (b.innerText || b.textContent || '').includes('เดินไปที่นี่') && !b.disabled);
            if (walkBtn && !walkBtn.disabled) {
                navClicked = true;
                // หากอยู่ในเมืองและไม่ได้เปิดประหยัดค่าวาร์ป แต่หน้าต่างที่เปิดเป็นแผนที่โลกปกติ (ไม่ใช่โหมดวาร์ปของ Alice)
                // ให้ยิง sendNpcWarp คู่ไปด้วยเผื่อแมพนี้เคยเปิดแล้วจะได้วาร์ปทันที ส่วนแมพที่ยังไม่เคยเปิดก็จะเดินไปตามปกติ
                if (inCity && !saveWarp && targetMapId && typeof window.sendNpcWarp === 'function') {
                    window.sendNpcWarp(targetMapId);
                }
                triggerClick(walkBtn);
                console.log('%c[PmheeAether] 🚀 คลิก "เดินไปที่นี่" สำเร็จ! กำลังเฝ้าดูการเดินทาง...', 'color: #22c55e; font-weight: bold;');

                setTimeout(() => {
                    if (isWorldMapOpen()) {
                        dispatchKeyAll('m', 'KeyM', 77);
                    }
                }, 1500);

                startArrivalWatcher(mapName);
                return true;
            }
            return false;
        }

        function clickMapPin(retries = 3) {
            if (!navLive()) return;   // a newer trip took over
            // ตัดข้อความวงเล็บเลเวลออก เช่น "ทะเลสาบอาซูร์ (Lv. 12-20)" -> "ทะเลสาบอาซูร์"
            const cleanMapName = cleanTargetMapName;

            const currentInspect = document.querySelector('.worldmap-inspect h3');
            if (currentInspect && currentInspect.textContent.includes(cleanMapName)) {
                if (clickWalkButton()) return;
            }

            // ค้นหาเฉพาะในคอนเทนเนอร์แผนที่เท่านั้น ห้ามค้นหาใน document.body เพื่อป้องกันการไปคลิกโดนผู้เล่นอื่น
            const stage = document.querySelector('.worldmap-stage, .worldmap-body, .worldmap-window, [class*="worldmap"]');
            if (!stage) {
                console.warn(`[PmheeAether] ⏳ หน้าต่างแผนที่ยังไม่เปิด กำลังรอ... (retries: ${retries})`);
                if (retries > 0) {
                    setTimeout(() => clickMapPin(retries - 1), 600);
                } else {
                    // Give up this attempt but free the travel state, so the watchdog starts a fresh one
                    console.warn(`[PmheeAether] ⚠️ เปิดแผนที่ไม่สำเร็จ — ยกเลิกรอบนี้ ระบบจะลองเดินทางใหม่`);
                    window.__isNavigating = false;
                    window.__navWalkOnly = false;
                    window.__isRecovering = false;
                }
                return;
            }

            const atlasPins = Array.from(stage.querySelectorAll('button.atlas-pin, .atlas-pin')).filter(el => {
                const txt = (el.textContent || '').trim();
                return txt.includes(cleanMapName);
            });

            const matches = atlasPins.length > 0 ? atlasPins : Array.from(stage.querySelectorAll('*')).filter(el => {
                if (el.closest('#pelican-hud') || el.closest('#pelican-data-modal')) return false;
                const txt = (el.textContent || '').trim();
                return txt.includes(cleanMapName);
            });

            const pin = atlasPins[0] || matches.find(el => !Array.from(el.children).some(c => c.textContent && c.textContent.includes(cleanMapName))) || matches[0];

            if (pin) {
                console.log(`%c[PmheeAether Map] 📍 คลิกหมุดแมพ: "${cleanMapName}"`, 'color: #00ffcc; font-weight: bold;');
                triggerClick(pin);
                try { pin.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true })); } catch(e) {}

                const mapId = targetMapId;

                if (window.__walkClickInterval) {
                    clearInterval(window.__walkClickInterval);
                    window.__walkClickInterval = null;
                }

                let walkTries = 0;
                window.__walkClickInterval = setInterval(() => {
                    if (!navLive() || (!window.__isBotRunning && !window.__isNavigating)) {
                        clearInterval(window.__walkClickInterval);
                        window.__walkClickInterval = null;
                        return;
                    }

                    walkTries++;
                    if (clickWalkButton() || walkTries >= 8) {
                        clearInterval(window.__walkClickInterval);
                        window.__walkClickInterval = null;
                        if (!navClicked && saveWarp && navLive()) {
                            console.warn('[PmheeAether] ⚠️ ไม่พบปุ่ม "เดินไปที่นี่" ในแผนที่ — ยกเลิกรอบนี้ ระบบจะลองเดินทางใหม่');
                            window.__isNavigating = false;
                            window.__navWalkOnly = false;
                            if (isWorldMapOpen()) dispatchKeyAll('m', 'KeyM', 77);
                        }
                    }
                }, 300);

                if (mapId && typeof window.sendNpcWarp === 'function' && !saveWarp) {
                    // Fallback only: when no map button could be pressed for this same trip
                    setTimeout(() => {
                        if (navLive() && !navClicked && (window.__isBotRunning || window.__isNavigating)) {
                            window.sendNpcWarp(mapId);
                        }
                    }, 1500);
                }
            } else if (retries > 0) {
                setTimeout(() => clickMapPin(retries - 1), 400);
            } else {
                console.warn(`[PmheeAether] ไม่พบหมุดแมพ "${cleanMapName}" บนหน้าต่างแผนที่`);
                const mapId = MAP_NAME_TO_ID[cleanMapName] || MAP_NAME_TO_ID[mapName];
                if (mapId && typeof window.sendNpcWarp === 'function' && !saveWarp) {
                    console.log(`[PmheeAether Warp] ⚡ ส่ง Packet วาร์ปตรงไปยัง "${cleanMapName}" (${mapId})...`);
                    window.sendNpcWarp(mapId);
                    startArrivalWatcher(cleanMapName);
                    return;
                }
                if (!clickWalkButton()) {
                    window.__isNavigating = false;
                    window.__navWalkOnly = false;
                    window.__isRecovering = false;
                }
            }
        }

        // ถ้าตัวละครอยู่ในเมืองหลวง ให้คุยกับ Alice (n6) เพื่อฮีลเลือด/มานาให้เต็มและเปิด Alice Warp Service ก่อน
        // (หากตั้งประหยัดค่าวาร์ปและเงินต่ำกว่าเกณฑ์ ให้แวะฮีลฟรีกับ Alice ก่อนถ้าเลือด/มานายังไม่เต็ม แล้วค่อยเปิดแผนที่โลกเดินไปเอง)
        if (saveWarp) {
            const hpSpNow = (typeof window.getCharacterHpSp === 'function') ? window.getCharacterHpSp() : null;
            if (typeof isCharacterInCity === 'function' && isCharacterInCity() && !isTargetCity && hpSpNow && hpSpNow.needsHeal) {
                console.log(`%c[PmheeAether Warp] 💖 แวะฮีลฟรีกับ NPC Alice ก่อนเดินเท้าไป "${mapName}" (HP: ${hpSpNow.hp}/${hpSpNow.maxHp}, SP: ${hpSpNow.sp}/${hpSpNow.maxSp})...`, 'color: #ec4899; font-weight: bold;');
                window.openAliceWarpService(() => {
                    if (!navLive()) return;
                    console.log(`%c[PmheeAether Warp] 💸 เงินต่ำกว่า ${Number(window.__travelConfig.minZenyForWarp).toLocaleString()} z -> ฮีลเสร็จแล้ว เปิดแผนที่โลกเดินไป "${mapName}"`, 'color: #f59e0b; font-weight: bold;');
                    openWorldMap(() => clickMapPin(2));
                }, { healOnly: true });
            } else {
                console.log(`%c[PmheeAether Warp] 💸 เงินต่ำกว่า ${Number(window.__travelConfig.minZenyForWarp).toLocaleString()} z -> ไม่ใช้วาร์ป Alice เปิดแผนที่โลกแล้วเดินไป "${mapName}"`, 'color: #f59e0b; font-weight: bold;');
                openWorldMap(() => clickMapPin(2));
            }
        } else if (typeof isCharacterInCity === 'function' && isCharacterInCity()) {
            console.log(`%c[PmheeAether Warp] 🏛️ ตัวละครอยู่ในเมืองหลวง -> คุยกับ NPC Alice เพื่อฮีลและเปิดวาร์ปเกตด่วนไป "${mapName}" (Warp Service ไม่ใช่ซื้อของ/ลูกธนู)`, 'color: #eab308; font-weight: bold;');
            window.openAliceWarpService(() => {
                setTimeout(() => { if (navLive()) clickMapPin(3); }, 400);
            });
        } else {
            console.log(`%c[PmheeAether] 🗺️ กำลังเปิดแผนที่โลกเพื่อเดินทางไปยัง "${mapName}"...`, 'color: #38bdf8; font-weight: bold;');
            openWorldMap(() => clickMapPin(2));
        }
    };

    function startArrivalWatcher(targetMap) {
        stopArrivalWatcher();
        const cleanTarget = String(targetMap || '').replace(/\s*\(Lv\..*?\)/i, '').trim() || String(targetMap || '');
        let lastWatcherMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
        let lastWatcherPos = window.__currentPos ? `${window.__currentPos.x},${window.__currentPos.y}` : '';
        let lastProgressAt = Date.now();
        console.log(`%c[PmheeAether] 📡 เริ่มต้นระบบตรวจจับการถึงแมพ: "${targetMap}"`, 'color: #38bdf8;');
        window.__arrivalWatcherInterval = setInterval(() => {
            if (!window.__isBotRunning && !window.__isNavigating) {
                stopArrivalWatcher();
                window.__isNavigating = false;
                window.__navWalkOnly = false;
                return;
            }

            if (typeof isCharacterDead === 'function' && isCharacterDead()) {
                stopArrivalWatcher();
                window.__isNavigating = false;
                window.__navWalkOnly = false;
                return;
            }

            const inCity = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;
            const currentMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
            const isTargetCity = cleanTarget.includes('เมืองหลวง') || cleanTarget.includes('โซลเฮเวน') || cleanTarget.includes('ตลาดคาราวาน');
            const curPosKey = window.__currentPos ? `${window.__currentPos.x},${window.__currentPos.y}` : '';

            if ((currentMap && currentMap !== lastWatcherMap) || (curPosKey && curPosKey !== lastWatcherPos)) {
                lastWatcherMap = currentMap || lastWatcherMap;
                lastWatcherPos = curPosKey || lastWatcherPos;
                lastProgressAt = Date.now();
            }

            // ระหว่างอยู่แมพทางผ่าน (ยังไม่ใช่แมพเป้าหมาย) ต้องปิด AUTO เสมอ เพื่อไม่ให้บอทตีมอนดึงตัวละครหลุดจากหน้าวาร์ป
            if (!inCity && currentMap && cleanTarget && !currentMap.includes(cleanTarget)) {
                if (typeof getInGameAutoStatus === 'function' && getInGameAutoStatus() === 'on') {
                    window.deactivateInGameAuto();
                }
            }

            if ((!inCity || isTargetCity) && currentMap && cleanTarget && currentMap.includes(cleanTarget)) {
                stopArrivalWatcher();
                console.log(`%c[PmheeAether] 🎯 เดินทางถึงแมพ "${targetMap}" สำเร็จ! เปิด Auto-Bot...`, 'color: #22c55e; font-weight: bold;');
                setTimeout(async () => {
                    try {
                        if (window.__isBotRunning) {
                            if (typeof isCharacterOverweight === 'function' && isCharacterOverweight()) {
                                console.warn('%c[PmheeAether] ⚖️ ถึงแมพฟาร์มแล้วแต่น้ำหนักเต็มหรือเกินเกณฑ์ (>= 90%)! สั่งวาร์ปกลับไปขายของทันที...', 'color: #ef4444; font-weight: bold;');
                                window.__pendingPostSellChannelCheck = false;
                                window.executeAutoShopRoutine();
                            } else {
                                if (!inCity && !isTargetCity && window.__channelCheckMode === 'always' && !window.__pendingPostSellChannelCheck) {
                                    window.__pendingPostSellChannelCheck = true;
                                    window.__pendingPostSellAt = Date.now();
                                    window.__pendingPostSellReason = window.__pendingPostSellReason || 'arrive-map';
                                }
                                if (!inCity && !isTargetCity && window.__pendingPostSellChannelCheck && typeof window.runPostSellChannelCheck === 'function') {
                                    await window.runPostSellChannelCheck(window.__pendingPostSellReason || 'after-sell');
                                }
                                if (!inCity && !isTargetCity && cleanTarget) {
                                    window.__lastFarmArrivalMapKey = cleanTarget;
                                }
                                if (window.__isBotRunning) {
                                    window.startBot();
                                }
                            }
                        }
                    } finally {
                        window.__isNavigating = false;
                        window.__navWalkOnly = false;
                        window.__isRecovering = false;
                    }
                }, 1500);
                return;
            }

            // หากตัวละครหยุดนิ่งไม่ขยับและไม่เปลี่ยนแมพนานเกิน 90 วินาที จึงถือว่าหมดเวลาเดินทางรอบนี้เพื่อให้ Watchdog สั่งเดินใหม่
            if (Date.now() - lastProgressAt > 90000) {
                stopArrivalWatcher();
                console.warn(`[PmheeAether] ⚠️ ตัวละครหยุดนิ่งระหว่างเดินทางไปยัง "${targetMap}" เกิน 90 วินาที — รีเซ็ตเพื่อให้ระบบสั่งเดินต่อ`);
                window.__isNavigating = false;
                window.__navWalkOnly = false;
                window.__isRecovering = false;
            }
        }, 1500);

        const longWalk = /เมืองหลวง|โซลเฮเวน/.test(targetMap) && window.__navWalkOnly;   // walking home without a wing
        window.__arrivalTimeout = setTimeout(() => {
            if (window.__isNavigating) {
                stopArrivalWatcher();
                console.warn(`[PmheeAether] ⚠️ หมดเวลาเฝ้าดูการเดินทางไปยัง "${targetMap}" (Timeout)`);
                window.__isNavigating = false;
                window.__navWalkOnly = false;
                window.__isRecovering = false;
            }
        }, longWalk ? 480000 : 300000);
    }


    // ==========================================
    // 6. Watchdog Loop
    // ==========================================
    let lastAutoActivateAttempt = 0;
    let autoActivateFailCount = 0;
    let lastPeriodicWeightRefresh = 0;
    let lastCityToFarmAttempt = 0, lastTownSweepAt = 0, cityTargetSince = 0;
    let navStaleSince = 0;
    let lastIntermediatePos = '', intermediateStillTicks = 0, lastIntermediateWalkAttempt = 0;

    // Why is the character in town? Judged when it ARRIVES: an arrival with a reason (a trip / Butterfly Wing /
    // shop / plan stay / respawn / consolidation, or the bot stopped) explains the whole stay until it leaves town.
    // Before, a plan trip (e.g. Weight Limit Scrolls) that finished in town was taken for an unexplained return.
    setInterval(() => {
        try {
            const curMapNow = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
            if (!curMapNow) return; // map label not rendered yet during reconnect/warp
            const inCityNow = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;
            if (!inCityNow) { window.__wasInCity = false; window.__townArrivalExplained = false; return; }
            if (window.__wasInCity === true) {
                if (!window.__isBotRunning || window.__isConsolidating || window.__isRecovering) window.__townArrivalExplained = true;
                return;
            }
            const first = window.__wasInCity === undefined;   // page just loaded in town
            window.__wasInCity = true;
            const recent = t => Date.now() - (Number(t) || 0) < 120000;
            const needs = typeof window.otherTownNeeds === 'function' ? window.otherTownNeeds('').length : 0;
            window.__townArrivalExplained = first || !window.__isBotRunning || !!(window.__isShopping || window.__isStoring || window.__isNavigating
                || window.__isWalkingToMap || window.__isRecovering || window.__isConsolidating || window.__isGearRefining || window.__isChangingJob
                || window.__isHumanizing || window.__isWeightScrollBusy || needs > 0 || ((window.__planJobChangeHoldUntil || 0) > Date.now())
                || recent(window.__lastBwingUsedAt) || recent(window.__goHomeWingAt) || recent(window.__lastRespawnAt)
                || recent(window.__lastIntentionalWarpAt) || recent(window.__lastTownTripAt) || recent(lastAutoShopCompletionTime)
                || (typeof isCharacterDead === 'function' && isCharacterDead()));
            if (!window.__townArrivalExplained) console.warn('[PmheeAether Watchdog] ⚠️ เข้าเมืองโดยไม่มีระบบไหนสั่ง (ไม่ได้เดินทาง / ใช้ปีก / ตาย)');
        } catch (e) {}
    }, 1000);

    setInterval(() => {
        if (!window.__isBotRunning || !window.__autoLoopEnabled || window.__isRecovering || window.__isConsolidating) return;
        const deadNow = typeof isCharacterDead === 'function' ? isCharacterDead() : false;
        if (window.__isShopping && !deadNow) return;
        if (deadNow && (window.__isShopping || window.__isNavigating)) {
            // a shop trip / walk can't finish while dead (e.g. Butterfly Wing loop): drop it and respawn
            console.warn('[PmheeAether] ⚠️ ตัวละครตายระหว่างซื้อขาย/เดินทาง -> ยกเลิกแล้วฟื้นที่จุดเกิด');
            window.__isShopping = false;
            window.__isNavigating = false;
            window.__navWalkOnly = false;
        }

        const isDead = deadNow;
        const inCity = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;

        if (inCity || isDead) {
            window.__lastFarmArrivalMapKey = null;
        }

        // 1. ตรวจจับการเสียชีวิต (Dead Check)
        if (isDead) {
            console.log('%c[PmheeAether] ⚠️ ตัวละครตาย! เริ่มชุบชีวิตและเตรียมเดินกลับแมพฟาร์ม...', 'color: #ef4444; font-weight: bold;');
            lastCityToFarmAttempt = Date.now() + 3000;   // the respawn below walks back itself (was sent twice)
            window.__isRecovering = true;
            if (window.__channelCheckMode === 'always') {
                window.__pendingPostSellChannelCheck = true;
                window.__pendingPostSellAt = Date.now();
                window.__pendingPostSellReason = 'after-death';
            }
            autoActivateFailCount = 0;

            // ส่ง Packet ชุบชีวิต
            if (typeof window.sendRespawn === 'function') {
                window.sendRespawn();
            }

            // คลิกปุ่มฟื้นคืนชีพบน Modal (เช่น "ฟื้นที่จุดเกิด")
            try {
                const respawnBtns = Array.from(document.querySelectorAll('button, div[role="button"], a.btn')).filter(el => {
                    if (el.closest('#pelican-hud') || el.closest('[class*="chat"]') || el.closest('.chat-log') || el.closest('.worldmap-window')) return false;
                    const txt = (el.innerText || '').trim().split('\n')[0].trim();
                    return (txt === 'ฟื้นที่จุดเกิด' || txt === 'ฟื้นคืนชีพ' || txt === 'ฟื้นอัตโนมัติ') && el.offsetWidth > 0 && el.offsetHeight > 0;
                });
                if (respawnBtns[0]) triggerClick(respawnBtns[0]);
            } catch(e) {}

            // รอจนกระทั่งตัวละครฟื้นคืนชีพและแมพสลับเข้าเมืองสำเร็จ
            let respawnCheckCount = 0;
            const respawnInterval = setInterval(() => {
                respawnCheckCount++;
                const stillDead = typeof isCharacterDead === 'function' ? isCharacterDead() : false;
                const nowInCity = typeof isCharacterInCity === 'function' ? isCharacterInCity() : false;

                // เมื่อตัวละครฟื้นแล้ว และเข้าสู่เมืองหลวงเรียบร้อย (หรือรอครบ 15 วินาที fail-safe)
                if (!stillDead && (nowInCity || respawnCheckCount >= 15)) {
                    clearInterval(respawnInterval);
                    window.__isRecovering = false;
                    console.log(`%c[PmheeAether] 🏛️ ตัวละครฟื้นคืนชีพเรียบร้อย (แมพ: "${getCurrentMapName()}")! สั่งเดินกลับไปฟาร์ม...`, 'color: #22c55e; font-weight: bold;');
                    setTimeout(() => {
                        if (window.__isBotRunning) {
                            window.walkToTargetMap(window.__targetFarmMap || 'ถนนต้นหลิว', true);
                        }
                    }, 1200);
                }
            }, 1000);

            // Fail-safe 20s ป้องกันติดค้าง
            setTimeout(() => {
                clearInterval(respawnInterval);
                window.__isRecovering = false;
            }, 20000);
            return;
        }

        // 2. ถ้ากำลังเดินทางข้ามแมพ ให้รอเดินทางเสร็จก่อน — but a "travelling" flag left on while the character
        //    stands in the capital for minutes (e.g. after the job-change trip) is stale: clear it, or nothing
        //    sends the character back to the farm until STOP / START
        if (window.__isNavigating) {
            if (!inCity || window.__isWalkingToMap) { navStaleSince = 0; return; }
            if (!navStaleSince) navStaleSince = Date.now();
            if (Date.now() - navStaleSince < 4 * 60 * 1000) return;
            console.warn('[PmheeAether Watchdog] ⚠️ สถานะ "กำลังเดินทาง" ค้างอยู่ในเมืองหลวงเกิน 4 นาที -> รีเซ็ตแล้วส่งกลับแมพฟาร์ม');
            window.__isNavigating = false;
            window.__navWalkOnly = false;
            navStaleSince = 0;
        } else navStaleSince = 0;

        // 3. ตรวจสอบน้ำหนักสัมภาระเกินเกณฑ์หรือช่องกระเป๋าเต็ม (Weight & Bag Slots Overload Check) - เช็คทั้งในเมืองและนอกเมือง!
        if (typeof isCharacterOverweight === 'function' && isCharacterOverweight()) {
            const w = (typeof getCharacterWeight === 'function' ? getCharacterWeight() : null) || window.__lastKnownWeight || window.__serverWeight;
            const slots = typeof getBagSlots === 'function' ? getBagSlots() : null;
            const slotsFull = typeof isBagSlotsFull === 'function' && isBagSlotsFull(slots);
            const reasonStr = slotsFull && slots
                ? `ช่องกระเป๋าเต็ม ${slots.current}/${slots.max} ช่อง (${slots.percent}%)`
                : `${w ? w.percent + '%' : '>= เกณฑ์'} >= ${window.__sellConfig?.weightThreshold || 80}%`;
            if (inCity) {
                console.warn(`%c[PmheeAether Watchdog] ⚖️ ตรวจพบตัวละครอยู่ในเมืองหลวง แต่กระเป๋าเต็มหรือน้ำหนักเกินเกณฑ์ (${reasonStr})! เดินไปร้านค้า (NPC n2) เพื่อขายของทันที...`, 'color: #ef4444; font-weight: bold;');
            } else {
                console.warn(`%c[PmheeAether Watchdog] ⚖️ ตรวจพบกระเป๋าเต็มหรือน้ำหนักเกินเกณฑ์ในสนามฟาร์ม (${reasonStr})! สั่งวาร์ปกลับไปขายของและเคลียร์กระเป๋าทันที...`, 'color: #ef4444; font-weight: bold;');
            }
            if (typeof playWarningChime === 'function') playWarningChime();
            autoActivateFailCount = 0;
            window.executeAutoShopRoutine();
            return;
        }

        // หมายเหตุ: ตัดระบบเปิดกระเป๋าอัตโนมัติเป็นระยะออกแล้ว เพื่อไม่ให้หน้าต่างกระเป๋าเด้งรบกวนผู้เล่น
        // ระบบจะอ่านน้ำหนักจาก Debuff Status (.hud-status) บนหน้าจอแทนแบบ 100% Passive

        // 4. ตรวจจับลูกธนูหมด สำหรับอาชีพ Archer / Hunter / Bard (ใส่จากกระเป๋าก่อนถ้ามี)
        if (window.arrowsNeeded() && window.equipAnyArrowFromBag()) return;
        if (window.arrowsNeeded() && !inCity) {
            const threshold = typeof window.__archerConfig.ammoThreshold === 'number' ? window.__archerConfig.ammoThreshold : 50;

            // ซิงก์จำนวนล่าสุดจาก Server / DOM ก่อนตัดสินใจ (ห้ามสแกน document.body.innerText เพราะจะไปเจอข้อความเก่าในแชทแล้วรีเซ็ต Ammo เป็น 0)
            if (typeof syncAmmoFromDOM === 'function') {
                syncAmmoFromDOM();
            }

            if (typeof window.__currentAmmo === 'number' && window.__currentAmmo <= threshold) {
                if (window.equipAnyArrowFromBag()) return;
                console.log(`%c[PmheeAether Archer] 🏹 ลูกธนูหมดหรือเหลือน้อย (${window.__currentAmmo} <= ${threshold} ดอก) -> สั่งวาร์ปกลับไปซื้อทันที!`, 'color: #ef4444; font-weight: bold;');
                autoActivateFailCount = 0;
                window.executeAutoShopRoutine();
                return;
            }
        }

        // 5. ตรวจสอบสถานะปุ่ม AUTO ในเกม (In-Game AUTO State Monitor)
        // เมื่ออยู่ในสนามฟาร์ม (ไม่ใช่ในเมือง) และบอทกำลัง START อยู่ และไม่ได้อยู่ในช่วงฟื้นฟู/เดินทาง/ช้อป/ตาย
        const isBusyTravelingOrRoutine = window.__isNavigating || window.__isWalkingToMap || window.__isShopping || 
            window.__isStoring || window.__isRecovering || window.__isConsolidating || window.__isGearRefining || 
            window.__isChangingJob || window.__isManualWarping || window.__isCheckingPostSellChannel;

        if (isBusyTravelingOrRoutine) {
            // ขณะเดินทางระหว่างแมพ หรือกำลังทำ Routine ห้ามเปิด AUTO เด็ดขาด และถ้าเปิดอยู่ให้ปิด
            if (getInGameAutoStatus() === 'on') {
                window.deactivateInGameAuto();
            }
            autoActivateFailCount = 0;
        } else if (!inCity) {
            const curMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
            if (!curMap) return; // รอให้ชื่อแมพบน Minimap โหลดเสร็จก่อน
            if (!/เมืองหลวง|โซลเฮเวน/.test(curMap)) {
                window.__lastKnownNonCityMap = curMap;
            }
            window.__unexpectedTownTicks = 0;

            const targetMap = window.__targetFarmMap || 'ถนนต้นหลิว';
            const cleanTarget = String(targetMap).replace(/\s*\(Lv\..*?\)/i, '').trim() || targetMap;
            const isTargetCity = /เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(cleanTarget);
            const onTargetMap = !cleanTarget || isTargetCity || curMap.includes(cleanTarget);

            // ห้ามเปิด AUTO เด็ดขาดหากยังอยู่ในแมพทางผ่าน (เช่น อยู่ทุ่งหญ้าตะวันออก แต่เป้าหมายคือหนองพิษ)
            if (!onTargetMap) {
                window.__lastFarmArrivalMapKey = null;
                autoActivateFailCount = 0;
                if (getInGameAutoStatus() === 'on') {
                    window.deactivateInGameAuto();
                }
                const posKey = window.__currentPos ? `${window.__currentPos.x},${window.__currentPos.y}` : '';
                if (posKey && posKey !== lastIntermediatePos) {
                    lastIntermediatePos = posKey;
                    intermediateStillTicks = 0;
                } else {
                    intermediateStillTicks++;
                }
                if (intermediateStillTicks >= 4 && Date.now() - lastIntermediateWalkAttempt > 10000) {
                    intermediateStillTicks = 0;
                    lastIntermediateWalkAttempt = Date.now();
                    console.log(`%c[PmheeAether Watchdog] 🗺️ ตัวละครอยู่แมพทางผ่าน ("${curMap}") ยังไม่ถึงแมพเป้าหมาย ("${targetMap}") -> สั่งเดินทางต่อทันที!`, 'color: #38bdf8; font-weight: bold;');
                    window.walkToTargetMap(targetMap, true);
                }
                return;
            }

            intermediateStillTicks = 0;
            if (cleanTarget && !isTargetCity && window.__lastFarmArrivalMapKey !== cleanTarget) {
                window.__lastFarmArrivalMapKey = cleanTarget;
                if (window.__channelCheckMode === 'always' && !window.__isCheckingPostSellChannel) {
                    const lastSwAt = (window.__lastPostSellChannelSwitch && window.__lastPostSellChannelSwitch.at) || 0;
                    if (Date.now() - lastSwAt > 8000) {
                        window.__pendingPostSellChannelCheck = true;
                        window.__pendingPostSellAt = Date.now();
                        window.__pendingPostSellReason = window.__pendingPostSellReason || 'enter-farm-map';
                    }
                }
            }
            if (window.__pendingPostSellChannelCheck && !window.__isCheckingPostSellChannel && typeof window.runPostSellChannelCheck === 'function') {
                window.activateInGameAuto();
                return;
            }
            const priestBusyBuffing = Boolean(window.__priestBusyBuffing && (Date.now() - (window.__priestBusyBuffingAt || 0) < 25000));
            const autoStatus = getInGameAutoStatus();
            if (autoStatus === 'on' || priestBusyBuffing) {
                // AUTO กำลังทำงานปกติ (หรือพระกำลังเดินไปร่ายบัฟให้เพื่อนในตี้) รีเซ็ตตัวนับความล้มเหลว
                autoActivateFailCount = 0;
                window.__isKnownOverweight = false;
            } else if (autoStatus === 'off') {
                if (Date.now() - lastAutoActivateAttempt > 1500) {
                    lastAutoActivateAttempt = Date.now();

                    // FAIL-SAFE: ถ้ากดเปิด AUTO ไปแล้ว 3 ครั้ง แต่สถานะยังคงเป็น "off" ตลอด
                    // แสดงว่าตัวเกมบล็อคไม่ให้เปิด AUTO เพราะน้ำหนักในกระเป๋าเต็มหรือเกิน 90%!
                    if (autoActivateFailCount >= 3 && !(typeof isCharacterDead === 'function' && isCharacterDead())) {
                        console.error('%c[PmheeAether Watchdog] 🛑 กดเปิด AUTO ไม่สำเร็จ 3 ครั้งติดต่อกัน! ตัวเกมล็อค AUTO เนื่องจากน้ำหนักในกระเป๋าเต็มหรือเกิน 90% -> สั่งวาร์ปกลับไปขายของและเคลียร์กระเป๋าทันที!', 'color: #ef4444; font-weight: bold; font-size: 13px;');
                        autoActivateFailCount = 0;
                        window.__isKnownOverweight = true;
                        window.executeAutoShopRoutine();
                        return;
                    }

                    autoActivateFailCount++;
                    console.log(`%c[PmheeAether Watchdog] ⚡ บอท START อยู่ในสนามรบ แต่ปุ่ม AUTO ในเกมปิดอยู่ ("AUTO ปิด") [ครั้งที่ ${autoActivateFailCount}/3] -> สั่งกดเปิด AUTO ทันที!`, 'color: #f59e0b; font-weight: bold;');
                    window.activateInGameAuto();
                }
            }
        }

        // 5.5 ระบบพักรอนิรภัย (Unexpected Town Return Cooldown Watcher)
        const unexpBox = document.getElementById('p-unexpected-town-box');
        const unexpCd = document.getElementById('p-unexpected-countdown');
        if (window.__unexpectedTownWaiting) {
            const remSec = Math.max(0, Math.ceil(((window.__unexpectedTownWaitUntil || 0) - Date.now()) / 1000));
            if (unexpBox) unexpBox.style.display = 'block';
            if (unexpCd) unexpCd.innerText = `${Math.floor(remSec / 60)}:${String(remSec % 60).padStart(2, '0')}`;

            if (Date.now() >= (window.__unexpectedTownWaitUntil || 0)) {
                window.__unexpectedTownWaiting = false;
                window.__unexpectedTownWaitUntil = 0;
                window.__unexpectedTownTicks = 0;
                if (unexpBox) unexpBox.style.display = 'none';
                console.log('%c[PmheeAether Watchdog] ⏰ สิ้นสุดระยะเวลาพักรอนิรภัยหลังกลับเมืองผิดปกติ -> บอทเตรียมตัวเดินทางกลับไปฟาร์ม', 'color: #22c55e; font-weight: bold;');
                const targetMap = window.__targetFarmMap || 'ถนนต้นหลิว';
                window.walkToTargetMap(targetMap, true, { skipWait: true });
                return;
            } else {
                if (getInGameAutoStatus() === 'on') {
                    window.deactivateInGameAuto();
                }
                return;
            }
        } else {
            if (unexpBox && unexpBox.style.display !== 'none') unexpBox.style.display = 'none';
        }

        // 5.9 Town stay of a plan system that is gone (plan switched off / changed, need expired): the farm map
        //     the trip remembered comes back once no system needs town any more
        //     (or any capital target nobody needs: after 20 s in town with nothing to do there)
        if (!/เมืองหลวง|โซลเฮเวน/.test(window.__targetFarmMap || '')) cityTargetSince = 0;
        else if (inCity) {
            if (!cityTargetSince) cityTargetSince = Date.now();
            else if (Date.now() - cityTargetSince > 20000 && Date.now() - lastTownSweepAt > 10000) {
                lastTownSweepAt = Date.now();
                if (window.recoverFarmTarget('watchdog')) cityTargetSince = 0;
            }
        }

        // 6. ตรวจสอบสถานะในเมืองหลวง & ตรวจจับกลับเมืองโดยไม่ทราบสาเหตุ
        if (inCity) {
            const targetMap = window.__targetFarmMap || 'ถนนต้นหลิว';
            const isTargetCity = targetMap.includes('เมืองหลวง') || targetMap.includes('โซลเฮเวน') || targetMap.includes('ตลาดคาราวาน');

            const isAliceActive = (window.__aliceWarpInterval != null) || (window.__alicePollInterval != null) || (typeof isAliceDialogOpen === 'function' && isAliceDialogOpen());
            const isPlanTownActive = ((window.__planJobChangeHoldUntil || 0) > Date.now()) || !!localStorage.getItem('pelican_gear_trip') || !!localStorage.getItem('pelican_job_return_map');

            const legitimateTownStay = 
                window.__townArrivalExplained === true ||
                isTargetCity ||
                window.__isShopping ||
                window.__isStoring ||
                window.__isNavigating ||
                window.__isWalkingToMap ||
                window.__isRecovering ||
                window.__isConsolidating ||
                window.__isGearRefining ||
                window.__isChangingJob ||
                window.__isHumanizing ||
                isAliceActive ||
                isPlanTownActive ||
                (Date.now() - (window.__lastRespawnAt || 0) < 60000) ||
                (Date.now() - (window.__lastBwingUsedAt || 0) < 60000) ||
                (Date.now() - (window.__goHomeWingAt || 0) < 60000) ||
                (Date.now() - (window.__lastIntentionalWarpAt || 0) < 60000) ||
                (Date.now() - (window.__lastTownTripAt || 0) < 60000) ||
                (Date.now() - (lastAutoShopCompletionTime || 0) < 45000) ||
                (Date.now() - (window.__botStartedAt || 0) < 15000) ||
                !window.__lastKnownNonCityMap;

            // 6.1 ตรวจจับกรณีกลับเมืองโดยไม่ทราบสาเหตุ (Unexpected Town Return)
            if (!legitimateTownStay && window.__unexpectedTownGuardEnabled !== false) {
                window.__unexpectedTownTicks = (window.__unexpectedTownTicks || 0) + 1;
                if (window.__unexpectedTownTicks >= 8) {
                    const waitMins = Math.floor(Math.random() * 11) + 5; // สุ่ม 5 ถึง 15 นาที
                    const waitSecs = Math.floor(Math.random() * 60);
                    const totalMs = (waitMins * 60 + waitSecs) * 1000;
                    window.__unexpectedTownWaiting = true;
                    window.__unexpectedTownMins = waitMins;
                    window.__unexpectedTownWaitUntil = Date.now() + totalMs;
                    window.__unexpectedTownReason = `ตรวจพบตัวละครกลับเมืองโดยไม่ทราบสาเหตุจาก "${window.__lastKnownNonCityMap}" (ตัวละครไม่ตาย, ไม่ได้กดบีวิง)`;
                    window.__unexpectedTownTicks = 0;

                    console.error(`%c[PmheeAether Watchdog] 🚨 ${window.__unexpectedTownReason}! สุ่มพักรอนิรภัย ${waitMins} นาที ${waitSecs} วินาที เพื่อความปลอดภัย...`, 'color: #ef4444; font-weight: bold; font-size: 13px;');
                    window.deactivateInGameAuto();
                    if (unexpBox) unexpBox.style.display = 'block';
                    if (unexpCd) unexpCd.innerText = `${waitMins}:${String(waitSecs).padStart(2, '0')}`;
                    return;
                }
                return;
            } else {
                window.__unexpectedTownTicks = 0;
            }

            // 6.2 ตัวละครตกค้างอยู่ในเมืองหลวงตามปกติ (City-to-Farm Auto-Dispatch)
            if (!window.__isShopping && !window.__isStoring && !window.__isNavigating && !window.__isRecovering && !window.__isConsolidating && !window.__isHumanizing && !((window.__planJobChangeHoldUntil || 0) > Date.now())) {
                if (!isTargetCity) {
                    const now = Date.now();
                    if (now - lastCityToFarmAttempt > 4000) {
                        lastCityToFarmAttempt = now;
                        console.log(`%c[PmheeAether Watchdog] 🏛️ ตัวละครตกค้างอยู่ในเมืองหลวง ("${getCurrentMapName()}") ขณะบอท START -> สั่งเดินทางไปยังแมพเป้าหมาย: "${targetMap}" ผ่าน NPC Alice ทันที!`, 'color: #38bdf8; font-weight: bold;');
                        window.walkToTargetMap(targetMap, true);
                        return;
                    }
                }
            }
        }
    }, 1000);

    // ==========================================
    // 6.5 AUTO-LOGIN & RECONNECT ENGINE
    // ==========================================
    let lastLoginAttemptTime = 0;
    let loginFailCount = 0;
    let isLoginInProgress = false;

    function safeClickOnce(el) {
        if (!el) return;
        try {
            const reactPropsKey = Object.keys(el).find(k => k.startsWith('__reactProps'));
            if (reactPropsKey && el[reactPropsKey] && typeof el[reactPropsKey].onClick === 'function') {
                el[reactPropsKey].onClick({ stopPropagation: () => {}, preventDefault: () => {} });
                return;
            }
        } catch (e) {}
        try { el.click(); } catch (e) {}
    }

    function setNativeInputValue(element, value) {
        if (!element) return;
        try { element.focus(); } catch (e) {}
        try {
            const prototype = Object.getPrototypeOf(element);
            const descriptor = Object.getOwnPropertyDescriptor(prototype, 'value');
            if (descriptor && descriptor.set) {
                descriptor.set.call(element, value);
            } else {
                element.value = value;
            }
        } catch(e) {
            element.value = value;
        }
        if (element._valueTracker) {
            try { element._valueTracker.setValue(''); } catch (e) {}
        }
        try {
            const reactPropsKey = Object.keys(element).find(k => k.startsWith('__reactProps'));
            if (reactPropsKey && element[reactPropsKey] && typeof element[reactPropsKey].onChange === 'function') {
                element[reactPropsKey].onChange({ target: element, currentTarget: element });
            }
        } catch (e) {}
        element.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));
        element.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));
        element.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, cancelable: true }));
        element.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, cancelable: true }));
    }

    function findLoginElements() {
        // หา password input ที่อยู่นอก #pelican-hud
        const passInputs = Array.from(document.querySelectorAll('input[type="password"]')).filter(el => {
            return !el.closest('#pelican-hud') && el.offsetWidth > 0;
        });
        const passInput = passInputs[0] || null;

        // หา text/username input ที่อยู่นอก #pelican-hud
        const allTextInputs = Array.from(document.querySelectorAll('input:not([type="password"]):not([type="checkbox"]):not([type="radio"]):not([type="button"]):not([type="submit"]):not([type="hidden"])')).filter(el => {
            return !el.closest('#pelican-hud') && el.offsetWidth > 0;
        });

        let userInput = allTextInputs.find(el => {
            const placeholder = (el.placeholder || '').toLowerCase();
            const name = (el.name || '').toLowerCase();
            const id = (el.id || '').toLowerCase();
            return placeholder.includes('ผู้ใช้') || placeholder.includes('user') || placeholder.includes('username') || placeholder.includes('id') ||
                   name.includes('user') || name.includes('username') || name.includes('login') ||
                   id.includes('user') || id.includes('username');
        });

        if (!userInput && passInput) {
            const form = passInput.closest('form');
            if (form) {
                userInput = form.querySelector('input:not([type="password"])');
            } else {
                userInput = allTextInputs[0] || null;
            }
        }

        // หาปุ่ม "เข้าเกม"
        const allButtons = Array.from(document.querySelectorAll('button, div[role="button"], a.btn, input[type="submit"]')).filter(el => {
            return !el.closest('#pelican-hud') && el.offsetWidth > 0;
        });

        const loginBtn = allButtons.find(el => {
            const txt = (el.innerText || el.textContent || el.value || '').trim();
            return txt === 'เข้าเกม' || txt === 'เข้าสู่ระบบ' || txt === 'Login' || txt === 'Sign In';
        }) || null;
        // The form can be in sign-up mode (3 fields, "สมัครและเข้าเกม"): logging in needs the login mode
        const loginForm = document.querySelector('form.login-form');
        const cfg = window.__authConfig || {};
        if (loginForm && loginForm.querySelectorAll('input').length >= 3 && !cfg.register) {
            if (cfg.enabled && cfg.username && cfg.password) {
                const toLogin = Array.from(loginForm.querySelectorAll('button.login-link, button.ghost, .login-links button, button, a')).find(b => {
                    const txt = (b.innerText || b.textContent || b.value || '').trim();
                    return /มีบัญชีแล้ว|เข้าสู่ระบบ|Log in|Sign in/i.test(txt);
                });
                return { userInput, passInput, loginBtn: null, toLogin };
            }
            return { userInput: null, passInput: null, loginBtn: null, toLogin: null };
        }

        return { userInput, passInput, loginBtn };
    }

    function isLoginScreenVisible() {
        if (document.querySelector('form.login-form')) return true;
        const { passInput, loginBtn } = findLoginElements();
        if (passInput && loginBtn) return true;

        const bodyText = document.body.innerText || '';
        const isAuthPage = bodyText.includes('เริ่มต้นเป็น Novice') || 
                           bodyText.includes('สมัครบัญชีใหม่') || 
                           bodyText.includes('ลงชื่อเข้าใช้ด้วย Google') ||
                           bodyText.includes('เล่นทันที ไม่ต้องสมัคร');

        if (isAuthPage && (passInput || loginBtn)) {
            return true;
        }
        return false;
    }

    function checkPostLoginScreen() {
        const cfg = window.__authConfig || {};
        if (isLoginScreenVisible()) return;
        const activeTag = document.activeElement && document.activeElement.tagName;
        if ((activeTag === 'INPUT' || activeTag === 'TEXTAREA') && !cfg.autoCreateChar) return;

        const bodyText = document.body.innerText || '';
        const isCharSelectScreen = !!document.querySelector('.char-select, .char-card') ||
                                   bodyText.includes('เลือกตัวละคร') || 
                                   bodyText.includes('สร้างตัวละคร') || 
                                   bodyText.includes('เข้าเกมด้วย') || 
                                   bodyText.includes('Select Character');

        // Helper: หาปุ่มเข้าเกมที่มีอยู่แล้ว (ข้ามปุ่มที่ disabled และไม่หยิบหัวข้อ "เลือกตัวละคร")
        function findEnterButton() {
            const directEnter = Array.from(document.querySelectorAll('button.char-enter:not([disabled])')).find(el => {
                if (el.offsetWidth === 0 || el.offsetHeight === 0) return false;
                const txt = (el.innerText || el.textContent || '').trim();
                return txt.startsWith('เข้าเกมด้วย') || txt === 'เข้าเกม' || txt === 'เริ่มเกม' || txt === 'Enter World' || txt === 'Start Game';
            });
            if (directEnter) return directEnter;

            const candidates = Array.from(document.querySelectorAll('button:not([disabled]), div[role="button"], a.btn, [class*="btn"]')).filter(el => {
                if (el.disabled) return false;
                if (el.closest('#pelican-hud') || el.offsetWidth === 0 || el.offsetHeight === 0) return false;
                if (el.offsetHeight > 140) return false; // ไม่ใช่ container ใหญ่
                const txt = (el.innerText || el.textContent || '').trim();
                if (!txt) return false;
                if (txt.startsWith('เข้าเกมด้วย') || 
                    txt === 'เข้าเกม' || 
                    txt === 'เริ่มเกม' || 
                    txt === 'เข้าสู่โลก' || 
                    txt === 'เข้าเล่น' || 
                    txt === 'Enter World' || 
                    txt === 'Start Game') {
                    return true;
                }
                return false;
            });
            candidates.sort((a, b) => (a.innerText || '').length - (b.innerText || '').length);
            return candidates[0] || null;
        }

        // Helper: หาการ์ดตัวละคร
        function findCharacterCards() {
            const directCards = Array.from(document.querySelectorAll('.char-card:not(.empty):not(.pending-delete)')).filter(el => el.offsetWidth > 0 && el.offsetHeight > 0);
            if (directCards.length > 0) return directCards;

            const cards = Array.from(document.querySelectorAll('div, button, a')).filter(el => {
                if (el.closest('#pelican-hud') || el.offsetWidth === 0 || el.offsetHeight === 0) return false;
                if (el.offsetWidth < 80 || el.offsetHeight < 80 || el.offsetWidth > 450 || el.offsetHeight > 500) return false;
                const txt = (el.innerText || el.textContent || '').trim();
                if (!txt) return false;
                if (txt.includes('สร้างตัวละคร') || txt.includes('ช่องว่าง')) return false;
                return txt.includes('Lv.') || txt.includes('Job') || txt.includes('Hunter') || txt.includes('Novice') || 
                       txt.includes('Knight') || txt.includes('Wizard') || txt.includes('Priest') || txt.includes('Assassin') || 
                       txt.includes('Blacksmith') || txt.includes('Bard') || txt.includes('Dancer') || txt.includes('Crusader') || 
                       txt.includes('Monk') || txt.includes('Sage') || txt.includes('Rogue') || txt.includes('Alchemist');
            });
            cards.sort((a, b) => (a.innerText || '').length - (b.innerText || '').length);
            return cards;
        }

        if (isCharSelectScreen && runAutoCreateCharacter()) return;
        if (isCharSelectScreen) {
            const cards = findCharacterCards();
            if (cards.length > 0) {
                let targetCard = null;
                if (cfg.charName && cfg.charName.trim().length > 0) {
                    targetCard = cards.find(c => (c.innerText || '').includes(cfg.charName.trim()));
                }
                if (!targetCard) {
                    targetCard = cards[0];
                }

                if (targetCard && !targetCard.classList.contains('selected')) {
                    safeClickOnce(targetCard);
                }
            }

            // คลิกปุ่มเข้าเกมหลังเลือกตัวละคร
            setTimeout(() => {
                if (deviceLimitErrorShown()) { handleDeviceLimitError(findEnterButton()); return; }
                deviceLimitRetryCount = 0;
                if (characterShownOnline()) { handleStaleCharacterSession(); return; }
                staleSessionSince = 0;
                const enterBtn = findEnterButton();
                if (enterBtn && !isLoginScreenVisible()) {
                    const btnTxt = (enterBtn.innerText || enterBtn.textContent || '').trim();
                    console.log(`%c[PmheeAether Auth] 🎮 เลือกตัวละคร & คลิกเข้าเกม ("${btnTxt}")...`, 'color: #22c55e; font-weight: bold;');
                    safeClickOnce(enterBtn);
                }
            }, 350);
        } else {
            const enterBtn = findEnterButton();
            if (enterBtn && !isLoginScreenVisible()) {
                const btnTxt = (enterBtn.innerText || enterBtn.textContent || '').trim();
                console.log(`%c[PmheeAether Auth] 🎮 พบคลิกปุ่มเข้าสู่โลก ("${btnTxt}") -> กำลังคลิกเข้าเกม...`, 'color: #22c55e; font-weight: bold;');
                safeClickOnce(enterBtn);
            }
        }
    }

    // When a proxy/network blip drops the WebSocket, the game's reconnect hits HTTP 400 ("character still online")
    // and dumps the player onto Character Select (.char-select), which fetches /characters only ONCE on mount
    // and permanently displays "ตัวนี้ออนไลน์อยู่" (disabled) + "บังคับออกจากระบบ".
    // Wait 3.5s for any brief disconnect to settle, then click "บังคับออกจากระบบ" (which calls POST /characters/:id/kick
    // and refreshes /characters in-place so the "เข้าเกมด้วย ..." button becomes enabled immediately), or reload after 12s.
    let lastDeviceLimitRotateAt = 0, deviceLimitRetryCount = 0;
    function deviceLimitErrorShown() {
        const txt = ((document.querySelector('.char-select, .login-card, .char-panel, body') || document.body).innerText || '');
        return /เครื่องนี้เล่นพร้อมกันได้สูงสุด|ออกจากตัวละครอื่นก่อนจึงจะเข้าได้/i.test(txt) && !!document.querySelector('.char-select, .char-card');
    }
    function handleDeviceLimitError(enterBtn) {
        const now = Date.now();
        if (now - lastDeviceLimitRotateAt < 2000) return;
        lastDeviceLimitRotateAt = now;
        deviceLimitRetryCount++;
        if (typeof window.__rotatePmDeviceId === 'function') {
            window.__rotatePmDeviceId('char-select-limit');
        }
        if (deviceLimitRetryCount >= 4) {
            deviceLimitRetryCount = 0;
            console.log('%c[PmheeAether Auth] ♻️ สุ่ม Device ID ใหม่แล้วยังติดหน้าเลือกตัวละคร -> รีเฟรชหน้าเกมอัตโนมัติ', 'color: #f59e0b; font-weight: bold;');
            location.reload();
            return;
        }
        const btn = enterBtn || Array.from(document.querySelectorAll('button.char-enter:not([disabled])')).find(el => el.offsetWidth > 0 && (el.innerText || '').trim().startsWith('เข้าเกมด้วย'));
        if (btn && !isLoginScreenVisible()) {
            console.log(`%c[PmheeAether Auth] 🔑 พบแจ้งเตือนจำกัด 3 ตัวละครต่อเครื่อง -> เปลี่ยน Device ID ใหม่และคลิกเข้าเกมอัตโนมัติ (ครั้งที่ ${deviceLimitRetryCount})...`, 'color: #38bdf8; font-weight: bold;');
            setTimeout(() => {
                if (!isLoginScreenVisible()) safeClickOnce(btn);
            }, 300);
        }
    }

    let staleSessionSince = 0, lastForceKickClickAt = 0;
    function characterShownOnline() {
        const btnOnline = Array.from(document.querySelectorAll('button.char-enter')).some(b => /ตัวนี้ออนไลน์อยู่|This character is online/i.test(b.innerText || ''));
        const errOnline = /ตัวละครนี้ออนไลน์อยู่แล้ว|ตัวละครอยู่ในเกม|already online/i.test((document.querySelector('.char-select, .login-card, .char-panel, body') || document.body).innerText || '');
        return btnOnline || (errOnline && !!document.querySelector('.char-card'));
    }
    function handleStaleCharacterSession() {
        const now = Date.now();
        if (!staleSessionSince) {
            staleSessionSince = now;
            console.log('%c[PmheeAether Auth] ⏳ เกมแสดงว่าตัวละครนี้ออนไลน์อยู่ (session เก่ายังค้าง) -> รอ 3.5 วินาทีเพื่อเคลียร์และเข้าเกมใหม่อัตโนมัติ', 'color: #f59e0b; font-weight: bold;');
            return;
        }
        const elapsed = now - staleSessionSince;
        if (elapsed < 3500) return;

        const forceKickBtn = Array.from(document.querySelectorAll('button.char-enter:not([disabled]), .char-select button:not([disabled])')).find(b => {
            if (b.offsetWidth === 0 || b.offsetHeight === 0) return false;
            const t = (b.innerText || b.textContent || '').trim();
            return /บังคับออกจากระบบ|Force logout/i.test(t);
        });
        if (forceKickBtn && (now - lastForceKickClickAt >= 6000)) {
            lastForceKickClickAt = now;
            console.log('%c[PmheeAether Auth] 🔓 กดปุ่ม "บังคับออกจากระบบ" เพื่อเคลียร์ตัวละครที่ค้างในเซิร์ฟเวอร์ แล้วเข้าเกมต่อทันที...', 'color: #f59e0b; font-weight: bold;');
            safeClickOnce(forceKickBtn);
            setTimeout(() => { try { checkPostLoginScreen(); } catch (_) {} }, 1200);
            setTimeout(() => { try { checkPostLoginScreen(); } catch (_) {} }, 2500);
            return;
        }

        if (elapsed < 12000) return;
        staleSessionSince = now;
        console.log('%c[PmheeAether Auth] ♻️ ตัวละครยังค้างสถานะออนไลน์อยู่ -> รีเฟรชหน้าเพื่อดึงสถานะใหม่', 'color: #f59e0b; font-weight: bold;');
        location.reload();
    }

    // ---------- Auto-register + auto-create character ----------
    // The Manager sets authConfig.register (profile created without a password): sign up with the given
    // ID/password on the game's login form, then create a character when the account has none.
    // registerDone / username changes are read back by the Manager (manager/auth_sync.js).
    const saveAuth = () => { try { localStorage.setItem('pelican_auth_cfg', JSON.stringify(window.__authConfig)); } catch (e) {} };
    const randomId = () => 'pm' + Math.random().toString(36).slice(2, 10).replace(/[^a-z0-9]/g, 'x');
    // Character names that look like players picked them: gamer words, FiveM-style lowercase tags, Thai nicknames
    // and short Thai words (the game allows rude words in names), mixed in several patterns. Game rule: English, Thai, digits and _ only, min..max
    // characters (read from the create form), unique — a taken name is simply re-rolled on the next try.
    const NAME_WORDS = {
        prefix: ['lnw', 'Pro', 'God', 'King', 'Baby', 'Master', 'Lord', 'Boss', 'Dark', 'Shadow', 'Ghost', 'Blood', 'Demon', 'Chaos', 'Void',
            'Phantom', 'Cyber', 'Neon', 'Apex', 'Viper', 'Silent', 'Lucky', 'Mini', 'Big', 'Little', 'Sweet', 'Crazy', 'Wild'],
        tag: ['cxllme', 'teary', 'lost', 'saddest', 'deadly', 'zodiac', 'mafia', 'gang', 'nightmare', 'lonely', 'sleepy', 'broken', 'silent',
            'hxrt', 'nxbody', 'cold', 'lazy', 'tired', 'sxdboy', 'midnight', 'blue', 'mxrning', 'xoxo', 'sxul', 'velvet',
            'fxxk', 'bxtch', 'pxssy', 'killer', 'psycho', 'ghosttown'],
        core: ['Dragon', 'Tiger', 'Phoenix', 'Wolf', 'Hawk', 'Snake', 'Lion', 'Panther', 'Raven', 'Thunder', 'Frost', 'Flame', 'Sniper',
            'Gamer', 'Player', 'Glitch', 'Assassin', 'Knight', 'Samurai', 'Ninja', 'Warrior', 'Guardian', 'Reaper', 'Stalker', 'Slayer',
            'Archer', 'Bard', 'Hunter', 'Ranger', 'Arrow', 'Storm', 'Moon', 'Star', 'Sky', 'Rain', 'Fox', 'Bear', 'Cat'],
        thai: ['ศูนย์', 'หมอก', 'นิ่ง', 'ฝน', 'เงา', 'เกือบตึง', 'บังเอิญ', 'แจกแต้ม', 'ง่วง', 'ขี้เกียจ', 'หิวข้าว', 'เด็กดี', 'คนเดิม',
            'ตัวตึง', 'สายฟ้า', 'จันทร์', 'ดาว', 'ลมหนาว', 'ทะเล', 'ภูเขา', 'นักธนู', 'ไม่ไหว'],
        nick: ['Tee', 'Bank', 'Boom', 'Non', 'Zen', 'Beam', 'Win', 'First', 'Nut', 'Gun', 'Phu', 'Pond', 'Dome', 'Earth', 'Mix', 'Mind',
            'Ice', 'Mild', 'Nam', 'Fon', 'Pleng', 'Cream', 'View', 'Ton', 'Pete', 'Fluke', 'Mark', 'Top', 'Off', 'Ohm', 'Fiat', 'Tar', 'Arm',
            'Bas', 'Jay', 'Kao', 'Mew', 'Nine', 'Pang', 'Plai', 'Ploy', 'Praew', 'Toey', 'June', 'Fah', 'Ning', 'Kwan', 'Mook', 'Bow', 'Gift'],
        suffix: ['Za', '007', '99', 'VIP', 'Gaming', 'GG', 'TH', 'BKK', '777', '888', '999', 'Z', 'X', 'THX', 'Jr', 'Kung', 'Nakub', 'Ja']
    };
    function randomCharName(minLen = 4, maxLen = 12) {
        const pick = a => a[Math.floor(Math.random() * a.length)];
        const num = () => String(Math.random() < 0.5 ? Math.floor(Math.random() * 90) + 10 : Math.floor(Math.random() * 900) + 100);
        const W = NAME_WORDS;
        const patterns = [
            () => pick(W.tag) + pick(W.nick),                         // cxllmeBank
            () => pick(W.tag) + '_' + pick(W.core),                   // teary_Wolf
            () => pick(W.prefix) + pick(W.core),                      // DarkDragon
            () => pick(W.prefix) + pick(W.core) + pick(W.suffix),     // DarkDragonZa
            () => pick(W.nick) + num(),                               // Tee404
            () => pick(W.tag) + num(),                                // lost999
            () => pick(W.core) + pick(W.suffix),                      // WolfTH
            () => pick(W.thai) + pick(W.suffix),                      // หมอกTH
            () => pick(W.thai) + pick(W.nick),                        // ฝนBeam
            () => pick(W.nick) + pick(W.core),                        // BankWolf
            () => pick(W.nick) + '_' + pick(W.suffix),                // Beam_TH
            () => pick(W.prefix) + pick(W.nick),                      // LuckyMild
            () => pick(W.thai) + num(),                               // เงา88
        ];
        for (let i = 0; i < 60; i++) {
            let n = pick(patterns)();
            // FiveM-style names are often all lowercase
            if (/^[a-z]/.test(n) || Math.random() < 0.15) n = n.replace(/[A-Z]/g, c => c.toLowerCase());
            if (n.length >= minLen && n.length <= maxLen && /^[A-Za-z0-9_฀-๿]+$/.test(n)) return n;
        }
        return (pick(W.nick) + num()).slice(0, Math.max(minLen, maxLen));
    }
    let registerSubmittedAt = 0;
    let registerTries = 0;
    function syncManualLoginFormWatcher() {
        const form = document.querySelector('form.login-form');
        if (!form || isLoginInProgress) return;
        const inputs = Array.from(form.querySelectorAll('input'));
        if (inputs.length !== 2) return;
        const [uEl, pEl] = inputs;
        const bindManualInput = (el, field) => {
            if (!el || el.__pmManualWatchBound) return;
            el.__pmManualWatchBound = true;
            const handler = (e) => {
                if (isLoginInProgress) return;
                if (e && e.isTrusted === false) return;
                const val = field === 'username' ? String(el.value || '').trim() : String(el.value || '');
                if (!val) return;
                const cfg = window.__authConfig || (window.__authConfig = {});
                cfg[field] = val;
                cfg.userEditedAt = Date.now();
                cfg.generatedUser = false;
                cfg.register = false;
                delete cfg.registerError;
                saveAuth();
                const hudEl = document.getElementById(field === 'username' ? 'p-auth-user' : 'p-auth-pass');
                if (hudEl && document.activeElement !== hudEl) hudEl.value = val;
            };
            el.addEventListener('input', handler, { passive: true });
            el.addEventListener('change', handler, { passive: true });
        };
        bindManualInput(uEl, 'username');
        bindManualInput(pEl, 'password');
    }
    function runAutoRegister() {
        const cfg = window.__authConfig;
        if (!cfg) return;
        const domUser = (document.getElementById('p-auth-user')?.value || '').trim();
        const domPass = document.getElementById('p-auth-pass')?.value || '';
        if (domUser && !cfg.username) cfg.username = domUser;
        if (domPass && !cfg.password) cfg.password = domPass;
        const isCustomUserId = Boolean(cfg.username && !/^pm[a-z0-9]{8}$/.test(cfg.username));
        if (!cfg.generatedUser && (Number(cfg.userEditedAt) > 0 || Number(cfg.verifiedLoginAt) > 0 || isCustomUserId)) {
            cfg.register = false;
            saveAuth();
            console.log(`%c[PmheeAether Auth] 🛡️ พบไอดีของผู้ใช้ ("${cfg.username}") -> ยกเลิกโหมดสมัครใหม่และใช้ไอดีเดิมเข้าเกม`, 'color: #38bdf8; font-weight: bold;');
            return;
        }
        const form = document.querySelector('form.login-form');
        if (!form || isLoginInProgress) return;
        const inputs = Array.from(form.querySelectorAll('input'));
        const switchBtn = Array.from(form.querySelectorAll('button.login-link, button.ghost, .login-links button, button, a')).find(b => {
            const txt = (b.innerText || b.textContent || b.value || '').trim();
            return /สมัครบัญชีใหม่|Create an account|สมัครสมาชิก|สมัครไอดี|Sign up/i.test(txt);
        });
        if (inputs.length < 3) {
            // login mode on screen: switch the form to "สมัครบัญชีใหม่"
            if (switchBtn) {
                console.log('%c[PmheeAether Auth] 📝 สลับหน้าเป็น "สมัครบัญชีใหม่"', 'color: #a855f7;');
                safeClickOnce(switchBtn);
            }
            return;
        }
        const now = Date.now();
        if (now - registerSubmittedAt < 6000) return;
        // the previous sign-up was refused (shown in the form): new generated ID, or log in with the user's ID
        const err = form.querySelector('.error');
        if (registerSubmittedAt && err && (err.innerText || '').trim()) {
            const msg = (err.innerText || '').trim();
            const isUsernameTaken = /ซ้ำ|มีผู้ใช้|ถูกใช้|already|taken|exists/i.test(msg);
            if (cfg.generatedUser && isUsernameTaken && registerTries < 6) {
                const old = cfg.username;
                cfg.username = randomId();
                saveAuth();
                console.warn(`[PmheeAether Auth] ⚠️ สมัครด้วย ID "${old}" ไม่สำเร็จ (${msg}) -> ลองใหม่ด้วย ID "${cfg.username}"`);
            } else {
                cfg.register = false;
                cfg.registerError = msg;
                saveAuth();
                console.warn(`[PmheeAether Auth] ⚠️ สมัครด้วย ID "${cfg.username}" ไม่สำเร็จ (${msg}) -> เปลี่ยนเป็นเข้าสู่ระบบด้วย ID/รหัสนี้แทน`);
                const back = Array.from(form.querySelectorAll('button.login-link, button.ghost, .login-links button, button, a')).find(b => {
                    const txt = (b.innerText || b.textContent || b.value || '').trim();
                    return /มีบัญชีแล้ว|เข้าสู่ระบบ|Log in|Sign in/i.test(txt);
                });
                if (back) {
                    safeClickOnce(back);
                }
                return;
            }
        }
        const submit = form.querySelector('button.login-go') || Array.from(form.querySelectorAll('button')).find(b => {
            if (b.classList.contains('ghost') || b.classList.contains('login-link') || b.type === 'button') return false;
            const txt = (b.innerText || b.textContent || b.value || '').trim();
            if (/เล่นทันที|ไม่ต้องสมัคร|Guest|สมัครบัญชีใหม่|มีบัญชีแล้ว/i.test(txt)) return false;
            return true;
        });
        if (!submit || submit.disabled) return;
        registerTries++;
        console.log(`%c[PmheeAether Auth] 📝 สมัครบัญชีใหม่อัตโนมัติ ID: "${cfg.username}" (ครั้งที่ ${registerTries})`, 'color: #a855f7; font-weight: bold;');
        setNativeInputValue(inputs[0], cfg.username);
        setNativeInputValue(inputs[1], cfg.password);
        setNativeInputValue(inputs[2], cfg.password);
        registerSubmittedAt = now;
        setTimeout(() => {
            try {
                if (typeof form.requestSubmit === 'function') {
                    form.requestSubmit(submit);
                    return;
                }
            } catch (e) {}
            try { submit.click(); } catch(e) {}
            try {
                const reactPropsKey = Object.keys(form).find(k => k.startsWith('__reactProps'));
                if (reactPropsKey && form[reactPropsKey] && typeof form[reactPropsKey].onSubmit === 'function') {
                    form[reactPropsKey].onSubmit({ preventDefault: () => {}, stopPropagation: () => {} });
                }
            } catch (e) {}
        }, 400);
    }
    // Called while not on the login screen: a sign-up from this page went through
    function confirmRegistered() {
        const cfg = window.__authConfig;
        if (!cfg || !cfg.register) return;
        // Never mark a candidate ID as registered if it was never submitted on the registration form!
        // If we are already in-game or at character select without having submitted a sign-up, cancel register mode.
        const inGameOrSelect = document.querySelector('.char-card') || (typeof getCurrentMapName === 'function' && getCurrentMapName());
        if (!registerSubmittedAt) {
            if (inGameOrSelect) {
                cfg.register = false;
                cfg.registerDone = false;
                saveAuth();
            }
            return;
        }
        cfg.register = false;
        cfg.registerDone = true;
        cfg.verifiedLoginAt = Date.now();
        delete cfg.registerError;
        saveAuth();
        console.log(`%c[PmheeAether Auth] ✅ สมัครบัญชี "${cfg.username}" สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
    }
    // Character select with no character yet: create one with a random name
    let charCreateAt = 0;
    let charCreateName = '';
    function runAutoCreateCharacter() {
        const cfg = window.__authConfig;
        if (!cfg || !cfg.autoCreateChar) return false;
        const realCards = document.querySelectorAll('.char-card:not(.empty)');
        if (realCards.length) {
            if (charCreateName) cfg.charName = charCreateName;
            cfg.autoCreateChar = false;
            saveAuth();
            if (charCreateName) console.log(`%c[PmheeAether Auth] ✅ สร้างตัวละคร "${charCreateName}" สำเร็จ -> เข้าเกม`, 'color: #22c55e; font-weight: bold;');
            return false;
        }
        const now = Date.now();
        if (now - charCreateAt < 5000) return true;
        const form = document.querySelector('form.char-create');
        if (!form) {
            const empty = document.querySelector('.char-card.empty');
            if (empty) { empty.click(); charCreateAt = now - 4000; }
            return true;
        }
        const input = form.querySelector('input');
        const btn = form.querySelector('button');
        if (!input || !btn) return true;
        // name length allowed by the server: the input's maxLength and the "{min}–{max} ตัว" hint under it
        const hint = ((form.querySelector('small') || {}).innerText || '').match(/(d+)s*[–-]s*(d+)/);
        const maxLen = Number(input.maxLength) > 0 ? Number(input.maxLength) : (hint ? Number(hint[2]) : 12);
        const minLen = hint ? Number(hint[1]) : 3;
        charCreateName = randomCharName(Math.max(3, minLen), Math.min(maxLen, 14));
        console.log(`%c[PmheeAether Auth] 🧝 สร้างตัวละครใหม่ชื่อ "${charCreateName}"...`, 'color: #a855f7; font-weight: bold;');
        setNativeInputValue(input, charCreateName);
        charCreateAt = now;
        setTimeout(() => { if (!btn.disabled) btn.click(); }, 400);
        return true;
    }

    window.executeAutoLogin = function(force = false) {
        const cfg = window.__authConfig || (window.__authConfig = {});
        const hudUserEl = document.getElementById('p-auth-user');
        const hudPassEl = document.getElementById('p-auth-pass');
        const hudCharEl = document.getElementById('p-auth-char');
        const domUser = hudUserEl ? hudUserEl.value.trim() : '';
        const domPass = hudPassEl ? hudPassEl.value : '';
        const domChar = hudCharEl ? hudCharEl.value.trim() : '';
        if (domUser && (force || !cfg.username)) cfg.username = domUser;
        if (domPass && (force || !cfg.password)) cfg.password = domPass;
        if (domChar && (force || !cfg.charName)) cfg.charName = domChar;
        if (force && cfg.username && cfg.password) {
            cfg.userEditedAt = Date.now();
            cfg.generatedUser = false;
            cfg.register = false;
            delete cfg.registerError;
            saveAuth();
        }
        if (!force && !cfg.enabled) return;
        if (cfg.register && cfg.username && cfg.password) {
            const isCustomUserId = Boolean(cfg.username && !/^pm[a-z0-9]{8}$/.test(cfg.username));
            if (!cfg.generatedUser && (Number(cfg.userEditedAt) > 0 || Number(cfg.verifiedLoginAt) > 0 || isCustomUserId)) {
                cfg.register = false;
                saveAuth();
            } else {
                runAutoRegister();
                return;
            }
        }

        if (!cfg.username || !cfg.password) {
            if (force) {
                console.warn('%c[PmheeAether Auth] ⚠️ ยังไม่ได้ตั้งค่าชื่อผู้ใช้ (ID) หรือ รหัสผ่าน (PS) ในแท็บ "ตั้งค่า"!', 'color: #f59e0b; font-weight: bold;');
                alert('กรุณากรอกชื่อผู้ใช้ (ID) และ รหัสผ่าน (PS) ในแท็บ "⚙️ ตั้งค่า" ก่อนเปิดใช้งาน Auto-Login');
            }
            return;
        }

        if (isLoginInProgress) return;

        const { userInput, passInput, loginBtn, toLogin } = findLoginElements();
        if (toLogin) { safeClickOnce(toLogin); return; }
        if (!passInput || !loginBtn) {
            if (force) {
                console.warn('%c[PmheeAether Auth] ⚠️ ไม่พบหน้าต่าง Login บนหน้าจอ (ตัวละครอาจอยู่ในเกมอยู่แล้ว)', 'color: #f59e0b;');
            }
            return;
        }

        const now = Date.now();
        if (!force && (now - lastLoginAttemptTime < 4500)) return;

        if (!force && loginFailCount >= 6) {
            if (now - lastLoginAttemptTime < 25000) {
                return;
            }
            loginFailCount = 0;
        }

        isLoginInProgress = true;
        lastLoginAttemptTime = now;
        loginFailCount++;

        console.log(`%c[PmheeAether Auth] 🔐 กำลังดำเนินการ Auto-Login (ครั้งที่ ${loginFailCount}) ด้วย ID: "${cfg.username}"...`, 'color: #a855f7; font-weight: bold;');

        // 1. กรอก Username
        if (userInput) {
            setNativeInputValue(userInput, cfg.username);
        }

        // 2. กรอก Password
        if (passInput) {
            setNativeInputValue(passInput, cfg.password);
        }

        // 3. คลิกปุ่มเข้าเกม
        setTimeout(() => {
            console.log('%c[PmheeAether Auth] 🚀 คลิกปุ่ม "เข้าเกม"...', 'color: #22c55e; font-weight: bold;');
            triggerClick(loginBtn);

            // ตรวจสอบหน้าต่างเลือกตัวละครหลายระลอก (1.5s, 3s, 5s) เพื่อความเสถียร
            [1500, 3000, 5000].forEach(delay => {
                setTimeout(() => {
                    isLoginInProgress = false;
                    checkPostLoginScreen();
                }, delay);
            });
        }, 500);
    };

    // Auto-Login Watcher & Reconnect Monitor (รันทุก 2.5 วินาที)
    setInterval(() => {
        const cfg = window.__authConfig || (window.__authConfig = {});
        const domUser = (document.getElementById('p-auth-user')?.value || '').trim();
        const domPass = document.getElementById('p-auth-pass')?.value || '';
        if (domUser && !cfg.username) {
            cfg.username = domUser;
            cfg.userEditedAt = cfg.userEditedAt || Date.now();
            cfg.generatedUser = false;
            cfg.register = false;
            saveAuth();
        }
        if (domPass && !cfg.password) {
            cfg.password = domPass;
            cfg.userEditedAt = cfg.userEditedAt || Date.now();
            cfg.generatedUser = false;
            cfg.register = false;
            saveAuth();
        }
        if (isLoginScreenVisible()) {
            syncManualLoginFormWatcher();
        }
        const botWasRunning = localStorage.getItem('pelican_bot_running') === 'true' ||
                              !!window.__autoLoopEnabled ||
                              !!window.__isBotRunning ||
                              !!window.__planScriptEnabled;
        const charSelectVisible = !!document.querySelector('.char-select, .char-card');
        if (!cfg.enabled && !botWasRunning && !charSelectVisible) return;

        // ถ้าอยู่ในหน้า Login
        if (isLoginScreenVisible()) {
            if (cfg.enabled) window.executeAutoLogin(false);
            return;
        }
        if (cfg.enabled) confirmRegistered();

        // ตรวจสอบหน้าเลือกตัวละคร (ถ้ามี)
        checkPostLoginScreen();

        // ตรวจสอบเมื่อกลับเข้าสู่เกมสำเร็จ และต้องการ Resume Bot ทำงานต่อ
        const curMap = typeof getCurrentMapName === 'function' ? getCurrentMapName() : '';
        if (curMap && curMap !== 'ไม่ทราบ' && curMap.length > 0 && !isLoginScreenVisible() && !charSelectVisible) {
            staleSessionSince = 0;
            if (cfg.username && cfg.password && (!cfg.verifiedLoginAt || cfg.register)) {
                cfg.register = false;
                cfg.verifiedLoginAt = Date.now();
                delete cfg.registerError;
                saveAuth();
            }
            if (loginFailCount > 0) {
                console.log('%c[PmheeAether Auth] ✅ เข้าสู่โลกสำเร็จเรียบร้อย! (แมพปัจจุบัน: ' + curMap + ')', 'color: #22c55e; font-weight: bold;');
                loginFailCount = 0;
            }

            const shouldResume = (cfg.autoResumeBot !== false) && (localStorage.getItem('pelican_bot_running') === 'true' || window.__autoLoopEnabled);
            if (shouldResume && !window.__isBotRunning && !window.__isNavigating && !window.__isShopping && !window.__isRecovering) {
                if (!window.__resumeTimer) {
                    console.log('%c[PmheeAether Auth] ⏳ กำลังเตรียมความพร้อมแผนที่... อีก 3 วินาทีจะเริ่มระบบฟาร์มอัตโนมัติต่อเนื่อง', 'color: #38bdf8; font-weight: bold;');
                    window.__resumeTimer = setTimeout(() => {
                        window.__resumeTimer = null;
                        if (!window.__isBotRunning && (localStorage.getItem('pelican_bot_running') === 'true' || window.__autoLoopEnabled)) {
                            console.log('%c[PmheeAether Auth] 🚀 Auto-Resume: ทำการ START BOT ฟาร์มต่อทันที 24 ชม.!', 'color: #10b981; font-weight: bold;');
                            window.startMasterBot();
                        }
                    }, 3500);
                }
            }
        }
    }, 2500);

