    // ==========================================
    // PMHEEAETHER SCRIPT PLAN EXECUTION ENGINE
    // ==========================================
    window.__currentScriptPlan = null;
    window.__planScriptEnabled = false; // ค่าเริ่มต้นเป็นปิด (Disabled) เสมอ
    window.__executedPlanTriggers = {};

    try {
        const savedEnabled = localStorage.getItem('pelican_plan_script_enabled');
        window.__planScriptEnabled = (savedEnabled === 'true'); // ต้องเปิดอย่างชัดเจนเท่านั้น
        const savedPlan = localStorage.getItem('pelican_script_plan');
        if (savedPlan) window.__currentScriptPlan = JSON.parse(savedPlan);
        const savedExec = localStorage.getItem('pelican_executed_triggers');
        if (savedExec) window.__executedPlanTriggers = JSON.parse(savedExec);
    } catch(e) {}

    window.__applyScriptPlan = function(plan, enable) {
        window.__currentScriptPlan = plan;
        if (typeof enable === 'boolean') {
            window.__planScriptEnabled = !!enable;
            try {
                localStorage.setItem('pelican_plan_script_enabled', String(window.__planScriptEnabled));
            } catch(e) {}
        }
        try {
            localStorage.setItem('pelican_script_plan', JSON.stringify(plan));
        } catch(e) {}
        console.log('%c[PmheeAether Plan] 📜 โหลดแผนการเล่น (สถานะ: ' + (window.__planScriptEnabled ? 'เปิดใช้งาน' : 'ปิดอยู่') + '):', 'color: #38bdf8; font-weight: bold;', plan ? plan.name : 'None');
        if (plan && Array.isArray(plan.triggers)) {
            console.log(`[PmheeAether Plan] แผนมีทั้งหมด ${plan.triggers.length} เงื่อนไขเลเวล`);
        }
        window.updatePlanHudLabel();
    };

    // HUD: plan name + switch (the plan usually arrives from the Manager after the HUD was built)
    window.updatePlanHudLabel = function() {
        const nameEl = document.getElementById('p-plan-name-display');
        const plan = window.__currentScriptPlan;
        if (nameEl) {
            const txt = plan && plan.name ? plan.name : '(ยังไม่เลือกแผน)';
            if (nameEl.textContent !== txt) nameEl.textContent = txt;
        }
        const cb = document.getElementById('p-plan-script-enabled');
        if (cb && document.activeElement !== cb && cb.checked !== !!window.__planScriptEnabled) cb.checked = !!window.__planScriptEnabled;
    };
    setInterval(() => { try { window.updatePlanHudLabel(); } catch (e) {} }, 3000);

    // Class tree (from manager/public/game-classes.json): id -> [thai name, previous class, tier]
    const PLAN_CLASS_TREE = {"novice":["โนวิซ",null,0],"swordsman":["นักดาบ","novice",1],"mage":["นักเวท","novice",1],"archer":["นักธนู","novice",1],"acolyte":["นักบวชฝึกหัด","novice",1],"merchant":["พ่อค้า","novice",1],"thief":["โจร","novice",1],"knight":["อัศวิน","swordsman",2],"crusader":["ครูเซเดอร์","swordsman",2],"wizard":["จอมเวท","mage",2],"sage":["นักปราชญ์","mage",2],"hunter":["นักล่า","archer",2],"bard":["กวี","archer",2],"dancer":["นักเต้น","archer",2],"priest":["พรีสต์","acolyte",2],"monk":["มองค์","acolyte",2],"blacksmith":["ช่างตีเหล็ก","merchant",2],"alchemist":["นักเล่นแร่แปรธาตุ","merchant",2],"assassin":["นักฆ่า","thief",2],"rogue":["โร้ก","thief",2],"dragon-knight":["อัศวินมังกร","knight",3],"paladin":["พาลาดิน","crusader",3],"revenant":["เรเวแนนท์","crusader",3],"stormweaver":["จอมเวทพายุ","wizard",3],"frost-sage":["ปราชญ์น้ำแข็ง","sage",3],"sniper":["สไนเปอร์","hunter",3],"high-priest":["ไฮพรีสต์","priest",3],"champion":["แชมเปียน","monk",3],"whitesmith":["ไวท์สมิธ","blacksmith",3],"creator":["ครีเอเตอร์","alchemist",3],"assassin-cross":["แอสแซสซินครอส","assassin",3],"stalker":["สตอล์คเกอร์","rogue",3],"draken-paladin":["พาลาดินมังกร","paladin",4]};

    // ['novice', 'archer', 'hunter'] for a hunter
    function planClassLineage(classId) {
        const out = [];
        let c = String(classId || '').trim().toLowerCase();
        for (let i = 0; c && i < 8; i++) {
            out.unshift(c);
            c = PLAN_CLASS_TREE[c] ? PLAN_CLASS_TREE[c][1] : null;
        }
        return out;
    }
    const planClassTier = id => { const e = PLAN_CLASS_TREE[String(id || '').trim().toLowerCase()]; return e ? e[2] : null; };
    const planJobOptions = ch => (Array.isArray(ch && ch.jobChangeOptions) ? ch.jobChangeOptions : [])
        .map(o => String((o && (o.id || o.classId)) || o).trim().toLowerCase()).filter(Boolean);

    function getPlanRoom() {
        return (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null)
            || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null);
    }

    // States during which plan actions must wait (AGENTS.md: never interrupt the Alice walk)
    function planBusyReason() {
        if (document.querySelector('.human-check')) return '🚨 กำลังรอตอบเช็คผู้เล่น (Human Check)';
        if (window.__unexpectedTownWaiting) return '⏳ พักรอนิรภัยหลังกลับเมืองผิดปกติ';
        if (window.__isHumanizing) return '🎭 กำลังทำกิจกรรมจำลองคน (Humanize)';
        if (window.__isWalkingToMap) return 'กำลังเดินกลับแมพผ่าน Alice';
        if (window.__isShopping) return 'กำลังซื้อ/ขายกับ NPC';
        if (window.__isStoring) return 'กำลังฝากของเข้าคลัง';
        if (window.__isCheckingPostSellChannel) return 'กำลังเช็ค/ย้าย Channel ที่คนน้อยสุด';
        if (window.__consolidationPending) return 'รอรวมเงิน';
        if (window.__isRecovering) return 'กำลังชุบชีวิต';
        if (window.__isConsolidating || window.__consolidationReceiverMode) return 'กำลังรวมเงิน/เทรด';
        if (window.__isChangingJob) return 'กำลังเปลี่ยนอาชีพ';
        if (window.__isGearRefining) return 'กำลังตีบวก (เซ็ตอุปกรณ์)';
        if (window.__isManualSelling || window.__isAutoSellingNow) return 'กำลังขายของ';
        return null;
    }
    window.planBusyReason = planBusyReason;

    // Plan action "change_map": remember the new farm map (same key the bot loads) and walk there now
    window.setTargetFarmMap = function(mapName, walkNow = false, opts = {}) {
        if (!mapName) return;
        const cleanMap = String(mapName).replace(/\s*\(Lv\..*?\)/i, '').trim() || mapName;
        window.__targetFarmMap = cleanMap;
        try { localStorage.setItem('pelican_farm_map', cleanMap); } catch (e) {}
        if (typeof window.rememberFarmMap === 'function') window.rememberFarmMap(cleanMap);
        if (opts && opts.fromParty) {
            window.__partyForcedMap = cleanMap;
            if (typeof window.setPlanManualMap === 'function') window.setPlanManualMap(cleanMap);
        }
        const sel = document.getElementById('p-target-map-select');
        if (sel) sel.value = cleanMap;
        if (walkNow && window.__isBotRunning && !planBusyReason() && typeof window.walkToTargetMap === 'function') {
            const cur = (typeof window.getCurrentMapName === 'function') ? (window.getCurrentMapName() || '') : '';
            if (!cur.includes(cleanMap)) window.walkToTargetMap(cleanMap, true, opts);
        }
    };

    // ---------- Random-option filter for plan equip actions: "dex, atk>=5, melee dmg" ----------
    const PLAN_OPTION_ALIASES = {
        ATK: ['atk', 'attack'], MATK: ['matk', 'magicatk'], DEF: ['def'], MDEF: ['mdef'], HIT: ['hit'], FLEE: ['flee'],
        CRIT: ['crit', 'cri', 'critical'], ASPD: ['aspd'], MAXHP: ['hp', 'maxhp'], MAXSP: ['sp', 'maxsp'],
        MOVE_SPEED: ['move', 'movespeed', 'speed'], CRIT_DAMAGE: ['critdmg', 'critdamage'],
        MELEE_DAMAGE_PERCENT: ['meleedmg', 'meleedamage', 'melee'], RANGED_DAMAGE_PERCENT: ['rangeddmg', 'rangedmg', 'rangeddamage', 'ranged', 'range'],
        MAGIC_DAMAGE_PERCENT: ['magicdmg', 'magicdamage', 'magic'], DAMAGE_REDUCTION: ['reduction', 'dmgreduction', 'dr'],
        BLOCK_CHANCE: ['block', 'blockchance'], HEAL_POWER: ['heal', 'healpower'],
        STR: ['str'], AGI: ['agi'], VIT: ['vit'], INT: ['int'], DEX: ['dex'], LUK: ['luk', 'luck']
    };
    const PLAN_PERCENT_STATS = new Set(['MOVE_SPEED', 'CRIT_DAMAGE', 'MELEE_DAMAGE_PERCENT', 'RANGED_DAMAGE_PERCENT', 'MAGIC_DAMAGE_PERCENT', 'DAMAGE_REDUCTION', 'BLOCK_CHANCE', 'HEAL_POWER']);
    function parsePlanOptionFilter(text) {
        const norm = s => String(s || '').toLowerCase().replace(/[\s_\-.]+/g, '');
        const terms = [];
        String(text || '').split(/[,;]+/).map(s => s.trim()).filter(Boolean).forEach(tok => {
            const m = tok.match(/^(.*?)\s*(?:>=|≥|>|=|\s)\s*(\d+)\s*%?\s*$/);
            let name = m && m[1].trim() ? m[1] : tok;
            const min = m && m[1].trim() ? Number(m[2]) : 0;
            const pct = /%\s*$/.test(name);
            name = norm(name.replace(/%\s*$/, ''));
            const type = Object.keys(PLAN_OPTION_ALIASES).find(t => norm(t) === name || PLAN_OPTION_ALIASES[t].includes(name));
            if (type) terms.push({ type, min, pct });
            else console.warn(`[PmheeAether Plan] ⚠️ ไม่รู้จักออปชั่น "${tok}" ในตัวกรอง (ข้าม)`);
        });
        return terms;
    }
    function itemPassesPlanOptions(item, terms) {
        if (!terms.length) return true;
        const affixes = Array.isArray(item && item.affixes) ? item.affixes : [];
        return terms.every(t => {
            const hits = affixes.filter(a => a && a.type === t.type && (!t.pct || a.mode !== 'base' || PLAN_PERCENT_STATS.has(a.type)));
            return hits.length > 0 && hits.reduce((s, a) => s + (Number(a.value) || 0), 0) >= t.min;
        });
    }

    // Market search for plan purchases. The bot's own sniper/auto-buy is paused meanwhile so these
    // results can never trigger an unrelated automatic purchase.
    // The bot's sniper / auto-buy is paused during plan and Manager market searches (their results must never
    // trigger a purchase). A depth counter: back-to-back or overlapping searches restore it only at the end.
    window.pauseSniper = function () {
        const cfg = window.__marketFilterConfig || (window.__marketFilterConfig = {});
        if (!window.__sniperPauseDepth) window.__sniperSaved = { autoBuy: cfg.autoBuy, sniperAlert: cfg.sniperAlert };
        window.__sniperPauseDepth = (window.__sniperPauseDepth || 0) + 1;
        cfg.autoBuy = false;
        cfg.sniperAlert = false;
    };
    window.resumeSniper = function (delayMs = 400) {
        setTimeout(() => {
            window.__sniperPauseDepth = Math.max(0, (window.__sniperPauseDepth || 0) - 1);
            if (window.__sniperPauseDepth === 0 && window.__sniperSaved) {
                const cfg = window.__marketFilterConfig || {};
                cfg.autoBuy = window.__sniperSaved.autoBuy;
                cfg.sniperAlert = window.__sniperSaved.sniperAlert;
                window.__sniperSaved = null;
            }
        }, delayMs);
    };
    async function planMarketSearch(room, q, term, page = 0) {
        window.pauseSniper();
        try {
            const filters = { q, sort: 'price_asc', page };
            if (term) { filters.affix = term.type; if (term.min) filters.affixMin = term.min; }
            const res = await new Promise(resolve => {
                let unsub;
                const timer = setTimeout(() => { if (typeof unsub === 'function') unsub(); resolve(null); }, 4000);
                unsub = room.onMessage('market_results', msg => { clearTimeout(timer); if (typeof unsub === 'function') unsub(); resolve(msg); });
                room.send('market', { op: 'search', filters });
            });
            return (res && Array.isArray(res.listings)) ? res.listings : [];
        } finally {
            window.resumeSniper();
        }
    }

    // Plan action "equip_item". Returns 'done' | 'pending' (try again later) | 'failed'.
    // Gems come in tiers by the % in their name: "Mana Gem (Skill) 3%" < "Mana Gem (Skill) 5%"
    const GEM_SLOTS = ['gem-1', 'gem-2', 'gem-3', 'gem-4'];
    function gemTier(item) {
        if (!item || item.equipType !== 'Gem') return null;
        const m = String(item.name || '').trim().match(/^(.*\S)\s+(\d+(?:\.\d+)?)\s*%$/);
        return m ? { family: m[1].toLowerCase(), pct: parseFloat(m[2]) } : null;
    }
    // Which gem slot a gem should go to: the slot holding a lower tier of the same gem, else an empty one
    function gemTargetSlot(equipment, gem) {
        const t = gemTier(gem);
        if (!t) return null;
        const same = GEM_SLOTS.find(k => { const w = gemTier(equipment[k]); return w && w.family === t.family && w.pct < t.pct; });
        return same || GEM_SLOTS.find(k => !equipment[k]) || null;
    }

    window.findAndEquipItemByName = async function(itemName, buyFromMarketIfMissing = true, maxPrice = 100000, optionFilter = '', targetSlot = '') {
        if (!itemName) return 'failed';
        const want = itemName.trim().toLowerCase();
        const terms = parsePlanOptionFilter(optionFilter);
        const nameOf = it => String((it && it.name) || '').trim().toLowerCase();
        const matches = it => it && nameOf(it) === want && itemPassesPlanOptions(it, terms);
        const ch = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
        const baseLv = Number(ch.baseLevel) || 0;
        const room = getPlanRoom();
        const bagItems = () => (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items : [];

        // 1. Already wearing it (character equipment data, not text on screen)
        const eq = ch.equipment || {};
        const worn = Object.values(eq).filter(Boolean);
        const alreadyInTargetSlot = targetSlot && !/^gem-/.test(targetSlot)
            ? matches(eq[targetSlot])
            : worn.some(matches);
        if (alreadyInTargetSlot) {
            console.log(`%c[PmheeAether Plan] 🛡️ สวม "${itemName}" อยู่แล้ว`, 'color: #22c55e;');
            return 'done';
        }
        // A better tier of the same gem is already in: never swap down to the one named in the plan
        const wantGem = gemTier({ name: itemName, equipType: 'Gem' });
        if (wantGem && worn.some(w => { const t = gemTier(w); return t && t.family === wantGem.family && t.pct >= wantGem.pct; })) {
            console.log(`%c[PmheeAether Plan] 💎 สวม "${itemName}" รุ่นเดียวกันที่ % เท่ากันหรือดีกว่าอยู่แล้ว`, 'color: #22c55e;');
            return 'done';
        }

        // 2. In the bag: exact name + options + level requirement -> equip (best refine first)
        const inBag = bagItems().filter(matches);
        const wearable = inBag.filter(it => !it.levelReq || it.levelReq <= baseLv).sort((a, b) => (b.refine || 0) - (a.refine || 0));
        if (wearable.length) {
            if (!room) return 'pending';
            const to = (/^gem-/.test(targetSlot) || gemTier(wearable[0]))
                ? gemTargetSlot(eq, wearable[0])
                : ((targetSlot === 'accessory-left' || targetSlot === 'accessory-right') ? targetSlot : null);
            room.send('equip', to ? { slot: wearable[0].slot, to } : { slot: wearable[0].slot });
            console.log(`%c[PmheeAether Plan] 🎒 สวมใส่ "${itemName}" จากกระเป๋า (ช่อง ${wearable[0].slot}${to ? ' → ' + to : ''})`, 'color: #22c55e; font-weight: bold;');
            return 'done';
        }
        if (inBag.length) {
            console.log(`[PmheeAether Plan] ⏳ มี "${itemName}" ในกระเป๋าแต่เลเวลยังไม่ถึง (ต้อง Lv.${inBag[0].levelReq}) รอเลเวลก่อน`);
            return 'pending';
        }
        if (!buyFromMarketIfMissing) {
            console.log(`[PmheeAether Plan] ⏳ ไม่พบ "${itemName}"${terms.length ? ' ที่ออปชั่นตรง' : ''} ในตัว/กระเป๋า (ไม่ได้เปิดซื้อจากตลาด) รอเก็บได้ก่อน`);
            return 'pending';
        }

        // 3. Buy the cheapest exact match (instant-buy listings only), then collect it and equip
        if (!room || window.__planMarketBuyInFlight) return 'pending';
        window.__planMarketBuyInFlight = true;
        try {
            const listings = await planMarketSearch(room, itemName, terms[0]);
            const now = Date.now();
            const best = listings
                .filter(l => l && !l.mine && Number(l.qty) === 1 && matches(l.item))
                .filter(l => !(l.auctionEndsAt && l.auctionEndsAt > now))
                .filter(l => !maxPrice || Number(l.price) <= maxPrice)
                .filter(l => !l.item.levelReq || l.item.levelReq <= baseLv)
                .sort((a, b) => Number(a.price) - Number(b.price))[0];
            if (!best) {
                console.log(`[PmheeAether Plan] ⏳ ยังไม่มีคนขาย "${itemName}"${terms.length ? ' ที่ออปชั่นตรง' : ''} ในราคาไม่เกิน ${Number(maxPrice).toLocaleString()} z — จะลองใหม่ภายหลัง`);
                return 'pending';
            }
            const zeny = Number(ch.zeny) || 0;
            if (Number(best.price) > zeny) {
                console.log(`%c[PmheeAether Plan] 💰 เงินไม่พอซื้อ "${itemName}" (มี ${zeny.toLocaleString()} z / ถูกสุด ${Number(best.price).toLocaleString()} z) — รอเงินพอแล้วจะซื้อให้เอง`, 'color: #f59e0b;');
                return 'pending';
            }
            console.log(`%c[PmheeAether Plan] 🛒 ซื้อ "${best.item.name}" ราคา ${Number(best.price).toLocaleString()} z จาก ${best.sellerName}`, 'color: #10b981; font-weight: bold;');
            room.send('market', { op: 'buy', listingId: Number(best.listingId), price: Number(best.price) });
            await new Promise(r => setTimeout(r, 1200));
            room.send('market', { op: 'collect_all' });   // purchases wait in the market "รับของ" tab
            for (let i = 0; i < 16; i++) {
                await new Promise(r => setTimeout(r, 500));
                const got = bagItems().find(matches);
                if (got) {
                    const liveEq = ((typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {}).equipment || eq;
                    const to = (/^gem-/.test(targetSlot) || gemTier(got))
                        ? gemTargetSlot(liveEq, got)
                        : ((targetSlot === 'accessory-left' || targetSlot === 'accessory-right') ? targetSlot : null);
                    room.send('equip', to ? { slot: got.slot, to } : { slot: got.slot });
                    console.log(`%c[PmheeAether Plan] 🛡️ สวมใส่ "${itemName}" ที่ซื้อมาแล้ว${to ? ' (' + to + ')' : ''}`, 'color: #22c55e; font-weight: bold;');
                    return 'done';
                }
            }
            return 'pending';   // bought but not in the bag yet: next retry equips it from the bag
        } catch (e) {
            console.warn('[PmheeAether Plan] Market buy error:', e);
            return 'pending';
        } finally {
            window.__planMarketBuyInFlight = false;
        }
    };

    // ---------- Level triggers (n8n-style: trigger -> actions) ----------
    // A trigger fires when the level *crosses* its target (so multi-level jumps or bot downtime can't
    // skip it). Progress is stored per character + plan; actions that can't finish yet are retried.
    const PLAN_RETRY_MS = 60 * 1000;
    const PLAN_SLOW_RETRY_MS = 5 * 60 * 1000;   // after 10 min of waiting (e.g. saving up zeny)
    const planTriggerId = (t, i) => t.id || `${t.type || 'base_level'}_${t.targetLevel}_${i}`;
    let planTriggersRunning = false;

    function readPlanLevels() {
        const el = document.querySelector('.hud-levels');
        const text = (el && (el.innerText || el.textContent)) || '';
        const b = text.match(/Base\s*(?:Lv\.?|Level)?\s*(\d+)/i);
        const j = text.match(/Job\s*(?:Lv\.?|Level)?\s*(\d+)/i);
        const ch = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : null;
        const base = b ? parseInt(b[1], 10) : (Number(ch && (ch.baseLevel || ch.level)) || 0);
        const job = j ? parseInt(j[1], 10) : (Number(ch && ch.jobLevel) || 0);
        if (!base || !job) return null;   // HUD not ready: never guess a level
        return { base, job, cls: String((ch && ch.classId) || '').toLowerCase() };
    }

    // Arrow action: the chosen arrow must actually be on the character — equip it from the bag, or have
    // the shop routine buy it (at most every 10 min) and equip it on the next retry
    let planArrowShopAt = 0;
    function ensurePlanArrows(cfg) {
        const ch = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
        const want = Number(cfg.arrowType) || 90030;
        const worn = ch.ammo;
        if (worn && Number(worn.itemId) === want) {
            console.log(`%c[PmheeAether Plan] 🏹 ใส่ "${worn.name}" อยู่แล้ว (${worn.qty} ดอก)`, 'color: #22c55e;');
            return 'done';
        }
        const bag = (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items : [];
        const stack = bag.filter(it => it && Number(it.itemId) === want).sort((a, b) => (b.qty || 0) - (a.qty || 0))[0];
        const room = getPlanRoom();
        if (stack && room) {
            console.log(`%c[PmheeAether Plan] 🏹 สวมลูกธนู "${stack.name}" จากกระเป๋า (${stack.qty} ดอก)${worn ? ` แทน "${worn.name}"` : ''}`, 'color: #22c55e; font-weight: bold;');
            room.send('equip', { slot: stack.slot });
            return 'pending';   // confirmed on the next retry
        }
        if (!window.__isShopping && Date.now() - planArrowShopAt > 10 * 60 * 1000 && typeof window.executeAutoShopRoutine === 'function') {
            planArrowShopAt = Date.now();
            window.__planArrowBuyUntil = Date.now() + 15 * 60 * 1000;
            console.log(`%c[PmheeAether Plan] 🏹 ไม่มีลูกธนูชนิดที่ตั้ง (#${want}) ในตัว/กระเป๋า -> ไปซื้อ ${cfg.arrowBuyQty} ดอก`, 'color: #f59e0b; font-weight: bold;');
            window.executeAutoShopRoutine();
        }
        return 'pending';
    }

    // "กลับไปขายของ" action: run the normal town trip once (sell by the sell settings, restock, back to the
    // farm map). Done when a trip started by this action has finished.
    const planSellTrips = {};
    function runPlanSellTrip(act) {
        const key = act.id || 'sell_trip';
        const started = planSellTrips[key];
        if (window.__isShopping) return 'pending';
        if (started && Date.now() - started > 3000) {
            delete planSellTrips[key];
            console.log('%c[PmheeAether Plan] 🛒 กลับไปขายของตามแผนเสร็จแล้ว', 'color: #22c55e; font-weight: bold;');
            return 'done';
        }
        if (started) return 'pending';
        if (typeof window.executeAutoShopRoutine !== 'function') return 'failed';
        console.log('%c[PmheeAether Plan] 🛒 ถึงเงื่อนไขในแผน -> กลับเมืองไปขายของ 1 รอบ', 'color: #f59e0b; font-weight: bold;');
        window.executeAutoShopRoutine();
        if (window.__isShopping) planSellTrips[key] = Date.now();   // refused (cooldown / walking): try again later
        return 'pending';
    }

    // "📦 Weight Limit Scroll" action: buy the scrolls from the NPC shop that sells them and use them until
    // this character has used `qty` (the game allows 10 per character). Uses are counted per character in
    // pelican_weight_scroll_<char>, so a character never buys them again once done.
    const WEIGHT_SCROLL_ID = 90309;
    // How many scrolls this character has used, from the game's own numbers: max weight = 2000 + 30 × STR
    // (base + bonus) + 500 × scrolls used (exact on all 15 characters checked). The count kept in localStorage
    // is lost when the storage changes (Electron -> browser mode, a new profile id) — that made characters
    // that had used all 10 buy 10 more, which the game then refused to use. null = the formula doesn't fit.
    window.getWeightScrollsUsed = function () {
        const limit = Number((window.__latestInventory || {}).weightLimit) || 0;
        const ch = (typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {};
        if (!limit || !ch.stats || typeof ch.stats.STR !== 'number') return null;
        if (Number((ch.skills || {})['enlarge-weight']) > 0) return null;   // Pack Mule adds weight too: unknown
        const str = (Number(ch.stats.STR) || 0) + (Number(ch.bonusStats && ch.bonusStats.STR) || 0);
        const isPrem = (typeof window.isPremiumCharacter === 'function' && window.isPremiumCharacter()) || (limit - 2000 - 30 * str >= 9500);
        const effectiveLimit = isPrem ? (limit - 10000) : limit;
        const x = (effectiveLimit - 2000 - 30 * str) / 500;
        const n = Math.round(x);
        return (Math.abs(x - n) < 0.01 && n >= 0 && n <= 10) ? n : null;
    };
    let weightScrollBusy = false;
    let weightShopTriedAt = 0;
    // No NPC sells the scroll, or not enough zeny: go back to farming and try again much later. Before, the
    // character stayed in town (or walked back) and asked the shops again every minute — "always in town
    // talking to the Blacksmith".
    let weightShopBackoffUntil = 0;
    const weightShopGiveUp = (r) => {
        const mins = r === 'not-sold' ? 30 : 10;
        weightShopBackoffUntil = Date.now() + mins * 60000;
        console.warn(`[PmheeAether Plan] 📦 ซื้อ Weight Limit Scroll ไม่ได้ (${r === 'not-sold' ? 'ไม่มีร้าน NPC ในเมืองที่ขาย' : 'เงินไม่พอ'}) -> กลับไปฟาร์มก่อน ลองใหม่ใน ${mins} นาที`);
        window.__planJobChangeHoldUntil = 0;
        if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('weight');
    };
    const planSleep = ms => new Promise(r => setTimeout(r, ms));
    const planBag = () => (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items.filter(Boolean) : [];
    const inCapital = () => /เมืองหลวง|โซลเฮเวน/.test((typeof window.getCurrentMapName === 'function' && window.getCurrentMapName()) || '');

    // Open each candidate NPC shop (arrow shop first, then Blacksmith Enok) and buy where the item is listed
    async function planBuyFromNpcShop(itemId, qty, maxTotal) {
        const room = getPlanRoom();
        if (!room || !room.state || !room.state.npcs) return 'no-room';
        const keys = [];
        const add = k => { if (k && !keys.includes(k)) keys.push(k); };
        add(window.__shopConfig && window.__shopConfig.npcKey);
        room.state.npcs.forEach((n, k) => { if (/Shopkeeper|Blacksmith|Bag Merchant/i.test((n && n.name) || '')) add(k); });
        const closeAll = () => { const x = document.querySelector('.shop-window .win-close, .npc-dialog .win-close'); if (x) x.click(); };
        for (const key of keys) {
            const npcName = (room.state.npcs.get && room.state.npcs.get(key) && room.state.npcs.get(key).name) || '?';
            console.log(`[PmheeAether Plan] 🏪 ถามร้าน NPC ${key} (${npcName}) ว่ามี item #${itemId} ไหม`);
            room.send('npc_talk', { npcKey: key });
            let shop = null, dlg = null;
            for (let i = 0; i < 75 && !shop && !dlg; i++) { await planSleep(200); shop = document.querySelector('.shop-window'); dlg = document.querySelector('.npc-dialog'); }
            if (dlg && !shop) {
                const opts = Array.from(dlg.querySelectorAll('.npc-options button')).map(b => (b.innerText || '').replace(/^\s*\d+\s*/, '').trim());
                const idx = opts.findIndex(o => /ซื้อ/.test(o) && !/แร่|ตีบวก/.test(o));
                if (idx < 0) { closeAll(); await planSleep(300); continue; }
                room.send('npc_option', { index: idx });
                for (let i = 0; i < 30 && !shop; i++) { await planSleep(200); shop = document.querySelector('.shop-window'); }
            }
            if (!shop) { closeAll(); await planSleep(300); continue; }
            const row = Array.from(shop.querySelectorAll('.shop-row')).find(r => {
                const fk = Object.keys(r).find(k => k.startsWith('__reactFiber'));
                return fk && r[fk] && String(r[fk].key) === String(itemId);
            });
            if (!row) { closeAll(); await planSleep(400); continue; }
            const price = parseInt(((row.querySelector('.shop-price') || {}).innerText || '').replace(/[^0-9]/g, ''), 10) || 0;
            const zeny = Number(((window.getLiveCharacterData && window.getLiveCharacterData()) || {}).zeny) || 0;
            let n = qty;
            if (price > 0) n = Math.min(qty, Math.floor(zeny / price), maxTotal ? Math.floor(maxTotal / price) : qty);
            if (n <= 0) {
                console.log(`%c[PmheeAether Plan] 💰 เงินไม่พอซื้อ (ราคา ${price.toLocaleString()} z / มี ${zeny.toLocaleString()} z) — รอเงินพอ`, 'color: #f59e0b;');
                closeAll();
                return 'no-money';
            }
            const before = planBag().filter(it => Number(it.itemId) === Number(itemId)).reduce((a, it) => a + (it.qty || 1), 0);
            console.log(`%c[PmheeAether Plan] 🛒 ซื้อ item #${itemId} x${n} (${price ? (price * n).toLocaleString() + ' z' : 'ราคาไม่ทราบ'}) จาก NPC ${key}`, 'color: #10b981; font-weight: bold;');
            room.send('shop_buy_many', { lines: [{ itemId: Number(itemId), qty: n }] });
            for (let i = 0; i < 20; i++) {
                await planSleep(250);
                const now = planBag().filter(it => Number(it.itemId) === Number(itemId)).reduce((a, it) => a + (it.qty || 1), 0);
                if (now > before) break;
            }
            closeAll();
            return 'bought';
        }
        return 'not-sold';
    }

    async function runWeightScrollAction(act) {
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        if (!charName || charName === 'default_char') return 'pending';
        const key = 'pelican_weight_scroll_v2_' + charName;   // v1 counted cooldown refusals as "quota full"
        const target = Math.max(1, Math.min(10, Number(act.qty) || 10));
        let used = Number(localStorage.getItem(key)) || 0;
        const counterKnown = localStorage.getItem(key) !== null;
        const finish = msg => {
            console.log(`%c[PmheeAether Plan] 📦 Weight Limit Scroll: ${msg}`, 'color: #22c55e; font-weight: bold;');
            window.__planJobChangeHoldUntil = 0;
            if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('weight');
            return 'done';
        };
        const real = window.getWeightScrollsUsed();
        if (real !== null && real > used) { used = real; try { localStorage.setItem(key, String(used)); } catch (e) {} }
        if (real !== null && real >= 10) return finish(`น้ำหนักสูงสุดบอกว่าตัวละครนี้ใช้ครบ 10 ครั้งแล้ว — ไม่ซื้อเพิ่ม`);
        if (used >= target) return finish(`ตัวละครนี้ใช้ครบ ${used} ครั้งแล้ว`);
        if (weightScrollBusy) return 'pending';
        weightScrollBusy = true; window.__isWeightScrollBusy = true;
        try {
            const room = getPlanRoom();
            if (!room) return 'pending';
            // 1. Use the scrolls in the bag one by one. The game has a ~3 s cooldown between uses, so wait
            //    between them; a use counts when the bag count drops or the max weight goes up (+500 each).
            //    Only 3 refusals in a row (spaced past the cooldown) mean the character's quota is full.
            const scrollQty = () => planBag().filter(it => Number(it.itemId) === WEIGHT_SCROLL_ID).reduce((a, it) => a + (it.qty || 1), 0);
            const weightLimit = () => Number((window.__latestInventory || {}).weightLimit) || 0;
            let scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
            let refusals = 0;
            while (scroll && used < target) {
                const qtyBefore = scrollQty();
                const limitBefore = weightLimit();
                room.send('inv_use', { slot: scroll.slot });
                let ok = false;
                for (let i = 0; i < 16 && !ok; i++) {
                    await planSleep(250);
                    ok = scrollQty() < qtyBefore || (limitBefore > 0 && weightLimit() > limitBefore);
                }
                if (!ok) {
                    refusals++;
                    if (refusals >= 3) {
                        localStorage.setItem(key, String(target));
                        return finish(`เกมไม่ให้ใช้เพิ่ม 3 ครั้งติดกัน (ใช้ครบโควตาของตัวละครนี้แล้ว) — ไม่ซื้ออีก`);
                    }
                    console.log(`[PmheeAether Plan] ⏳ ใช้ Weight Limit Scroll ยังไม่ติด (อาจติดคูลดาวน์) -> รอแล้วลองใหม่ (${refusals}/3)`);
                    await planSleep(4000);
                    scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
                    continue;
                }
                refusals = 0;
                used++;
                localStorage.setItem(key, String(used));
                console.log(`%c[PmheeAether Plan] 📦 ใช้ Weight Limit Scroll (${used}/${target}) น้ำหนักสูงสุด ${weightLimit().toLocaleString()}`, 'color: #38bdf8;');
                await planSleep(3500);   // game cooldown between uses
                scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
            }
            if (used >= target) return finish(`ใช้ครบ ${used}/${target} แล้ว บันทึกไว้กับตัวละครนี้ (จะไม่ซื้อซ้ำ)`);

            // 2. Need more: go to the capital, then buy the missing amount from the shop that sells it
            if (Date.now() < weightShopBackoffUntil) return 'pending';
            if (!inCapital()) {
                if (window.__isNavigating || window.__isWalkingToMap) return 'pending';
                const farm = window.__targetFarmMap || '';
                if (farm && !/เมืองหลวง|โซลเฮเวน/.test(farm)) { try { localStorage.setItem('pelican_job_return_map', farm); } catch (e) {} }
                window.__planJobChangeHoldUntil = Date.now() + 120000; if (typeof window.needTown === 'function') window.needTown('weight');
                console.log(`%c[PmheeAether Plan] 📦 ต้องซื้อ Weight Limit Scroll อีก ${target - used} อัน -> กลับเมืองหลวง`, 'color: #f59e0b; font-weight: bold;');
                window.planTripToCapital('weight');
                return 'pending';
            }
            if (Date.now() - weightShopTriedAt < 60000) return 'pending';
            weightShopTriedAt = Date.now();
            window.__planJobChangeHoldUntil = Date.now() + 60000; if (typeof window.needTown === 'function') window.needTown('weight');
            // Uses unknown (no counter here and max weight can't tell, e.g. Pack Mule): buy 1 first — if the game
            // refuses it the quota is full and only that one scroll was spent
            const buyQty = (real === null && !counterKnown) ? 1 : target - used;
            const r = await planBuyFromNpcShop(WEIGHT_SCROLL_ID, buyQty, Number(act.maxPrice) || 0);
            if (r === 'not-sold' || r === 'no-money') weightShopGiveUp(r);
            return 'pending';   // next round uses what was bought
        } finally {
            weightScrollBusy = false; window.__isWeightScrollBusy = false;
        }
    }

    // "⚖️ เช็คน้ำหนัก" (Manager button): a character on a plan whose max weight is still below the target
    // (e.g. its weight-scroll step ran when only one scroll got used) buys and uses the missing Weight Limit
    // Scrolls (+500 max weight each) until the target is reached. The request is kept in localStorage so it
    // survives a page refresh; it runs from the plan loop (START BOT on, nothing else busy).
    const WEIGHT_TOPUP_KEY = 'pelican_weight_topup';
    const WEIGHT_PER_SCROLL = 500;
    let weightTopUpShopAt = 0, weightTopUpNoMoneyAt = 0;
    const planWeightLimit = () => Number((window.__latestInventory || {}).weightLimit) || 0;
    window.getWeightTopUpState = function () {
        try { return JSON.parse(localStorage.getItem(WEIGHT_TOPUP_KEY) || 'null'); } catch (e) { return null; }
    };
    window.requestWeightTopUp = function (target = 7000) {
        const t = Math.max(1000, Math.min(20000, Number(target) || 7000));
        try { localStorage.setItem(WEIGHT_TOPUP_KEY, JSON.stringify({ target: t, at: Date.now() })); } catch (e) {}
        weightTopUpShopAt = 0;
        weightTopUpNoMoneyAt = 0;
        console.log(`%c[PmheeAether Plan] ⚖️ เช็คน้ำหนัก: เป้าหมายน้ำหนักสูงสุด ${t.toLocaleString()} (ตอนนี้ ${planWeightLimit().toLocaleString()})`, 'color: #38bdf8; font-weight: bold;');
        return true;
    };
    // true = working on it this round (walking / buying / using), false = nothing to do or waiting for zeny
    window.runWeightTopUpStep = async function () {
        const req = window.getWeightTopUpState();
        if (!req || !req.target) return false;
        const effectivePlanWeightLimit = () => {
            const lim = planWeightLimit();
            if (!lim) return 0;
            const isPrem = (typeof window.isPremiumCharacter === 'function' && window.isPremiumCharacter()) || lim >= 12000;
            return (isPrem && req.target <= 10000) ? Math.max(0, lim - 10000) : lim;
        };
        const limit = effectivePlanWeightLimit();
        if (!limit) return false;
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        const usedKey = charName && charName !== 'default_char' ? 'pelican_weight_scroll_v2_' + charName : '';
        const done = msg => {
            try { localStorage.removeItem(WEIGHT_TOPUP_KEY); } catch (e) {}
            console.log(`%c[PmheeAether Plan] ⚖️ เช็คน้ำหนัก: ${msg}`, 'color: #22c55e; font-weight: bold;');
            window.__planJobChangeHoldUntil = 0;
            if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('topup');
            return false;
        };
        if (limit >= req.target) return done(`น้ำหนักสูงสุด ${planWeightLimit().toLocaleString()} ถึงเป้า ${req.target.toLocaleString()} แล้ว`);
        const realUsed = window.getWeightScrollsUsed();
        if (realUsed !== null && realUsed >= 10) {
            if (usedKey) { try { localStorage.setItem(usedKey, '10'); } catch (e) {} }
            return done(`ตัวละครนี้ใช้ Weight Limit Scroll ครบ 10 ครั้งแล้ว (น้ำหนักสูงสุด ${planWeightLimit().toLocaleString()}) — เพิ่มอีกไม่ได้ ไม่ซื้อ`);
        }
        if (weightScrollBusy) return true;
        weightScrollBusy = true; window.__isWeightScrollBusy = true;
        try {
            const room = getPlanRoom();
            if (!room) return false;
            // 1. Use the scrolls already in the bag, one at a time (game cooldown ~3 s)
            const scrollQty = () => planBag().filter(it => Number(it.itemId) === WEIGHT_SCROLL_ID).reduce((a, it) => a + (it.qty || 1), 0);
            let scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
            let refusals = 0;
            while (scroll && effectivePlanWeightLimit() < req.target) {
                const qtyBefore = scrollQty();
                const limitBefore = planWeightLimit();
                room.send('inv_use', { slot: scroll.slot });
                let ok = false;
                for (let i = 0; i < 16 && !ok; i++) {
                    await planSleep(250);
                    ok = scrollQty() < qtyBefore || planWeightLimit() > limitBefore;
                }
                if (!ok) {
                    if (++refusals >= 3) {
                        if (usedKey) localStorage.setItem(usedKey, '10');
                        return done(`เกมไม่ให้ใช้เพิ่มแล้ว (ตัวละครนี้ใช้ครบโควตา) น้ำหนักสูงสุด ${planWeightLimit().toLocaleString()}`);
                    }
                    await planSleep(4000);
                    scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
                    continue;
                }
                refusals = 0;
                if (usedKey) localStorage.setItem(usedKey, String(Math.min(10, (Number(localStorage.getItem(usedKey)) || 0) + 1)));
                console.log(`%c[PmheeAether Plan] ⚖️ ใช้ Weight Limit Scroll -> น้ำหนักสูงสุด ${planWeightLimit().toLocaleString()} / ${req.target.toLocaleString()}`, 'color: #38bdf8;');
                await planSleep(3500);
                scroll = planBag().find(it => Number(it.itemId) === WEIGHT_SCROLL_ID);
            }
            if (effectivePlanWeightLimit() >= req.target) return done(`น้ำหนักสูงสุด ${planWeightLimit().toLocaleString()} ถึงเป้าแล้ว`);

            // 2. Buy the missing amount in the capital (not more than the zeny allows — waits for zeny otherwise)
            const usedNow = window.getWeightScrollsUsed();
            let need = Math.min(10 - (usedNow || 0), Math.ceil((req.target - effectivePlanWeightLimit()) / WEIGHT_PER_SCROLL));
            let counterKnown = false;
            try { counterKnown = !!usedKey && localStorage.getItem(usedKey) !== null; } catch (e) {}
            if (usedNow === null && !counterKnown) need = Math.min(need, 1);   // unknown quota: 1 scroll as a probe
            if (need <= 0) return done(`ตัวละครนี้ใช้ Weight Limit Scroll ครบโควตาแล้ว — ไม่ซื้อ`);
            if (Date.now() - weightTopUpNoMoneyAt < 5 * 60000 || Date.now() < weightShopBackoffUntil) return false;
            if (!inCapital()) {
                if (window.__isNavigating || window.__isWalkingToMap) return true;
                const farm = window.__targetFarmMap || '';
                if (farm && !/เมืองหลวง|โซลเฮเวน/.test(farm)) { try { localStorage.setItem('pelican_job_return_map', farm); } catch (e) {} }
                window.__planJobChangeHoldUntil = Date.now() + 120000; if (typeof window.needTown === 'function') window.needTown('topup');
                console.log(`%c[PmheeAether Plan] ⚖️ ต้องซื้อ Weight Limit Scroll ${need} อัน -> กลับเมืองหลวง`, 'color: #f59e0b; font-weight: bold;');
                window.planTripToCapital('topup');
                return true;
            }
            if (Date.now() - weightTopUpShopAt < 60000) return true;
            weightTopUpShopAt = Date.now();
            window.__planJobChangeHoldUntil = Date.now() + 60000; if (typeof window.needTown === 'function') window.needTown('topup');
            const r = await planBuyFromNpcShop(WEIGHT_SCROLL_ID, need, 0);
            if (r === 'no-money') {
                // go back to farming; try again in 5 minutes
                weightTopUpNoMoneyAt = Date.now();
                window.__planJobChangeHoldUntil = 0;
                if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('topup');
                return false;
            }
            if (r === 'not-sold') { weightShopGiveUp(r); return false; }
            return true;   // next round uses what was bought
        } finally {
            weightScrollBusy = false; window.__isWeightScrollBusy = false;
        }
    };

    // ---------- 🛡️ Gear set of the plan (plan.gearPlan, made in the Manager's "เซ็ตอุปกรณ์") ----------
    // Steps run strictly in order, one at a time: a step starts only when every step before it is done and
    // the zeny has reached its amount. Done = checked on the character every time (wearing the item with the
    // required random options / refined to the level), so a broken or replaced item is bought again.
    //   every step also waits for Base Lv. >= minLevel (0 = any)
    //   { kind: 'equip',  slot, itemName, options, zeny, jobs }  -> bag / market (price up to zeny), then equip
    //   { kind: 'refine', slot, itemName, toLevel, zeny, blessing } -> Blacksmith Enok (capital), buys the ore
    const GEAR_ACC = ['accessory-left', 'accessory-right'];
    const GEAR_TRIP_KEY = 'pelican_gear_trip';   // kept in localStorage: an Auto-update refresh mid-trip must still go back
    let gearBusy = false, gearNextTry = 0, gearWaitLog = '', gearWaitLogAt = 0, gearSmithBackoffUntil = 0;
    const gearEquipTries = {}, gearEquipHistory = {}, gearWasWorn = {};
    const gearName = it => String((it && it.name) || '').trim().toLowerCase();
    const gearChar = () => (typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {};
    const gearKey = suffix => {
        const plan = window.__currentScriptPlan || {};
        const ch = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        return `pelican_gear_${suffix}_${ch}_${plan.id || plan.name || 'plan'}`;
    };
    const gearGet = (k, d) => { try { const v = JSON.parse(localStorage.getItem(k) || 'null'); return v == null ? d : v; } catch (e) { return d; } };
    const gearSet = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };
    const gearLog = (msg, color = '#f59e0b') => console.log(`%c[PmheeAether Gear] ${msg}`, `color: ${color}; font-weight: bold;`);
    const gearWait = msg => {   // the same "waiting" line at most every 10 min
        if (msg !== gearWaitLog || Date.now() - gearWaitLogAt > 600000) { gearWaitLog = msg; gearWaitLogAt = Date.now(); console.log(`[PmheeAether Gear] ⏳ ${msg}`); }
    };
    // Steps given up on for this character + plan (refine maxed / not in the refine list / broke twice)
    const gearSkipped = () => gearGet(gearKey('skip'), {});
    const gearIsSkipped = (sk, step) => { const e = sk[step.id]; return !!e && (!e.until || e.until > Date.now()); };
    const gearSkip = (step, why, mins) => {
        const sk = gearSkipped();
        sk[step.id] = { why, until: mins ? Date.now() + mins * 60000 : 0 };
        gearSet(gearKey('skip'), sk);
        gearLog(`⏭️ ข้ามรายการ "${step.kind === 'refine' ? `ตีบวก ${step.itemName} +${step.toLevel}` : step.itemName}" — ${why}${mins ? ` (ลองใหม่ใน ${mins} นาที)` : ''}`, '#94a3b8');
    };
    const gearJobId = n => String(n || '').trim().toLowerCase().replace(/\s+/g, '-');

    // The item a step is about, as worn now. Accessories: the other side counts too, unless the plan also wants
    // this same item on the other side (two of the same ring)
    function gearWorn(step, equipment, steps) {
        const want = String(step.itemName || '').trim().toLowerCase();
        const terms = step.kind === 'equip' ? parsePlanOptionFilter(step.options) : [];
        const ok = it => it && gearName(it) === want && itemPassesPlanOptions(it, terms);
        if (/^gem-/.test(step.slot)) {
            // gems: one of each kind, in any gem slot — the same gem at a better % counts too (never swapped down)
            const exact = GEM_SLOTS.map(k => equipment[k]).find(ok);
            if (exact) return exact;
            const t = gemTier({ name: step.itemName, equipType: 'Gem' });
            if (step.kind === 'equip' && t) return GEM_SLOTS.map(k => equipment[k]).find(w => { const wt = gemTier(w); return wt && wt.family === t.family && wt.pct > t.pct; }) || null;
            return null;
        }
        if (ok(equipment[step.slot])) return equipment[step.slot];
        if (GEAR_ACC.includes(step.slot)) {
            const o = GEAR_ACC.find(k => k !== step.slot);
            const otherPlanned = (steps || []).some(x => x && x.kind === 'equip' && x.slot === o && gearName({ name: x.itemName }) === want);
            if (!otherPlanned && ok(equipment[o])) return equipment[o];
        }
        return null;
    }
    // Cards on an item (game: item.cards) that are this step's card
    function gearCardCount(item, step) {
        const want = String(step.cardName || '').trim().toLowerCase();
        return (Array.isArray(item && item.cards) ? item.cards : []).filter(c => c && (typeof c === 'object'
            ? (gearName(c) === want || Number(c.itemId) === Number(step.cardId))
            : Number(c) === Number(step.cardId))).length;
    }
    // A card step is the n-th of its card on that item (two of the same card = two steps)
    const gearCardOrdinal = (step, steps) => {
        const i = steps.indexOf(step);
        return steps.slice(0, i + 1).filter(x => x && x.kind === 'card' && x.slot === step.slot && x.itemName === step.itemName && x.cardName === step.cardName).length;
    };
    function gearStepDone(step, equipment, steps) {
        const w = gearWorn(step, equipment, steps);
        if (!w) return false;
        if (step.kind === 'card') return gearCardCount(w, step) >= gearCardOrdinal(step, steps || [step]);
        return step.kind !== 'refine' || (Number(w.refine) || 0) >= (Number(step.toLevel) || 0);
    }
    // First step that still has work. Also done: a step whose slot moved on to a later item of the plan (the
    // starter bow after the better bow is worn). A refine step with no equip step of its item before it can
    // never run (moved above it / its equip step deleted): skipped so it never blocks the set.
    window.getGearPlanStatus = function () {
        const plan = window.__currentScriptPlan || {};
        const gp = plan.gearPlan;
        const steps = (gp && Array.isArray(gp.steps)) ? gp.steps : [];
        const equipment = gearChar().equipment || {};
        const sk = gearSkipped();
        for (let i = 0; i < steps.length; i++) {
            const st = steps[i];
            if (!st || !st.slot || !st.itemName || gearIsSkipped(sk, st)) continue;
            if (gearStepDone(st, equipment, steps)) { delete gearEquipTries[st.id]; if (st.kind === 'equip') gearWasWorn[st.id] = true; continue; }
            const superseded = steps.slice(i + 1).some(x => x && x.kind === 'equip' && x.slot === st.slot && gearName({ name: x.itemName }) !== gearName({ name: st.itemName }) && gearWorn(x, equipment, steps));
            if (superseded) continue;
            if ((st.kind === 'refine' || st.kind === 'card') && !steps.slice(0, i).some(x => x && x.kind === 'equip' && x.slot === st.slot && gearName({ name: x.itemName }) === gearName({ name: st.itemName }))) continue;
            return { index: i, step: st, total: steps.length, steps };
        }
        return { index: -1, step: null, total: steps.length, steps };
    };

    const gearGoTown = why => {
        if (window.__isNavigating || window.__isWalkingToMap) return;
        window.__planJobChangeHoldUntil = Date.now() + 120000; if (typeof window.needTown === 'function') window.needTown('gear');
        try { localStorage.setItem(GEAR_TRIP_KEY, String(Date.now())); } catch (e) {}
        gearLog(`🏙️ ${why} -> กลับเมืองหลวงไปหา Blacksmith`);
        window.planTripToCapital('gear');
    };
    // Back to the farm map after a town trip of the gear set (also after a page refresh during the trip)
    const gearBackToFarm = () => {
        let trip = null;
        try { trip = localStorage.getItem(GEAR_TRIP_KEY); } catch (e) {}
        if (!trip) return;
        try { localStorage.removeItem(GEAR_TRIP_KEY); } catch (e) {}
        window.__planJobChangeHoldUntil = 0;
        if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('gear');
    };
    const gearCloseNpc = () => {
        try {
            document.querySelectorAll('.refine-window .win-close, .shop-window .win-close, .npc-dialog .win-close').forEach(x => {
                try { x.click(); } catch (_) {}
            });
            if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
        } catch (e) {}
    };
    function gearSmithKey(room) {
        let key = null;
        if (room && room.state && room.state.npcs && typeof room.state.npcs.forEach === 'function') {
            room.state.npcs.forEach((n, k) => { if (!key && n && /Blacksmith/i.test(n.name || '')) key = k; });
        }
        return key;
    }
    // Talk to the Blacksmith and pick the dialog option whose text passes `pick`
    async function gearSmithOption(room, key, pick, waitFor) {
        try {
            const npc = room && room.state && room.state.npcs && typeof room.state.npcs.get === 'function' ? room.state.npcs.get(key) : null;
            if (npc && Number.isFinite(Number(npc.x)) && Number.isFinite(Number(npc.y))) {
                const getMe = () => (room.state && room.state.players && typeof room.state.players.get === 'function') ? room.state.players.get(room.sessionId) : null;
                let me = getMe();
                if (me && Number.isFinite(Number(me.x)) && Math.hypot(me.x - npc.x, me.y - npc.y) > 115) {
                    const walkStart = Date.now();
                    let lastMove = 0;
                    while (Date.now() - walkStart < 15000 && window.__isBotRunning) {
                        me = getMe();
                        if (me && Math.hypot(me.x - npc.x, me.y - npc.y) <= 115) break;
                        if (Date.now() - lastMove > 1800) {
                            lastMove = Date.now();
                            room.send('move_to', { x: Number(npc.x), y: Number(npc.y) });
                        }
                        await planSleep(250);
                    }
                    await planSleep(250);
                }
            }
        } catch (e) {}
        const got = waitFor ? new Promise(resolve => {
            let unsub;
            const timer = setTimeout(() => { if (typeof unsub === 'function') unsub(); resolve(null); }, 12000);
            unsub = room.onMessage(waitFor, msg => { clearTimeout(timer); if (typeof unsub === 'function') unsub(); resolve(msg); });
        }) : null;
        room.send('npc_talk', { npcKey: key });
        let dlg = null;
        for (let i = 0; i < 75 && !dlg; i++) { await planSleep(200); dlg = document.querySelector('.npc-dialog'); if (dlg && !dlg.querySelector('.npc-options button')) dlg = null; }
        if (!dlg) { gearCloseNpc(); return { error: 'ไม่มีหน้าต่างคุยกับ Blacksmith' }; }
        const opts = Array.from(dlg.querySelectorAll('.npc-options button')).map(b => (b.innerText || '').replace(/^\s*\d+\s*/, '').trim());
        const idx = opts.findIndex(pick);
        if (idx < 0) { gearCloseNpc(); return { error: 'ไม่มีตัวเลือกที่ต้องการ (' + opts.join(' / ') + ')' }; }
        room.send('npc_option', { index: idx });
        return { msg: got ? await got : null };
    }

    // Refine ores (game wiki): weapons Phracon +1-4 / Emveretarcon +5-7 / Oridecon +8-10, everything else
    // Rough Elunium / Elunium / Enriched Elunium. Only the +1-4 ores are sold by Blacksmith Enok (200 z).
    const GEAR_ORES = {
        weapon: [{ id: 90201, name: 'Phracon', npcPrice: 200 }, { id: 90202, name: 'Emveretarcon' }, { id: 90203, name: 'Oridecon' }],
        armor: [{ id: 90204, name: 'Rough Elunium', npcPrice: 200 }, { id: 90205, name: 'Elunium' }, { id: 90206, name: 'Enriched Elunium' }]
    };
    const GEAR_ORE_PER_TRIP = 5;   // at most 5 ores bought per round
    const gearOreFor = (slot, to) => GEAR_ORES[slot === 'main-hand' ? 'weapon' : 'armor'][to <= 4 ? 0 : to <= 7 ? 1 : 2];
    const gearOreById = id => [...GEAR_ORES.weapon, ...GEAR_ORES.armor].find(o => o.id === Number(id)) || null;
    const gearOreCount = id => planBag().filter(it => Number(it.itemId) === Number(id)).reduce((a, it) => a + (Number(it.qty) || 1), 0);
    const gearOreMarketTried = {};

    // Ores from the market: cheapest per ore first, again and again until `maxQty` (≤ 5) ores were bought this
    // round. Never above the Blacksmith's price (+1-4 ores), never more than twice the first (cheapest) price,
    // never a listing that would go past maxQty, never more than the budget. Looks at up to 5 result pages
    // ("Elunium" also finds the cheap Rough Elunium). Returns how many arrived.
    async function gearBuyOreMarket(room, ore, budget, maxQty = GEAR_ORE_PER_TRIP) {
        if (!room || !ore || window.__planMarketBuyInFlight) return 0;
        gearOreMarketTried[ore.id] = Date.now();
        const cap = Math.max(1, Math.min(GEAR_ORE_PER_TRIP, maxQty));
        // Paid earlier but it never reached the bag (bag full / overweight / refresh): collect, never pay again
        const paidKey = gearKey('ore_paid_' + ore.id);
        if (gearOreCount(ore.id) > 0) { try { localStorage.removeItem(paidKey); } catch (e) {} }
        else if (Date.now() - (Number(gearGet(paidKey, 0)) || 0) < 30 * 60000) {
            room.send('market', { op: 'collect_all' });
            gearWait(`ซื้อ ${ore.name} ไปแล้วแต่ยังไม่เข้ากระเป๋า — รับของจากตลาดก่อน ไม่ซื้อซ้ำภายใน 30 นาที`);
            return 0;
        }
        window.__planMarketBuyInFlight = true;
        let bought = 0, spent = 0, firstUnit = 0;
        try {
            // whatever was bought earlier lands first, so it is never counted as this round's purchase
            const startCount = gearOreCount(ore.id);
            room.send('market', { op: 'collect_all' });
            await planSleep(1500);
            if (gearOreCount(ore.id) > startCount) { gearLog(`📦 รับ ${ore.name} ที่ซื้อไว้ก่อนหน้าจากตลาดแล้ว`, '#22c55e'); return gearOreCount(ore.id) - startCount; }
            const nameLc = ore.name.toLowerCase();
            for (let round = 0; round < cap && bought < cap; round++) {
                const left = cap - bought;
                const zenyNow = Number(gearChar().zeny) || 0;
                const canPay = Math.min(zenyNow, budget - spent);
                let best = null;
                for (let page = 0; page < 5 && !best; page++) {
                    const now = Date.now();
                    const listings = await planMarketSearch(room, ore.name, null, page);
                    best = listings
                        .filter(l => l && !l.mine && l.item && (Number(l.item.itemId) === ore.id || gearName(l.item) === nameLc))
                        .filter(l => !(l.auctionEndsAt && l.auctionEndsAt > now))
                        .map(l => ({ l, qty: Math.max(1, Number(l.qty) || 1), price: Number(l.price) || 0 }))
                        .filter(c => c.price > 0 && c.qty <= left && c.price <= canPay)
                        .filter(c => !ore.npcPrice || c.price / c.qty <= ore.npcPrice)
                        .filter(c => !firstUnit || c.price / c.qty <= firstUnit * 2)
                        .sort((x, y) => x.price / x.qty - y.price / y.qty)[0] || null;
                    // last page, or every listing on it already costs more than we can pay (sorted cheapest first)
                    if (listings.length < 20 || listings.every(l => Number(l.price) > canPay)) break;
                }
                if (!best) break;
                if (!firstUnit) firstUnit = best.price / best.qty;
                const before = gearOreCount(ore.id);
                const zenyBefore = Number(gearChar().zeny) || 0;
                gearLog(`🛒 ซื้อ ${ore.name} x${best.qty} ราคา ${best.price.toLocaleString()} z (${Math.round(best.price / best.qty).toLocaleString()} z/ก้อน) จากตลาด — ${best.l.sellerName || '?'}`, '#10b981');
                gearSet(paidKey, Date.now());   // counts as paid if the page reloads before we know
                room.send('market', { op: 'buy', listingId: Number(best.l.listingId), price: best.price });
                await planSleep(1200);
                room.send('market', { op: 'collect_all' });   // purchases wait in the market "รับของ" tab
                let got = 0;
                for (let i = 0; i < 24 && got <= 0; i++) { await planSleep(250); got = gearOreCount(ore.id) - before; }
                if (got <= 0) {
                    // paid (zeny went down) but not delivered: remember it; not paid (someone bought it first): just stop
                    if ((Number(gearChar().zeny) || 0) < zenyBefore) {
                        gearLog(`⚠️ ซื้อ ${ore.name} แล้วแต่ยังไม่เข้ากระเป๋า — หยุดซื้อรอบนี้ (กระเป๋าเต็ม/น้ำหนักเกิน?)`, '#ef4444');
                    } else {
                        try { localStorage.removeItem(paidKey); } catch (e) {}
                        gearLog(`ℹ️ ซื้อ ${ore.name} รายการนี้ไม่สำเร็จ (มีคนซื้อตัดหน้า?) — ลองใหม่รอบหน้า`, '#94a3b8');
                    }
                    break;
                }
                try { localStorage.removeItem(paidKey); } catch (e) {}
                bought += got;
                spent += best.price;
                await planSleep(600);
            }
        } catch (e) {
            console.warn('[PmheeAether Gear] ore market error:', e);
        } finally {
            window.__planMarketBuyInFlight = false;
        }
        if (bought) gearLog(`💎 ได้ ${ore.name} จากตลาด ${bought} ก้อน (${spent.toLocaleString()} z) — มีทั้งหมด ${gearOreCount(ore.id)} ก้อน`, '#22c55e');
        return bought;
    }

    // At the Blacksmith without the ore the refine window asks for: market first, then Enok's shop (+1-4 ores)
    async function gearBuyOre(room, key, mat, budget) {
        const ore = gearOreById(mat.itemId) || { id: Number(mat.itemId), name: mat.name };
        if (Date.now() - (gearOreMarketTried[ore.id] || 0) > 2 * 60000) {
            const got = await gearBuyOreMarket(room, ore, budget);
            if (got > 0) return 'bought';
        }
        const r = await gearSmithOption(room, key, o => /ซื้อ/.test(o));
        if (!r.error) {
            let shop = null;
            for (let i = 0; i < 30 && !shop; i++) { await planSleep(200); shop = document.querySelector('.shop-window'); }
            const row = shop && Array.from(shop.querySelectorAll('.shop-row')).find(rw => {
                const fk = Object.keys(rw).find(k => k.startsWith('__reactFiber'));
                return fk && rw[fk] && String(rw[fk].key) === String(ore.id);
            });
            if (row) {
                const price = parseInt(((row.querySelector('.shop-price') || {}).innerText || '').replace(/[^0-9]/g, ''), 10) || 0;
                const zeny = Number(gearChar().zeny) || 0;
                const qty = price ? Math.min(GEAR_ORE_PER_TRIP - Math.min(GEAR_ORE_PER_TRIP, gearOreCount(ore.id)), Math.floor(Math.min(zeny, budget) / price)) : 1;
                if (qty < 1) { gearCloseNpc(); return 'no-money'; }
                const before = gearOreCount(ore.id);
                gearLog(`🛒 ซื้อ ${ore.name} x${qty} (${(price * qty).toLocaleString()} z) จาก Blacksmith`, '#10b981');
                room.send('shop_buy_many', { lines: [{ itemId: ore.id, qty }] });
                let got = false;
                for (let i = 0; i < 16 && !got; i++) { await planSleep(250); got = gearOreCount(ore.id) > before; }
                gearCloseNpc();
                if (!got) gearSmithBackoffUntil = Date.now() + 2 * 60000;   // never buy again right away
                return 'bought';
            }
            gearCloseNpc();
        }
        return 'none';
    }

    async function gearRefineStep(step, worn, zeny, steps) {
        window.__isGearRefining = true;   // the shop trip / page reloads wait while the gear set is at work
        try { return await gearRefineStepInner(step, worn, zeny, steps); } finally { window.__isGearRefining = false; }
    }
    async function gearRefineStepInner(step, worn, zeny, steps) {
        const room = getPlanRoom();
        if (!room) return true;
        // Every way out that is not "refined just now" waits a while AND goes back to farming
        const giveUp = (mins, msg) => {
            gearSmithBackoffUntil = Date.now() + mins * 60000;
            if (msg) gearLog(msg, '#ef4444');
            gearCloseNpc();
            gearBackToFarm();
            return false;
        };
        if (Date.now() < gearSmithBackoffUntil) { gearBackToFarm(); return false; }
        // Ore for the next level first, from the market (works anywhere: no town trip just to buy it). The ore and
        // fee the refine window showed for this slot + level are remembered and win over the built-in table.
        const cur = Number(worn.refine) || 0;
        const seen = gearGet(gearKey('refine_seen'), {})[`${step.slot}:${cur + 1}`] || null;
        const ore = (seen && seen.ore && (gearOreById(seen.ore) || (seen.oreName ? { id: Number(seen.ore), name: seen.oreName } : null))) || gearOreFor(step.slot, cur + 1);
        const fee = (seen && Number(seen.fee)) || 0;
        if (fee && zeny < fee) {
            gearWait(`เงินยังไม่พอค่าตีบวก ${step.itemName} +${cur + 1} (${fee.toLocaleString()} z) — ฟาร์มต่อก่อน`);
            return giveUp(5);
        }
        if (gearOreCount(ore.id) < 1 && Date.now() - (gearOreMarketTried[ore.id] || 0) > 2 * 60000) {
            // as many ores as the levels left in this ore's range (x2 for failures), at most 5
            const target = Math.max(...steps.filter(x => x && x.kind === 'refine' && x.slot === step.slot && gearName({ name: x.itemName }) === gearName({ name: step.itemName })).map(x => Number(x.toLevel) || 0), Number(step.toLevel) || 0);
            const tierEnd = cur + 1 <= 4 ? 4 : cur + 1 <= 7 ? 7 : 10;
            const maxQty = Math.min(GEAR_ORE_PER_TRIP, Math.max(1, 2 * (Math.min(target, tierEnd) - cur)));
            const reserve = Math.max(5000, Math.round(zeny * 0.1), fee);   // keep zeny for the refine fee
            const got = await gearBuyOreMarket(room, ore, Math.max(0, zeny - reserve), maxQty);
            if (got > 0) return true;
            if (!ore.npcPrice) {
                gearWait(`ยังไม่มี ${ore.name} ขายในตลาดในราคาที่จ่ายได้ — ลองใหม่ใน 5 นาที`);
                return giveUp(5);
            }
            // +1-4 ores: Blacksmith Enok sells them for 200 z (bought there when the refine window asks)
        }
        const npcs = room.state && room.state.npcs;
        const npcCount = npcs && typeof npcs.size === 'number' ? npcs.size : 0;
        const key = gearSmithKey(room);
        if (!key) {
            if (!inCapital()) { gearGoTown(`ตีบวก ${step.itemName} → +${step.toLevel}`); return true; }
            if (!npcCount) return true;   // capital NPCs not loaded yet
            return giveUp(10, '⚠️ ไม่พบ NPC Blacksmith ในเมืองหลวง -> กลับไปฟาร์มก่อน ลองใหม่ใน 10 นาที');
        }
        window.__planJobChangeHoldUntil = Date.now() + 60000; if (typeof window.needTown === 'function') window.needTown('gear');
        try { localStorage.setItem(GEAR_TRIP_KEY, localStorage.getItem(GEAR_TRIP_KEY) || String(Date.now())); } catch (e) {}   // goes back to the farm when done
        try {
            // 1. Open the refine window and find this item (the server sends the list with rates and costs)
            const r = await gearSmithOption(room, key, o => /ตีบวก/.test(o) && !/ซื้อ|วิธี|เสริมพลัง|สุ่ม/.test(o), 'refine');
            if (r.error || !r.msg || !Array.isArray(r.msg.items)) return giveUp(5, `⚠️ เปิดหน้าต่างตีบวกไม่สำเร็จ: ${r.error || 'ไม่มีข้อมูลจากเซิร์ฟเวอร์'} — ลองใหม่ใน 5 นาที`);
            const win = r.msg;
            const want = gearName({ name: step.itemName });
            const f = win.items.find(x => x && x.source && x.source.kind === 'equip' && String(x.source.slot) === String(step.slot) && gearName(x.item) === want)
                || win.items.find(x => x && x.source && x.source.kind === 'equip' && gearName(x.item) === want);
            if (!f) { gearSkip(step, 'ไม่พบไอเทมที่สวมอยู่ในรายการตีบวก (ตีบวกไม่ได้?)', 60); return giveUp(0); }
            if (f.maxed) { gearSkip(step, 'ตีบวกสูงสุดแล้ว'); return giveUp(0); }
            {   // remember the real ore + fee of this slot + level for the next rounds (market pre-buy, zeny check)
                const all = gearGet(gearKey('refine_seen'), {});
                all[`${step.slot}:${f.to}`] = { ore: f.material && f.material.itemId, oreName: f.material && f.material.name, fee: Number(f.zeny) || 0 };
                gearSet(gearKey('refine_seen'), all);
            }
            // 2. Ore
            if (!f.material || f.material.have < 1) {
                gearCloseNpc();
                await planSleep(500);
                const budget = Math.max(0, zeny - (Number(f.zeny) || 0));
                const b = await gearBuyOre(room, key, f.material || {}, budget);
                if (b === 'bought') return true;
                gearWait(`ยังหาซื้อ ${(f.material || {}).name || 'แร่'} ไม่ได้ (${b === 'no-money' ? 'เงินไม่พอ' : 'ไม่มีขายในตลาด/ร้านในราคาที่จ่ายได้'}) — ลองใหม่ใน 5 นาที`);
                return giveUp(5);
            }
            if ((Number(win.zeny) || 0) < (Number(f.zeny) || 0)) {
                gearWait(`เงินไม่พอค่าตีบวก ${step.itemName} (${Number(f.zeny).toLocaleString()} z) — ลองใหม่ใน 5 นาที`);
                return giveUp(5);
            }
            // 3. A level that can break the item: only with a Blessing when the step asks for one
            const blessHave = (win.blessing && win.blessing.have) || 0;
            const bless = step.blessing !== false && f.onFail !== 'no-change' && blessHave > 0;
            const canBreak = f.onFail === 'destroy' || !!f.destroyChance;
            if (canBreak && !bless && step.blessing !== false) {
                gearWait(`ตีบวก ${step.itemName} +${f.to} อาจทำให้แตก — รอให้มี Blacksmith Blessing ก่อน (เอาติ๊ก Blessing ออกถ้าจะเสี่ยงตีเลย)`);
                return giveUp(10);
            }
            // 4. Refine once
            const before = Number(worn.refine) || 0;
            gearLog(`🔨 ตีบวก ${step.itemName} +${before} → +${f.to} (สำเร็จ ${f.success}%${f.onFail && f.onFail !== 'no-change' ? ', พลาด = ' + f.onFail : ''}${bless ? ', ใช้ Blessing' : ''}) ค่าตีบวก ${Number(f.zeny).toLocaleString()} z`, '#a855f7');
            const res = await new Promise(resolve => {
                let unsub;
                const timer = setTimeout(() => { if (typeof unsub === 'function') unsub(); resolve(null); }, 8000);
                unsub = room.onMessage('refine_result', msg => { clearTimeout(timer); if (typeof unsub === 'function') unsub(); resolve(msg); });
                room.send('refine', { source: f.source, blessing: bless });
            });
            await planSleep(800);
            const nowWorn = gearWorn(step, gearChar().equipment || {}, steps);
            const after = nowWorn ? (Number(nowWorn.refine) || 0) : null;
            if (after === null) {
                const brk = gearGet(gearKey('breaks'), {});
                brk[step.id] = (brk[step.id] || 0) + 1;
                gearSet(gearKey('breaks'), brk);
                gearLog(`💥 ${step.itemName} หายไปจากตัว (แตก?) ครั้งที่ ${brk[step.id]} — รายการซื้อของชิ้นนี้จะทำงานอีกครั้ง`, '#ef4444');
                if (brk[step.id] >= 2) gearSkip(step, 'ของแตกไปแล้ว 2 ครั้ง');
            } else if (after > before) gearLog(`✨ ตีบวกสำเร็จ! ${step.itemName} +${after}`, '#22c55e');
            else gearLog(`❌ ตีบวกไม่สำเร็จ (${step.itemName} +${after})${res ? '' : ' — ไม่ได้รับผลจากเซิร์ฟเวอร์'}`, '#f97316');
            gearCloseNpc();
            gearNextTry = Date.now() + 2500;
            return true;
        } finally {
            window.__isGearRefining = false;
        }
    }

    // Items the gear set still needs: ores (capped at GEAR_ORE_MAX_KEEP = 100 per needed ore) + Blessing of refine
    // steps not done, cards of card steps not done, and at most 1 best copy per uncompleted equip step.
    const GEAR_ORE_MAX_KEEP = 100;
    window.GEAR_ORE_MAX_KEEP = GEAR_ORE_MAX_KEEP;
    const ALL_GEAR_ORES = [...GEAR_ORES.weapon, ...GEAR_ORES.armor];
    const gearOreByName = n => {
        const lc = String(n || '').replace(/^\+\s*\d+\s*/, '').replace(/\s*\[\s*\d+\s*\]\s*$/, '').trim().toLowerCase();
        return ALL_GEAR_ORES.find(o => o.name.toLowerCase() === lc) || null;
    };
    function gearNeededOreIds() {
        if (!window.__planScriptEnabled) return [];
        const plan = window.__currentScriptPlan || {};
        const steps = (plan.gearPlan && Array.isArray(plan.gearPlan.steps)) ? plan.gearPlan.steps : [];
        if (!steps.length) return [];
        const eq = gearChar().equipment || {};
        const sk = gearSkipped();
        const ores = new Set();
        steps.forEach((x, i) => {
            if (!x || x.kind !== 'refine' || gearIsSkipped(sk, x) || gearStepDone(x, eq, steps)) return;
            const superseded = steps.slice(i + 1).some(s => s && s.kind === 'equip' && s.slot === x.slot && gearName({ name: s.itemName }) !== gearName({ name: x.itemName }) && gearWorn(s, eq, steps));
            if (superseded) return;
            const w = gearWorn(x, eq, steps);
            for (let to = (w ? Number(w.refine) || 0 : 0) + 1; to <= (Number(x.toLevel) || 0); to++) {
                ores.add(gearOreFor(x.slot, to).id);
            }
        });
        return [...ores];
    }
    function gearKeepIds() {
        if (!window.__planScriptEnabled) return [];
        const plan = window.__currentScriptPlan || {};
        const steps = (plan.gearPlan && Array.isArray(plan.gearPlan.steps)) ? plan.gearPlan.steps : [];
        if (!steps.length) return [];
        const eq = gearChar().equipment || {};
        const sk = gearSkipped();
        const keep = new Set();
        steps.forEach((x, i) => {
            if (!x || x.kind !== 'refine' || gearIsSkipped(sk, x) || gearStepDone(x, eq, steps)) return;
            const superseded = steps.slice(i + 1).some(s => s && s.kind === 'equip' && s.slot === x.slot && gearName({ name: s.itemName }) !== gearName({ name: x.itemName }) && gearWorn(s, eq, steps));
            if (superseded) return;
            if (x.blessing !== false) keep.add(90208);   // Blacksmith Blessing
        });
        steps.forEach(x => { if (x && x.kind === 'card' && x.cardId && !gearIsSkipped(sk, x) && !gearStepDone(x, eq, steps)) keep.add(Number(x.cardId)); });
        return [...keep];
    }
    function gearKeptEquipSlots(steps, eq, sk, bag) {
        const kept = new Set();
        if (!Array.isArray(bag) || !bag.length) return kept;
        steps.forEach((st, i) => {
            if (!st || st.kind !== 'equip' || gearIsSkipped(sk, st) || gearStepDone(st, eq, steps)) return;
            const name = gearName({ name: st.itemName });
            const superseded = steps.slice(i + 1).some(x => x && x.kind === 'equip' && x.slot === st.slot && gearName({ name: x.itemName }) !== name && gearWorn(x, eq, steps));
            if (superseded) return;
            const terms = parsePlanOptionFilter(st.options);
            const candidates = bag
                .map(b => b && (b.raw || b))
                .filter(it => it && gearName(it) === name && itemPassesPlanOptions(it, terms))
                .sort((a, b) => ((Number(b.refine) || 0) - (Number(a.refine) || 0))
                    || (((Array.isArray(b.affixes) ? b.affixes.length : 0) - (Array.isArray(a.affixes) ? a.affixes.length : 0)))
                    || ((Number(b.slots) || 0) - (Number(a.slots) || 0))
                    || ((Number(a.slot) || 0) - (Number(b.slot) || 0)));
            const pick = candidates.find(it => it.slot !== undefined && it.slot !== null && it.slot !== '-' && !kept.has(Number(it.slot)));
            if (pick) kept.add(Number(pick.slot));
        });
        return kept;
    }
    let gearKeepMemo = { at: 0, plan: null, enabled: false, ids: [], oreIds: [], eq: null, sk: null, keptEquipSlots: new Set(), hasBag: false, bag: [] };
    function refreshGearKeepMemo() {
        const plan = window.__currentScriptPlan || {};
        const enabled = !!window.__planScriptEnabled;
        if (Date.now() - gearKeepMemo.at > 1000 || gearKeepMemo.plan !== plan || gearKeepMemo.enabled !== enabled) {
            const steps = (enabled && plan.gearPlan && Array.isArray(plan.gearPlan.steps)) ? plan.gearPlan.steps : [];
            const eq = gearChar().equipment || {};
            const sk = gearSkipped();
            const rawBag = planBag();
            const bag = rawBag.length ? rawBag : ((typeof window.getBagItems === 'function') ? window.getBagItems().map(x => x && (x.raw || x)).filter(Boolean) : []);
            gearKeepMemo = {
                at: Date.now(),
                plan,
                enabled,
                ids: gearKeepIds(),
                oreIds: gearNeededOreIds(),
                eq,
                sk,
                keptEquipSlots: gearKeptEquipSlots(steps, eq, sk, bag),
                hasBag: bag.length > 0,
                bag
            };
        }
        return gearKeepMemo;
    }
    window.getGearOreReserveQty = function (itemOrNameOrId) {
        try {
            if (!window.__planScriptEnabled || itemOrNameOrId === null || itemOrNameOrId === undefined) return 0;
            const memo = refreshGearKeepMemo();
            if (!memo.oreIds.length) return 0;
            if (typeof itemOrNameOrId === 'number' || (typeof itemOrNameOrId === 'string' && /^\d+$/.test(itemOrNameOrId.trim()))) {
                return memo.oreIds.includes(Number(itemOrNameOrId)) ? GEAR_ORE_MAX_KEEP : 0;
            }
            if (typeof itemOrNameOrId === 'string') {
                const ore = gearOreByName(itemOrNameOrId);
                return (ore && memo.oreIds.includes(ore.id)) ? GEAR_ORE_MAX_KEEP : 0;
            }
            const raw = itemOrNameOrId.raw || itemOrNameOrId;
            const id = Number(raw.itemId ?? raw.id ?? itemOrNameOrId.itemId ?? itemOrNameOrId.id);
            if (Number.isFinite(id) && id > 0 && memo.oreIds.includes(id)) return GEAR_ORE_MAX_KEEP;
            const ore = gearOreByName(raw.name || itemOrNameOrId.name || '');
            return (ore && memo.oreIds.includes(ore.id)) ? GEAR_ORE_MAX_KEEP : 0;
        } catch (e) { return 0; }
    };
    window.isGearKeptItem = function (raw) {
        try {
            if (!window.__planScriptEnabled) return false;
            const plan = window.__currentScriptPlan || {};
            const steps = (plan.gearPlan && Array.isArray(plan.gearPlan.steps)) ? plan.gearPlan.steps : [];
            if (!raw || !steps.length) return false;
            const item = raw.raw || raw;
            const memo = refreshGearKeepMemo();
            const itemId = Number(item.itemId ?? item.id ?? raw.itemId ?? raw.id);
            if (memo.ids.includes(itemId)) return true;
            const oreObj = (Number.isFinite(itemId) && itemId > 0 && gearOreById(itemId)) || gearOreByName(item.name || raw.name || '');
            if (oreObj && memo.oreIds.includes(oreObj.id)) {
                const slot = item.slot ?? raw.slot;
                if (slot !== undefined && slot !== null && slot !== '-' && typeof window.getGuildDonationSlotSellableQty === 'function') {
                    const info = window.getGuildDonationSlotSellableQty(slot, memo.bag, item);
                    return info.sellableQty <= 0;
                }
                const qty = Math.max(1, Number(item.qty ?? raw.qty) || 1);
                const bagTotal = Array.isArray(memo.bag) && memo.bag.length
                    ? memo.bag.filter(b => b && (Number(b.itemId ?? b.id) === oreObj.id || gearName(b) === oreObj.name.toLowerCase()))
                        .reduce((s, b) => s + Math.max(1, Number(b.qty) || 1), 0)
                    : qty;
                return Math.max(qty, bagTotal) <= GEAR_ORE_MAX_KEEP;
            }
            const eq = memo.eq;
            const sk = memo.sk;
            const name = gearName(item);
            const matchesStep = steps.some((st, i) => st && st.kind === 'equip' && !gearIsSkipped(sk, st) && gearName({ name: st.itemName }) === name
                && !gearStepDone(st, eq, steps)
                && !steps.slice(i + 1).some(x => x && x.kind === 'equip' && x.slot === st.slot && gearName({ name: x.itemName }) !== name && gearWorn(x, eq, steps))
                && itemPassesPlanOptions(item, parsePlanOptionFilter(st.options)));
            if (!matchesStep) return false;
            const slot = item.slot ?? raw.slot;
            if (slot !== undefined && slot !== null && slot !== '-' && memo.hasBag && memo.keptEquipSlots.size > 0) {
                return memo.keptEquipSlots.has(Number(slot));
            }
            return true;
        } catch (e) { return false; }
    };

    // 🃏 Insert a card into the worn item (card from the bag, else bought on the market for up to the step's amount).
    // The game never lets the player take a card out again — the step is only run when the item has a free slot.
    const gearCardFails = {};
    async function gearCardStep(step, worn, zeny, need, steps) {
        const room = getPlanRoom();
        if (!room) return false;
        const used = (Array.isArray(worn.cards) ? worn.cards : []).filter(Boolean).length;
        if ((Number(worn.slots) || 0) - used <= 0) { gearSkip(step, `${step.itemName} ไม่มีช่องการ์ดว่างแล้ว`); return false; }
        const want = String(step.cardName || '').trim().toLowerCase();
        const isCard = it => it && (Number(it.itemId) === Number(step.cardId) || gearName(it) === want);
        room.send('market', { op: 'collect_all' });
        await planSleep(1200);
        const card = planBag().find(isCard);
        if (card) {
            const before = gearCardCount(worn, step);
            gearLog(`🃏 ใส่ "${card.name}" ใน ${step.itemName} (ใส่แล้วถอดเองไม่ได้)`, '#38bdf8');
            room.send('card_insert', { card: Number(card.slot), target: { kind: 'equip', slot: step.slot } });
            for (let i = 0; i < 12; i++) {
                await planSleep(250);
                const w2 = gearWorn(step, gearChar().equipment || {}, steps);
                if (w2 && gearCardCount(w2, step) > before) {
                    gearLog(`✅ ใส่การ์ด "${card.name}" ใน ${step.itemName} แล้ว`, '#22c55e');
                    delete gearCardFails[step.id];
                    gearNextTry = Date.now() + 3000;
                    return true;
                }
            }
            const n = gearCardFails[step.id] = (gearCardFails[step.id] || 0) + 1;
            if (n >= 3) { delete gearCardFails[step.id]; gearSkip(step, 'เกมไม่ยอมให้ใส่การ์ดนี้ 3 ครั้ง (ชนิดอุปกรณ์ไม่ตรง?)', 60); }
            gearNextTry = Date.now() + 30000;
            return false;
        }
        // not in the bag: the cheapest one on the market, never paying twice (same markers as equip steps)
        const boughtKey = gearKey('bought_' + step.id);
        const pendingAt = Number(gearGet(boughtKey + '_pending', 0)) || 0;
        if (pendingAt && Date.now() - pendingAt < 5 * 60000) gearSet(boughtKey, pendingAt);
        if (pendingAt) { try { localStorage.removeItem(boughtKey + '_pending'); } catch (e) {} }
        if (Date.now() - (Number(gearGet(boughtKey, 0)) || 0) < 30 * 60000) {
            gearWait(`ซื้อการ์ด ${step.cardName} ไปแล้ว รอรับของจากตลาด (ไม่ซื้อซ้ำภายใน 30 นาที)`);
            gearNextTry = Date.now() + 60000;
            return false;
        }
        if (window.__planMarketBuyInFlight) return false;
        const budget = Math.min(need || zeny, zeny);
        window.__planMarketBuyInFlight = true;
        try {
            const now = Date.now();
            const best = (await planMarketSearch(room, step.cardName))
                .filter(l => l && !l.mine && l.item && isCard(l.item) && Number(l.qty || 1) === 1 && !(l.auctionEndsAt && l.auctionEndsAt > now))
                .filter(l => Number(l.price) > 0 && Number(l.price) <= budget)
                .sort((a, b) => Number(a.price) - Number(b.price))[0];
            if (!best) {
                gearWait(`ยังไม่มี ${step.cardName} ขายในตลาดราคาไม่เกิน ${budget.toLocaleString()} z — ลองใหม่ภายหลัง`);
                gearNextTry = Date.now() + 5 * 60000;
                return false;
            }
            gearLog(`🛒 ซื้อการ์ด "${best.item.name}" ราคา ${Number(best.price).toLocaleString()} z จากตลาด (${best.sellerName || '?'})`, '#10b981');
            const zeny0 = Number(gearChar().zeny) || 0;
            gearSet(boughtKey + '_pending', Date.now());
            room.send('market', { op: 'buy', listingId: Number(best.listingId), price: Number(best.price) });
            await planSleep(1200);
            room.send('market', { op: 'collect_all' });
            await planSleep(2000);
            try { localStorage.removeItem(boughtKey + '_pending'); } catch (e) {}
            if ((Number(gearChar().zeny) || 0) < zeny0) gearSet(boughtKey, Date.now());
            gearNextTry = Date.now() + 5000;
            return true;
        } catch (e) {
            console.warn('[PmheeAether Gear] card buy error:', e);
            gearNextTry = Date.now() + 60000;
            return false;
        } finally {
            window.__planMarketBuyInFlight = false;
        }
    }

    // true = working on the gear set this round (other plan work waits), false = nothing to do / waiting
    window.runGearPlanStep = async function () {
        const plan = window.__currentScriptPlan;
        const gp = plan && plan.gearPlan;
        if (!gp || !Array.isArray(gp.steps) || !gp.steps.length) { gearBackToFarm(); return false; }
        if (gearBusy || Date.now() < gearNextTry) return false;
        const lv = readPlanLevels();
        if (!lv || !lv.cls) return false;
        const lineage = planClassLineage(lv.cls);
        const start = String(gp.startClass || 'novice').toLowerCase();
        if (!lineage.includes(start)) { gearWait(`เซ็ตอุปกรณ์เริ่มเมื่อเป็น ${start} (ตอนนี้ ${lv.cls})`); gearBackToFarm(); return false; }
        const { index, step, total, steps } = window.getGearPlanStatus();
        if (!step) {
            gearBackToFarm();
            // "เมื่อเซ็ตครบ -> เปลี่ยนแมพฟาร์ม": once per character + plan + map (a later manual / plan map change is
            // never undone). Not while a step is only skipped for a while (it is not really done).
            const map = String(gp.onCompleteMap || '').trim();
            const sk = gearSkipped();
            const waiting = steps.some(x => x && sk[x.id] && sk[x.id].until && sk[x.id].until > Date.now());
            const doneKey = gearKey('complete_map_' + map);
            let fired = null;
            try { fired = localStorage.getItem(doneKey); } catch (e) {}
            if (map && steps.length && !waiting && !fired) {
                try { localStorage.setItem(doneKey, String(Date.now())); localStorage.setItem(planLastMapKey(), map); } catch (e) {}
                gearLog(`🎉 เซ็ตอุปกรณ์ครบทุกรายการแล้ว -> เปลี่ยนแมพฟาร์มเป็น "${map}" (ครั้งเดียว)`, '#22c55e');
                window.setTargetFarmMap(map, true);
                return true;
            }
            return false;
        }
        const ch = gearChar();
        const zeny = Number(ch.zeny) || 0;
        const need = Number(step.zeny) || 0;
        const label = `รายการ ${index + 1}/${total}: ${step.kind === 'refine' ? `ตีบวก ${step.itemName} +${step.toLevel}` : step.kind === 'card' ? `ใส่การ์ด ${step.cardName} ใน ${step.itemName}` : `สวม ${step.itemName}${step.options ? ' [' + step.options + ']' : ''}`}`;
        if (zeny < need) { gearWait(`${label} — รอเงินถึง ${need.toLocaleString()} z (มี ${zeny.toLocaleString()} z)`); gearBackToFarm(); return false; }
        const needLv = Math.min(99, Number(step.minLevel) || 0);
        if (needLv && lv.base < needLv) { gearWait(`${label} — รอ Base Lv. ถึง ${needLv} (ตอนนี้ ${lv.base})`); gearBackToFarm(); return false; }
        gearBusy = true;
        try {
            if (step.kind === 'card') {
                const worn = gearWorn(step, ch.equipment || {}, steps);
                if (!worn) { gearWait(`${label} — ยังไม่ได้สวม ${step.itemName}`); gearBackToFarm(); return false; }
                gearBackToFarm();
                return await gearCardStep(step, worn, zeny, need, steps);
            }
            if (step.kind === 'refine') {
                const worn = gearWorn(step, ch.equipment || {}, steps);
                if (!worn) { gearWait(`${label} — ยังไม่ได้สวม ${step.itemName}`); gearBackToFarm(); return false; }
                return await gearRefineStep(step, worn, zeny, steps);
            }
            gearBackToFarm();
            // The class must be able to wear it (wiki "jobs" stored with the step; a later class of the line counts)
            const jobs = Array.isArray(step.jobs) ? step.jobs.map(gearJobId).filter(Boolean) : [];
            if (jobs.length && !lineage.some(c => jobs.includes(c))) {
                gearWait(`${label} — อาชีพตอนนี้ (${lv.cls}) ยังใส่ไม่ได้ (ต้องเป็น ${step.jobs.join('/')}) รอเปลี่ยนอาชีพก่อน`);
                return false;
            }
            const room = getPlanRoom();
            if (room) { room.send('market', { op: 'collect_all' }); await planSleep(1500); }   // bought earlier: lands first
            // equip: from the bag, else buy on the market for up to the step's amount
            const terms = parsePlanOptionFilter(step.options);
            const want = gearName({ name: step.itemName });
            const inBag = planBag().filter(it => gearName(it) === want && itemPassesPlanOptions(it, terms) && (!it.levelReq || it.levelReq <= lv.base))
                .sort((a, b) => (Number(b.refine) || 0) - (Number(a.refine) || 0))[0];
            if (inBag && room) {
                // Equipped again and again (something else takes it off: a plan equip action, a two-handed weapon
                // vs the off-hand step...): stop fighting for an hour
                const hist = (gearEquipHistory[step.id] || []).filter(t => Date.now() - t < 30 * 60000);
                if (gearWasWorn[step.id]) { hist.push(Date.now()); gearWasWorn[step.id] = false; }   // worn before, taken off since
                gearEquipHistory[step.id] = hist;
                if (hist.length > 4) {
                    gearEquipHistory[step.id] = [];
                    gearSkip(step, 'ใส่แล้วถูกถอดออกซ้ำๆ (มีระบบอื่นเปลี่ยนของในช่องนี้ / อาวุธสองมือ?)', 60);
                    return false;
                }
                const tries = gearEquipTries[step.id] = (gearEquipTries[step.id] || 0) + 1;
                if (tries > 6) {
                    gearEquipTries[step.id] = 0;
                    gearNextTry = Date.now() + 10 * 60000;
                    gearLog(`⚠️ ${label} — สวมไม่ติด 6 ครั้ง (อาชีพนี้ใส่ไม่ได้ / เลเวลไม่ถึง?) รอ 10 นาทีแล้วลองใหม่`, '#ef4444');
                    return false;
                }
                gearLog(`🎒 ${label} — สวมจากกระเป๋า (ช่อง ${inBag.slot})`, '#22c55e');
                if (/^gem-/.test(step.slot)) {
                    // gems: into the slot of the lower % of the same gem, else an empty gem slot
                    const to = gemTargetSlot(ch.equipment || {}, inBag);
                    if (!to) { gearSkip(step, 'ช่องเจมเต็มทั้ง 4 ช่อง (เจมชนิดอื่น)', 30); return false; }
                    room.send('equip', { slot: inBag.slot, to });
                    gearNextTry = Date.now() + 5000;
                    return true;
                }
                // accessories: ask for the planned side (every other try without it, in case the game ignores "to")
                room.send('equip', GEAR_ACC.includes(step.slot) && tries % 2 === 1 ? { slot: inBag.slot, to: step.slot } : { slot: inBag.slot });
                gearNextTry = Date.now() + 5000;
                return true;
            }
            // Paid for it already (not delivered yet: bag full / refresh between buy and collect)? Never pay twice.
            const boughtKey = gearKey('bought_' + step.id);
            // a buy that was under way when the page reloaded counts as paid until proven otherwise
            const pendingAt = Number(gearGet(boughtKey + '_pending', 0)) || 0;
            if (pendingAt && Date.now() - pendingAt < 5 * 60000) gearSet(boughtKey, pendingAt);
            if (pendingAt) { try { localStorage.removeItem(boughtKey + '_pending'); } catch (e) {} }
            if (Date.now() - (Number(gearGet(boughtKey, 0)) || 0) < 30 * 60000) {
                gearWait(`${label} — ซื้อไปแล้ว รอรับของจากตลาด (ไม่ซื้อซ้ำภายใน 30 นาที)`);
                gearNextTry = Date.now() + 60000;
                return false;
            }
            gearLog(`🛒 ${label} — เงินถึง ${need.toLocaleString()} z แล้ว หาซื้อในตลาด (ราคาไม่เกิน ${(need || zeny).toLocaleString()} z)`, '#38bdf8');
            gearSet(boughtKey + '_pending', Date.now());
            const r = await window.findAndEquipItemByName(step.itemName, true, need || zeny, step.options || '', step.slot || '');
            try { localStorage.removeItem(boughtKey + '_pending'); } catch (e) {}
            if ((Number(gearChar().zeny) || 0) < zeny) gearSet(boughtKey, Date.now());
            gearNextTry = Date.now() + (r === 'done' ? 5000 : 60000);
            return r === 'done';
        } catch (e) {
            console.warn('[PmheeAether Gear] error:', e);
            gearNextTry = Date.now() + 60000;
            return false;
        } finally {
            gearBusy = false;
        }
    };

    // The farm map the plan says to be on now: the change_map of the highest Base trigger at or below the
    // current Base Lv. (and Job triggers of the current class at or below the current Job Lv.)
    const planLastMapKey = () => {
        const plan = window.__currentScriptPlan || {};
        const name = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        return `pelican_plan_lastmap_${name}_${plan.id || plan.name || 'plan'}`;
    };
    function inferJobTriggerClassId(t, plan) {
        if (!t || t.type !== 'job_level') return '';
        if (t.classId) return String(t.classId).trim().toLowerCase();
        const cc = (t.actions || []).find(a => a && a.type === 'change_class' && a.targetClass);
        if (cc) {
            const entry = PLAN_CLASS_TREE[String(cc.targetClass).trim().toLowerCase()];
            if (entry && entry[1]) return entry[1];
        }
        const lvl = parseInt(t.targetLevel, 10) || 0;
        const mapAct = (t.actions || []).filter(a => a && a.type === 'change_map' && a.targetMap).pop();
        if (lvl <= 10 && mapAct && /ถนนต้นหลิว|ทุ่งหญ้าตะวันออก|ทุ่งโคลเวอร์|ไร่ซันเกรน|สวนนักผจญภัยมือใหม่/.test(mapAct.targetMap)) {
            return 'novice';
        }
        if (plan && plan.class1Target && lvl > 10) {
            return String(plan.class1Target).trim().toLowerCase();
        }
        return '';
    }
    const PLAN_MAP_MIN_LEVEL = {
        'ทุ่งโคลเวอร์': 1,
        'ทุ่งหญ้าตะวันออก': 1,
        'ไร่ซันเกรน': 1,
        'สวนนักผจญภัยมือใหม่': 2,
        'ถนนต้นหลิว': 8,
        'ทะเลสาบอาซูร์': 14,
        'ป่ามูนลีฟ': 15,
        'เส้นทางก็อบลิน': 16,
        'เหมืองคริสตัลเก่า': 20,
        'ค่ายออร์ค': 26,
        'ถ้ำเอมเบอร์': 27,
        'ที่ราบสูงเกล': 28,
        'แอ่งเวอร์แดนท์': 33,
        'ช่องเขาฟรอสต์พีค': 38,
        'ชายฝั่งปะการัง': 43,
        'ซากโบราณสถาน': 48,
        'สุสานเงา': 52,
        'หนองพิษ': 62,
        'โบสถ์อเวจี': 82,
        'บึงรากเน่า': 92,
        'เนินทรายแผดเผา': 102,
        'บัลลังก์ราชาลิช': 105,
        'พีระมิดจมทราย': 117,
        'สุสานฟาโรห์': 135,
        'แกนลาวา': 137
    };

    window.setPlanManualMap = function (map) {
        if (!map || /เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(map)) return;
        const cleanMap = String(map).replace(/\s*\(Lv\..*?\)/i, '').trim();
        if (!cleanMap) return;
        try {
            localStorage.setItem('pelican_plan_manual_map', cleanMap);
            if (window.__currentScriptPlan) {
                localStorage.setItem(planLastMapKey(), cleanMap);
                localStorage.setItem(planLastMapKey() + '_manual', cleanMap);
            }
        } catch (e) {}
    };
    window.isPlanLevelMapProgressionDone = function() {
        const plan = window.__currentScriptPlan;
        const lv = readPlanLevels();
        if (!plan || !Array.isArray(plan.triggers) || !lv) return true;
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        const stKey = `pelican_plan_state_${charName}_${plan.id || plan.name || 'plan'}`;
        let st = null;
        try { st = JSON.parse(localStorage.getItem(stKey) || 'null'); } catch (e) {}
        const done = (st && st.done) || {};
        const pending = (st && st.pending) || {};
        const order = ['novice', plan.class1Target, plan.class2Target].filter(Boolean).map(x => String(x).toLowerCase());
        const ci = order.indexOf(lv.cls);

        for (let idx = 0; idx < plan.triggers.length; idx++) {
            const t = plan.triggers[idx];
            if (!t || (t.type !== 'base_level' && t.type !== 'job_level')) continue;
            const acts = Array.isArray(t.actions) ? t.actions : [];
            const hasMapOrClass = acts.some(a => a && (a.type === 'change_map' || a.type === 'change_class'));
            if (!hasMapOrClass) continue;
            const id = planTriggerId(t, idx);
            if (done[id]) continue;
            if (pending[id]) {
                const left = Array.isArray(pending[id].actions) ? pending[id].actions.map(i => acts[i]).filter(Boolean) : acts;
                if (left.some(a => a && (a.type === 'change_map' || a.type === 'change_class'))) return false;
                continue;
            }
            const targetLv = parseInt(t.targetLevel, 10) || 0;
            if (t.type === 'base_level') {
                if (lv.base < targetLv) return false;
            } else if (t.type === 'job_level') {
                const trigCls = inferJobTriggerClassId(t, plan) || String(t.classId || '').trim().toLowerCase();
                if (trigCls) {
                    const ti = order.indexOf(trigCls);
                    if (ti >= 0 && ci >= 0) {
                        if (ci < ti) return false;
                        if (ci > ti) continue;
                    }
                }
                if (lv.job < targetLv) return false;
            }
        }
        return true;
    };

    window.planMapForNow = function() {
        const plan = window.__currentScriptPlan;
        const lv = readPlanLevels();
        if (!plan || !Array.isArray(plan.triggers) || !lv) return null;
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        const stKey = `pelican_plan_state_${charName}_${plan.id || plan.name || 'plan'}`;
        let st = null;
        try { st = JSON.parse(localStorage.getItem(stKey) || 'null'); } catch (e) {}
        const done = (st && st.done) || {};
        const pending = (st && st.pending) || {};
        const lineage = planClassLineage(lv.cls);

        let best = null;
        plan.triggers.forEach((t, idx) => {
            const acts = t.actions || [];
            let mapIdx = -1;
            for (let i = acts.length - 1; i >= 0; i--) {
                if (acts[i] && acts[i].type === 'change_map' && acts[i].targetMap) { mapIdx = i; break; }
            }
            if (mapIdx < 0) return;
            const map = String(acts[mapIdx].targetMap).replace(/\s*\(Lv\..*?\)/i, '').trim();
            if (!map) return;
            const id = planTriggerId(t, idx);
            // A change_map still held back behind an unfinished action in this trigger isn't reached yet
            if (pending[id] && Array.isArray(pending[id].actions) && pending[id].actions.includes(mapIdx)) return;

            const lvl = parseInt(t.targetLevel, 10) || 0;
            const trigCls = t.type === 'job_level' ? inferJobTriggerClassId(t, plan) : String(t.classId || '').trim().toLowerCase();
            let ok = false, tierRank = 0;
            if (t.type === 'job_level') {
                if (done[id]) ok = true;
                else if (!trigCls || trigCls === lv.cls) ok = lvl <= lv.job;
                else if (lineage.includes(trigCls)) ok = true;
                tierRank = (planClassTier(trigCls || lv.cls) * 200) + lvl;
            } else if (t.type === 'zeny') {
                ok = Boolean(done[id]);
                tierRank = 500;
            } else {
                ok = Boolean(done[id]) || lvl <= lv.base;
                tierRank = lvl * 5;
            }
            if (!ok) return;
            const mapLv = PLAN_MAP_MIN_LEVEL[map] || 0;
            const rank = mapLv * 10000 + tierRank * 10 + (idx % 10);
            if (!best || rank >= best.rank) best = { rank, map, mapLv, trigBaseLv: t.type === 'base_level' ? lvl : 0 };
        });

        const gp = plan.gearPlan;
        const gpMap = gp && String(gp.onCompleteMap || '').replace(/\s*\(Lv\..*?\)/i, '').trim();
        if (gpMap && Array.isArray(gp.steps) && gp.steps.length > 0 && lineage.includes(String(gp.startClass || 'novice').toLowerCase())) {
            let gpDone = false;
            try { gpDone = Boolean(localStorage.getItem(gearKey('complete_map_' + gpMap))); } catch (e) {}
            if (!gpDone && typeof window.getGearPlanStatus === 'function') {
                const gs = window.getGearPlanStatus();
                const sk = gearSkipped();
                const waiting = (gs.steps || []).some(x => x && sk[x.id] && sk[x.id].until && sk[x.id].until > Date.now());
                if (gs && !gs.step && (gs.steps || []).length > 0 && !waiting) gpDone = true;
            }
            if (gpDone) {
                const mapLv = PLAN_MAP_MIN_LEVEL[gpMap] || 0;
                const rank = mapLv * 10000 + 9999;
                if (!best || rank >= best.rank) best = { rank, map: gpMap, mapLv, trigBaseLv: 0 };
            }
        }

        // เมื่อผ่านเงื่อนไข Base Level / Job Level ของแผนครบหมดแล้ว (เหลือเฉพาะเซ็ตอุปกรณ์ / เงิน Zeny):
        // ปลดล็อคแมพฟาร์ม! ให้ตามปาร์ตี้หรือแมพที่เลือกไว้ได้โดยไม่ถูกแผนดึงกลับแมพสุดท้ายซ้ำ
        if (typeof window.isPlanLevelMapProgressionDone === 'function' && window.isPlanLevelMapProgressionDone()) {
            const forcedPartyMap = String(window.__partyForcedMap || '').replace(/\s*\(Lv\..*?\)/i, '').trim();
            if (forcedPartyMap && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(forcedPartyMap)) {
                return forcedPartyMap;
            }
            const finalSyncKey = planLastMapKey() + '_final_synced';
            let syncedMap = '', manualMap = '';
            try {
                syncedMap = localStorage.getItem(finalSyncKey) || '';
                manualMap = localStorage.getItem(planLastMapKey() + '_manual') || '';
            } catch (e) {}
            const curTarget = String(window.__targetFarmMap || '').replace(/\s*\(Lv\..*?\)/i, '').trim();
            const hasValidCurTarget = Boolean(curTarget && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(curTarget));
            if (best && best.map) {
                if ((best.trigBaseLv > 0 && lv.base > best.trigBaseLv) || syncedMap === best.map || manualMap) {
                    if (syncedMap !== best.map) {
                        try { localStorage.setItem(finalSyncKey, best.map); } catch (e) {}
                    }
                    if (hasValidCurTarget) return curTarget;
                    if (manualMap && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(manualMap)) return manualMap;
                } else {
                    try { localStorage.setItem(finalSyncKey, best.map); } catch (e) {}
                }
            } else if (hasValidCurTarget) {
                return curTarget;
            }
        }
        return best ? best.map : null;
    };

    async function runPlanAction(act) {
        if (act.type === 'change_map' && act.targetMap) {
            let targetMap = String(act.targetMap).replace(/\s*\(Lv\..*?\)/i, '').trim();
            const planMap = typeof window.planMapForNow === 'function' ? window.planMapForNow() : null;
            if (planMap && (PLAN_MAP_MIN_LEVEL[planMap] || 0) > (PLAN_MAP_MIN_LEVEL[targetMap] || 0)) {
                console.log(`%c[PmheeAether Plan] 🗺️ ข้ามการย้อนแมพ "${targetMap}" (แมพเป้าหมายตามเงื่อนไขปัจจุบันคือ "${planMap}")`, 'color: #38bdf8; font-weight: bold;');
                targetMap = planMap;
            }
            try {
                localStorage.setItem(planLastMapKey(), targetMap);
                localStorage.removeItem(planLastMapKey() + '_manual');
                localStorage.removeItem('pelican_plan_manual_map');
            } catch (e) {}
            console.log(`%c[PmheeAether Plan] 🗺️ เปลี่ยนแมพฟาร์มเป็น "${targetMap}"`, 'color: #38bdf8; font-weight: bold;');
            window.setTargetFarmMap(targetMap, true);
            return 'done';
        }
        if (act.type === 'equip_item' && act.itemName) {
            return await window.findAndEquipItemByName(act.itemName, act.buyFromMarket !== false, Number(act.maxPrice) || 0, act.optionFilter || '');
        }
        if (act.type === 'sell_trip') return runPlanSellTrip(act);
        if (act.type === 'weight_scroll') return await runWeightScrollAction(act);
        if (act.type === 'set_arrow') {
            // Arrow supply for this stage of the plan (e.g. turn it on once the character is an Archer)
            const cfg = window.__archerConfig || (window.__archerConfig = {});
            cfg.requireArrow = act.requireArrow !== false;
            if (Number(act.arrowType) > 0) cfg.arrowType = Number(act.arrowType);
            if (Number(act.arrowBuyQty) > 0) cfg.arrowBuyQty = Math.round(Number(act.arrowBuyQty));
            if (Number(act.ammoThreshold) > 0) cfg.ammoThreshold = Math.max(50, Math.round(Number(act.ammoThreshold)));
            try { localStorage.setItem('pelican_archer_cfg', JSON.stringify(cfg)); } catch (e) {}
            if (typeof window.syncAllHudInputsFromConfig === 'function') window.syncAllHudInputsFromConfig();
            console.log(`%c[PmheeAether Plan] 🏹 ตั้งค่าลูกธนู: ${cfg.requireArrow ? `เปิด (ซื้อให้ครบ ${cfg.arrowBuyQty} ดอก, ซื้อเมื่อเหลือ <= ${cfg.ammoThreshold})` : 'ปิด'}`, 'color: #38bdf8; font-weight: bold;');
            return cfg.requireArrow ? ensurePlanArrows(cfg) : 'done';
        }
        if (act.type === 'change_class' && act.targetClass) {
            const target = String(act.targetClass).trim().toLowerCase();
            const ch = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {};
            if (planClassLineage(ch.classId).includes(target)) return 'done';
            if (!planJobOptions(ch).includes(target)) return 'pending';   // not eligible yet: keep waiting
            return (await window.executeAutoJobChange(target)) ? 'done' : 'pending';
        }
        return 'failed';
    }

    window.checkAndExecutePlanTriggers = async function() {
        const plan = window.__currentScriptPlan;
        if (!plan || !Array.isArray(plan.triggers) || plan.triggers.length === 0 || planTriggersRunning) return;
        const lv = readPlanLevels();
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        if (!lv || !charName || charName === 'default_char') return;

        const key = `pelican_plan_state_${charName}_${plan.id || plan.name || 'plan'}`;
        let st = null;
        try { st = JSON.parse(localStorage.getItem(key) || 'null'); } catch (e) {}
        // First run of this plan for this character: triggers at the current level still fire once,
        // levels already passed don't (no retroactive buying or map hopping)
        if (!st) st = { lastBase: lv.base - 1, lastJob: lv.job - 1, lastJobClass: lv.cls, done: {}, pending: {}, known: {} };
        const firstSeen = !st.known;   // older state: every current trigger is already "known"
        if (!st.known) st.known = {};
        const save = () => { try { localStorage.setItem(key, JSON.stringify(st)); } catch (e) {} };

        // 1. Queue triggers whose level was crossed since the last check.
        // Job Lv. starts again at 1 with every class, so a job trigger can be tied to a class (t.classId):
        // "Job 10 novice" and "Job 10 archer" are different moments.
        const classChanged = lv.cls && st.lastJobClass && st.lastJobClass !== lv.cls;
        const lastJob = classChanged ? 0 : st.lastJob;
        const crossed = [];
        const zenyNow = Number(((typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {}).zeny) || 0;
        plan.triggers.forEach((t, i) => {
            const id = planTriggerId(t, i);
            if (t.type === 'zeny') {
                const need = Number(t.targetZeny) || 0;
                if (need > 0 && !st.done[id] && !st.pending[id] && zenyNow >= need) crossed.push({ id, t, lvl: need });
                return;
            }
            const lvl = parseInt(t.targetLevel, 10);
            if (!lvl || st.done[id] || st.pending[id]) return;
            const isJob = t.type === 'job_level';
            const trigCls = isJob ? inferJobTriggerClassId(t, plan) : '';
            if (isJob && trigCls && lv.cls && trigCls !== lv.cls) return;
            const cur = isJob ? lv.job : lv.base;
            // A trigger the player just added: its level counts if the character is on it right now
            const isNew = !firstSeen && !st.known[id];
            const last = isNew ? Math.min(cur - 1, isJob ? lastJob : st.lastBase) : (isJob ? lastJob : st.lastBase);
            if (last < lvl && lvl <= cur) crossed.push({ id, t, lvl });
        });
        plan.triggers.forEach((t, i) => { st.known[planTriggerId(t, i)] = 1; });
        st.lastBase = lv.base;
        st.lastJob = lv.job;
        if (lv.cls) st.lastJobClass = lv.cls;
        crossed.sort((a, b) => ((a.t.type === 'zeny') - (b.t.type === 'zeny')) || a.lvl - b.lvl);
        // When several triggers are crossed at once only the last map change matters
        const lastMapTrigger = [...crossed].reverse().find(c => (c.t.actions || []).some(a => a.type === 'change_map'));
        crossed.forEach(c => {
            const actions = (c.t.actions || []).map((a, i) => i).filter(i => c.t.actions[i].type !== 'change_map' || c === lastMapTrigger);
            const cCls = c.t.type === 'job_level' ? inferJobTriggerClassId(c.t, plan) : '';
            st.pending[c.id] = { actions, firstAt: Date.now(), nextAt: 0, level: c.lvl, type: c.t.type || 'base_level', cls: cCls };
            const what = c.t.type === 'zeny' ? `เงินถึง ${c.lvl.toLocaleString()} z` : `${c.t.type === 'job_level' ? `Job${cCls ? ' (' + cCls + ')' : ''}` : 'Base'} Lv.${c.lvl}`;
            console.log(`%c[PmheeAether Plan] 🎯 ถึงเงื่อนไข ${what} — เริ่มทำ ${actions.length} action`, 'color: #f59e0b; font-weight: bold;');
        });
        save();

        // Sweep pending triggers: give up on equip_item after 30 minutes or when superseded by an active Gear Set / later completed trigger
        const gp = plan.gearPlan;
        const gpSteps = (gp && Array.isArray(gp.steps)) ? gp.steps : [];
        const gpActive = gpSteps.length > 0 && planClassLineage(lv.cls).includes(String(gp.startClass || 'novice').toLowerCase());
        const curEq = ((typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || {}).equipment || {};
        const gpWornAny = gpActive && gpSteps.some(gs => gs && gs.kind === 'equip' && gearWorn(gs, curEq, gpSteps));
        let swept = false;
        for (const [pid, pe] of Object.entries(st.pending)) {
            const pTrig = plan.triggers.find((t, i) => planTriggerId(t, i) === pid);
            if (!pTrig || !pe || !Array.isArray(pe.actions)) continue;
            const timedOut30m = pe.firstAt && (Date.now() - pe.firstAt > 30 * 60 * 1000);
            const laterBaseDone = pTrig.type === 'base_level' && plan.triggers.some((t2, j) => t2 && t2.type === 'base_level' && (Number(t2.targetLevel) || 0) > (Number(pTrig.targetLevel) || 0) && st.done[planTriggerId(t2, j)]);
            const pTrigCls = pTrig.type === 'job_level' ? inferJobTriggerClassId(pTrig, plan) : '';
            const outdatedJobTrig = pTrigCls && lv.cls && pTrigCls !== lv.cls && planClassLineage(lv.cls).includes(pTrigCls);
            const filtered = pe.actions.filter(ai => {
                const a = (pTrig.actions || [])[ai];
                if (!a) return false;
                if (a.type === 'change_map' && (laterBaseDone || outdatedJobTrig)) return false;
                if (a.type === 'equip_item') {
                    if (timedOut30m || gpWornAny || outdatedJobTrig || (laterBaseDone && lv.base >= (Number(pTrig.targetLevel) || 0) + 15)) {
                        console.log(`%c[PmheeAether Plan] ⏭️ ข้ามการใส่ "${a.itemName}" ของเงื่อนไข Lv.${pe.level} (ใส่เซ็ตอุปกรณ์/ผ่านระดับนี้ไปแล้ว หรือเกิน 30 นาที)`, 'color: #94a3b8;');
                        return false;
                    }
                }
                return true;
            });
            if (filtered.length !== pe.actions.length) {
                swept = true;
                if (!filtered.length) {
                    delete st.pending[pid];
                    st.done[pid] = Date.now();
                } else {
                    pe.actions = filtered;
                }
            }
        }
        if (swept) save();

        // 2. Run pending actions (one trigger per cycle), unless the bot is busy with something that must not be interrupted
        const busy = planBusyReason();
        if (busy) return;
        const nextId = Object.keys(st.pending).sort((a, b) => st.pending[a].level - st.pending[b].level)
            .find(id => Date.now() >= (st.pending[id].nextAt || 0));
        if (!nextId) {
            const expectedMap = window.planMapForNow();
            if (expectedMap && window.__targetFarmMap && expectedMap !== window.__targetFarmMap && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(window.__targetFarmMap)) {
                console.log(`%c[PmheeAether Plan] 🗺️ ซิงค์แมพฟาร์มตามแผนสำหรับเลเวลปัจจุบัน: "${expectedMap}" (แทน "${window.__targetFarmMap}")`, 'color: #38bdf8; font-weight: bold;');
                try { localStorage.setItem(planLastMapKey(), expectedMap); } catch (e) {}
                window.setTargetFarmMap(expectedMap, true);
            }
            return;
        }
        const trig = plan.triggers.find((t, i) => planTriggerId(t, i) === nextId);
        if (!trig) { delete st.pending[nextId]; save(); return; }

        planTriggersRunning = true;
        try {
            const p = st.pending[nextId];
            // Run in the order the player placed them (e.g. change class first, then equip the bow):
            // the first action that isn't finished yet holds back the ones after it
            const remaining = [];
            let blocker = null;
            let quickRetry = false;
            for (const ai of p.actions) {
                const act = (trig.actions || [])[ai];
                if (!act) continue;
                if (blocker) { remaining.push(ai); continue; }
                let r = 'failed';
                try { r = await runPlanAction(act); } catch (e) { console.warn('[PmheeAether Plan] Action error:', e); r = 'pending'; }
                if (r === 'pending') {
                    remaining.push(ai);
                    if (act.type === 'change_class') blocker = act;
                    if (act.type === 'sell_trip' || act.type === 'weight_scroll') quickRetry = true;
                } else if (r === 'failed') {
                    console.warn('[PmheeAether Plan] ⚠️ Action ไม่ถูกต้อง (ข้าม):', act);
                }
            }
            const waitingOn = blocker;
            if (!remaining.length) {
                console.log(`%c[PmheeAether Plan] ✅ ทำเงื่อนไข Lv.${p.level} ครบแล้ว`, 'color: #22c55e; font-weight: bold;');
                delete st.pending[nextId];
                st.done[nextId] = Date.now();
            } else {
                p.actions = remaining;
                // A job change walks to Valkyrie: keep at it (other systems would pull the character back to the farm)
                const waitedLong = Date.now() - p.firstAt > 10 * 60 * 1000;
                p.nextAt = Date.now() + ((waitingOn || quickRetry) ? 4000 : (waitedLong ? PLAN_SLOW_RETRY_MS : PLAN_RETRY_MS));
            }
            save();
        } finally {
            planTriggersRunning = false;
        }
    };

    // -------------------------------------------------------------
    // LIVE CHARACTER DATA & PLAN AUTOMATION ENGINE
    // -------------------------------------------------------------
    let lastCharFiberScanAt = 0;
    let lastInvFiberScanAt = 0;
    let lastAppliedInvSig = '';

    window.getLiveCharacterData = function(forceScan = false) {
        const now = Date.now();
        if (!forceScan && window.__latestCharacterData && (now - lastCharFiberScanAt < 800)) {
            const liveMe = window.__gameRoom?.state?.players?.get?.(window.__gameRoom?.sessionId) || null;
            if (!window.__latestCharacterData.name) {
                const liveName = document.querySelector('.hud-name')?.innerText?.trim() || liveMe?.name || window.__charName || '';
                if (liveName) {
                    window.__charName = liveName;
                    window.__latestCharacterData.name = liveName;
                    window.__latestCharacterData.charName = liveName;
                }
            }
            if (liveMe) {
                if (typeof liveMe.maxHp === 'number' && liveMe.maxHp > 0) window.__latestCharacterData.maxHp = liveMe.maxHp;
                if (typeof liveMe.hp === 'number' && liveMe.hp >= 0) window.__latestCharacterData.hp = liveMe.hp;
                if (typeof liveMe.maxSp === 'number' && liveMe.maxSp > 0) window.__latestCharacterData.maxSp = liveMe.maxSp;
                if (typeof liveMe.sp === 'number' && liveMe.sp >= 0) window.__latestCharacterData.sp = liveMe.sp;
            }
            return window.__latestCharacterData;
        }
        lastCharFiberScanAt = now;
        const root = document.querySelector('#root');
        const key = root ? Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber')) : null;
        let fiber = (root && key) ? root[key] : null;
        let charData = null;
        let visited = 0;
        function walk(n, depth = 0) {
            if (!n || depth > 40 || charData || ++visited > 350) return;
            if (n.memoizedProps) {
                if (n.memoizedProps.character && n.memoizedProps.character.stats) charData = n.memoizedProps.character;
                else if (n.memoizedProps.stats && n.memoizedProps.skills) charData = n.memoizedProps;
            }
            if (!charData && n.memoizedState) {
                let s = n.memoizedState;
                let steps = 0;
                while (s && ++steps < 25) {
                    const ms = s.memoizedState;
                    if (ms && typeof ms === 'object') {
                        if (ms.character && ms.character.stats) { charData = ms.character; break; }
                        if (ms.stats && ms.skills) { charData = ms; break; }
                    }
                    s = s.next;
                }
            }
            if (n.child) walk(n.child, depth + 1);
            if (n.sibling) walk(n.sibling, depth + 1);
        }
        if (fiber) walk(fiber);
        const targetChar = charData || window.__latestCharacterData || null;
        if (targetChar) {
            const liveMe = window.__gameRoom?.state?.players?.get?.(window.__gameRoom?.sessionId) || null;
            const liveName = document.querySelector('.hud-name')?.innerText?.trim() || liveMe?.name || targetChar.name || targetChar.charName || window.__charName || '';
            if (liveName) {
                window.__charName = liveName;
                if (!targetChar.name) targetChar.name = liveName;
                if (!targetChar.charName) targetChar.charName = liveName;
            }
            const derived = (targetChar.derived && typeof targetChar.derived === 'object') ? targetChar.derived : {};
            const resolvedMaxHp = (liveMe && typeof liveMe.maxHp === 'number' && liveMe.maxHp > 0) ? liveMe.maxHp : (typeof derived.maxHp === 'number' && derived.maxHp > 0 ? derived.maxHp : targetChar.maxHp);
            const resolvedHp = (liveMe && typeof liveMe.hp === 'number' && liveMe.hp >= 0) ? liveMe.hp : (typeof targetChar.hp === 'number' ? targetChar.hp : resolvedMaxHp);
            const resolvedMaxSp = (liveMe && typeof liveMe.maxSp === 'number' && liveMe.maxSp > 0) ? liveMe.maxSp : (typeof derived.maxSp === 'number' && derived.maxSp > 0 ? derived.maxSp : targetChar.maxSp);
            const resolvedSp = (liveMe && typeof liveMe.sp === 'number' && liveMe.sp >= 0) ? liveMe.sp : (typeof targetChar.sp === 'number' ? targetChar.sp : resolvedMaxSp);
            if (typeof resolvedMaxHp === 'number') targetChar.maxHp = resolvedMaxHp;
            if (typeof resolvedHp === 'number') targetChar.hp = resolvedHp;
            if (typeof resolvedMaxSp === 'number') targetChar.maxSp = resolvedMaxSp;
            if (typeof resolvedSp === 'number') targetChar.sp = resolvedSp;
        }
        if (charData && typeof window.applyLiveCharacterPacket === 'function') {
            window.applyLiveCharacterPacket(charData, false);
        }
        return targetChar;
    };

    window.getLiveInventoryData = function() {
        const now = Date.now();
        if (window.__latestInventory && window.__latestInventory.feeZeny === undefined && typeof window.__latestInventory.weightLimit === 'number' && (now - lastInvFiberScanAt < 800)) {
            return window.__latestInventory;
        }
        lastInvFiberScanAt = now;
        const root = document.querySelector('#root');
        const key = root ? Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber')) : null;
        let fiber = (root && key) ? root[key] : null;
        let invData = null;
        let visited = 0;
        function isInvObj(o) {
            return o && typeof o === 'object' && Array.isArray(o.items) && o.feeZeny === undefined && (typeof o.weight === 'number' || typeof o.weightLimit === 'number');
        }
        function walk(n, depth = 0) {
            if (!n || depth > 40 || invData || ++visited > 350) return;
            if (n.memoizedProps) {
                if (isInvObj(n.memoizedProps.inventory)) invData = n.memoizedProps.inventory;
                else if (isInvObj(n.memoizedProps)) invData = n.memoizedProps;
            }
            if (!invData && n.memoizedState) {
                let s = n.memoizedState;
                let steps = 0;
                while (s && ++steps < 25) {
                    const ms = s.memoizedState;
                    if (ms && typeof ms === 'object') {
                        if (isInvObj(ms.inventory)) { invData = ms.inventory; break; }
                        if (isInvObj(ms)) { invData = ms; break; }
                    }
                    s = s.next;
                }
            }
            if (n.child) walk(n.child, depth + 1);
            if (n.sibling) walk(n.sibling, depth + 1);
        }
        if (fiber) walk(fiber);
        if (invData && typeof window.applyLiveInventoryPacket === 'function') {
            const sig = `${invData.items ? invData.items.length : 0}:${invData.weight ?? ''}:${invData.weightLimit ?? ''}:${invData.items && invData.items[0] ? `${invData.items[0].slot}:${invData.items[0].itemId}:${invData.items[0].qty}` : ''}`;
            if (sig !== lastAppliedInvSig || !window.__latestInventory) {
                lastAppliedInvSig = sig;
                window.applyLiveInventoryPacket(invData, true);
            } else {
                window.__latestInventory = invData;
            }
        }
        return invData || window.__latestInventory || null;
    };

    window.syncLiveCharacterAndInventory = function() {
        try {
            window.getLiveCharacterData();
            window.getLiveInventoryData();
            if (typeof window.__currentZeny === 'number') {
                const quickZeny = document.getElementById('p-quick-zeny');
                const expected = `💰 ${window.__currentZeny.toLocaleString()} z`;
                if (quickZeny && quickZeny.innerText !== expected) {
                    quickZeny.innerText = expected;
                }
            }
        } catch (e) {}
    };
    setInterval(window.syncLiveCharacterAndInventory, 2000);
    setTimeout(window.syncLiveCharacterAndInventory, 1000);

    // 1. Automated Skill Allocation (follows the plan's point queue)
    // A queued skill is skipped (not blocking the rest) while it can't be learned yet: wrong class
    // for now, prerequisite not met, or the server refused it (no progress -> retry in 10 min).
    const planSkillBlockedUntil = {};
    let planLastSkillAttempt = null;
    window.autoAllocateSkills = async function() {
        const plan = window.__currentScriptPlan;
        const queue = plan && plan.skillBuild && Array.isArray(plan.skillBuild.skillPointQueue) ? plan.skillBuild.skillPointQueue : [];
        if (!queue.length) return;
        const ch = window.getLiveCharacterData();
        if (!ch || !(ch.skillPoints > 0)) { planLastSkillAttempt = null; return; }
        const room = getPlanRoom();
        if (!room) return;
        const skills = ch.skills || {};

        if (planLastSkillAttempt) {
            const a = planLastSkillAttempt;
            if ((skills[a.id] || 0) <= a.level && ch.skillPoints >= a.points) {
                planSkillBlockedUntil[a.id] = Date.now() + 10 * 60 * 1000;
                console.warn(`[PmheeAether Plan] ⚠️ อัปสกิล "${a.id}" ไม่สำเร็จ (เกมไม่รับ) — ข้ามไปสกิลถัดไปในคิว แล้วจะลองใหม่ใน 10 นาที`);
            }
            planLastSkillAttempt = null;
        }

        const catalog = (window.__skillCatalog && Array.isArray(window.__skillCatalog.skills)) ? window.__skillCatalog.skills : [];
        const meta = {};
        catalog.forEach(s => { meta[s.id] = s; });
        const lineage = planClassLineage(ch.classId);
        const canLearnNow = id => {
            if ((planSkillBlockedUntil[id] || 0) > Date.now()) return false;
            const s = meta[id];
            if (!s) return catalog.length === 0;   // no catalog yet: let the server decide
            if (lineage.length && !lineage.includes(s.classId)) return false;
            if ((skills[id] || 0) >= (s.learnMaxLevel || s.maxLevel || 10)) return false;
            return (s.prerequisites || []).every(p => (skills[p.skill] || 0) >= p.level);
        };

        const wanted = {};
        let pick = null;
        for (const id of queue) {
            wanted[id] = (wanted[id] || 0) + 1;
            if ((skills[id] || 0) >= wanted[id]) continue;
            if (canLearnNow(id)) { pick = id; break; }
        }
        if (!pick) return false;
        planLastSkillAttempt = { id: pick, level: skills[pick] || 0, points: ch.skillPoints };
        console.log(`%c[PmheeAether Plan] ⚡ อัปสกิลตามแผน: "${pick}" Lv.${(skills[pick] || 0) + 1} (แต้มคงเหลือ ${ch.skillPoints})`, 'color: #a855f7; font-weight: bold;');
        try { room.send('skill_up', { skillId: pick }); } catch (err) { console.warn('[PmheeAether Plan] skill_up error:', err); }
        return true;   // a point was spent -> the job change waits for the next cycle
    };

    // 1.5 Gem auto-upgrade (plan setting "อัปเกรดเจมอัตโนมัติ", on unless turned off): when the bag holds a
    // higher % of a worn gem (same name), put it into that gem slot. One swap per cycle; a swap the game
    // didn't take pauses that slot for 10 min.
    let gemUpgradeAttempt = null;
    const gemUpgradeBlockedUntil = {};
    window.autoUpgradeGems = async function() {
        const plan = window.__currentScriptPlan;
        if (!plan || plan.autoUpgradeGems === false) return false;
        const ch = window.getLiveCharacterData();
        const room = getPlanRoom();
        if (!ch || !ch.equipment || !room) return false;
        const eq = ch.equipment;
        if (gemUpgradeAttempt) {
            const a = gemUpgradeAttempt;
            const now = gemTier(eq[a.to]);
            if (!(now && now.pct >= a.pct)) {
                gemUpgradeBlockedUntil[a.to] = Date.now() + 10 * 60 * 1000;
                console.warn(`[PmheeAether Plan] ⚠️ อัปเกรดเจมช่อง ${a.to} เป็น "${a.name}" ไม่สำเร็จ — พักช่องนี้ 10 นาที`);
            }
            gemUpgradeAttempt = null;
        }
        const baseLv = Number(ch.baseLevel) || 0;
        const bag = (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items : [];
        for (const slotKey of GEM_SLOTS) {
            const cur = gemTier(eq[slotKey]);
            if (!cur || (gemUpgradeBlockedUntil[slotKey] || 0) > Date.now()) continue;
            const better = bag
                .filter(it => { const t = gemTier(it); return t && t.family === cur.family && t.pct > cur.pct && !(it.levelReq > baseLv); })
                .sort((a, b) => gemTier(b).pct - gemTier(a).pct)[0];
            if (!better) continue;
            const pct = gemTier(better).pct;
            console.log(`%c[PmheeAether Plan] 💎 อัปเกรดเจม ${slotKey}: "${eq[slotKey].name}" → "${better.name}"`, 'color: #a855f7; font-weight: bold;');
            gemUpgradeAttempt = { to: slotKey, pct, name: better.name };
            try { room.send('equip', { slot: better.slot, to: slotKey }); } catch (e) { console.warn('[PmheeAether Plan] equip error:', e); }
            return true;
        }
        return false;
    };

    // 1.6 Built-in plan step (every plan, switch "รับสัตว์เลี้ยง Event"): at Base Lv.15 get the free pet egg
    // from Event Lily in the capital and use it. Once per character; skipped for good when Lily says it was
    // already taken or the event NPC is gone.
    const EVENT_PET_MIN_BASE = 15;
    const EVENT_PET_EGG_ID = 90334;   // Orc Cub Egg
    let eventPetNextTry = 0;
    let eventPetFails = 0;
    let eventPetEggRefusals = 0;
    window.runEventPetStep = async function() {
        const plan = window.__currentScriptPlan;
        if (!plan || plan.eventPet === false || Date.now() < eventPetNextTry) return false;
        const charName = (typeof window.getCharacterName === 'function') ? window.getCharacterName() : '';
        const lv = readPlanLevels();
        if (!charName || charName === 'default_char' || !lv || lv.base < EVENT_PET_MIN_BASE) return false;
        const doneKey = 'pelican_event_pet_' + charName;
        if (localStorage.getItem(doneKey)) return false;
        const room = getPlanRoom();
        if (!room) return false;
        const sleep = ms => new Promise(r => setTimeout(r, ms));
        const bag = () => (window.__latestInventory && Array.isArray(window.__latestInventory.items)) ? window.__latestInventory.items.filter(Boolean) : [];
        const finish = why => {
            try { localStorage.setItem(doneKey, why || String(Date.now())); } catch (e) {}
            window.__planJobChangeHoldUntil = 0;
            if (typeof window.restoreFarmMapAfterJobChange === 'function') window.restoreFarmMapAfterJobChange('pet');
        };

        // 0. The character already has this pet: nothing to do (the game refuses another egg of it)
        const petsNow = ((typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {}).pets;
        if (petsNow && Array.isArray(petsNow.owned) && petsNow.owned.some(p => /orc/i.test(String(p)))) {
            console.log('%c[PmheeAether Plan] 🐣 ตัวละครนี้มีสัตว์เลี้ยงออร์คน้อยแล้ว -> ข้ามขั้นตอนรับ/ฟักไข่', 'color: #22c55e;');
            finish('owned');
            return false;
        }

        // 1. Egg already in the bag: hatch it
        const egg = bag().find(it => Number(it.itemId) === EVENT_PET_EGG_ID);
        if (egg) {
            console.log(`%c[PmheeAether Plan] 🥚 ใช้ "${egg.name}" เพื่อฟักสัตว์เลี้ยง`, 'color: #22c55e; font-weight: bold;');
            room.send('inv_use', { slot: egg.slot });
            await sleep(1500);
            const left = bag().filter(it => Number(it.itemId) === EVENT_PET_EGG_ID).reduce((a, it) => a + (it.qty || 1), 0);
            if (left < (egg.qty || 1)) finish('hatched');
            else if (++eventPetEggRefusals >= 3) {
                console.log('%c[PmheeAether Plan] 🐣 เกมไม่ให้ฟักไข่ (3 ครั้ง) — น่าจะมีสัตว์เลี้ยงตัวนี้แล้ว -> ข้าม', 'color: #94a3b8;');
                finish('egg-refused');
            } else eventPetNextTry = Date.now() + 15000;
            return true;
        }

        // 2. Go to the capital (farm map is remembered and put back afterwards)
        const map = (typeof window.getCurrentMapName === 'function') ? (window.getCurrentMapName() || '') : '';
        if (!/เมืองหลวง|โซลเฮเวน/.test(map)) {
            if (window.__isWalkingToMap || window.__isNavigating) return false;
            const farm = window.__targetFarmMap || '';
            if (farm && !/เมืองหลวง|โซลเฮเวน/.test(farm)) { try { localStorage.setItem('pelican_job_return_map', farm); } catch (e) {} }
            console.log('%c[PmheeAether Plan] 🐣 Base Lv.15 แล้ว -> กลับเมืองหลวงไปรับไข่สัตว์เลี้ยงจาก Event Lily', 'color: #f59e0b; font-weight: bold;');
            window.__planJobChangeHoldUntil = Date.now() + 120000; if (typeof window.needTown === 'function') window.needTown('pet');
            window.planTripToCapital('pet');
            eventPetNextTry = Date.now() + 15000;
            return true;
        }

        // 3. Talk to Event Lily (the server walks the character over) and take the egg
        let lily = null;
        if (room.state && room.state.npcs && typeof room.state.npcs.forEach === 'function') {
            room.state.npcs.forEach((n, k) => { if (!lily && n && /Event Lily/i.test(n.name || '')) lily = k; });
        }
        if (!lily) {
            console.warn('[PmheeAether Plan] 🐣 ไม่พบ NPC Event Lily ในเมือง (อีเวนต์อาจจบแล้ว) -> ข้ามขั้นตอนรับสัตว์เลี้ยง');
            finish('no-npc');
            return false;
        }
        window.__planJobChangeHoldUntil = Date.now() + 30000; if (typeof window.needTown === 'function') window.needTown('pet');
        const readDialog = () => {
            const d = document.querySelector('.npc-dialog');
            if (!d) return null;
            return { text: ((d.querySelector('.npc-body p') || d).innerText || '').trim(), options: Array.from(d.querySelectorAll('.npc-options button')).map(b => (b.innerText || '').replace(/^\s*\d+\s*/, '').trim()) };
        };
        const closeDialog = () => { const x = document.querySelector('.npc-dialog .win-close'); if (x) x.click(); else room.send('npc_close', {}); };
        console.log(`%c[PmheeAether Plan] 💬 คุยกับ Event Lily (${lily}) เพื่อรับไข่สัตว์เลี้ยง...`, 'color: #a855f7; font-weight: bold;');
        room.send('npc_talk', { npcKey: lily });
        let dl = null;
        for (let i = 0; i < 75 && !(dl && dl.options.length); i++) { await sleep(200); dl = readDialog(); }
        if (!dl) {
            eventPetFails++;
            eventPetNextTry = Date.now() + Math.min(600000, 20000 * eventPetFails);
            return true;
        }
        console.log(`[PmheeAether Plan] 📜 Event Lily: "${dl.text.slice(0, 80)}" | ตัวเลือก: ${dl.options.map((o, i) => `${i}:${o}`).join(' / ')}`);
        const idx = dl.options.findIndex(o => /รับ/.test(o) && !/ไว้ก่อน/.test(o));
        if (idx < 0) {
            closeDialog();
            console.log('[PmheeAether Plan] 🐣 Event Lily ไม่มีตัวเลือกรับไข่แล้ว (รับไปแล้ว) -> ข้าม');
            finish('already');
            return true;
        }
        room.send('npc_option', { index: idx });
        for (let i = 0; i < 20; i++) {
            await sleep(250);
            if (bag().some(it => Number(it.itemId) === EVENT_PET_EGG_ID)) break;
        }
        if (readDialog()) closeDialog();
        eventPetNextTry = Date.now() + 1000;   // next cycle hatches the egg
        return true;
    };

    // 2. Automated Stat Allocation: fill stats to their targets in priority order.
    // The game's stat_up payload is { stat, n }. Cost per point = floor((value - 1) / 10) + 2.
    const planStatCost = v => Math.floor((v - 1) / 10) + 2;
    let planLastStatAttempt = null;
    window.autoAllocateStats = async function() {
        const plan = window.__currentScriptPlan;
        const sb = plan && plan.statBuild;
        if (!sb || !((Array.isArray(sb.queue) && sb.queue.length) || sb.targets)) return;
        const ch = window.getLiveCharacterData();
        if (!ch || !(ch.statusPoints > 0)) { planLastStatAttempt = null; return; }
        const room = getPlanRoom();
        if (!room) return;

        const stats = ch.stats || {};
        let singleStep = false;
        if (planLastStatAttempt) {
            const a = planLastStatAttempt;
            const noProgress = (Number(stats[a.stat]) || 1) <= a.value && ch.statusPoints >= a.points;
            if (noProgress && a.n > 1) singleStep = true;   // batch refused: fall back to one point at a time
            else if (noProgress) {
                console.warn(`[PmheeAether Plan] ⚠️ อัปสเตตัส ${a.stat} ไม่สำเร็จ — พักไว้ 1 รอบ`);
                planLastStatAttempt = null;
                return;
            }
            planLastStatAttempt = null;
        }

        // The plan's stat queue (Manager "Stat Build": step 1 to its value, then step 2, ...). Plans saved
        // before the queue: targets in priority order (the same as before).
        const steps = (Array.isArray(sb.queue) && sb.queue.length)
            ? sb.queue
            : ((Array.isArray(sb.priorityOrder) && sb.priorityOrder.length) ? sb.priorityOrder : ['DEX', 'AGI', 'LUK', 'VIT', 'INT', 'STR']).map(k => ({ stat: k, to: (sb.targets || {})[String(k).toUpperCase()] }));
        for (const stp of steps) {
            const key = String((stp && stp.stat) || '').toUpperCase();
            if (!['STR', 'AGI', 'VIT', 'INT', 'DEX', 'LUK'].includes(key)) continue;
            const target = Math.min(99, Math.max(1, Number(stp.to) || 1));
            const cur = Number(stats[key]) || 1;
            if (cur >= target) continue;
            let n = 0, spent = 0;
            const firstCost = (ch.statCosts && Number(ch.statCosts[key])) || planStatCost(cur);
            while (cur + n < target && !(singleStep && n >= 1)) {
                const c = n === 0 ? firstCost : planStatCost(cur + n);
                if (spent + c > ch.statusPoints) break;
                spent += c;
                n++;
            }
            if (n === 0) return;   // can't afford the next point of the top-priority stat yet: wait for more points
            planLastStatAttempt = { stat: key, value: cur, points: ch.statusPoints, n };
            console.log(`%c[PmheeAether Plan] 📊 อัปสเตตัสตามแผน: ${key} +${n} (${cur} → ${cur + n}, ใช้ ${spent} แต้ม)`, 'color: #38bdf8; font-weight: bold;');
            try { room.send('stat_up', { stat: key, n }); } catch (err) { console.warn('[PmheeAether Plan] stat_up error:', err); }
            return;
        }
    };

    window.getCharacterName = function() {
        const hud = (document.querySelector('.hud-name')?.innerText || '').trim();
        if (hud) return hud;
        const r = window.getColyseusRoom ? window.getColyseusRoom() : window.__colyseusRoom;
        if (r && r.state && r.state.players) {
            const p = r.state.players.get ? r.state.players.get(r.sessionId) : r.state.players[r.sessionId];
            if (p && p.name) return p.name;
        }
        return 'default_char';
    };

    // 3. Automated Class 1 & Class 2 job change.
    // The game itself says when a job change is possible (character.jobChangeOptions), so no guessing
    // from Base/Job level. Novice -> plan.class1Target, first class -> plan.class2Target.
    let planJobWarned = '';
    // Plan setting "เปลี่ยนอาชีพอัตโนมัติ". Older plans without the setting: automatic unless the player
    // already placed a "เปลี่ยนอาชีพ" action (then the triggers decide when to change)
    function planAutoJobChange(plan) {
        if (!plan) return false;
        if (typeof plan.autoJobChange === 'boolean') return plan.autoJobChange;
        return !(plan.triggers || []).some(t => (t.actions || []).some(a => a.type === 'change_class'));
    }

    window.checkAndExecuteAutoJobChange = async function() {
        if (!window.__planScriptEnabled) return false;
        const plan = window.__currentScriptPlan;
        if (!plan || !planAutoJobChange(plan)) return false;
        const ch = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : null;
        if (!ch) return false;
        const options = planJobOptions(ch);
        if (!options.length || window.__isWalkingToMap || window.__isChangingJob) return false;

        const tier = planClassTier(ch.classId);
        const wanted = tier === 0 ? plan.class1Target : tier === 1 ? plan.class2Target : null;
        if (!wanted) return false;
        const target = String(wanted).trim().toLowerCase();

        // Change at the Job Lv. set in the plan (default Class 1 = 10, Class 2 = 50: the game already allows
        // Class 2 at Job 40, waiting for 50 gives 10 more skill points). Capped by the class's max job level.
        const wantJob = Math.round(Number(tier === 0 ? plan.class1JobLevel : plan.class2JobLevel) || (tier === 0 ? 10 : 50));
        const needJob = Math.min(wantJob, Number(ch.jobMaxLevel) || wantJob);
        if ((Number(ch.jobLevel) || 0) < needJob) {
            const wait = `wait:${ch.classId}:${needJob}`;
            if (planJobWarned !== wait) {
                planJobWarned = wait;
                console.log(`[PmheeAether Plan] ⏳ เปลี่ยนเป็น ${target} ได้แล้ว แต่แผนตั้งให้รอ Job Lv.${needJob} (ตอนนี้ Job Lv.${ch.jobLevel})`);
            }
            return false;
        }
        if (ch.skillPoints > 0) console.warn(`[PmheeAether Plan] ⚠️ เปลี่ยนอาชีพโดยยังเหลือแต้มสกิล ${ch.skillPoints} แต้ม (ไม่มีสกิลในคิวที่อัปได้)`);

        if (!options.includes(target)) {
            const warn = `${ch.classId}->${target}`;
            if (planJobWarned !== warn) {
                planJobWarned = warn;
                console.warn(`[PmheeAether Plan] ⚠️ แผนตั้งให้เปลี่ยนเป็น "${target}" แต่ ${ch.classId} เปลี่ยนได้แค่: ${options.join(', ')} — ตรวจ Class 1/Class 2 ในแผน`);
            }
            return false;
        }

        console.log(`%c[PmheeAether Plan] 👑 เปลี่ยนอาชีพได้แล้ว! ${ch.classId} → ${target}`, 'color: #a855f7; font-weight: bold;');
        window.__isChangingJob = true;
        try {
            await window.executeAutoJobChange(target);
        } finally {
            window.__isChangingJob = false;
        }
        return true;
    };

    // ==========================================
    // 4. AUTOMATED COMBAT & GAME DISPLAY CONFIGURATION
    // ==========================================
    const KNOWN_ACTIVE_SKILLS = new Set([
        "first-aid","whirlwind","starfall","angel-starfall","berserk","earthquake",
        "bash","provoke","magnum-break","endure","fire-bolt","cold-bolt","lightning-bolt",
        "soul-strike","napalm-beat","frost-diver","sight","arcane-surge","double-strafe",
        "arrow-shower","improve-concentration","focus-shooting","heal","blessing","increase-agi",
        "holy-light","mammonite","loud-exclamation","steal","back-slide","envenom","pierce",
        "bowling-bash","brandish-spear","two-hand-quicken","parry","charge-attack","holy-cross",
        "grand-cross","shield-charge","shield-boomerang","auto-guard","safety-wall","jupitel-thunder",
        "heavens-drive","quagmire","storm-gust","meteor-storm","lord-of-vermilion","earth-spike",
        "endow-blaze","endow-tsunami","endow-tornado","endow-quake","auto-spell","create-converter",
        "land-protector","blitz-beat","land-mine","ankle-snare","claymore-trap","detecting",
        "musical-strike","frost-joke","poem-of-bragi","assassin-cross-of-sunset","apple-of-idun",
        "throw-arrow","service-for-you","fortune-kiss","scream","magnus-exorcismus","kyrie-eleison",
        "impositio-manus","gloria","sanctuary","aspersio","pneuma","resurrection","call-spirits",
        "finger-offensive","six-saint","investigate","asura-strike","hammer-fall","adrenaline-rush",
        "over-thrust","weapon-perfection","acid-terror","demonstration","potion-pitcher",
        "chemical-protection","sonic-blow","grimtooth","enchant-poison","venom-dust","back-stab",
        "raid","strip-armor","snatcher","dragon-breath","hagglers-wit","crusader-heal","humming","priest-safety-wall"
    ]);

    window.__autoConfigCharEnabled = true;
    try {
        const savedAuto = localStorage.getItem('pelican_auto_config_char_enabled');
        if (savedAuto !== null) window.__autoConfigCharEnabled = (savedAuto === 'true');
    } catch(e) {}

    window.__autoMuteDisplayEnabled = true;
    try {
        const savedMute = localStorage.getItem('pelican_auto_mute_display_enabled');
        if (savedMute !== null) window.__autoMuteDisplayEnabled = (savedMute === 'true');
    } catch(e) {}

    // 4.1 Automated Combat Config: Sets huntRadiusTiles to 'all' and ticks all auto skills (ทำงานเฉพาะเมื่อรัน Plan Script)
    window.autoConfigureCombat = async function(force = false) {
        // ต้องเปิดใช้งาน Plan Script และมีแผนการเล่นที่เลือกไว้เท่านั้น (ยกเว้นกดปุ่ม Force Apply จาก UI)
        if (!force && (!window.__planScriptEnabled || !window.__currentScriptPlan)) return false;
        if (!window.__autoConfigCharEnabled && !force) return false;

        const charData = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : (window.__latestCharacterData || null);
        if (!charData) return false;

        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : null;
        if (!room) return false;

        const charName = charData.name || (typeof window.getCharacterName === 'function' ? window.getCharacterName() : 'default_char');
        if (!charName || charName === 'default_char') return false;

        const currentAuto = charData.auto || {};
        const currentConfig = currentAuto.config || {};
        const curRadius = currentConfig.huntRadiusTiles;
        const currentSkills = Array.isArray(currentConfig.skills) ? [...currentConfig.skills] : [];
        const learnedSkills = charData.skills || {};

        // รวบรวมสกิลที่มี autoUse ที่ตัวละครได้อัปเลเวลไว้ (> 0)
        let autoUsableSkills = [];

        // ลำดับที่ 1: ดึงจาก skill_catalog ที่เซิร์ฟเวอร์ส่งมา
        if (window.__skillCatalog && Array.isArray(window.__skillCatalog.skills)) {
            autoUsableSkills = window.__skillCatalog.skills
                .filter(s => s && s.autoUse && (learnedSkills[s.id] || 0) > 0)
                .map(s => s.id);
        }

        // ลำดับที่ 2: ดึงจาก React Fiber state หาก catalog ยังไม่ได้ถูกแคชในตัวแปร
        if (autoUsableSkills.length === 0) {
            try {
                const root = document.querySelector('#root');
                let fiber = root ? root[Object.keys(root).find(k => k.startsWith('__reactContainer'))] : null;
                function walkFiber(n, depth = 0) {
                    if (!n || depth > 40 || autoUsableSkills.length > 0) return;
                    const cat = n.memoizedProps?.catalog || n.memoizedState?.memoizedState?.catalog || n.memoizedState?.memoizedState?.value?.catalog;
                    if (cat && Array.isArray(cat.skills)) {
                        autoUsableSkills = cat.skills
                            .filter(s => s && s.autoUse && (learnedSkills[s.id] || 0) > 0)
                            .map(s => s.id);
                        return;
                    }
                    if (n.child) walkFiber(n.child, depth + 1);
                    if (n.sibling) walkFiber(n.sibling, depth + 1);
                }
                if (fiber) walkFiber(fiber);
            } catch(e) {}
        }

        // ลำดับที่ 3: ใช้ฐานข้อมูลสกิล Active สากล (Fallback)
        if (autoUsableSkills.length === 0) {
            autoUsableSkills = Object.keys(learnedSkills).filter(skillId => {
                return (learnedSkills[skillId] || 0) > 0 && KNOWN_ACTIVE_SKILLS.has(skillId);
            });
        }

        // Skills switched off in the plan's skill page ("ใช้ใน AUTO" off, skillBuild.autoOff) are never ticked,
        // and are unticked when they already are
        const planNow = window.__currentScriptPlan;
        const autoOff = new Set(planNow && planNow.skillBuild && Array.isArray(planNow.skillBuild.autoOff) ? planNow.skillBuild.autoOff : []);
        autoUsableSkills = autoUsableSkills.filter(id => !autoOff.has(id));
        // Passives can't be ticked (the skill catalog marks some of them autoUse anyway), and skills the server
        // dropped from the AUTO list after we sent them (not allowed / over its limit) are not sent again —
        // otherwise auto_set went out every 5 s forever. Remembered per character + class for this page.
        const kindOf = {};
        ((window.__skillCatalog && window.__skillCatalog.skills) || []).forEach(sk => { if (sk && sk.id) kindOf[sk.id] = sk.kind; });
        window.__autoSkillRejected = window.__autoSkillRejected || {};
        window.__autoSkillSent = window.__autoSkillSent || {};
        const rejKey = charName + ':' + (charData.classId || '');
        const rejected = window.__autoSkillRejected[rejKey] || (window.__autoSkillRejected[rejKey] = new Set());
        const sentBefore = window.__autoSkillSent[rejKey];
        if (sentBefore && Date.now() - sentBefore.at > 6000) {
            sentBefore.skills.filter(id => !currentSkills.includes(id)).forEach(id => {
                if (!rejected.has(id)) console.log(`[PmheeAether Auto] ℹ️ เกมไม่รับสกิล "${id}" ใน AUTO -> ไม่ส่งซ้ำ`);
                rejected.add(id);
            });
            delete window.__autoSkillSent[rejKey];
        }
        autoUsableSkills = autoUsableSkills.filter(id => kindOf[id] !== 'passive' && !rejected.has(id));

        // จัดเตรียมรายการสกิลเป้าหมาย: คงลำดับสกิลเดิมไว้ และเพิ่มสกิล Auto ที่ยังไม่ได้ติ๊กต่อท้าย (สูงสุด 9 สกิล)
        const targetSkills = currentSkills.filter(id => !autoOff.has(id));
        for (const skillId of autoUsableSkills) {
            if (!targetSkills.includes(skillId) && targetSkills.length < 9) {
                targetSkills.push(skillId);
            }
        }

        // ตรวจสอบว่าต้องอัปเดตหรือไม่
        // 1. ระยะล่าไม่ตรงกับที่ต้องการ (ปกติ 'all' หรือตามระยะปาร์ตี้ window.__partyOverrideRadius)
        // 2. มีสกิล Auto ที่ยังไม่ได้ถูกติ๊กใน config
        const desiredRadius = window.__partyOverrideRadius || 'all';
        const needsRadiusUpdate = curRadius !== desiredRadius;
        const needsSkillsUpdate = targetSkills.length !== currentSkills.length || targetSkills.some((id, i) => id !== currentSkills[i]);

        if (!needsRadiusUpdate && !needsSkillsUpdate && !force) {
            return false;
        }

        // ป้องกันการส่งแพ็กเก็ตซ้ำเร็วเกินไป (Throttle 5 วินาทีต่อครั้งสำหรับตัวละครเดียวกัน ถ้าไม่ใช่ force)
        const now = Date.now();
        window.__lastAutoSetTime = window.__lastAutoSetTime || {};
        if (!force && (now - (window.__lastAutoSetTime[charName] || 0)) < 5000) {
            return false;
        }
        window.__lastAutoSetTime[charName] = now;
        window.__autoSkillSent[rejKey] = { skills: targetSkills.slice(), at: now };

        console.log(`%c[PmheeAether Auto] 🎯 [${charName}] ปรับแต่งต่อสู้อัตโนมัติ: ระยะล่า -> ${desiredRadius === 'all' ? 'ทั้งแมพ ("all")' : desiredRadius + ' ช่อง'} | สกิล Auto -> [${targetSkills.join(', ')}]`, 'color: #10b981; font-weight: bold;');

        const enabledBuffPotionIds = (window.__buffPotionConfig)
            ? Object.keys(window.__buffPotionConfig).filter(id => window.__buffPotionConfig[id]?.enabled).map(Number)
            : (Array.isArray(currentConfig.buffItems) ? currentConfig.buffItems : []);

        const isPriestCls = /^(priest|acolyte)$/i.test(String(charData.classId || ''));
        const newConfig = {
            skills: targetSkills,
            monsters: currentConfig.monsters || [],
            hpPercent: typeof currentConfig.hpPercent === 'number' ? currentConfig.hpPercent : 40,
            spPercent: typeof currentConfig.spPercent === 'number' ? currentConfig.spPercent : 20,
            pickupLoot: currentConfig.pickupLoot !== false,
            huntRadiusTiles: desiredRadius,
            basicAttack: currentConfig.basicAttack !== false,
            buffParty: currentConfig.buffParty !== false,
            healPartyPercent: isPriestCls ? Math.max(Number(currentConfig.healPartyPercent) || 80, 80) : (typeof currentConfig.healPartyPercent === 'number' ? currentConfig.healPartyPercent : 60),
            flyWing: currentConfig.flyWing === true,
            buffItems: enabledBuffPotionIds
        };

        try {
            room.send('auto_set', { config: newConfig });
            if (charData.auto) {
                charData.auto.config = { ...charData.auto.config, ...newConfig };
            }
            return true;
        } catch(err) {
            console.warn('[PmheeAether Auto] Error sending auto_set packet:', err);
            return false;
        }
    };

    // 4.2 Automated Game Settings (Display, Graphics & Character Privacy — checked once upon initial character login/load into the game)
    function writeOptimalGameSettingsToStorage() {
        let updated = false;
        try {
            if (typeof localStorage.removeItem === 'function') localStorage.removeItem('fx-used');
            const rawCam = localStorage.getItem('webgame.camera');
            const cam = rawCam ? JSON.parse(rawCam) : {};
            const desiredCam = {
                render: 1,              // ความคมชัด: ลื่นสุด
                maxPlayers: 10,         // ผู้เล่นอื่นที่แสดงบนจอ: 10 คน (น้อยสุดของเมนูตั้งค่า)
                effects: 'off',         // เอฟเฟกต์สกิลและการโจมตี: ปิด
                fpsLimit: 30,           // เฟรมเรต: 30 FPS (ของตัวเกมเอง ไม่ใช่การดัก rAF)
                ground: 'painted',      // พื้นแผนที่: ภาพวาด
                hatBob: false,          // หมวกขยับตามจังหวะเดิน: ปิด
                hatSparkle: false,      // ประกายวิบที่หมวก: ปิด
                footAura: false,        // ออร่าใต้เท้า: ปิด
                shake: false,           // สั่นจอ: ปิด
                banners: false,         // แสดงประกาศบนจอ: ปิด
                damageNumbers: 'off',   // ตัวเลขดาเมจ: ปิด
                monsterHp: 'hit',       // แสดงหลอด HP มอนสเตอร์ทุกตัว: ปิด
                playerNames: 'hover'    // ชื่อผู้เล่นอื่น: ชี้เมาส์
            };
            let camChanged = false;
            for (const [k, v] of Object.entries(desiredCam)) {
                if (cam[k] !== v) {
                    cam[k] = v;
                    camChanged = true;
                }
            }
            if (camChanged) {
                localStorage.setItem('webgame.camera', JSON.stringify(cam));
                updated = true;
            }
        } catch (e) {}

        try {
            const rawMob = localStorage.getItem('webgame.mobile');
            const mob = rawMob ? JSON.parse(rawMob) : {};
            if (mob.newsOnEnter !== false) {
                mob.newsOnEnter = false; // เปิดหน้าข่าวสารเองเมื่อเข้าเกม: ปิด
                localStorage.setItem('webgame.mobile', JSON.stringify(mob));
                updated = true;
            }
        } catch (e) {}
        return updated;
    }

    // Pre-seed localStorage immediately at script startup
    writeOptimalGameSettingsToStorage();

    window.applyPelicanSettings = function(force = false) {
        if (!window.__autoMuteDisplayEnabled && !force) return;

        // ปิดหน้าต่างข่าวสารอัปเดต (News Window) หากเปิดค้างหรือเผลอเด้งขึ้นมา
        try {
            const newsWindow = document.querySelector('.news-window');
            if (newsWindow) {
                const closeBtn = newsWindow.querySelector('.win-close');
                if (closeBtn) closeBtn.click();
            }
        } catch (e) {}

        const charName = (typeof window.getCharacterName === 'function' ? window.getCharacterName() : '')
            || (window.__latestCharacterData && window.__latestCharacterData.name) || '';

        if (force) {
            window.__pmDisplaySettingsSynced = false;
            window.__pmDisplaySettingsTries = 0;
        }
        // เช็คแค่ครั้งแรกที่ login เลือกตัวละคร โหลดเข้าเกมสำเร็จ (ต่อตัวละคร)
        if (!force && window.__pmDisplaySettingsSynced && (!charName || window.__pmDisplaySettingsSyncedChar === charName)) {
            return;
        }

        writeOptimalGameSettingsToStorage();

        // ส่งคำสั่งปิดการส่องอุปกรณ์และสเตตัส (inspect_privacy: hidden = true)
        try {
            const liveChar = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData;
            if (liveChar && liveChar.inspectHidden !== true) {
                const room = (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null)
                    || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null)
                    || window.__colyseusRoom;
                if (room && typeof room.send === 'function') {
                    room.send('inspect_privacy', { hidden: true });
                    liveChar.inspectHidden = true;
                }
            }
        } catch (e) {}

        // รอจนกว่าจะโหลดเข้าตัวละครในเกมสำเร็จและไม่มีหน้าต่างเช็คผู้เล่น
        if (!charName && !force) return;
        if (document.querySelector('.human-check')) return;
        if (window.__pmDisplaySettingsOpening) return;
        if (!force && ((window.__pmDisplaySettingsTries || 0) >= 3 || planBusyReason() !== null)) return;

        const setSwitch = (win, keywords, targetChecked) => {
            const rows = Array.from(win.querySelectorAll('label.set-row, label.settings-check'));
            for (const row of rows) {
                const text = (row.innerText || row.textContent || '').trim();
                if (!keywords.some(kw => text.includes(kw))) continue;
                const cb = row.querySelector('input[type="checkbox"]');
                if (cb && Boolean(cb.checked) !== Boolean(targetChecked)) {
                    cb.click();
                }
            }
        };

        const setRadio = (win, rowKeywords, optionKeywords, fallbackIdx) => {
            const blocks = Array.from(win.querySelectorAll('.set-row.set-block'));
            for (const blk of blocks) {
                const titleEl = blk.querySelector('.set-text b');
                const titleText = ((titleEl && titleEl.textContent) || blk.innerText || '').trim();
                if (!rowKeywords.some(kw => titleText.includes(kw))) continue;
                const radios = Array.from(blk.querySelectorAll('.settings-choice button[role="radio"], .settings-choice button'));
                if (!radios.length) continue;
                let targetBtn = radios.find(b => {
                    const bText = (b.innerText || b.textContent || '').trim();
                    return optionKeywords.some(okw => bText.startsWith(okw) || bText.includes(okw));
                });
                if (!targetBtn && Number.isInteger(fallbackIdx) && radios[fallbackIdx]) {
                    targetBtn = radios[fallbackIdx];
                }
                if (targetBtn && targetBtn.getAttribute('aria-checked') !== 'true' && !targetBtn.classList.contains('active')) {
                    targetBtn.click();
                }
            }
        };

        const clickTab = (win, keywords) => {
            const navBtns = Array.from(win.querySelectorAll('.set-nav button'));
            const tabBtn = navBtns.find(b => {
                const t = (b.innerText || b.textContent || '').trim();
                return keywords.some(kw => t.includes(kw));
            });
            if (tabBtn && !tabBtn.classList.contains('on')) {
                tabBtn.click();
            }
            return !!tabBtn;
        };

        const syncAllSettingsTabs = async (openedByBot) => {
            const delay = ms => new Promise(r => setTimeout(r, ms));
            try {
                const win = document.querySelector('.settings-window');
                if (!win) return;

                // 1) หมวด "การแสดงผล"
                clickTab(win, ['การแสดงผล', 'Display']);
                await delay(100);
                setSwitch(win, ['แสดงประกาศบนจอ', 'Show announcements'], false);
                setSwitch(win, ['เปิดหน้าข่าวสารเองเมื่อเข้าเกม', 'Open the news'], false);
                setRadio(win, ['ตัวเลขดาเมจ', 'Damage numbers'], ['ปิด', 'Off'], 2);
                setSwitch(win, ['แสดงหลอด HP มอนสเตอร์ทุกตัว', 'Show HP bar'], false);
                setRadio(win, ['ชื่อผู้เล่นอื่น', 'Player names', 'Other player'], ['ชี้เมาส์', 'Hover'], 2);

                // 2) หมวด "กราฟิกและความลื่น"
                clickTab(win, ['กราฟิกและความลื่น', 'Graphics']);
                await delay(100);
                setRadio(win, ['ความคมชัด', 'Resolution', 'Render'], ['ลื่นสุด', 'Fastest', 'Low'], 0);
                setRadio(win, ['ผู้เล่นอื่นที่แสดงบนจอ', 'Other players', 'Max players'], ['10 คน', '10 '], 4);
                setRadio(win, ['เอฟเฟกต์สกิลและการโจมตี', 'เอฟเฟกต์สกิล', 'Effects'], ['ปิด', 'Off'], 2);
                setRadio(win, ['เฟรมเรต', 'Frame rate', 'FPS'], ['30 FPS', '30'], 1);
                setRadio(win, ['พื้นแผนที่', 'Ground', 'Map'], ['ภาพวาด', 'Painted'], 1);

                // 3) หมวด "ตัวละคร"
                clickTab(win, ['ตัวละคร', 'Character']);
                await delay(100);
                setSwitch(win, ['หมวกขยับตามจังหวะเดิน', 'Hat bob'], false);
                setSwitch(win, ['ประกายวิบที่หมวก', 'Hat sparkle'], false);
                setSwitch(win, ['ให้ผู้เล่นอื่นตรวจสอบอุปกรณ์', 'ตรวจสอบอุปกรณ์', 'inspect'], false);

                await delay(80);
                window.__pmDisplaySettingsSynced = true;
                if (charName) window.__pmDisplaySettingsSyncedChar = charName;
                console.log('%c[PmheeAether Settings] ✅ ตั้งค่าเกมอัตโนมัติครบทั้ง 3 หมวด (การแสดงผล / กราฟิกลื่นสุด 30FPS / ตัวละคร) เรียบร้อยแล้ว', 'color: #38bdf8; font-weight: bold;');

                if (openedByBot) {
                    const close = win.querySelector('.win-close');
                    if (close) close.click();
                }
            } catch (e) {
            } finally {
                window.__pmDisplaySettingsOpening = false;
            }
        };

        try {
            if (document.querySelector('.settings-window')) {
                window.__pmDisplaySettingsOpening = true;
                syncAllSettingsTabs(false);
            } else {
                const btn = Array.from(document.querySelectorAll('button.menu-btn')).find(b => {
                    const t = ((b.querySelector('small') || {}).textContent || '').trim();
                    return t === 'ตั้งค่า' || t === 'Settings';
                });
                if (btn) {
                    window.__pmDisplaySettingsOpening = true;
                    window.__pmDisplaySettingsTries = (window.__pmDisplaySettingsTries || 0) + 1;
                    btn.click();
                    setTimeout(() => {
                        syncAllSettingsTabs(true);
                    }, 180);
                }
            }
        } catch (e) {
            window.__pmDisplaySettingsOpening = false;
        }
    };

    // Plan Script loop (every 4 s). Initial game settings check runs once per character load even if Plan Script is off;
    // combat config, job change, skills, stats, level triggers run only while Plan Script + START BOT are on.
    let planLoopRunning = false;
    setInterval(async () => {
        if (!window.__pmDisplaySettingsSynced && typeof window.applyPelicanSettings === 'function') {
            window.applyPelicanSettings();
        }
        if (planLoopRunning || !window.__planScriptEnabled || !window.__currentScriptPlan) return;
        planLoopRunning = true;
        try {
            if (typeof window.applyPelicanSettings === 'function') window.applyPelicanSettings();
            if (!window.__isBotRunning) {
                if (typeof window.planMapForNow === 'function' && typeof window.setTargetFarmMap === 'function') {
                    const desiredMap = window.planMapForNow();
                    const curTarget = window.__targetFarmMap || '';
                    if (desiredMap && desiredMap !== curTarget && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(curTarget)) {
                        window.setTargetFarmMap(desiredMap, false);
                    }
                }
                return;
            }
            if (window.__consolidationPending) return;   // money consolidation is about to start: nothing new
            if (typeof window.autoConfigureCombat === 'function') await window.autoConfigureCombat();
            // Spend skill points of the current class before changing job
            if (await window.autoAllocateSkills()) return;
            if (await window.checkAndExecuteAutoJobChange()) return;
            await window.autoAllocateStats();
            if (planBusyReason() === null && await window.autoUpgradeGems()) return;
            if (planBusyReason() === null && await window.runEventPetStep()) return;
            if (planBusyReason() === null && await window.runWeightTopUpStep()) return;
            if (planBusyReason() === null && await window.runGearPlanStep()) return;
            await window.checkAndExecutePlanTriggers();
            if (planBusyReason() === null && typeof window.planMapForNow === 'function' && typeof window.setTargetFarmMap === 'function') {
                const desiredMap = window.planMapForNow();
                const curTarget = window.__targetFarmMap || '';
                if (desiredMap && desiredMap !== curTarget && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(curTarget)) {
                    console.log(`%c[PmheeAether Plan] 🗺️ คืนแมพเป้าหมายตามแผนสคริปต์: "${curTarget || '-'}" → "${desiredMap}"`, 'color: #38bdf8; font-weight: bold;');
                    window.setTargetFarmMap(desiredMap, true);
                }
            }
        } catch (e) {
            console.warn('[PmheeAether Plan] loop error:', e);
        } finally {
            planLoopRunning = false;
        }
    }, 4000);

    // ==========================================
    // CENTRALIZED ZENY CONSOLIDATION, CHANNELS & MARKET CLAIM ENGINE
    // ==========================================
    window.claimAllMarket = async function() {
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : (window.__gameRoom || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null));
        if (!room) return { success: false, error: 'No room connection' };
        console.log('%c[PmheeAether Market] 🛒 ส่งคำสั่งรับของทั้งหมดจากตลาดกลาง (collect_all)...', 'color: #38bdf8; font-weight: bold;');
        try {
            room.send('market', { op: 'collect_all' });
            room.send('market', { op: 'mine' });
            return { success: true, timestamp: Date.now() };
        } catch (err) {
            return { success: false, error: err.message };
        }
    };

    window.getCurrentChannel = function() {
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : (window.__gameRoom || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null));
        if (room && room.state && typeof room.state.channel === 'number') {
            return room.state.channel;
        }
        return window.__currentChannel || 1;
    };

    window.getChannelsList = function(timeoutMs = 4000) {
        return new Promise((resolve) => {
            const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : (window.__gameRoom || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null));
            if (!room) return resolve({ success: false, error: 'No room connection' });
            
            let resolved = false;
            let unsub = null;
            try {
                unsub = room.onMessage('channels', (data) => {
                    if (resolved) return;
                    resolved = true;
                    if (typeof unsub === 'function') unsub();
                    resolve({
                        success: true,
                        currentCh: room.state ? room.state.channel : (data ? data.current : 1),
                        data: data
                    });
                });
            } catch(e) {}
            
            try { room.send('channel_list'); } catch(e) {}
            
            setTimeout(() => {
                if (!resolved) {
                    resolved = true;
                    if (typeof unsub === 'function') unsub();
                    resolve({ success: false, error: 'Timeout waiting for channels' });
                }
            }, timeoutMs);
        });
    };

    // รายการ Channel ที่ปาร์ตี้อื่นของเรา (ใน Manager เดียวกัน) จอง/ใช้งานอยู่บนแมพเดียวกัน เพื่อไม่ให้แต่ละตี้ทับ Channel กัน
    window.getOtherPartyAvoidChannels = function(mapId = null, mapName = null, extraAvoid = null) {
        const avoid = new Set();
        if (Array.isArray(extraAvoid)) {
            for (const ch of extraAvoid) {
                const n = Number(ch);
                if (Number.isFinite(n) && n > 0) avoid.add(n);
            }
        }
        const sync = window.__pmPartySync;
        if (!sync || (Date.now() - (sync.updatedAt || 0) > 120000)) return avoid;
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        const curMapId = mapId || (room && room.state && room.state.mapId) || null;
        const curMapName = mapName || (room && room.state && room.state.displayName) || (typeof window.getCurrentMapName === 'function' ? window.getCurrentMapName() : null) || '';
        const cleanMapName = String(curMapName || '').replace(/\s*\(Lv\..*?\)/i, '').trim();

        const byMap = sync.otherPartyChannelsByMap;
        if (byMap && typeof byMap === 'object') {
            if (curMapId && Array.isArray(byMap[curMapId])) {
                for (const ch of byMap[curMapId]) {
                    const n = Number(ch);
                    if (Number.isFinite(n) && n > 0) avoid.add(n);
                }
            }
            if (cleanMapName && Array.isArray(byMap[cleanMapName])) {
                for (const ch of byMap[cleanMapName]) {
                    const n = Number(ch);
                    if (Number.isFinite(n) && n > 0) avoid.add(n);
                }
            }
            if (cleanMapName) {
                for (const [k, arr] of Object.entries(byMap)) {
                    if (!Array.isArray(arr) || !k) continue;
                    if (k.includes(cleanMapName) || cleanMapName.includes(k)) {
                        for (const ch of arr) {
                            const n = Number(ch);
                            if (Number.isFinite(n) && n > 0) avoid.add(n);
                        }
                    }
                }
            }
        }
        if (Array.isArray(sync.avoidChannels)) {
            const syncMapClean = String(sync.partyMapName || sync.forcedMap || '').replace(/\s*\(Lv\..*?\)/i, '').trim();
            if (!cleanMapName || !syncMapClean || cleanMapName.includes(syncMapClean) || syncMapClean.includes(cleanMapName) || (curMapId && sync.partyMapId && curMapId === sync.partyMapId)) {
                for (const ch of sync.avoidChannels) {
                    const n = Number(ch);
                    if (Number.isFinite(n) && n > 0) avoid.add(n);
                }
            }
        }
        return avoid;
    };

    window.findLeastPopulatedChannel = async function(extraAvoid = null) {
        const res = await window.getChannelsList(3500);
        if (!res.success || !res.data || !Array.isArray(res.data.channels)) {
            return null;
        }
        const list = res.data.channels;
        const hardCap = res.data.hardCap || 40;
        const available = list.filter(c => c.players < hardCap);
        if (available.length === 0) return res.data.current || 1;
        const avoid = window.getOtherPartyAvoidChannels(null, null, extraAvoid);
        const nonOverlap = available.filter(c => !avoid.has(Number(c.channel)));
        const pool = nonOverlap.length > 0 ? nonOverlap : available;
        pool.sort((a, b) => a.players - b.players || a.channel - b.channel);
        const avoidNote = avoid.size > 0 ? ` (หลบ CH ตี้อื่น: ${[...avoid].join(', ')})` : '';
        console.log(`%c[PmheeAether Channel] 📊 สแกน Channel: พบ CH ${pool[0].channel} คนน้อยสุด (${pool[0].players} คน)${avoidNote}`, 'color: #22c55e; font-weight: bold;');
        return pool[0].channel;
    };

    // ตรวจสอบ Channel ที่คนน้อยที่สุดสำหรับปาร์ตี้ 1 ครั้งเมื่อลงแมพฟาร์ม (ตัดสมาชิกปาร์ตี้ตัวเองออก และไม่ทับ CH ปาร์ตี้อื่นของเรา)
    window.evaluatePartyChannelSwitch = async function(partySize = 1, partyNames = [], extraAvoid = null) {
        const res = await window.getChannelsList(3500);
        if (!res || !res.success || !res.data || !Array.isArray(res.data.channels)) {
            return { success: false, error: 'no-channels' };
        }
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        const currentCh = (room && room.state && typeof room.state.channel === 'number') ? room.state.channel : (res.currentCh || res.data.current || 1);
        const mapId = (room && room.state && room.state.mapId) || null;
        const mapName = (room && room.state && room.state.displayName) || (typeof window.getCurrentMapName === 'function' ? window.getCurrentMapName() : null);
        const hardCap = res.data.hardCap || 40;
        const size = Math.max(1, Number(partySize) || 1);
        const partySet = new Set((Array.isArray(partyNames) ? partyNames : []).map(n => String(n || '').trim().toLowerCase()).filter(Boolean));
        try {
            const me = room && room.state && room.state.players && room.state.players.get ? room.state.players.get(room.sessionId) : null;
            if (me && me.name) partySet.add(String(me.name).trim().toLowerCase());
        } catch (e) {}

        let strangersInRoom = 0;
        let partyInRoom = 0;
        try {
            const players = room && room.state && room.state.players;
            if (players && typeof players.forEach === 'function') {
                players.forEach(p => {
                    if (!p || !p.name) return;
                    const nm = String(p.name).trim().toLowerCase();
                    if (partySet.has(nm)) partyInRoom++;
                    else strangersInRoom++;
                });
            }
        } catch (e) {}

        const list = res.data.channels;
        const curRow = list.find(c => c.channel === currentCh);
        const curTotal = curRow && typeof curRow.players === 'number' ? curRow.players : (strangersInRoom + Math.max(1, partyInRoom));
        const strangersOnCurrentCh = Math.max(strangersInRoom, Math.max(0, curTotal - Math.max(1, partyInRoom)));

        const avoid = window.getOtherPartyAvoidChannels(mapId, mapName, extraAvoid);
        const available = list.filter(c => (c.players + size) <= hardCap || c.players < hardCap);
        if (!available.length) {
            return { success: true, currentCh, channel: currentCh, strangersOnCurrentCh, bestPlayers: curTotal, shouldSwitch: false, avoidChannels: [...avoid] };
        }
        const nonOverlap = available.filter(c => !avoid.has(Number(c.channel)));
        const pool = nonOverlap.length > 0 ? nonOverlap : available;
        pool.sort((a, b) => a.players - b.players || a.channel - b.channel);
        const best = pool[0];
        const currentIsOverlapped = avoid.has(Number(currentCh)) && nonOverlap.length > 0;
        const shouldSwitch = Boolean(
            best &&
            best.channel !== currentCh &&
            (currentIsOverlapped || (strangersOnCurrentCh > 0 && best.players < strangersOnCurrentCh))
        );
        if (shouldSwitch) {
            if (currentIsOverlapped) {
                console.log(`%c[PmheeAether Party CH] 🚫 CH ${currentCh} มีปาร์ตี้อื่นของเราอยู่แล้ว -> ย้ายไป CH ${best.channel} ที่คนน้อยรองลงมา (${best.players} คน)`, 'color: #f59e0b; font-weight: bold;');
            } else {
                console.log(`%c[PmheeAether Party CH] 📊 CH ${currentCh} มีคนอื่น ${strangersOnCurrentCh} คน -> ย้ายไป CH ${best.channel} ที่คนน้อยสุด (${best.players} คน)`, 'color: #22c55e; font-weight: bold;');
            }
        } else {
            console.log(`%c[PmheeAether Party CH] ✅ ปักหลักที่ CH ${currentCh} (คนอื่น ${strangersOnCurrentCh} คน, CH ที่น้อยสุดคือ CH ${best ? best.channel : currentCh}: ${best ? best.players : 0} คน)`, 'color: #38bdf8; font-weight: bold;');
        }
        return {
            success: true,
            currentCh,
            channel: shouldSwitch ? best.channel : currentCh,
            bestChannel: best ? best.channel : currentCh,
            strangersOnCurrentCh,
            bestPlayers: best ? best.players : 0,
            currentIsOverlapped,
            avoidChannels: [...avoid],
            shouldSwitch
        };
    };

    // =========================================================================
    // POST-SELL / FARM-ARRIVAL CHANNEL CHECK & PARTY CHANNEL FOLLOW HELPERS
    // Modes: 'always' | 'all' (default) | 'party_only' | 'solo_only' | 'off'
    // =========================================================================
    (function initChannelCheckMode() {
        const VALID_MODES = ['always', 'all', 'party_only', 'solo_only', 'off'];
        let saved = 'all';
        try {
            const raw = localStorage.getItem('pelican_channel_check_mode');
            if (raw && VALID_MODES.includes(raw)) saved = raw;
        } catch (e) {}
        window.__channelCheckMode = saved;
    })();

    window.setChannelCheckMode = function(mode) {
        const VALID_MODES = ['always', 'all', 'party_only', 'solo_only', 'off'];
        const valid = VALID_MODES.includes(mode) ? mode : 'all';
        window.__channelCheckMode = valid;
        try { localStorage.setItem('pelican_channel_check_mode', valid); } catch (e) {}
        return { success: true, mode: valid };
    };

    window.findBestChannelAfterSell = async function(extraAvoid = null) {
        const res = await window.getChannelsList(3500);
        if (!res || !res.success || !res.data || !Array.isArray(res.data.channels)) {
            return { success: false, error: (res && res.error) || 'no-channels' };
        }
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        const currentCh = (room && room.state && typeof room.state.channel === 'number')
            ? room.state.channel
            : (res.currentCh || res.data.current || 1);
        const mapId = (room && room.state && room.state.mapId) || null;
        const mapName = (room && room.state && room.state.displayName)
            || (typeof window.getCurrentMapName === 'function' ? window.getCurrentMapName() : null);
        const hardCap = res.data.hardCap || 45;
        const avoid = window.getOtherPartyAvoidChannels(mapId, mapName, extraAvoid);

        let inGameParty = null;
        try {
            if (window.__pmPartyGetters && typeof window.__pmPartyGetters.party === 'function') {
                inGameParty = window.__pmPartyGetters.party();
            }
        } catch (e) {}
        const sync = window.__pmPartySync || null;
        const inParty = Boolean((inGameParty && Array.isArray(inGameParty.members) && inGameParty.members.length > 1) || (sync && sync.partyId));

        // Count how many of our own party members are currently on each channel of this map
        const partyCountByCh = {};
        let partySize = 1;
        if (inParty) {
            const seenNames = new Set();
            if (inGameParty && Array.isArray(inGameParty.members)) {
                for (const m of inGameParty.members) {
                    if (!m || m.online === false) continue;
                    const nm = String(m.name || '').trim().toLowerCase();
                    if (nm) seenNames.add(nm);
                    if ((!mapId || !m.mapId || m.mapId === mapId) && typeof m.channel === 'number') {
                        partyCountByCh[m.channel] = (partyCountByCh[m.channel] || 0) + 1;
                    }
                }
            }
            if (sync && Array.isArray(sync.partyNames)) {
                for (const nm of sync.partyNames) {
                    const clean = String(nm || '').trim().toLowerCase();
                    if (clean) seenNames.add(clean);
                }
            }
            if (sync && sync.ownPartyCountByCh && typeof sync.ownPartyCountByCh === 'object') {
                const samePartyMap = !mapId || !sync.partyMapId || sync.partyMapId === mapId;
                if (samePartyMap) {
                    for (const [chKey, cnt] of Object.entries(sync.ownPartyCountByCh)) {
                        const chNum = Number(chKey);
                        const cNum = Number(cnt) || 0;
                        if (Number.isFinite(chNum) && cNum > 0) {
                            partyCountByCh[chNum] = Math.max(partyCountByCh[chNum] || 0, cNum);
                        }
                    }
                }
            }
            partyCountByCh[currentCh] = Math.max(1, partyCountByCh[currentCh] || 0);
            partySize = Math.max(1, seenNames.size);
        } else {
            partyCountByCh[currentCh] = 1;
        }

        // Determine the primary channel where our party currently is (preferring channels not occupied by other parties)
        let mainPartyCh = (sync && typeof sync.settledChannel === 'number' && !avoid.has(Number(sync.settledChannel)))
            ? Number(sync.settledChannel)
            : currentCh;
        let maxPartyOnCh = 0;
        for (const [chKey, cnt] of Object.entries(partyCountByCh)) {
            const chNum = Number(chKey);
            if (avoid.has(chNum)) continue;
            if (cnt > maxPartyOnCh) {
                maxPartyOnCh = cnt;
                mainPartyCh = chNum;
            }
        }

        const list = res.data.channels;
        const annotated = list.map(c => {
            const chNum = Number(c.channel);
            const totalPlayers = Math.max(0, Number(c.players) || 0);
            const ownOnCh = partyCountByCh[chNum] || (chNum === currentCh ? 1 : 0);
            const effectiveOthers = Math.max(0, totalPlayers - ownOnCh);
            const extraNeeded = inParty ? Math.max(0, partySize - ownOnCh) : (chNum === currentCh ? 0 : 1);
            const hasRoom = (totalPlayers + extraNeeded) <= hardCap || totalPlayers < hardCap;
            return {
                channel: chNum,
                players: totalPlayers,
                ownOnCh,
                effectiveOthers,
                overlappedByOtherParty: avoid.has(chNum),
                hasRoom
            };
        });

        const curEntry = annotated.find(x => x.channel === currentCh) || {
            channel: currentCh,
            players: 0,
            ownOnCh: 1,
            effectiveOthers: 0,
            overlappedByOtherParty: avoid.has(Number(currentCh)),
            hasRoom: true
        };
        const available = annotated.filter(x => x.hasRoom);
        if (!available.length) {
            return {
                success: true,
                inParty,
                partySize,
                currentCh,
                targetCh: currentCh,
                bestChannel: currentCh,
                currentPlayers: curEntry.players,
                currentStrangers: curEntry.effectiveOthers,
                bestPlayers: curEntry.players,
                bestStrangers: curEntry.effectiveOthers,
                currentIsOverlapped: false,
                avoidChannels: [...avoid],
                shouldSwitch: false,
                mapId,
                mapName
            };
        }

        const nonOverlap = available.filter(x => !avoid.has(Number(x.channel)));
        const pool = nonOverlap.length > 0 ? nonOverlap : available;

        pool.sort((a, b) => {
            if (a.effectiveOthers !== b.effectiveOthers) return a.effectiveOthers - b.effectiveOthers;
            // Tie-breaker: prefer the channel where our party already is, then currentCh, then lowest channel number
            if (a.channel === mainPartyCh && b.channel !== mainPartyCh) return -1;
            if (b.channel === mainPartyCh && a.channel !== mainPartyCh) return 1;
            if (a.channel === currentCh && b.channel !== currentCh) return -1;
            if (b.channel === currentCh && a.channel !== currentCh) return 1;
            return a.channel - b.channel;
        });

        const best = pool[0];
        const currentIsOverlapped = avoid.has(Number(currentCh)) && nonOverlap.length > 0;
        const shouldSwitch = Boolean(
            best &&
            best.channel !== currentCh &&
            (currentIsOverlapped ||
             best.effectiveOthers < curEntry.effectiveOthers ||
             (inParty && best.channel === mainPartyCh && !avoid.has(Number(mainPartyCh)) && best.effectiveOthers === curEntry.effectiveOthers))
        );
        return {
            success: true,
            inParty,
            partySize,
            currentCh,
            targetCh: shouldSwitch ? best.channel : currentCh,
            bestChannel: best ? best.channel : currentCh,
            currentPlayers: curEntry.players,
            currentStrangers: curEntry.effectiveOthers,
            bestPlayers: best ? best.players : 0,
            bestStrangers: best ? best.effectiveOthers : 0,
            currentIsOverlapped,
            avoidChannels: [...avoid],
            shouldSwitch,
            mapId,
            mapName
        };
    };

    window.runPostSellChannelCheck = async function(reason = 'after-sell') {
        window.__pendingPostSellChannelCheck = false;
        window.__pendingPostSellAt = 0;
        window.__pendingPostSellReason = null;

        const mode = window.__channelCheckMode || 'all';
        if (mode === 'off') {
            return { skipped: true, reason: 'mode-off', mode };
        }
        if (typeof isCharacterInCity === 'function' && isCharacterInCity()) {
            return { skipped: true, reason: 'in-city', mode };
        }

        let inGameParty = null;
        try {
            if (window.__pmPartyGetters && typeof window.__pmPartyGetters.party === 'function') {
                inGameParty = window.__pmPartyGetters.party();
            }
        } catch (e) {}
        const sync = window.__pmPartySync || null;
        const inParty = Boolean((inGameParty && Array.isArray(inGameParty.members) && inGameParty.members.length > 1) || (sync && sync.partyId));

        if (mode === 'party_only' && !inParty) {
            return { skipped: true, reason: 'solo-in-party-only-mode', mode };
        }
        if (mode === 'solo_only' && inParty) {
            return { skipped: true, reason: 'party-in-solo-only-mode', mode };
        }
        if (mode !== 'always' && reason !== 'after-sell') {
            return { skipped: true, reason: 'non-sell-in-post-sell-mode', mode };
        }

        const reasonLabels = {
            'after-sell': 'หลังขายของกลับแมพ',
            'after-death': 'หลังตายกลับแมพฟาร์ม',
            'from-town': 'กลับจากเมืองถึงแมพฟาร์ม',
            'start-bot': 'เริ่มฟาร์มบนแมพ',
            'enter-farm-map': 'เข้าแมพฟาร์ม',
            'arrive-map': 'เดินทางถึงแมพฟาร์ม'
        };
        const reasonText = reasonLabels[reason] || 'กลับถึงแมพฟาร์ม';

        window.__isCheckingPostSellChannel = true;
        try {
            const roomNow = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
            const curMapId = (roomNow && roomNow.state && roomNow.state.mapId) || null;
            const curChNow = (roomNow && roomNow.state && typeof roomNow.state.channel === 'number') ? roomNow.state.channel : null;
            const avoidNow = window.getOtherPartyAvoidChannels(curMapId, null);

            // หากสมาชิกคนอื่นในปาร์ตี้เดียวกันเพิ่งสแกนและย้าย CH ของตี้ไปเมื่อไม่เกิน 18 วินาทีที่แล้ว ให้ย้ายตามเข้า CH ของตี้ทันทีโดยไม่แย่งย้ายซ้ำ
            if (
                inParty &&
                sync &&
                typeof sync.settledChannel === 'number' &&
                sync.lastPartyChannelSwitchAt &&
                (Date.now() - sync.lastPartyChannelSwitchAt < 18000) &&
                (!curMapId || !sync.partyMapId || sync.partyMapId === curMapId) &&
                !avoidNow.has(Number(sync.settledChannel))
            ) {
                const wantPartyCh = Number(sync.settledChannel);
                let finalCh = curChNow || wantPartyCh;
                let switched = false;
                if (curChNow !== wantPartyCh) {
                    console.log(`%c[PmheeAether Channel] 🤝 ${reasonText}: สมาชิกในตี้เพิ่งเลือก CH ${wantPartyCh} -> ย้ายตามไปรวมตี้ที่ CH ${wantPartyCh} ทันที...`, 'color: #22c55e; font-weight: bold;');
                    const mv = await window.moveToChannel(wantPartyCh, 45000);
                    const rAfter = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
                    finalCh = (mv && typeof mv.channel === 'number')
                        ? mv.channel
                        : ((rAfter && rAfter.state && typeof rAfter.state.channel === 'number') ? rAfter.state.channel : wantPartyCh);
                    switched = (finalCh !== curChNow);
                }
                return {
                    success: true,
                    joinedRecentPartySwitch: true,
                    channel: finalCh,
                    switched,
                    reason,
                    mode
                };
            }

            const plan = await window.findBestChannelAfterSell();
            if (!plan || !plan.success) {
                return { success: false, error: (plan && plan.error) || 'scan-failed' };
            }
            let finalCh = plan.currentCh;
            let switched = false;
            const avoidNote = Array.isArray(plan.avoidChannels) && plan.avoidChannels.length > 0
                ? ` [ไม่ทับ CH ตี้อื่น: ${plan.avoidChannels.join(', ')}]`
                : '';
            if (plan.shouldSwitch && plan.targetCh !== plan.currentCh) {
                if (plan.currentIsOverlapped) {
                    console.log(`%c[PmheeAether Channel] 🚫 ${reasonText} (${plan.mapName || ''}): CH ${plan.currentCh} มีปาร์ตี้อื่นของเราอยู่แล้ว -> ย้ายไป CH ${plan.targetCh} ที่คนน้อยรองลงมา (คนอื่น ${plan.bestStrangers} คน)${avoidNote}...`, 'color: #f59e0b; font-weight: bold;');
                } else {
                    console.log(`%c[PmheeAether Channel] 🔄 ${reasonText} (${plan.mapName || ''}): CH ${plan.currentCh} มีคนอื่น ${plan.currentStrangers} คน -> ย้ายไป CH ${plan.targetCh} ที่คนน้อยสุด (คนอื่น ${plan.bestStrangers} คน)${avoidNote}...`, 'color: #22c55e; font-weight: bold;');
                }
                const mv = await window.moveToChannel(plan.targetCh, 45000);
                const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
                finalCh = (mv && typeof mv.channel === 'number')
                    ? mv.channel
                    : ((room && room.state && typeof room.state.channel === 'number') ? room.state.channel : plan.currentCh);
                switched = (finalCh !== plan.currentCh);
            } else {
                console.log(`%c[PmheeAether Channel] ✅ ${reasonText} (${plan.mapName || ''}): CH ${plan.currentCh} คนน้อยสุดอยู่แล้ว (คนอื่น ${plan.currentStrangers} คน)${avoidNote} -> เริ่มฟาร์มทันที`, 'color: #38bdf8; font-weight: bold;');
            }
            const record = {
                channel: finalCh,
                previousChannel: plan.currentCh,
                switched,
                inParty: plan.inParty,
                partySize: plan.partySize,
                currentStrangers: plan.currentStrangers,
                bestStrangers: plan.bestStrangers,
                avoidChannels: plan.avoidChannels || [],
                mapId: plan.mapId,
                mapName: plan.mapName,
                reason,
                mode,
                at: Date.now()
            };
            window.__lastPostSellChannelSwitch = record;
            return Object.assign({ success: true }, record);
        } catch (err) {
            return { success: false, error: String((err && err.message) || err) };
        } finally {
            window.__isCheckingPostSellChannel = false;
        }
    };

    window.switchChannel = async function(targetCh, timeoutMs = 8000) {
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : (window.__gameRoom || (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null));
        if (!room) return { success: false, error: 'No room connection' };
        const target = parseInt(targetCh);
        if (isNaN(target)) return { success: false, error: 'Invalid channel number' };
        if (room.state && room.state.channel === target) {
            console.log(`%c[PmheeAether Channel] ℹ️ ตัวละครอยู่ที่ CH ${target} อยู่แล้ว`, 'color: #94a3b8;');
            return { success: true, alreadyThere: true, channel: target };
        }
        console.log(`%c[PmheeAether Channel] 🔄 กำลังย้ายไป Channel ${target}...`, 'color: #38bdf8; font-weight: bold;');
        room.send('channel_switch', { channel: target });
        
        const start = Date.now();
        while (Date.now() - start < timeoutMs) {
            await new Promise(r => setTimeout(r, 400));
            const curRoom = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
            if (curRoom && curRoom.state && curRoom.state.channel === target) {
                console.log(`%c[PmheeAether Channel] ✅ ย้ายไป CH ${target} สำเร็จ!`, 'color: #22c55e; font-weight: bold;');
                return { success: true, channel: target };
            }
        }
        return { success: false, error: 'Timeout waiting for channel switch', channel: room.state?.channel };
    };

    // Move to a channel and really get there: waits out the game's channel-switch cooldown and, when the
    // channel is full, waits for a free slot (the game's own picker disables both). Returns the channel the
    // character ended up on — callers must use that, not the one they asked for.
    window.moveToChannel = async function(targetCh, maxWaitMs = 90000) {
        const target = parseInt(targetCh);
        if (isNaN(target)) return { success: false, error: 'Invalid channel number' };
        const roomNow = () => (typeof window.getGameRoom === 'function') ? window.getGameRoom() : null;
        const current = () => { const r = roomNow(); return r && r.state && typeof r.state.channel === 'number' ? r.state.channel : null; };
        const start = Date.now();
        let lastReason = '';
        while (Date.now() - start < maxWaitMs) {
            if (current() === target) return { success: true, channel: target };
            const list = await window.getChannelsList(3500);
            const d = list && list.success ? list.data : null;
            if (d && d.cooldownUntil && d.cooldownUntil > Date.now()) {
                lastReason = 'ติดคูลดาวน์เปลี่ยน channel';
                const wait = Math.min(d.cooldownUntil - Date.now() + 600, maxWaitMs - (Date.now() - start));
                console.log(`[PmheeAether Channel] ⏳ รอคูลดาวน์เปลี่ยน channel ${Math.ceil(wait / 1000)} วิ`);
                if (wait > 0) await new Promise(r => setTimeout(r, wait));
                continue;
            }
            const row = d && Array.isArray(d.channels) ? d.channels.find(c => c.channel === target) : null;
            if (row && d.hardCap && row.players >= d.hardCap) {
                lastReason = `CH ${target} เต็ม`;
                console.log(`[PmheeAether Channel] ⏳ CH ${target} เต็ม (${row.players}/${d.hardCap}) -> รอที่ว่าง`);
                await new Promise(r => setTimeout(r, 5000));
                continue;
            }
            const r = await window.switchChannel(target, 9000);
            if (r && r.success) return { success: true, channel: target };
            lastReason = (r && r.error) || 'switch failed';
            await new Promise(r2 => setTimeout(r2, 3000));
        }
        return { success: false, error: lastReason || 'timeout', channel: current() };
    };

    // Walk up to another player on the same map + channel (server pathfinding via move_to), until within
    // `nearPx` (3 tiles). Used so a sender stands next to the receiver before asking to trade.
    window.walkToPlayer = async function(name, maxMs = 45000, nearPx = 96) {
        const want = String(name || '').trim().toLowerCase();
        if (!want) return { success: false, error: 'Missing name' };
        const start = Date.now();
        let lastSend = 0, seen = false;
        while (Date.now() - start < maxMs) {
            const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : null;
            const players = room && room.state && room.state.players;
            const me = players && players.get ? players.get(room.sessionId) : null;
            let target = null;
            if (players && players.forEach) players.forEach(p => { if (!target && p && String(p.name || '').trim().toLowerCase() === want) target = p; });
            if (me && target) {
                seen = true;
                const dist = Math.hypot((me.x || 0) - (target.x || 0), (me.y || 0) - (target.y || 0));
                if (dist <= nearPx) return { success: true, distance: Math.round(dist) };
                if (Date.now() - lastSend > 3000) {
                    lastSend = Date.now();
                    room.send('move_to', { x: target.x, y: target.y });
                }
            }
            await new Promise(r => setTimeout(r, 500));
        }
        return { success: false, error: seen ? 'เดินไปไม่ถึงตัวรับเงิน' : 'ไม่เห็นตัวรับเงินในแมพ/channel นี้' };
    };

    window.executeBwingHome = async function(timeoutMs = 12000) {
        window.__isConsolidating = true;
        window.__isBotRunning = false;
        window.__autoLoopEnabled = false;
        window.__isWalkingToMap = false;
        window.__isNavigating = false;
        if (typeof window.stopMasterBot === 'function') window.stopMasterBot();
        if (typeof window.stopFollow === 'function') window.stopFollow();
        
        const curMap = (typeof window.getCurrentMapName === 'function') ? window.getCurrentMapName() : '';
        if (curMap.includes('โซลเฮเวน') || curMap.includes('เมืองหลวง')) {
            console.log('%c[PmheeAether Bwing] 🏛️ ตัวละครอยู่ที่เมืองหลวงโซลเฮเวนอยู่แล้ว', 'color: #94a3b8;');
            return { success: true, alreadyHome: true, map: curMap };
        }

        window.keepFarmMapForTrip();   // put back by restoreKeptFarmMap when the bot starts again
        const how = window.goToCapital('รวมเงิน', { allowDuringConsolidation: true });
        if (how === 'walk' || how === 'walking') return { success: false, walking: true, error: 'ไม่มี Butterfly Wing — กำลังเดินกลับเมืองหลวง' };
        
        const start = Date.now();
        while (Date.now() - start < timeoutMs) {
            await new Promise(r => setTimeout(r, 500));
            const mapNow = (typeof window.getCurrentMapName === 'function') ? window.getCurrentMapName() : '';
            if (mapNow.includes('โซลเฮเวน') || mapNow.includes('เมืองหลวง')) {
                console.log('%c[PmheeAether Bwing] ✅ วาร์ปถึงเมืองหลวงโซลเฮเวนสำเร็จ!', 'color: #22c55e; font-weight: bold;');
                return { success: true, map: mapNow };
            }
        }
        return { success: false, error: 'Timeout waiting to arrive at capital' };
    };

    // ---- Zeny consolidation trades (driven one sender at a time by the Manager) ----
    // The game sends 'trade' = { partner, mine: {items, zeny, locked, confirmed}, theirs: {...}, expiresAt } while a
    // trade window is open and null when it closes. A trade counts as done only when the window closed after both
    // sides confirmed AND the zeny really changed. Each side acts only on a trade with the expected partner,
    // sends offer / lock / confirm once, and there is never more than one receiver watcher.
    const tradeRoom = () => (typeof window.getGameRoom === 'function') ? window.getGameRoom() : (typeof window.getColyseusRoom === 'function' ? window.getColyseusRoom() : null);
    const tradeZeny = () => Number(((typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {}).zeny);
    const sameName = (x, y) => String(x || '').trim().toLowerCase() === String(y || '').trim().toLowerCase();

    window.stopReceiverTradeWatcher = function () {
        if (typeof window.__receiverWatcherStop === 'function') window.__receiverWatcherStop('stopped');
        return true;
    };

    function getPlayerPixelPos(room) {
        const r = room || tradeRoom();
        const me = r && r.state && r.state.players && r.state.players.get(r.sessionId);
        if (me && Number.isFinite(me.x) && Number.isFinite(me.y)) {
            return { x: Number(me.x), y: Number(me.y) };
        }
        return null;
    }

    window.__readAuthoritativeBagInventory = function() {
        const root = document.querySelector('#root');
        const key = root ? Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber')) : null;
        const fiber = (root && key) ? root[key] : null;
        let invData = null;
        let visited = 0;
        function isRealBagInv(o) {
            return Boolean(
                o &&
                typeof o === 'object' &&
                Array.isArray(o.items) &&
                o.feeZeny === undefined &&
                (typeof o.weight === 'number' || typeof o.weightLimit === 'number')
            );
        }
        function walk(n, depth = 0) {
            if (!n || depth > 42 || invData || ++visited > 450) return;
            if (n.memoizedProps) {
                if (isRealBagInv(n.memoizedProps.inventory)) invData = n.memoizedProps.inventory;
                else if (isRealBagInv(n.memoizedProps)) invData = n.memoizedProps;
            }
            if (!invData && n.memoizedState) {
                let s = n.memoizedState;
                let steps = 0;
                while (s && ++steps < 30) {
                    const ms = s.memoizedState;
                    if (ms && typeof ms === 'object') {
                        if (isRealBagInv(ms.inventory)) { invData = ms.inventory; break; }
                        if (isRealBagInv(ms)) { invData = ms; break; }
                    }
                    s = s.next;
                }
            }
            if (n.child) walk(n.child, depth + 1);
            if (n.sibling) walk(n.sibling, depth + 1);
        }
        if (fiber) walk(fiber);
        if (invData) {
            window.__latestInventory = invData;
            try { localStorage.setItem('pelican_latest_inventory', JSON.stringify(invData)); } catch (_) {}
            return invData;
        }
        if (isRealBagInv(window.__latestInventory)) return window.__latestInventory;
        return null;
    };

    function getRealWeightInfo() {
        const inv = (typeof window.__readAuthoritativeBagInventory === 'function' ? window.__readAuthoritativeBagInventory() : window.__latestInventory) || {};
        const live = (typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {};
        const weight = Number(inv.weight ?? live.weight) || 0;
        const weightLimit = Number(inv.weightLimit ?? live.weightLimit) || 2000;
        const usedSlots = Array.isArray(inv.items) ? inv.items.filter(Boolean).length : 0;
        const maxSlots = Number(inv.slots) || 200;
        return { weight, weightLimit, usedSlots, maxSlots, inv };
    }

    function closeConsolidationStorageAndDialogs() {
        try {
            const stClose = document.querySelector('.storage-window .win-close');
            if (stClose) stClose.click();
            const dlgClose = document.querySelector('.npc-dialog .win-close');
            if (dlgClose) dlgClose.click();
            if (typeof window.closeShopUI === 'function') window.closeShopUI();
            if (typeof window.sendNpcClose === 'function') window.sendNpcClose();
        } catch (_) {}
    }

    // Helper: Get matching stash items currently in character bag
    window.getConsolidationMatchingBagItems = function(itemList) {
        const list = Array.isArray(itemList) ? itemList : (window.__stashTradeConfig && window.__stashTradeConfig.items) || [];
        const inv = (typeof window.__readAuthoritativeBagInventory === 'function') ? window.__readAuthoritativeBagInventory() : window.__latestInventory;
        const bag = (inv && Array.isArray(inv.items))
            ? inv.items.filter(Boolean)
            : ((typeof window.getBagItems === 'function') ? window.getBagItems() : []);
        const matched = [];
        let totalQty = 0;
        let totalWeight = 0;
        for (const it of bag) {
            if (!it || it.locked || it.equipped) continue;
            const raw = it.raw || it;
            if (!window.matchesStashItemList(raw, list)) continue;
            const qty = Math.max(1, Number(it.qty ?? raw.qty ?? 1) || 1);
            const unitW = Math.max(0, Number(raw.weight ?? it.weight ?? 1) || 1);
            matched.push({
                slot: Number(it.slot ?? raw.slot),
                id: raw.itemId ?? raw.id ?? it.itemId ?? it.id,
                name: it.name || raw.name || 'Item',
                qty,
                unitWeight: unitW,
                totalWeight: qty * unitW
            });
            totalQty += qty;
            totalWeight += qty * unitW;
        }
        matched.sort((a, b) => (b.qty || 0) - (a.qty || 0));
        return { items: matched, totalQty, totalWeight };
    };

    // Helper: Quick sell trash at capital shop before withdrawing stash items during consolidation
    // Skips walking to Shopkeeper Bor if bag already has plenty of free weight and character has >= 40z storage fee
    window.runConsolidationQuickSellTrash = async function(timeoutMs = 28000) {
        try {
            const wBefore = getRealWeightInfo();
            const liveBefore = (typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {};
            const zenyBefore = Number(liveBefore.zeny ?? window.__currentZeny) || 0;
            const freeWeight = Math.max(0, wBefore.weightLimit - wBefore.weight);
            const heavyRatio = wBefore.weightLimit > 0 ? (wBefore.weight / wBefore.weightLimit) : 0;
            const freeSlots = Math.max(0, wBefore.maxSlots - wBefore.usedSlots);
            if (freeWeight >= 800 && heavyRatio < 0.80 && freeSlots > 4 && zenyBefore >= 40) {
                return {
                    success: true,
                    skipped: true,
                    sold: false,
                    weight: wBefore.weight,
                    weightLimit: wBefore.weightLimit,
                    zeny: zenyBefore
                };
            }
            if (typeof window.triggerAutoSellTrash !== 'function') {
                return { success: true, skipped: true, sold: false, weight: wBefore.weight, weightLimit: wBefore.weightLimit, zeny: zenyBefore };
            }
            window.triggerAutoSellTrash();
            await new Promise(r => setTimeout(r, 900));
            const start = Date.now();
            while (Date.now() - start < timeoutMs) {
                if (!window.__isShopping && !window.__isNavigating) break;
                await new Promise(r => setTimeout(r, 500));
            }
            closeConsolidationStorageAndDialogs();
            const live = (typeof window.getLiveCharacterData === 'function' && window.getLiveCharacterData()) || {};
            const wInfo = getRealWeightInfo();
            return {
                success: true,
                sold: true,
                weight: wInfo.weight,
                weightLimit: wInfo.weightLimit,
                zeny: Number(live.zeny) || 0
            };
        } catch (err) {
            return { success: false, error: err.message };
        }
    };

    // Helper: Walk to capital storage & withdraw matching items into bag (respecting weight limit)
    window.withdrawConsolidationItemsFromStorage = async function(itemList) {
        const list = Array.isArray(itemList) && itemList.length > 0
            ? itemList
            : ((window.__stashTradeConfig && window.__stashTradeConfig.items) || ['Enchant Rune']);
        const room = tradeRoom();
        if (!room) return { success: false, error: 'No room connection', withdrawnQty: 0 };

        try {
            let st = (typeof window.openStorageWindow === 'function')
                ? await window.openStorageWindow(room, () => false)
                : null;
            if (!st || !Array.isArray(st.items)) {
                closeConsolidationStorageAndDialogs();
                return { success: false, error: 'เปิดคลังไม่สำเร็จ (ตรวจดูว่าตัวละครมีเงิน >= 40z และอยู่ในเมืองหลวง)', withdrawnQty: 0 };
            }

            let withdrawnQty = 0;
            const withdrawnDetails = [];

            for (let pass = 0; pass < 60; pass++) {
                const wInfo = getRealWeightInfo();
                const safeAvailWeight = Math.max(0, wInfo.weightLimit - wInfo.weight - 20); // Leave 20 weight safety margin
                if (safeAvailWeight <= 0) break;

                if (wInfo.maxSlots > 0 && wInfo.usedSlots >= wInfo.maxSlots - 1) break;

                const stItems = Array.isArray(st.items) ? st.items : [];
                const candidates = stItems
                    .filter(it => it && window.matchesStashItemList(it, list) && (Number(it.qty) || 0) > 0)
                    .sort((a, b) => (Number(b.qty) || 0) - (Number(a.qty) || 0));
                const target = candidates[0];
                if (!target) break;

                const unitW = Math.max(0.1, Number(target.weight) || 1);
                const maxByWeight = unitW > 0 ? Math.floor(safeAvailWeight / unitW) : target.qty;
                const takeQty = Math.min(Number(target.qty) || 1, maxByWeight);
                if (takeQty <= 0) break;

                const nextPromise = new Promise(resolve => {
                    let done = false;
                    const unsub = room.onMessage('storage', msg => {
                        if (done) return;
                        done = true;
                        if (typeof unsub === 'function') unsub();
                        resolve(msg);
                    });
                    setTimeout(() => {
                        if (done) return;
                        done = true;
                        if (typeof unsub === 'function') unsub();
                        resolve(null);
                    }, 3500);
                });

                room.send('storage_take', { slot: Number(target.slot), qty: Number(takeQty) });
                const updated = await nextPromise;
                withdrawnQty += takeQty;
                withdrawnDetails.push(`${target.name || 'Item'} x${takeQty}`);
                if (updated && Array.isArray(updated.items)) {
                    st = updated;
                } else {
                    await new Promise(r => setTimeout(r, 400));
                    break;
                }
                await new Promise(r => setTimeout(r, 220));
            }

            closeConsolidationStorageAndDialogs();
            if (withdrawnQty > 0) {
                try { room.send('inv_sort', {}); } catch (e) {}
                await new Promise(r => setTimeout(r, 500));
            }
            const bagMatch = window.getConsolidationMatchingBagItems(list);
            const wAfter = getRealWeightInfo();
            return {
                success: true,
                withdrawnQty,
                withdrawnDetails,
                bagMatchingQty: bagMatch.totalQty,
                bagMatchingWeight: bagMatch.totalWeight,
                weight: wAfter.weight,
                weightLimit: wAfter.weightLimit
            };
        } catch (err) {
            closeConsolidationStorageAndDialogs();
            return { success: false, error: err.message, withdrawnQty: 0 };
        }
    };

    // Helper: Walk to capital storage & deposit matching items from bag into storage (used by Receiver when bag gets heavy or after consolidation)
    window.depositConsolidationItemsToStorage = async function(itemList, returnTileCoords = null) {
        const list = Array.isArray(itemList) && itemList.length > 0
            ? itemList
            : ((window.__stashTradeConfig && window.__stashTradeConfig.items) || ['Enchant Rune']);
        const room = tradeRoom();
        if (!room) return { success: false, error: 'No room connection', depositedQty: 0 };

        const beforePos = getPlayerPixelPos(room);
        try {
            let st = (typeof window.openStorageWindow === 'function')
                ? await window.openStorageWindow(room, () => false)
                : null;
            if (!st || !Array.isArray(st.items)) {
                closeConsolidationStorageAndDialogs();
                return { success: false, error: 'เปิดคลังไม่สำเร็จ', depositedQty: 0 };
            }

            let depositedQty = 0;
            for (let pass = 0; pass < 40; pass++) {
                const bagMatch = window.getConsolidationMatchingBagItems(list);
                const it = bagMatch.items[0];
                if (!it || !Number.isFinite(it.slot) || it.qty <= 0) break;

                const nextPromise = new Promise(resolve => {
                    let done = false;
                    const unsub = room.onMessage('storage', msg => {
                        if (done) return;
                        done = true;
                        if (typeof unsub === 'function') unsub();
                        resolve(msg);
                    });
                    setTimeout(() => {
                        if (done) return;
                        done = true;
                        if (typeof unsub === 'function') unsub();
                        resolve(null);
                    }, 3000);
                });

                room.send('storage_put', { slot: Number(it.slot), qty: Number(it.qty) });
                depositedQty += it.qty;
                await nextPromise;
                await new Promise(r => setTimeout(r, 240));
            }
            closeConsolidationStorageAndDialogs();

            // Walk back to trade spot if requested
            const backTarget = returnTileCoords || beforePos;
            if (backTarget && Number.isFinite(backTarget.x) && Number.isFinite(backTarget.y)) {
                const tx = backTarget.x > 250 ? backTarget.x : (backTarget.x * 32 + 16);
                const ty = backTarget.y > 250 ? backTarget.y : (backTarget.y * 32 + 16);
                room.send('move_to', { x: tx, y: ty });
                const backStart = Date.now();
                while (Date.now() - backStart < 12000) {
                    await new Promise(r => setTimeout(r, 350));
                    const p = getPlayerPixelPos(room);
                    if (p && Math.hypot(p.x - tx, p.y - ty) <= 96) break;
                }
            }

            const wAfter = getRealWeightInfo();
            return {
                success: true,
                depositedQty,
                weight: wAfter.weight,
                weightLimit: wAfter.weightLimit
            };
        } catch (err) {
            closeConsolidationStorageAndDialogs();
            return { success: false, error: err.message, depositedQty: 0 };
        }
    };

    window.setupReceiverTradeWatcher = function(allowedSenderName, timeoutMs = 60000) {
        // a new sender replaces the previous watcher (old ones used to keep answering for 40 s)
        window.stopReceiverTradeWatcher();
        return new Promise((resolve) => {
            const room = tradeRoom();
            if (!room) return resolve({ success: false, error: 'No room connection' });
            const expected = allowedSenderName ? String(allowedSenderName).trim() : '';
            if (!expected) return resolve({ success: false, error: 'Missing sender name' });

            window.__consolidationReceiverMode = true;
            window.__consolidationExpectedSender = expected.toLowerCase();
            console.log(`%c[PmheeAether Trade] 👑 Receiver Standby: รอรับคำขอเทรดจาก '${expected}'...`, 'color: #a855f7; font-weight: bold;');

            const zenyBefore = tradeZeny();
            let accepted = false, lockSent = false, confirmSent = false, finished = false, receivedOffer = 0, receivedItemsCount = 0;
            let unsubInvite = null, unsubTrade = null;

            const finish = (result) => {
                if (finished) return;
                finished = true;
                clearTimeout(timer);
                if (typeof unsubInvite === 'function') unsubInvite();
                if (typeof unsubTrade === 'function') unsubTrade();
                if (window.__receiverWatcherStop === stop) {
                    window.__receiverWatcherStop = null;
                    window.__consolidationReceiverMode = false;
                    window.__consolidationExpectedSender = null;
                }
                resolve(result);
            };
            const stop = reason => finish({ success: false, error: `Receiver watcher ${reason}` });
            window.__receiverWatcherStop = stop;
            const timer = setTimeout(() => finish({ success: false, error: 'Receiver timeout waiting for trade' }), timeoutMs);

            unsubInvite = room.onMessage('invite', (inv) => {
                if (finished || !inv || inv.kind !== 'trade' || accepted) return;
                if (!sameName(inv.from, expected)) {
                    console.log(`[PmheeAether Trade] 👑 Receiver: ไม่รับคำขอเทรดจาก ${inv.from} (รอ ${expected})`);
                    return;
                }
                accepted = true;
                console.log(`%c[PmheeAether Trade] 👑 Receiver: ได้รับคำขอเทรดจาก ${inv.from} -> ตอบรับ (accept)`, 'color: #22c55e; font-weight: bold;');
                room.send('trade', { action: 'accept' });
            });

            unsubTrade = room.onMessage('trade', (tr) => {
                if (finished) return;
                if (!tr) {
                    // window closed: done if we confirmed and the zeny/items arrived, else the sender cancelled
                    if (!confirmSent) { accepted = false; lockSent = false; return; }
                    setTimeout(() => {
                        const now = tradeZeny();
                        const got = (isFinite(now) && isFinite(zenyBefore)) ? now - zenyBefore : receivedOffer;
                        finish((got > 0 || receivedItemsCount > 0)
                            ? { success: true, receivedZeny: Math.max(0, got), receivedItemsCount }
                            : { success: false, error: 'หน้าต่างเทรดปิดแต่เงิน/ไอเทมไม่เข้า' });
                    }, 1200);
                    return;
                }
                if (!sameName(tr.partner, expected)) return;
                if (tr.theirs && typeof tr.theirs.zeny === 'number') receivedOffer = tr.theirs.zeny;
                if (tr.theirs && Array.isArray(tr.theirs.items)) {
                    receivedItemsCount = tr.theirs.items.reduce((sum, x) => sum + (Number(x && x.qty) || 0), 0);
                }
                if (tr.theirs && tr.theirs.locked && tr.mine && !tr.mine.locked && !lockSent) {
                    lockSent = true;
                    const itemNote = receivedItemsCount > 0 ? ` + ไอเทม ${receivedItemsCount} ชิ้น` : '';
                    console.log(`%c[PmheeAether Trade] 👑 Receiver: อีกฝ่ายล็อคแล้ว (เสนอ ${Number(tr.theirs.zeny || 0).toLocaleString()} z${itemNote}) -> ล็อค`, 'color: #38bdf8;');
                    setTimeout(() => { if (!finished) room.send('trade', { action: 'lock' }); }, 300);
                }
                if (tr.theirs && tr.theirs.locked && tr.mine && tr.mine.locked && !tr.mine.confirmed && !confirmSent) {
                    confirmSent = true;
                    console.log('%c[PmheeAether Trade] 👑 Receiver: ทั้งสองฝ่ายล็อคแล้ว -> ยืนยัน (confirm)', 'color: #22c55e; font-weight: bold;');
                    setTimeout(() => { if (!finished) room.send('trade', { action: 'confirm' }); }, 400);
                }
            });
        });
    };

    window.executeSenderTrade = function(receiverCharName, zenyAmount, timeoutMs = 45000, itemNamesToOffer = null, maxReceiverExtraWeight = null) {
        // one trade at a time per client: a second call while one runs must not send another request
        if (window.__senderTradeBusy) return Promise.resolve({ success: false, error: 'กำลังเทรดอยู่แล้ว (ไม่ส่งซ้ำ)' });
        return new Promise((resolve) => {
            const room = tradeRoom();
            if (!room) return resolve({ success: false, error: 'No room connection' });
            if (!receiverCharName) return resolve({ success: false, error: 'Missing receiver name' });
            const amount = Math.max(0, parseInt(zenyAmount) || 0);
            const zenyBefore = tradeZeny();
            if (isFinite(zenyBefore) && amount > zenyBefore) return resolve({ success: false, error: `เงินไม่พอ (มี ${zenyBefore.toLocaleString()} z)` });

            // Build items offer array (up to 10 trade slots, respecting receiver available weight if provided)
            const offerItems = [];
            let offerItemsTotalQty = 0;
            if (Array.isArray(itemNamesToOffer) && itemNamesToOffer.length > 0 && typeof window.getConsolidationMatchingBagItems === 'function') {
                const bagMatch = window.getConsolidationMatchingBagItems(itemNamesToOffer);
                let remWeight = (typeof maxReceiverExtraWeight === 'number' && Number.isFinite(maxReceiverExtraWeight))
                    ? Math.max(0, maxReceiverExtraWeight)
                    : Infinity;
                for (const it of bagMatch.items) {
                    if (offerItems.length >= 10) break;
                    if (!Number.isFinite(it.slot) || it.qty <= 0) continue;
                    const unitW = Math.max(0, Number(it.unitWeight) || 1);
                    const allowedQty = (unitW > 0 && Number.isFinite(remWeight))
                        ? Math.min(it.qty, Math.floor(remWeight / unitW))
                        : it.qty;
                    if (allowedQty <= 0) continue;
                    offerItems.push({ slot: Number(it.slot), qty: Number(allowedQty) });
                    offerItemsTotalQty += allowedQty;
                    if (Number.isFinite(remWeight)) remWeight = Math.max(0, remWeight - allowedQty * unitW);
                }
            }

            if (amount <= 0 && offerItems.length === 0) {
                return resolve({ success: false, error: 'ไม่มีเงินหรือไอเทมที่จะเทรด' });
            }

            const bagMatchBefore = (offerItems.length > 0 && typeof window.getConsolidationMatchingBagItems === 'function')
                ? window.getConsolidationMatchingBagItems(itemNamesToOffer).totalQty
                : 0;

            window.__senderTradeBusy = true;
            const itemDesc = offerItemsTotalQty > 0 ? ` + ไอเทม ${offerItemsTotalQty} ชิ้น` : '';
            console.log(`%c[PmheeAether Trade] 📤 Sender: เริ่มเทรดเงิน ${amount.toLocaleString()} z${itemDesc} ให้ '${receiverCharName}'...`, 'color: #38bdf8; font-weight: bold;');

            let opened = false, offerSent = false, lockSent = false, confirmSent = false, finished = false;
            let unsubTrade = null;
            const finish = (result) => {
                if (finished) return;
                finished = true;
                clearTimeout(timer);
                clearTimeout(noAnswer);
                if (typeof unsubTrade === 'function') unsubTrade();
                window.__senderTradeBusy = false;
                resolve(result);
            };
            const timer = setTimeout(() => {
                try { room.send('trade', { action: 'cancel' }); } catch (e) {}
                finish({ success: false, error: 'Sender timeout in trade process' });
            }, timeoutMs);
            // the receiver never opened the trade: give up instead of asking again
            const noAnswer = setTimeout(() => {
                if (!opened) finish({ success: false, error: 'ตัวรับไม่ตอบรับคำขอเทรด (ไม่ได้ส่งคำขอซ้ำ)' });
            }, 12000);

            unsubTrade = room.onMessage('trade', (tr) => {
                if (finished) return;
                if (!tr) {
                    if (!opened) return;
                    if (!confirmSent) return finish({ success: false, error: 'อีกฝ่ายยกเลิก/ปิดหน้าต่างเทรด' });
                    setTimeout(() => {
                        const now = tradeZeny();
                        const sent = (isFinite(now) && isFinite(zenyBefore)) ? zenyBefore - now : null;
                        const bagMatchAfter = (offerItems.length > 0 && typeof window.getConsolidationMatchingBagItems === 'function')
                            ? window.getConsolidationMatchingBagItems(itemNamesToOffer).totalQty
                            : 0;
                        const sentItems = Math.max(0, bagMatchBefore - bagMatchAfter);
                        if (sent === null && offerItems.length === 0) {
                            finish({ success: true, transferredZeny: amount, transferredItemsQty: offerItemsTotalQty, unverified: true });
                        } else if ((sent !== null && sent > 0) || sentItems > 0) {
                            finish({ success: true, transferredZeny: Math.max(0, sent || 0), transferredItemsQty: sentItems });
                        } else {
                            finish({ success: false, error: 'หน้าต่างเทรดปิดแต่เงิน/ไอเทมไม่ลด (เทรดไม่สำเร็จ)' });
                        }
                    }, 1200);
                    return;
                }
                if (!sameName(tr.partner, receiverCharName)) return;
                opened = true;
                if (!offerSent) {
                    offerSent = true;
                    console.log(`%c[PmheeAether Trade] 📤 Sender: ใส่ข้อเสนอ ${amount.toLocaleString()} z${itemDesc}`, 'color: #38bdf8;');
                    setTimeout(() => { if (!finished) room.send('trade', { action: 'offer', items: offerItems, zeny: amount }); }, 350);
                    return;
                }
                const zenyMatched = tr.mine && tr.mine.zeny === amount;
                const itemsMatched = offerItems.length === 0 || (tr.mine && Array.isArray(tr.mine.items) && tr.mine.items.length === offerItems.length);
                if (!lockSent && zenyMatched && itemsMatched && !tr.mine.locked) {
                    lockSent = true;
                    console.log('%c[PmheeAether Trade] 📤 Sender: ล็อคข้อเสนอ (lock)', 'color: #38bdf8;');
                    setTimeout(() => { if (!finished) room.send('trade', { action: 'lock' }); }, 400);
                    return;
                }
                if (lockSent && !confirmSent && tr.mine && tr.mine.locked && tr.theirs && tr.theirs.locked && !tr.mine.confirmed) {
                    confirmSent = true;
                    console.log('%c[PmheeAether Trade] 📤 Sender: ทั้งสองฝ่ายล็อคแล้ว -> ยืนยัน (confirm)', 'color: #22c55e; font-weight: bold;');
                    setTimeout(() => { if (!finished) room.send('trade', { action: 'confirm' }); }, 400);
                }
            });

            setTimeout(() => {
                if (finished) return;
                console.log(`%c[PmheeAether Trade] 📤 Sender: ส่งคำขอเทรดไปยัง '${receiverCharName}' (ครั้งเดียว)`, 'color: #38bdf8;');
                room.send('trade', { action: 'request', name: receiverCharName });
            }, 600);
        });
    };

    // MULTI-CLIENT HUB REAL-TIME STATE SYNC
    // ==========================================
    window.__getClientLiveState = function() {
        // 1. Character Name, Class & Levels
        const nameEl = document.querySelector('.hud-name');
        const classEl = document.querySelector('.hud-class');
        const levelsEl = document.querySelector('.hud-levels');
        
        // 2. HP & SP
        const hpBar = document.querySelector('.bar-fill.bar-hp')?.closest('.bar');
        const hpText = hpBar?.querySelector('.bar-num')?.innerText?.trim() || null;
        const spBar = document.querySelector('.bar-fill.bar-sp')?.closest('.bar');
        const spText = spBar?.querySelector('.bar-num')?.innerText?.trim() || null;
        
        let hpCurrent = null, hpMax = null;
        if (hpText) {
            const m = hpText.match(/(\d+)\s*\/\s*(\d+)/);
            if (m) { hpCurrent = Number(m[1]); hpMax = Number(m[2]); }
        }
        let spCurrent = null, spMax = null;
        if (spText) {
            const m = spText.match(/(\d+)\s*\/\s*(\d+)/);
            if (m) { spCurrent = Number(m[1]); spMax = Number(m[2]); }
        }

        // 3. Map Name
        let mapName = null;
        const footer = document.querySelector('.minimap-footer');
        if (footer) {
            const spans = Array.from(footer.querySelectorAll('span, div')).map(s => s.innerText.trim()).filter(Boolean);
            const foundMap = spans.find(t => t.length > 2 && !t.includes(',') && !/^CH\s*\d+/i.test(t) && !/^\d+%?$/.test(t));
            if (foundMap) mapName = foundMap;
        }
        if (!mapName && typeof window.getCurrentMapName === 'function') {
            mapName = window.getCurrentMapName();
        }

        // 4. Pos
        const pos = window.__currentPos || { x: 0, y: 0, tileX: 0, tileY: 0 };
        
        // 5. Ammo, Weight & Zeny
        const ammo = (typeof window.__currentAmmo === 'number') ? window.__currentAmmo : 0;
        const weightText = document.getElementById('p-quick-weight')?.innerText?.replace('⚖️', '')?.trim() || null;
        let currentZeny = window.__currentZeny;
        if (typeof currentZeny !== 'number' && typeof window.tryRecoverCharacterFromPackets === 'function') {
            currentZeny = window.tryRecoverCharacterFromPackets();
        }

        // 6. Bot Status & Actions
        const hudState = document.getElementById('p-char-state')?.innerText?.trim();
        let activity = '🟢 ยืนรอ / แสตนด์บาย';
        if (window.__isRecovering) activity = '⚠️ กำลังชุบชีวิต';
        else if (window.__isShopping) activity = '🛒 ซื้อ/ขายของที่ NPC';
        else if (window.__isCheckingPostSellChannel) activity = '📡 กำลังเลือก CH ที่คนน้อยสุด...';
        else if (window.__isNavigating) activity = '🚶 กำลังเดินทาง';
        else if (window.__unexpectedTownWaiting) {
            const remSec = Math.max(0, Math.ceil(((window.__unexpectedTownWaitUntil || 0) - Date.now()) / 1000));
            activity = `🛡️ พักรอนิรภัย (${Math.floor(remSec / 60)}:${String(remSec % 60).padStart(2, '0')})`;
        }
        else if (window.__isHumanizing) activity = '🎭 กิจกรรมเสมือนคน';
        else if (window.__isBotRunning) activity = '⚔️ Auto-Farm ทำงาน';   // the 24h-loop switch alone is not running
        else if (hudState) activity = hudState;

        const liveChar = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        const rawClassText = classEl?.innerText?.trim() || null;
        const cId = liveChar.classId || (rawClassText ? rawClassText.toLowerCase() : null);
        const faceUrl = cId ? `https://www.aetheria-online.in.th/art/classes/${cId}-face.webp` : null;
        const fullArtUrl = cId ? `https://www.aetheria-online.in.th/art/classes/${cId}.webp` : null;

        const premUntil = (typeof window.getCharacterPremiumUntil === 'function')
            ? window.getCharacterPremiumUntil()
            : (Number(liveChar.premiumUntil) || Number(window.__gameRoom?.state?.players?.get?.(window.__gameRoom?.sessionId)?.premiumUntil) || 0);
        const hasPremium = (typeof window.hasCharacterPremium === 'function')
            ? window.hasCharacterPremium()
            : (premUntil > Date.now() || Boolean(document.querySelector('.hud-buff-icon[title*="Premium" i], .hud-buff-icon[title*="พรีเมียม" i], .buff-icon[title*="Premium" i], [data-buff*="premium" i]')));

        const resolvedCharName = nameEl?.innerText?.trim() || window.__gameRoom?.state?.players?.get?.(window.__gameRoom?.sessionId)?.name || liveChar.name || liveChar.charName || window.__charName || null;
        if (resolvedCharName) window.__charName = resolvedCharName;

        const authCfg = window.__authConfig || {};
        const domAuthUser = document.getElementById('p-auth-user')?.value?.trim() || '';
        const domAuthPass = document.getElementById('p-auth-pass')?.value || '';
        const domAuthChar = document.getElementById('p-auth-char')?.value?.trim() || '';
        if (domAuthUser && !authCfg.username) {
            authCfg.username = domAuthUser;
            authCfg.userEditedAt = authCfg.userEditedAt || Date.now();
            authCfg.generatedUser = false;
            authCfg.register = false;
        }
        if (domAuthPass && !authCfg.password) {
            authCfg.password = domAuthPass;
            authCfg.userEditedAt = authCfg.userEditedAt || Date.now();
            authCfg.generatedUser = false;
            authCfg.register = false;
        }
        if (domAuthChar && !authCfg.charName) {
            authCfg.charName = domAuthChar;
        }

        return {
            charName: resolvedCharName,
            charClass: rawClassText || liveChar.className || (cId ? (cId.charAt(0).toUpperCase() + cId.slice(1)) : null),
            classId: cId,
            portrait: faceUrl,
            fullPortrait: fullArtUrl,
            levels: levelsEl?.innerText?.trim() || '',
            baseLv: liveChar.baseLevel || null,
            jobLv: liveChar.jobLevel || null,
            hp: hpCurrent,
            hpMax: hpMax,
            hpText: hpText,
            sp: spCurrent,
            spMax: spMax,
            spText: spText,
            map: mapName || 'ไม่ทราบแมพ',
            targetMap: window.__targetFarmMap || null,
            pos: pos,
            coords: pos.tileX ? (pos.tileX + ', ' + pos.tileY + ' (' + pos.x + ', ' + pos.y + ')') : (pos.x ? (pos.x + ', ' + pos.y) : '--'),
            ammo: ammo,
            weight: weightText,
            zeny: (typeof currentZeny === 'number') ? currentZeny : null,
            zenyText: (typeof currentZeny === 'number') ? (currentZeny.toLocaleString() + ' z') : '--',
            grossZenyGained: (typeof window.__grossZenyGained === 'number' && Number.isFinite(window.__grossZenyGained)) ? window.__grossZenyGained : null,
            consolidationReceiverMode: Boolean(window.__consolidationReceiverMode || window.__isConsolidating),
            channel: (typeof window.getCurrentChannel === 'function') ? window.getCurrentChannel() : 1,
            channelText: 'CH ' + ((typeof window.getCurrentChannel === 'function') ? window.getCurrentChannel() : 1),
            botStatus: activity,
            navigating: !!window.__isNavigating,
            recovering: !!window.__isRecovering,
            shopping: !!window.__isShopping,
            unexpectedTown: window.__unexpectedTownWaiting ? {
                waiting: true,
                reason: window.__unexpectedTownReason || 'กลับเมืองโดยไม่ทราบสาเหตุ',
                remainingSec: Math.max(0, Math.ceil(((window.__unexpectedTownWaitUntil || 0) - Date.now()) / 1000)),
                waitUntil: window.__unexpectedTownWaitUntil || 0
            } : null,
            humanizing: !!window.__isHumanizing,
            autoLoop: !!window.__autoLoopEnabled,
            isBotRunning: !!window.__isBotRunning,
            zeroRender: !!window.__pmZeroRender,
            hasSocket: !!window.__gameSocket,
            hasInventory: !!window.__latestInventory,
            premiumUntil: premUntil,
            hasPremium: hasPremium,
            authConfig: {
                enabled: !!authCfg.enabled,
                username: String(authCfg.username || '').trim(),
                password: String(authCfg.password || ''),
                charName: String(authCfg.charName || '').trim(),
                generatedUser: !!authCfg.generatedUser,
                register: !!authCfg.register,
                registerDone: !!authCfg.registerDone,
                registerError: String(authCfg.registerError || ''),
                userEditedAt: Number(authCfg.userEditedAt) || 0,
                verifiedLoginAt: Number(authCfg.verifiedLoginAt) || 0
            },
            isOnline: true
        };
    };

    // ==========================================
    // FULL CHARACTER SHEET & EQUIPMENT MANAGEMENT ENGINE
    // ==========================================
    window.getCharacterFullDetail = function() {
        const char = (typeof window.getLiveCharacterData === 'function' ? window.getLiveCharacterData() : null) || window.__latestCharacterData || {};
        const bag = (typeof window.getBagItems === 'function' ? window.getBagItems() : []);
        
        const classId = char.classId || (char.className ? char.className.toLowerCase() : 'hunter');
        const faceAvatar = `https://www.aetheria-online.in.th/art/classes/${classId}-face.webp`;
        const fullPortrait = `https://www.aetheria-online.in.th/art/classes/${classId}.webp`;

        // Icon paths come from the game's icon manifest (by itemId); names alone often don't match
        // the file (e.g. Formal Suit -> items/rogear-formal-suit.webp). Always return absolute URLs
        // because the Manager renders these outside the game origin.
        const resolveCharIcon = (it) => {
            if (!it) return null;
            const url = (typeof window.getItemIconUrl === 'function') ? window.getItemIconUrl(it) : null;
            if (url) return new URL(url, 'https://www.aetheria-online.in.th').href;
            if (!it.name) return null;
            const slug = String(it.name).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
            return `https://www.aetheria-online.in.th/art/icons/items/${slug}.webp`;
        };

        // Process all equippable items in inventory bag
        const equippableBag = bag.map(b => {
            const raw = b.raw || {};
            const iconUrl = resolveCharIcon({ ...raw, itemId: raw.itemId ?? b.id, name: raw.name || b.name });
            return {
                slot: b.slot,
                itemId: b.id,
                name: b.name,
                qty: b.qty,
                type: raw.type || 'Equipment',
                equipType: raw.equipType || null,
                weaponType: raw.weaponType || null,
                levelReq: raw.levelReq || 0,
                rarity: raw.rarity || 'common',
                refine: b.refine || raw.refine || 0,
                slots: raw.slots || 0,
                cards: raw.cards || [],
                attributes: raw.attributes || [],
                affixes: raw.affixes || [],
                effects: raw.effects || [],
                locked: !!raw.locked,
                icon: iconUrl
            };
        });

        // Process currently equipped items with real icons
        const equipmentWithIcons = {};
        if (char.equipment) {
            for (const [slotKey, it] of Object.entries(char.equipment)) {
                if (it) {
                    equipmentWithIcons[slotKey] = {
                        ...it,
                        icon: resolveCharIcon(it)
                    };
                } else {
                    equipmentWithIcons[slotKey] = null;
                }
            }
        }

        // Ammo slot handling
        if (char.ammo) {
            equipmentWithIcons['ammo'] = {
                ...char.ammo,
                icon: resolveCharIcon(char.ammo)
            };
        }

        const nameEl = document.querySelector('.hud-name');
        const resolvedName = nameEl?.innerText?.trim() || window.__charName || char.charName || char.name || (char.className ? `${char.className} Player` : 'Player');

        return {
            success: true,
            charName: resolvedName,
            classId: classId,
            className: char.className || 'Hunter',
            baseLevel: char.baseLevel || 1,
            jobLevel: char.jobLevel || 1,
            jobMaxLevel: char.jobMaxLevel || 50,
            baseExp: char.baseExp || 0,
            baseExpNext: char.baseExpNext || 1,
            jobExp: char.jobExp || 0,
            jobExpNext: char.jobExpNext || 1,
            hp: char.derived?.maxHp ? Math.min(char.derived.maxHp, char.hp || char.derived.maxHp) : 100,
            hpMax: char.derived?.maxHp || 100,
            sp: char.derived?.maxSp ? Math.min(char.derived.maxSp, char.sp || char.derived.maxSp) : 50,
            spMax: char.derived?.maxSp || 50,
            zeny: (typeof window.__currentZeny === 'number') ? window.__currentZeny : (char.zeny || 0),
            statusPoints: char.statusPoints || 0,
            skillPoints: char.skillPoints || 0,
            stats: char.stats || { STR: 1, AGI: 1, VIT: 1, INT: 1, DEX: 1, LUK: 1 },
            bonusStats: char.bonusStats || { STR: 0, AGI: 0, VIT: 0, INT: 0, DEX: 0, LUK: 0 },
            statCosts: char.statCosts || { STR: 2, AGI: 2, VIT: 2, INT: 2, DEX: 2, LUK: 2 },
            derived: char.derived || {},
            equipment: equipmentWithIcons,
            bagItems: equippableBag,
            faceAvatar: faceAvatar,
            fullPortrait: fullPortrait,
            map: (typeof window.getCurrentMapName === 'function') ? window.getCurrentMapName() : '',
            channel: (typeof window.getCurrentChannel === 'function') ? window.getCurrentChannel() : 1
        };
    };

    window.executeEquipItem = function(bagSlot, targetSlot) {
        const room = (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null) || window.__gameRoom;
        if (!room) return { success: false, error: 'No room connection' };
        const payload = { slot: Number(bagSlot) };
        if (targetSlot) payload.to = targetSlot;
        console.log(`%c[PmheeAether Equip] ⚔️ สวมใส่ไอเทมช่องกระเป๋า ${bagSlot} -> ${targetSlot || 'auto'}`, 'color: #38bdf8; font-weight: bold;');
        room.send('equip', payload);
        return { success: true };
    };

    window.executeUnequipItem = function(slotKey) {
        const room = (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null) || window.__gameRoom;
        if (!room) return { success: false, error: 'No room connection' };
        console.log(`%c[PmheeAether Equip] 🛡️ ถอดไอเทมช่อง ${slotKey}`, 'color: #f59e0b; font-weight: bold;');
        room.send('unequip', { slot: slotKey });
        return { success: true };
    };

    window.executeAddStat = function(statKey, count = 1) {
        const room = (typeof window.getGameRoom === 'function' ? window.getGameRoom() : null) || window.__gameRoom;
        if (!room) return { success: false, error: 'No room connection' };
        console.log(`%c[PmheeAether Stat] 📈 อัปค่าสถานะ ${statKey} +${count}`, 'color: #22c55e; font-weight: bold;');
        room.send('stat_up', { stat: String(statKey).toUpperCase(), n: Number(count) || 1 });   // the game uses STR/AGI/... (lower case was ignored)
        return { success: true };
    };

    // ==========================================
    // PRIEST-CENTRIC PARTY COORDINATOR (v4.42.3)
    // ==========================================
    window.getPartyPriestBuffStatus = function(minRemainMs = 25000) {
        const live = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        const me = room && room.state && room.state.players && room.state.players.get ? room.state.players.get(room.sessionId) : null;
        const buffs = (live && Array.isArray(live.buffs)) ? live.buffs : [];
        const now = Date.now();
        let blessingMs = 0;
        let agiMs = 0;
        let impositioMs = 0;
        let kyrieMs = 0;
        let gloriaMs = 0;
        let aspersioMs = 0;
        for (const b of buffs) {
            if (!b || !b.skillId) continue;
            const rem = typeof b.remainingMs === 'number' ? b.remainingMs : (b.endsAt ? Math.max(0, b.endsAt - now) : 0);
            if (b.skillId === 'blessing') blessingMs = Math.max(blessingMs, rem);
            else if (b.skillId === 'increase-agi') agiMs = Math.max(agiMs, rem);
            else if (b.skillId === 'impositio-manus') impositioMs = Math.max(impositioMs, rem);
            else if (b.skillId === 'kyrie-eleison') kyrieMs = Math.max(kyrieMs, rem);
            else if (b.skillId === 'gloria') gloriaMs = Math.max(gloriaMs, rem);
            else if (b.skillId === 'aspersio') aspersioMs = Math.max(aspersioMs, rem);
        }
        const hp = (me && typeof me.hp === 'number') ? me.hp : (live && typeof live.hp === 'number' ? live.hp : 100);
        const maxHp = (me && typeof me.maxHp === 'number' && me.maxHp > 0) ? me.maxHp : (live && live.derived && live.derived.maxHp ? live.derived.maxHp : 100);
        const hpPct = maxHp > 0 ? (hp / maxHp) : 1;
        const minCoreBuffMs = Math.min(blessingMs, agiMs);
        const needsBuff = (blessingMs < minRemainMs) || (agiMs < minRemainMs);
        const needsHeal = hpPct > 0 && hpPct < 0.65;
        return {
            blessingMs,
            agiMs,
            impositioMs,
            kyrieMs,
            gloriaMs,
            aspersioMs,
            minCoreBuffMs,
            hpPct,
            needsBuff,
            needsHeal,
            needsPriest: needsBuff || needsHeal
        };
    };

    // รายการสกิลบัฟทั้งหมดของ Priest ที่จะร่ายให้เป้าหมายครบทุกสกิลในครั้งเดียว (แม้บัฟบางอันยังไม่หมด)
    // เรียงลำดับให้ Blessing + Increase AGI อยู่ท้ายสุด เพื่อเมื่อร่ายครบทั้งสองสกิลแล้ว ตัวตีจะรู้ทันทีว่าได้บัฟครบทุกสกิลแล้ว!
    window.getPriestPartyBuffSkills = function() {
        const live = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
        if (!live) return [];
        const learned = live.skills || {};
        const autoSkills = (live.auto && live.auto.config && Array.isArray(live.auto.config.skills))
            ? new Set(live.auto.config.skills)
            : null;
        const order = ['impositio-manus', 'gloria', 'kyrie-eleison', 'aspersio', 'blessing', 'increase-agi'];
        const out = [];
        for (const id of order) {
            if (!(Number(learned[id]) > 0)) continue;
            if (id !== 'blessing' && id !== 'increase-agi') {
                if (autoSkills && autoSkills.size > 0 && !autoSkills.has(id)) continue;
                if ((!autoSkills || autoSkills.size === 0) && id === 'aspersio') continue;
            }
            out.push(id);
        }
        return out;
    };

    // อ่านข้อมูลปาร์ตี้และรายการบัฟสดของสมาชิกทุกคนจาก React Store ของตัวเกมโดยตรง (0ms real-time ไม่ต้องรอ Manager sync)
    window.getInGamePartyState = function() {
        try {
            let g = window.__pmPartyGetters;
            if (!g || !g.party) {
                const out = {};
                const rootEl = document.getElementById('root') || (document.body && document.body.firstElementChild);
                const key = rootEl && Object.keys(rootEl).find(k => k.startsWith('__reactContainer$') || k.startsWith('__reactFiber$'));
                if (key) {
                    let start = rootEl[key];
                    if (start && start.stateNode && start.stateNode.current) start = start.stateNode.current;
                    const stack = [start];
                    let n = 0;
                    while (stack.length && n++ < 100000 && !(out.party && out.invite && out.follow)) {
                        const f = stack.pop();
                        if (!f) continue;
                        let h = f.memoizedState, gc = 0;
                        while (h && typeof h === 'object' && gc++ < 80) {
                            const q = h.queue;
                            if (q && typeof q.getSnapshot === 'function') {
                                const src = String(q.getSnapshot).replace(/\s+/g, '');
                                if (!out.party && /^\(\)=>[A-Za-z_$][\w$]*\.party$/.test(src)) out.party = q.getSnapshot;
                                if (!out.invite && /^\(\)=>[A-Za-z_$][\w$]*\.invite$/.test(src)) out.invite = q.getSnapshot;
                                if (!out.follow && /^\(\)=>[A-Za-z_$][\w$]*\.follow$/.test(src)) out.follow = q.getSnapshot;
                            }
                            h = h.next;
                        }
                        if (f.sibling) stack.push(f.sibling);
                        if (f.child) stack.push(f.child);
                    }
                }
                if (out.party) window.__pmPartyGetters = Object.assign({}, g, out);
                g = window.__pmPartyGetters;
            }
            return (g && typeof g.party === 'function') ? g.party() : null;
        } catch (e) {
            return null;
        }
    };

    function getMemberBuffRemainingMs(memberNameLower, skillId) {
        try {
            const now = Date.now();
            const party = typeof window.getInGamePartyState === 'function' ? window.getInGamePartyState() : null;
            if (party && Array.isArray(party.members)) {
                const m = party.members.find(x => x && String(x.name || '').trim().toLowerCase() === memberNameLower);
                if (m && Array.isArray(m.buffs)) {
                    const b = m.buffs.find(x => x && x.skillId === skillId);
                    if (b) return typeof b.remainingMs === 'number' ? b.remainingMs : (b.endsAt ? Math.max(0, b.endsAt - now) : 0);
                }
            }
        } catch (e) {}
        return 0;
    }

    function setPriestBuffWalkAutoPause(pause) {
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        const live = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
        if (pause) {
            window.__priestBusyBuffing = true;
            window.__priestBusyBuffingAt = Date.now();
            const isAutoOn = Boolean((live && live.auto && live.auto.enabled) || (typeof getInGameAutoStatus === 'function' && getInGameAutoStatus() === 'on'));
            if (isAutoOn || !window.__priestPausedAutoForBuff) {
                window.__priestPausedAutoForBuff = true;
                try { if (room && typeof room.send === 'function') room.send('auto_set', { enabled: false }); } catch (e) {}
            }
        } else {
            window.__priestBusyBuffing = false;
            window.__priestBusyBuffingAt = 0;
            if (window.__priestPausedAutoForBuff) {
                window.__priestPausedAutoForBuff = false;
                if (window.__isBotRunning && !window.__isShopping && !window.__isNavigating) {
                    try { if (room && typeof room.send === 'function') room.send('auto_set', { enabled: true }); } catch (e) {}
                    setTimeout(() => {
                        if (window.__isBotRunning && !window.__priestBusyBuffing && typeof getInGameAutoStatus === 'function' && getInGameAutoStatus() === 'off') {
                            if (typeof window.activateInGameAuto === 'function') window.activateInGameAuto();
                        }
                    }, 250);
                }
            }
        }
    }

    // สั่งให้ Priest ร่ายบัฟทั้งหมดทุกสกิลใส่เป้าหมายรวดเดียว (แม้บัฟจะยังไม่หมด) เพื่อรีเซ็ตเวลาพร้อมกันทุกสกิล
    window.castFullPriestBuffSuite = async function(targetKey, targetName) {
        if (window.__priestCastingJob) return false;
        const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
        if (!room || !room.state || !room.state.players || !targetKey) return false;
        const wantNameLower = String(targetName || '').trim().toLowerCase();
        window.__priestCastingJob = { targetKey, targetName: wantNameLower, startedAt: Date.now() };
        window.__priestBuffingTarget = targetName || null;
        setPriestBuffWalkAutoPause(true);
        const sleep = ms => new Promise(r => setTimeout(r, ms));
        try {
            const liveInit = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
            const learned = (liveInit && liveInit.skills) || {};
            const buffSkills = window.getPriestPartyBuffSkills();
            if (!buffSkills.length) return false;

            const findTarget = () => {
                const players = room && room.state && room.state.players;
                if (!players) return null;
                let p = players.get ? players.get(targetKey) : null;
                let k = targetKey;
                if (!p && wantNameLower && typeof players.forEach === 'function') {
                    players.forEach((cand, ck) => {
                        if (!p && cand && String(cand.name || '').trim().toLowerCase() === wantNameLower) {
                            p = cand;
                            k = ck;
                        }
                    });
                }
                return p ? { player: p, key: k } : null;
            };

            const castSingleSkill = async (skillId, isPartyWide = false) => {
                const castWaitMs = (skillId === 'increase-agi' || skillId === 'kyrie-eleison' || skillId === 'aspersio') ? 920 : 450;
                for (let attempt = 0; attempt < 3; attempt++) {
                    if (!window.__isBotRunning) return false;
                    window.__priestBusyBuffingAt = Date.now();
                    const me = room.state.players.get(room.sessionId);
                    const found = findTarget();
                    if (!me || !found || (typeof found.player.hp === 'number' && found.player.hp <= 0)) return false;

                    // หากเป้าหมายขยับออกนอกระยะ 8 ช่อง (~235px) ให้เดินตามเข้าไปใกล้ก่อนร่าย
                    if (!isPartyWide && found.key !== room.sessionId) {
                        const dist = Math.hypot((me.x || 0) - (found.player.x || 0), (me.y || 0) - (found.player.y || 0));
                        if (dist > 235) {
                            try { room.send('auto_set', { enabled: false }); } catch (e) {}
                            room.send('move_to', { x: found.player.x, y: found.player.y, auto: true });
                            await sleep(500);
                            continue;
                        }
                    }

                    const liveBefore = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
                    const cdLeft = (liveBefore && liveBefore.cooldowns && Number(liveBefore.cooldowns[skillId])) || 0;
                    if (cdLeft > 200 && cdLeft < 3500) {
                        await sleep(Math.min(cdLeft + 100, 1800));
                    }

                    const remBefore = wantNameLower ? getMemberBuffRemainingMs(wantNameLower, skillId) : 0;
                    const payload = isPartyWide ? { skillId } : { skillId, targetId: found.key };
                    room.send('cast', payload);
                    await sleep(castWaitMs);

                    const liveAfter = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
                    const cdAfter = (liveAfter && liveAfter.cooldowns && Number(liveAfter.cooldowns[skillId])) || 0;
                    const remAfter = wantNameLower ? getMemberBuffRemainingMs(wantNameLower, skillId) : 0;
                    if (cdAfter > 0 || remAfter > remBefore + 5000 || remAfter >= 22000) return true;
                    if (skillId === 'heal') return true;
                    await sleep(320);
                }
                return false;
            };

            const initialFound = findTarget();
            if (!initialFound) return false;
            const hpPct = (initialFound.player.maxHp > 0 && typeof initialFound.player.hp === 'number')
                ? (initialFound.player.hp / initialFound.player.maxHp)
                : 1;

            console.log(`%c[PmheeAether Priest] ✨ เริ่มร่ายบัฟครบทุกสกิล (${buffSkills.join(', ')}) ให้ "${targetName || targetKey}"`, 'color: #a855f7; font-weight: bold;');

            // 1. ฮีลก่อนถ้าเลือดลด (< 85%)
            if (hpPct > 0 && hpPct < 0.85 && Number(learned['heal']) > 0) {
                await castSingleSkill('heal', false);
            }

            // 2. ร่ายสกิลบัฟทั้งหมดทุกสกิล แม้บัฟบางตัวจะยังไม่หมดเวลา!
            let anyCastSuccess = false;
            for (const skillId of buffSkills) {
                if (!window.__isBotRunning) break;
                if (skillId === 'gloria') {
                    if (Date.now() - (window.__lastPriestGloriaAt || 0) < 7000) continue;
                    const ok = await castSingleSkill('gloria', true);
                    if (ok) {
                        window.__lastPriestGloriaAt = Date.now();
                        anyCastSuccess = true;
                    }
                } else {
                    const ok = await castSingleSkill(skillId, false);
                    if (ok) anyCastSuccess = true;
                }
            }

            const blessAfter = wantNameLower ? getMemberBuffRemainingMs(wantNameLower, 'blessing') : 240000;
            const agiAfter = wantNameLower ? getMemberBuffRemainingMs(wantNameLower, 'increase-agi') : 240000;
            const coreLanded = (blessAfter > 45000 && agiAfter > 45000) || (targetKey === room.sessionId && anyCastSuccess);
            if (!window.__priestRecentlyBuffed) window.__priestRecentlyBuffed = {};
            if (wantNameLower && (coreLanded || anyCastSuccess)) {
                window.__priestRecentlyBuffed[wantNameLower] = coreLanded ? Date.now() : (Date.now() - 10000);
            }
            console.log(`%c[PmheeAether Priest] ✅ ร่ายบัฟครบทุกสกิลให้ "${targetName || targetKey}" เสร็จเรียบร้อย!`, 'color: #22c55e; font-weight: bold;');
            return true;
        } catch (e) {
            return false;
        } finally {
            window.__priestCastingJob = null;
            window.__priestBuffingTarget = null;
        }
    };

    // ปรับเฉพาะระยะล่า (huntRadiusTiles) ของปาร์ตี้ โดยไม่ไปแตะหรือติ๊กสกิล Auto ที่ผู้ใช้ตั้งไว้เอง!
    window.applyPartyRadiusOverride = function(targetRadius) {
        const prevOverride = window.__partyOverrideRadius || null;
        window.__partyOverrideRadius = targetRadius || null;
        if (prevOverride === window.__partyOverrideRadius) return false;

        // ถ้าเปิด Plan Script อยู่ ให้ใช้ autoConfigureCombat แบบไม่ force (เคารพเงื่อนไขแผนและ skillBuild.autoOff)
        if (window.__planScriptEnabled && window.__currentScriptPlan && window.__autoConfigCharEnabled) {
            if (typeof window.autoConfigureCombat === 'function') window.autoConfigureCombat(false);
            return true;
        }

        // ถ้าไม่ได้เปิด Plan Script: แก้เฉพาะ huntRadiusTiles และคง currentConfig.skills เดิมไว้ 100%
        const charData = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : (window.__latestCharacterData || null);
        const room = (typeof window.getColyseusRoom === 'function') ? window.getColyseusRoom() : window.__gameRoom;
        if (!charData || !room || typeof room.send !== 'function') return false;

        const currentAuto = charData.auto || {};
        const currentConfig = currentAuto.config || {};
        const curRadius = currentConfig.huntRadiusTiles || 'all';

        if (targetRadius) {
            if (!window.__prePartyHuntRadius && curRadius !== targetRadius) {
                window.__prePartyHuntRadius = curRadius;
            }
        }
        const desiredRadius = targetRadius || window.__prePartyHuntRadius || 'all';
        if (!targetRadius) window.__prePartyHuntRadius = null;

        if (curRadius === desiredRadius) return false;

        const isPriestCls = /^(priest|acolyte)$/i.test(String(charData.classId || ''));
        const newConfig = Object.assign({}, currentConfig, {
            skills: Array.isArray(currentConfig.skills) ? [...currentConfig.skills] : [],
            huntRadiusTiles: desiredRadius,
            buffParty: currentConfig.buffParty !== false,
            healPartyPercent: isPriestCls ? Math.max(Number(currentConfig.healPartyPercent) || 80, 80) : (typeof currentConfig.healPartyPercent === 'number' ? currentConfig.healPartyPercent : 60)
        });

        try {
            room.send('auto_set', { config: newConfig });
            if (charData.auto) {
                charData.auto.config = Object.assign({}, charData.auto.config, newConfig);
            }
            return true;
        } catch (e) {
            return false;
        }
    };

    function clearPartyPriestFollow(room, sync, forceEmit = false) {
        const fm = sync && sync.followMode ? String(sync.followMode) : 'none';
        if (fm !== 'none' && fm !== 'priest') return;
        const chipBtn = typeof document.querySelector === 'function' ? document.querySelector('.follow-chip button') : null;
        if (chipBtn && typeof chipBtn.click === 'function') {
            chipBtn.click();
        }
        if (forceEmit || chipBtn) {
            try {
                const r = room || ((typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom);
                const handlers = r && r.onMessageHandlers;
                if (handlers && typeof handlers.emit === 'function') {
                    handlers.emit('party_follow', { name: null });
                }
            } catch (e) {}
        }
    }

    window.updatePartySyncState = function(sync) {
        if (!sync) {
            const prevSync = window.__pmPartySync;
            window.__pmPartySync = null;
            window.__partyForcedMap = null;
            if (window.__partyOverrideRadius || window.__returningToPriest) {
                window.__returningToPriest = false;
                if (typeof window.applyPartyRadiusOverride === 'function') window.applyPartyRadiusOverride(null);
            }
            setPriestBuffWalkAutoPause(false);
            clearPartyPriestFollow(null, prevSync, true);
            return { success: true, cleared: true };
        }
        window.__pmPartySync = Object.assign({}, sync, { updatedAt: Date.now() });
        if (sync.forcedMap && !/เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(sync.forcedMap)) {
            window.__partyForcedMap = String(sync.forcedMap).replace(/\s*\(Lv\..*?\)/i, '').trim();
        } else if (sync.clearForcedMap) {
            window.__partyForcedMap = null;
        }
        return { success: true };
    };

    if (window.__pmPartyCoordInterval) clearInterval(window.__pmPartyCoordInterval);
    window.__pmPartyCoordInterval = setInterval(() => {
        try {
            const busyNow = (typeof window.planBusyReason === 'function' ? window.planBusyReason() : (typeof planBusyReason === 'function' ? planBusyReason() : null)) !== null;
            if (!window.__isBotRunning || busyNow) {
                if (window.__priestPausedAutoForBuff) setPriestBuffWalkAutoPause(false);
                return;
            }
            if ((typeof window.isCharacterDeadNow === 'function' && window.isCharacterDeadNow()) || (typeof isCharacterDead === 'function' && isCharacterDead())) {
                if (window.__priestPausedAutoForBuff) setPriestBuffWalkAutoPause(false);
                return;
            }
            const curMap = (typeof window.getCurrentMapName === 'function') ? (window.getCurrentMapName() || '') : '';
            if (!curMap || /เมืองหลวง|โซลเฮเวน|ตลาดคาราวาน/.test(curMap)) {
                if (window.__priestPausedAutoForBuff) setPriestBuffWalkAutoPause(false);
                return;
            }

            const room = (typeof window.getGameRoom === 'function') ? window.getGameRoom() : window.__gameRoom;
            const now = Date.now();
            const rawSync = window.__pmPartySync;
            const syncFresh = Boolean(rawSync && (now - (rawSync.updatedAt || 0) <= 45000));
            const sync = syncFresh ? rawSync : null;
            const inGameParty = typeof window.getInGamePartyState === 'function' ? window.getInGamePartyState() : null;
            const hasInGameParty = Boolean(inGameParty && Array.isArray(inGameParty.members) && inGameParty.members.length > 1);

            if (!sync && !hasInGameParty) {
                if (window.__partyOverrideRadius || window.__returningToPriest) {
                    window.__returningToPriest = false;
                    clearPartyPriestFollow(room, rawSync, true);
                    if (typeof window.applyPartyRadiusOverride === 'function') window.applyPartyRadiusOverride(null);
                }
                if (window.__priestPausedAutoForBuff) setPriestBuffWalkAutoPause(false);
                return;
            }

            if (window.__partyOverrideRadius !== null && typeof window.applyPartyRadiusOverride === 'function') {
                window.applyPartyRadiusOverride(null);
            }

            const players = room && room.state && room.state.players;
            const me = players && players.get ? players.get(room.sessionId) : null;
            if (!room || !players || !me) return;

            const live = (typeof window.getLiveCharacterData === 'function') ? window.getLiveCharacterData() : window.__latestCharacterData;
            const myClass = String((me && me.classId) || (live && live.classId) || '').toLowerCase();
            const isMePriest = /^(priest|acolyte)$/.test(myClass);

            // กรณีตัวเองเป็น Priest: เดินไปหาสมาชิกที่ไม่มีบัฟ (เพิ่งกลับมาจากเมือง/ตายวาร์ปกลับมา) หรือบัฟใกล้หมด/เลือดต่ำ และร่ายบัฟครบทุกสกิล!
            if (isMePriest) {
                const chipBtn = document.querySelector('.follow-chip button');
                if (chipBtn && typeof chipBtn.click === 'function') chipBtn.click();

                if (window.__priestCastingJob) {
                    // กำลังร่ายชุดบัฟอยู่ รอให้ครบชุด (ป้องกันค้างเกิน 14 วิ)
                    if (now - (window.__priestCastingJob.startedAt || 0) > 14000) {
                        window.__priestCastingJob = null;
                        window.__priestBuffingTarget = null;
                    } else {
                        window.__priestBusyBuffing = true;
                        window.__priestBusyBuffingAt = now;
                        return;
                    }
                }

                if (!window.__priestRecentlyBuffed) window.__priestRecentlyBuffed = {};
                if (!window.__priestWalkSkipUntil) window.__priestWalkSkipUntil = {};
                const myNameLower = String(me.name || '').trim().toLowerCase();
                const learned = (live && live.skills) || {};
                const hasBlessLearned = Number(learned['blessing']) > 0;
                const hasAgiLearned = Number(learned['increase-agi']) > 0;

                // 1) เช็กบัฟของตัว Priest เองด้วย: ถ้าบัฟตัวเองใกล้หมด (< 28 วิ) หรือเลือดต่ำ ให้ร่ายครบทุกสกิลใส่ตัวเองก่อน
                const myBuffSt = window.getPartyPriestBuffStatus(28000);
                const selfRecentAt = window.__priestRecentlyBuffed[myNameLower] || 0;
                if ((myBuffSt.needsPriest && (now - selfRecentAt > 10000)) || myBuffSt.needsHeal) {
                    window.castFullPriestBuffSuite(room.sessionId, me.name || 'Self');
                    return;
                }

                // 2) รวบรวมรายชื่อและสถานะบัฟสดของสมาชิกในปาร์ตี้จากทั้ง inGameParty (0ms real-time) และ sync
                const partySet = new Set();
                if (sync && Array.isArray(sync.partyNames)) {
                    for (const n of sync.partyNames) if (n) partySet.add(String(n).trim().toLowerCase());
                }
                const inGameBuffMap = new Map();
                if (inGameParty && Array.isArray(inGameParty.members)) {
                    for (const m of inGameParty.members) {
                        if (!m || !m.name) continue;
                        const nl = String(m.name).trim().toLowerCase();
                        partySet.add(nl);
                        if (Array.isArray(m.buffs)) {
                            let bMs = 0, aMs = 0, impMs = 0, kyrMs = 0;
                            for (const b of m.buffs) {
                                if (!b || !b.skillId) continue;
                                const rem = typeof b.remainingMs === 'number' ? b.remainingMs : (b.endsAt ? Math.max(0, b.endsAt - now) : 0);
                                if (b.skillId === 'blessing') bMs = Math.max(bMs, rem);
                                else if (b.skillId === 'increase-agi') aMs = Math.max(aMs, rem);
                                else if (b.skillId === 'impositio-manus') impMs = Math.max(impMs, rem);
                                else if (b.skillId === 'kyrie-eleison') kyrMs = Math.max(kyrMs, rem);
                            }
                            const coreList = [];
                            if (hasBlessLearned) coreList.push(bMs);
                            if (hasAgiLearned) coreList.push(aMs);
                            const minCore = coreList.length ? Math.min(...coreList) : Math.min(bMs, aMs);
                            const missingCore = (hasBlessLearned && bMs <= 0) || (hasAgiLearned && aMs <= 0);
                            inGameBuffMap.set(nl, { blessingMs: bMs, agiMs: aMs, impositioMs: impMs, kyrieMs: kyrMs, minCoreBuffMs: minCore, missingCoreBuff: missingCore });
                        }
                    }
                }

                const roomPartyMap = new Map();
                if (typeof players.forEach === 'function') {
                    players.forEach((p, k) => {
                        if (!p || !p.name || p === me || p.dead) return;
                        if (typeof p.hp === 'number' && p.hp <= 0) return;
                        const nl = String(p.name).trim().toLowerCase();
                        if (!partySet.has(nl)) return;
                        const dist = Math.hypot((me.x || 0) - (p.x || 0), (me.y || 0) - (p.y || 0));
                        const hpPct = (p.maxHp > 0 && typeof p.hp === 'number') ? (p.hp / p.maxHp) : 1;
                        roomPartyMap.set(nl, { key: k, player: p, name: p.name, dist, hpPct });
                    });
                }

                const syncQueueMap = new Map();
                if (sync && Array.isArray(sync.buffQueue)) {
                    for (const q of sync.buffQueue) {
                        if (q && q.name) syncQueueMap.set(String(q.name).trim().toLowerCase(), q);
                    }
                }

                const candidates = [];
                for (const [nl, rp] of roomPartyMap.entries()) {
                    if (nl === myNameLower) continue;
                    const liveNeedsHeal = rp.hpPct > 0 && rp.hpPct < 0.68;
                    const skipUntil = window.__priestWalkSkipUntil[nl] || 0;
                    if (!liveNeedsHeal && now < skipUntil) continue;

                    const ig = inGameBuffMap.get(nl);
                    const sq = syncQueueMap.get(nl);
                    const recentAt = window.__priestRecentlyBuffed[nl] || 0;
                    const sinceRecent = now - recentAt;

                    let minCoreBuffMs = 999999;
                    let missingCoreBuff = false;
                    if (ig) {
                        minCoreBuffMs = ig.minCoreBuffMs;
                        missingCoreBuff = ig.missingCoreBuff;
                    } else if (sq) {
                        minCoreBuffMs = typeof sq.minCoreBuffMs === 'number' ? sq.minCoreBuffMs : 0;
                        missingCoreBuff = minCoreBuffMs <= 0;
                    } else {
                        minCoreBuffMs = Math.max(0, 210000 - sinceRecent);
                        missingCoreBuff = recentAt === 0;
                    }

                    const cooldownGuardMs = missingCoreBuff ? 3500 : 12000;
                    if (!liveNeedsHeal && sinceRecent < cooldownGuardMs) continue;

                    const needsBuffNow = missingCoreBuff || minCoreBuffMs < 32000 || Boolean(sq && (sq.needsBuff || sq.returningToPriest));
                    const nearbyRefresh = rp.dist <= 235 && minCoreBuffMs < 65000;
                    if (liveNeedsHeal || needsBuffNow || nearbyRefresh) {
                        candidates.push({
                            name: rp.name,
                            nameLower: nl,
                            key: rp.key,
                            player: rp.player,
                            dist: rp.dist,
                            hpPct: rp.hpPct,
                            needsHeal: Boolean(liveNeedsHeal || (sq && sq.needsHeal)),
                            missingCoreBuff,
                            minCoreBuffMs
                        });
                    }
                }

                // เรียงลำดับความสำคัญ:
                // 1. เลือดต่ำด่วนสุด (< 68%)
                // 2. คนที่อยู่ในระยะร่ายของพระอยู่แล้ว (<= 210px) และต้องการบัฟ ให้ร่ายให้เสร็จก่อนเดินไปไกล
                // 3. คนที่ไม่มีบัพเลย (missingCoreBuff = เพิ่งกลับมาจากเมืองหรือตายวาร์ปกลับมา!)
                // 4. เวลาบัฟเหลือน้อยสุด / อยู่ใกล้พระที่สุด
                candidates.sort((a, b) => {
                    if (a.needsHeal !== b.needsHeal) return a.needsHeal ? -1 : 1;
                    if (a.needsHeal && b.needsHeal && Math.abs(a.hpPct - b.hpPct) > 0.05) return a.hpPct - b.hpPct;
                    const aInRange = a.dist <= 210 && (a.missingCoreBuff || a.minCoreBuffMs < 32000);
                    const bInRange = b.dist <= 210 && (b.missingCoreBuff || b.minCoreBuffMs < 32000);
                    if (aInRange !== bInRange) return aInRange ? -1 : 1;
                    if (a.missingCoreBuff !== b.missingCoreBuff) return a.missingCoreBuff ? -1 : 1;
                    if (Math.abs(a.minCoreBuffMs - b.minCoreBuffMs) > 6000) return a.minCoreBuffMs - b.minCoreBuffMs;
                    return a.dist - b.dist;
                });

                if (candidates.length > 0) {
                    const top = candidates[0];
                    window.__priestBuffingTarget = top.name;
                    if (top.dist > 205) {
                        if (window.__priestWalkTarget !== top.nameLower) {
                            window.__priestWalkTarget = top.nameLower;
                            window.__priestWalkStartedAt = now;
                        } else if (now - (window.__priestWalkStartedAt || now) > 16000) {
                            window.__priestWalkSkipUntil[top.nameLower] = now + 9000;
                            window.__priestWalkTarget = null;
                            return;
                        }

                        // พัก AUTO โจมตีมอนสเตอร์ชั่วคราวเพื่อให้พระเดินตรงไปหาเพื่อนที่ไม่มีบัพทันทีโดยไม่หยุดตีมอนระหว่างทาง!
                        setPriestBuffWalkAutoPause(true);

                        // ป้องกันตัวเองระหว่างเดิน: หากเลือดพระลดหรือเกราะ Kyrie หมด ให้ร่ายใส่ตัวเองระหว่างเดินได้
                        const cdMap = (live && live.cooldowns) || {};
                        if (myBuffSt.hpPct < 0.78 && Number(learned['heal']) > 0 && !(Number(cdMap['heal']) > 0)) {
                            try { room.send('cast', { skillId: 'heal', targetId: room.sessionId }); } catch (e) {}
                        } else if (myBuffSt.kyrieMs <= 0 && Number(learned['kyrie-eleison']) > 0 && !(Number(cdMap['kyrie-eleison']) > 0) && (now - (window.__lastPriestWalkKyrieAt || 0) > 4500)) {
                            window.__lastPriestWalkKyrieAt = now;
                            try { room.send('cast', { skillId: 'kyrie-eleison', targetId: room.sessionId }); } catch (e) {}
                        }

                        if (window.__lastPriestWalkLogTarget !== top.nameLower || (now - (window.__lastPriestWalkLogAt || 0) > 5000)) {
                            window.__lastPriestWalkLogTarget = top.nameLower;
                            window.__lastPriestWalkLogAt = now;
                            const statusLabel = top.missingCoreBuff ? 'ไม่มีบัพ/เพิ่งกลับมา' : `บัฟเหลือ ${Math.round(top.minCoreBuffMs / 1000)}s`;
                            console.log(`%c[PmheeAether Priest] 🏃‍♂️ เดินไปหา "${top.name}" (${statusLabel} · ระยะ ${Math.round(top.dist)}px) เพื่อร่ายบัฟครบทุกสกิล`, 'color: #38bdf8; font-weight: bold;');
                        }
                        room.send('move_to', { x: top.player.x, y: top.player.y, auto: true });
                    } else {
                        window.__priestWalkTarget = null;
                        // อยู่ในระยะร่ายบัฟแล้ว -> ร่ายบัฟทั้งหมดทุกสกิลรวดเดียว!
                        window.castFullPriestBuffSuite(top.key, top.name);
                    }
                    return;
                }

                window.__priestWalkTarget = null;
                window.__priestBuffingTarget = null;
                setPriestBuffWalkAutoPause(false);
                return;
            }

            // กรณีเป็นสมาชิกหรือหัวตี้ที่มี Priest อยู่ในปาร์ตี้
            let priestName = (sync && sync.priestName) ? String(sync.priestName).trim() : '';
            if (!priestName && inGameParty && Array.isArray(inGameParty.members)) {
                const pm = inGameParty.members.find(m => m && m.online !== false && /^(priest|acolyte)$/i.test(String(m.classId || '')));
                if (pm && pm.name) priestName = String(pm.name).trim();
            }
            if (!priestName) {
                if (window.__returningToPriest) {
                    window.__returningToPriest = false;
                    clearPartyPriestFollow(room, sync, true);
                }
                return;
            }

            let priestPlayer = null;
            const wantPriest = priestName.toLowerCase();
            if (typeof players.forEach === 'function') {
                players.forEach(p => {
                    if (!priestPlayer && p && !p.dead && String(p.name || '').trim().toLowerCase() === wantPriest) priestPlayer = p;
                });
            }
            if (!priestPlayer || (typeof priestPlayer.hp === 'number' && priestPlayer.hp <= 0)) {
                if (window.__returningToPriest) {
                    window.__returningToPriest = false;
                    clearPartyPriestFollow(room, sync, true);
                }
                return;
            }

            const distToPriest = Math.hypot((me.x || 0) - (priestPlayer.x || 0), (me.y || 0) - (priestPlayer.y || 0));
            const buffSt = window.getPartyPriestBuffStatus(25000);
            const hasNoCoreBuffs = (buffSt.blessingMs <= 0 || buffSt.agiMs <= 0);

            if (!window.__returningToPriest && buffSt.needsPriest && now >= (window.__priestBuffCooldownUntil || 0)) {
                window.__returningToPriest = true;
                window.__returnToPriestStartedAt = now;
                window.__returnNearPriestSince = distToPriest <= 220 ? now : 0;
                window.__returnMinBlessMs = buffSt.blessingMs;
                window.__returnMinAgiMs = buffSt.agiMs;
                window.__returnGotBless = false;
                window.__returnGotAgi = false;
                if (hasNoCoreBuffs && distToPriest > 260) {
                    console.log(`%c[PmheeAether Party] 🙏 เพิ่งกลับเข้าแมพ/ไม่มีบัพพระ -> รอให้ Priest "${priestName}" (ระยะ ${Math.round(distToPriest)}px) เดินมาบัพให้โดยไม่วิ่งฝ่าฝูงมอนไปตาย`, 'color: #38bdf8; font-weight: bold;');
                } else {
                    console.log(`%c[PmheeAether Party] 🙏 บัฟพระใกล้หมดหรือเลือดต่ำ (Bless:${Math.round(buffSt.blessingMs / 1000)}s, AGI:${Math.round(buffSt.agiMs / 1000)}s, HP:${Math.round(buffSt.hpPct * 100)}%) -> ประสานงานรับบัฟกับ Priest "${priestName}"`, 'color: #38bdf8; font-weight: bold;');
                }
            }

            if (window.__returningToPriest) {
                if (distToPriest <= 220 && !window.__returnNearPriestSince) {
                    window.__returnNearPriestSince = now;
                }
                // ติดตามค่าต่ำสุดของบัฟระหว่างเดิน เมื่อ Priest ร่ายบัฟใหม่ เวลาจะดีดสูงขึ้นเกินค่าต่ำสุด (หรือ >= 200 วิ)
                if (buffSt.blessingMs < (window.__returnMinBlessMs ?? buffSt.blessingMs)) {
                    window.__returnMinBlessMs = buffSt.blessingMs;
                }
                if (buffSt.agiMs < (window.__returnMinAgiMs ?? buffSt.agiMs)) {
                    window.__returnMinAgiMs = buffSt.agiMs;
                }
                if (buffSt.blessingMs >= 200000 || buffSt.blessingMs > (window.__returnMinBlessMs || 0) + 8000) {
                    window.__returnGotBless = true;
                }
                if (buffSt.agiMs >= 200000 || buffSt.agiMs > (window.__returnMinAgiMs || 0) + 8000) {
                    window.__returnGotAgi = true;
                }

                const nearDuration = window.__returnNearPriestSince ? (now - window.__returnNearPriestSince) : 0;
                const fullSuiteReady = window.__returnGotBless && window.__returnGotAgi && !buffSt.needsHeal;
                const fallbackReady = nearDuration >= 6500 && buffSt.blessingMs >= 35000 && buffSt.agiMs >= 35000 && !buffSt.needsHeal;

                if (fullSuiteReady || fallbackReady) {
                    window.__returningToPriest = false;
                    window.__returnNearPriestSince = 0;
                    console.log(`%c[PmheeAether Party] ✨ รับบัฟครบทุกสกิลจาก Priest "${priestName}" เรียบร้อย (Bless:${Math.round(buffSt.blessingMs / 1000)}s, AGI:${Math.round(buffSt.agiMs / 1000)}s) -> ลุยฟาร์มต่อ!`, 'color: #22c55e; font-weight: bold;');
                    clearPartyPriestFollow(room, sync, true);
                    return;
                }

                if (nearDuration > 18000 || (now - (window.__returnToPriestStartedAt || now) > 32000)) {
                    // ป้องกันค้างกรณีพระติดสถานะหรือ SP หมดชั่วคราว
                    window.__priestBuffCooldownUntil = now + (hasNoCoreBuffs ? 6000 : 18000);
                    window.__returningToPriest = false;
                    window.__returnNearPriestSince = 0;
                    clearPartyPriestFollow(room, sync, true);
                    return;
                }

                // ป้องกันตัวละครที่เพิ่งกลับมาจากเมือง/ตาย (ไม่มีบัพเลย) วิ่งฝ่าดงมอนไปหาพระจนตายระหว่างทาง:
                // ให้สู้ป้องกันตัวอยู่กับที่จนกว่าพระจะเดินเข้ามาใกล้ (<= 260px) แล้วค่อยขยับเข้ามารับบัฟ
                const maxSafeMeetDist = hasNoCoreBuffs ? 260 : 450;
                if (distToPriest > 145 && distToPriest <= maxSafeMeetDist) {
                    room.send('move_to', { x: priestPlayer.x, y: priestPlayer.y, auto: true });
                } else {
                    clearPartyPriestFollow(room, sync, false);
                }
                return;
            }

            // เมื่อบัฟยังเต็มอยู่: ยกเลิกป้ายติดตามหากค้างอยู่
            clearPartyPriestFollow(room, sync, false);
        } catch (e) {}
    }, 550);

